      ).toThrow(ForbiddenException);
    });

    it('allows matching class', () => {
      expect(() =>
        service.assertBelongsToClass({ class_id: 'class-a' }, 'class-a'),
      ).not.toThrow();
    });
  });

  describe('release/editability rules', () => {
