        {
          system_section_score: 15,
          manual_section_score: 10,
        },
        {
          manual_max_score: 20,
        },
      );

      expect(result).toEqual({
        systemScore: 15,
        manualScore: 10,
        totalScore: 25,
        manualMaxScore: 20,
      });
    });
  });

  describe('buildResult', () => {
