// @/modules/assessment/core/assessment.repository.ts
import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';

@Injectable()
export class AssessmentRepository {
  constructor(private readonly db: DatabaseService) {}

  // ───────── ASSESSMENT CRUD ─────────

  async create(data: {
    orgId: string;
    classId: string;
    lessonId?: string;
    termId: string;
    type: string;
    title?: string;
    totalItems: number;
    releaseDate?: Date;
    endDate?: Date;
    weekNumber?: number;
    gradingMode?: string;
    manualMaxScore?: number;
    showBreakdown?: boolean;
  }) {
    return this.db.assessment.create({
      data: {
        org_id: data.orgId,
        class_id: data.classId,
        lesson_id: data.lessonId ?? null,
        term_id: data.termId,
        type: data.type,
        title: data.title ?? null,
        total_items: data.totalItems,
        release_date: data.releaseDate ?? null,
        end_date: data.endDate ?? null,
        week_number: data.weekNumber ?? null,
        is_published: false,
        grading_mode: (data.gradingMode as any) ?? 'system',
        manual_max_score: data.manualMaxScore ?? null,
        show_breakdown: data.showBreakdown ?? false,
      },
    });
  }

  async findAll(
    classId: string,
    orgId: string,
    filters: { termId?: string; type?: string; weekNumber?: number },
  ) {
    return this.db.assessment.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
        ...(filters.termId ? { term_id: filters.termId } : {}),
        ...(filters.type ? { type: filters.type } : {}),
        ...(filters.weekNumber ? { week_number: filters.weekNumber } : {}),
      },
      orderBy: { created_at: 'asc' },
    });
  }

  async findById(id: string, orgId: string) {
    return this.db.assessment.findFirst({ where: { id, org_id: orgId } });
  }

  async update(
    id: string,
    data: {
      releaseDate?: Date | null;
      endDate?: Date | null;
      type?: string;
      title?: string;
      isPublished?: boolean;
      showBreakdown?: boolean;
      gradingMode?: string;
      manualMaxScore?: number | null;
      weekNumber?: number | null;
    },
  ) {
    return this.db.assessment.update({
      where: { id },
      data: {
        ...(data.releaseDate !== undefined
          ? { release_date: data.releaseDate }
          : {}),
        ...(data.endDate !== undefined ? { end_date: data.endDate } : {}),
        ...(data.type !== undefined ? { type: data.type } : {}),
        ...(data.title !== undefined ? { title: data.title } : {}),
        ...(data.isPublished !== undefined
          ? { is_published: data.isPublished }
          : {}),
        ...(data.showBreakdown !== undefined
          ? { show_breakdown: data.showBreakdown }
          : {}),
        ...(data.gradingMode !== undefined
          ? { grading_mode: data.gradingMode as any }
          : {}),
        ...(data.manualMaxScore !== undefined
          ? { manual_max_score: data.manualMaxScore }
          : {}),
        ...(data.weekNumber !== undefined
          ? { week_number: data.weekNumber }
          : {}),
      },
    });
  }

  async softDelete(id: string) {
    return this.db.assessment.delete({ where: { id } });
  }

  // ───────── QUESTIONS ─────────

  async createQuestions(
    questions: Array<{
      orgId: string;
      assessmentId: string;
      type: string;
      questionText: string;
      correctAnswer?: string;
      choices?: string[];
      order: number;
      isManual?: boolean;
      sectionType?: string;
    }>,
  ) {
    return this.db.question.createMany({
      data: questions.map((q) => ({
        org_id: q.orgId,
        assessment_id: q.assessmentId,
        type: q.type,
        question_text: q.questionText,
        correct_answer: q.correctAnswer ?? null,
        choices: q.choices ? q.choices : undefined,
        order: q.order,
        is_manual: q.isManual ?? false,
        section_type: q.sectionType ?? null,
      })),
    });
  }

  async findQuestions(assessmentId: string) {
    return this.db.question.findMany({
      where: { assessment_id: assessmentId },
      orderBy: { order: 'asc' },
    });
  }

  async findQuestionById(id: string) {
    return this.db.question.findFirst({ where: { id } });
  }

  async updateQuestion(
    id: string,
    data: { questionText?: string; correctAnswer?: string },
  ) {
    return this.db.question.update({
      where: { id },
      data: {
        ...(data.questionText !== undefined
          ? { question_text: data.questionText }
          : {}),
        ...(data.correctAnswer !== undefined
          ? { correct_answer: data.correctAnswer }
          : {}),
      },
    });
  }

  // ───────── SUBMISSIONS ─────────

  async findSubmissions(assessmentId: string, orgId: string) {
    return this.db.submission.findMany({
      where: { assessment_id: assessmentId, org_id: orgId },
    });
  }

  async findSubmissionById(id: string) {
    return this.db.submission.findFirst({ where: { id } });
  }

  async findSubmissionByStudent(assessmentId: string, studentId: string) {
    return this.db.submission.findFirst({
      where: { assessment_id: assessmentId, student_id: studentId },
    });
  }

  async upsertSubmission(data: {
    orgId: string;
    assessmentId: string;
    studentId: string;
    status: string;
    score?: number;
    manualScore?: number;
    submittedAt?: Date;
    manualSectionScore?: number;
    systemSectionScore?: number;
    isMissed?: boolean;
    isExempted?: boolean;
  }) {
    const existing = await this.findSubmissionByStudent(
      data.assessmentId,
      data.studentId,
    );

    if (existing) {
      return this.db.submission.update({
        where: { id: existing.id },
        data: {
          status: data.status as any,
          ...(data.score !== undefined ? { score: data.score } : {}),
          ...(data.manualScore !== undefined
            ? { manual_score: data.manualScore }
            : {}),
          ...(data.manualSectionScore !== undefined
            ? { manual_section_score: data.manualSectionScore }
            : {}),
          ...(data.systemSectionScore !== undefined
            ? { system_section_score: data.systemSectionScore }
            : {}),
          ...(data.isMissed !== undefined ? { is_missed: data.isMissed } : {}),
          ...(data.isExempted !== undefined
            ? { is_exempted: data.isExempted }
            : {}),
          ...(data.submittedAt !== undefined
            ? { submitted_at: data.submittedAt }
            : {}),
        },
      });
    }

    return this.db.submission.create({
      data: {
        org_id: data.orgId,
        assessment_id: data.assessmentId,
        student_id: data.studentId,
        status: data.status as any,
        score: data.score ?? null,
        manual_score: data.manualScore ?? null,
        manual_section_score: data.manualSectionScore ?? null,
        system_section_score: data.systemSectionScore ?? null,
        is_missed: data.isMissed ?? false,
        is_exempted: data.isExempted ?? false,
        submitted_at: data.submittedAt ?? null,
      },
    });
  }

  async updateSubmissionStatus(
    id: string,
    data: { status: string; manualScore?: number; score?: number },
  ) {
    const isMissed = data.status === 'missed';
    const isExempted = data.status === 'exempted';
    return this.db.submission.update({
      where: { id },
      data: {
        status: data.status as any,
        is_missed: isMissed,
        is_exempted: isExempted,
        ...(data.manualScore !== undefined
          ? { manual_score: data.manualScore }
          : {}),
        ...(data.score !== undefined ? { score: data.score } : {}),
      },
    });
  }

  async gradeEssay(id: string, score: number, manualSectionScore?: number) {
    return this.db.submission.update({
      where: { id },
      data: {
        manual_score: score,
        ...(manualSectionScore !== undefined
          ? { manual_section_score: manualSectionScore }
          : {}),
      },
    });
  }

  async publishAllByClass(classId: string, orgId: string) {
    return this.db.assessment.updateMany({
      where: { class_id: classId, org_id: orgId },
      data: { is_published: true },
    });
  }
}

// @/modules/assessment/core/assessment-core.service.ts
import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { AssessmentRepository } from './assessment-core.repository';

@Injectable()
export class AssessmentCoreService {
  constructor(private readonly repo: AssessmentRepository) {}

  // ───────── FETCHERS ─────────

  async findAssessmentOrThrow(assessmentId: string, orgId: string) {
    const assessment = await this.repo.findById(assessmentId, orgId);
    if (!assessment) throw new NotFoundException('Assessment not found.');
    return assessment;
  }

  async findAssessmentsByClass(
    classId: string,
    orgId: string,
    filters: { termId?: string; type?: string } = {},
  ) {
    return this.repo.findAll(classId, orgId, filters);
  }

  async getQuestions(assessmentId: string) {
    return this.repo.findQuestions(assessmentId);
  }

  async getSubmissionByStudent(assessmentId: string, studentId: string) {
    return this.repo.findSubmissionByStudent(assessmentId, studentId);
  }

  // ───────── BUSINESS RULES ─────────

  isReleased(assessment: any): boolean {
    if (!assessment.release_date) return true;
    return new Date() >= new Date(assessment.release_date);
  }

  isEditable(assessment: any): boolean {
    if (!assessment.release_date) return true;
    return new Date() < new Date(assessment.release_date);
  }

  isPastEndDate(assessment: any): boolean {
    if (!assessment.end_date) return false;
    return new Date() > new Date(assessment.end_date);
  }

  canViewScore(assessment: any, isGradeLocked: boolean): boolean {
    return assessment.is_published || isGradeLocked;
  }

  assertBelongsToClass(assessment: any, classId: string) {
    if (assessment.class_id !== classId)
      throw new ForbiddenException('Invalid class access.');
  }

  // ───────── HYBRID GRADING HELPERS ─────────

  isHybridAssessment(assessment: any): boolean {
    return assessment.grading_mode === 'hybrid';
  }

  isManualAssessment(assessment: any): boolean {
    return assessment.grading_mode === 'manual';
  }

  isSystemAssessment(assessment: any): boolean {
    return assessment.grading_mode === 'system' || !assessment.grading_mode;
  }

  calculateSystemSectionScore(submission: any): number {
    return submission.system_section_score ?? 0;
  }

  calculateManualSectionScore(submission: any): number {
    return submission.manual_section_score ?? 0;
  }

  buildResultWithSections(submission: any, assessment: any): any {
    const systemScore = this.calculateSystemSectionScore(submission);
    const manualScore = this.calculateManualSectionScore(submission);
    return {
      systemScore,
      manualScore,
      totalScore: systemScore + manualScore,
      manualMaxScore: assessment.manual_max_score ?? null,
    };
  }

  // ───────── BUILDERS ─────────

  buildAssessmentListItem(assessment: any, submission: any | null) {
    return {
      id: assessment.id,
      title: assessment.title,
      type: assessment.type,
      totalItems: assessment.total_items,
      releaseDate: assessment.release_date,
      endDate: assessment.end_date,
      isPublished: assessment.is_published,
      gradingMode: assessment.grading_mode ?? 'system',
      showBreakdown: assessment.show_breakdown ?? false,
      submissionStatus: submission?.status ?? 'not_started',
      submittedAt: submission?.submitted_at ?? null,
      termId: assessment.term_id,
      weekNumber: assessment.week_number,
    };
  }

  private mapQuestion(raw: any) {
    return {
      id: raw.id,
      questionText: raw.question_text,
      type: raw.type,
      choices: raw.choices,
      order: raw.order,
      isManual: raw.is_manual ?? false,
      sectionType: raw.section_type ?? null,
    };
  }

  private mapQuestionWithAnswer(raw: any, studentAnswer: string | null) {
    return {
      id: raw.id,
      questionText: raw.question_text,
      type: raw.type,
      correctAnswer: raw.correct_answer,
      choices: raw.choices,
      order: raw.order,
      isManual: raw.is_manual ?? false,
      sectionType: raw.section_type ?? null,
      studentAnswer,
    };
  }

  buildAssessmentDetail(
    assessment: any,
    questions: any[] | null,
    locked: boolean,
  ) {
    return {
      id: assessment.id,
      type: assessment.type,
      totalItems: assessment.total_items,
      releaseDate: assessment.release_date,
      endDate: assessment.end_date,
      isPublished: assessment.is_published,
      gradingMode: assessment.grading_mode ?? 'system',
      showBreakdown: assessment.show_breakdown ?? false,
      manualMaxScore: assessment.manual_max_score ?? null,
      locked,
      ...(locked
        ? {}
        : { questions: questions?.map((q) => this.mapQuestion(q)) }),
    };
  }

  buildResult(
    submission: any,
    assessment: any,
    isGradeLocked: boolean,
    questions: any[] = [],
    answers: any[] = [],
  ) {
    const canView = this.canViewScore(assessment, isGradeLocked);
    const answerMap = new Map(answers.map((a: any) => [a.question_id, a]));

    const review = canView
      ? questions.map((q: any) => {
          const ans = answerMap.get(q.id);
          return {
            id: q.id,
            questionText: q.question_text,
            type: q.type,
            correctAnswer: q.correct_answer,
            choices: q.choices,
            order: q.order,
            isManual: q.is_manual ?? false,
            sectionType: q.section_type ?? null,
            studentAnswer: ans?.answer ?? null,
            isCorrect: ans?.is_correct ?? null,
          };
        })
      : undefined;

    const score = canView
      ? (submission.manual_score ?? submission.score)
      : null;

    const result: any = {
      status: submission.status,
      submittedAt: submission.submitted_at,
      score,
      isPublished: assessment.is_published,
      totalItems: assessment.total_items,
      gradingMode: assessment.grading_mode ?? 'system',
      showBreakdown: assessment.show_breakdown ?? false,
      questions: review,
    };

    if (this.isHybridAssessment(assessment)) {
      const sections = this.buildResultWithSections(submission, assessment);
      result.systemScore = sections.systemScore;
      result.manualScore = sections.manualScore;
      result.manualMaxScore = sections.manualMaxScore;
    }

    return result;
  }

  handleMissedSubmission(submission: any): any {
    return { ...submission, score: 0, is_missed: true };
  }

  handleExemptedSubmission(submission: any): any {
    return { ...submission, score: 0, is_exempted: true };
  }
}

