import { Type } from 'class-transformer';

// ── Grading mode ──────────────────────────────────────────────────────────────

export enum GradingMode {
  SYSTEM = 'system',
  MANUAL = 'manual',
  HYBRID = 'hybrid',
}

// ── Question type options ─────────────────────────────────────────────────────

export const QUESTION_TYPES = [
  'multiple_choice',
  'true_or_false',
  'identification',
  'enumeration',
  'essay',
  'manual',
] as const;

export type QuestionType = (typeof QUESTION_TYPES)[number];

export const ASSESSMENT_TYPES = [
  'written_work',
  'performance_task',
  'quarterly_assessment',
  'exam',
  'quiz',
  'assignment',
  'project',
  'recitation',
  'participation',
  'behavior',
  'attendance',
  'activity',
  'custom',
  'other',
] as const;

// ── Item range for generation config ─────────────────────────────────────────

export class ItemRangeDto {
  @IsInt()
  @Min(1)
  from: number;

  @IsInt()
  @Min(1)
  to: number;

  @IsIn(QUESTION_TYPES)
  questionType: QuestionType;

  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  conceptSections: string[]; // section names from concept build — empty for manual sections

  @IsOptional()
  @IsString()
  manualQuestionText?: string; // educator-written question text for manual sections

  @IsOptional()
  @IsInt()
  @Min(0)
  manualMaxScore?: number; // max score for this manual section (1 question = N points)
}

