  lessonId?: string;

  @IsUUID()
  termId: string;

  @IsString()
  type: string;

  @IsOptional()
  @IsString()
  title?: string;

  @IsInt()
  @Min(1)
  totalItems: number;

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => ItemRangeDto)
  ranges?: ItemRangeDto[];

  @IsOptional()
  @IsEnum(GradingMode)
  gradingMode?: GradingMode;

  @IsOptional()
  @IsInt()
  @Min(0)
  manualMaxScore?: number;

  @IsOptional()
  @IsBoolean()
  showBreakdown?: boolean;

  @IsOptional()
  @IsString()
  manualInstructions?: string;

  @IsOptional()
  @IsDateString()
  releaseDate?: string;

  @IsOptional()
  @IsDateString()
  endDate?: string;

