import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { AssessmentCoreService } from '../core/assessment-core.service';
import { AssessmentRepository } from '../core/assessment-core.repository';
import { ClassRepository } from '@/modules/class/class.repository';
import { AuditLogService } from '@/modules/audit-log/audit-log.service';
import { AttendanceService } from '@/modules/attendance/attendance.service';
import { GradeEducatorService } from '@/modules/grade/educator/grade-educator.service';
import { DatabaseService } from '@/core/database/database.provider';
import { AssessmentCreationHelper } from './helpers/assessment-creation.helper';
import { AssessmentSubmissionHelper } from './helpers/assessment-submission.helper';
import { AssessmentGenerationHelper } from './assessment-generation.helper';
import {
  CreateAssessmentDto,
  UpdateAssessmentDto,
  UpdateQuestionDto,
  QueryAssessmentDto,
  PublishScoresDto,
  GradeEssayDto,
  UpdateSubmissionStatusDto,
  AssignStudentsDto,
  ReopenAssessmentDto,
  SetGradeVisibilityDto,
  GradingMode,
} from '../dto/assessment.dto';
import { Logger } from '@nestjs/common';

@Injectable()
export class AssessmentEducatorService {
  private readonly logger = new Logger(AssessmentEducatorService.name);

  constructor(
    private readonly repo: AssessmentRepository,
    private readonly core: AssessmentCoreService,
    private readonly db: DatabaseService,
    private readonly classRepo: ClassRepository,
    private readonly auditLog: AuditLogService,
    private readonly attendanceService: AttendanceService,
    private readonly gradeService: GradeEducatorService,
    private readonly creation: AssessmentCreationHelper,
    private readonly submission: AssessmentSubmissionHelper,
    private readonly generation: AssessmentGenerationHelper,
  ) {}

  // ───────── GUARDS ─────────

  private async assertEducatorOwnsClass(
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId)
      throw new ForbiddenException('You do not own this class.');
    return cls;
  }

  private async assertAssessmentEditable(assessmentId: string, orgId: string) {
    const assessment = await this.repo.findById(assessmentId, orgId);
    if (!assessment) throw new NotFoundException('Assessment not found.');
    if (
      assessment.release_date &&
      new Date() >= new Date(assessment.release_date)
    ) {
      throw new ForbiddenException(
        'Assessment has been released — questions are locked.',
      );
    }
    return assessment;
  }

  getGenerationStatus(assessmentId: string) {
    return this.generation.getGenerationStatus(assessmentId);
  }

  // ───────── CREATE ─────────

  async create(
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    await this.creation.assertTypeMatchesScheme(classId, orgId, dto.type);

    const effectiveGradingMode = this.creation.resolveGradingMode(dto);
    const isManual = effectiveGradingMode === GradingMode.MANUAL;

    if (!isManual) await this.creation.validateSystemDto(dto);

    const assessment = await this.creation.createAssessmentRecord(
      orgId,
      classId,
      dto,
      effectiveGradingMode,
    );

    if (isManual) {
      await this.creation.createManualQuestions(orgId, assessment.id, dto);
      const questions = await this.core.getQuestions(assessment.id);
      (assessment as any).questions = questions;
    } else {
      await this.creation.createManualSectionQuestions(
        orgId,
        assessment.id,
        dto,
      );
      const aiRanges = (dto.ranges ?? []).filter(
        (r) => r.questionType !== 'manual',
      );
      if (aiRanges.length > 0) {
        await this.generation.startGeneration(
          assessment.id,
          orgId,
          educatorId,
          { ...dto, ranges: aiRanges },
        );
      }
    }

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_created',
      entityType: 'class',
      entityId: classId,
      metadata: {
        assessmentId: assessment.id,
        type: dto.type,
        gradingMode: effectiveGradingMode,
      },
    });
    return assessment;
  }

  // ───────── READ ─────────

  async findAll(
    classId: string,
    orgId: string,
    educatorId: string,
    query: QueryAssessmentDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const assessments = await this.repo.findAll(classId, orgId, {
      termId: query.termId,
      type: query.type,
      weekNumber: query.weekNumber,
    });
    if (!assessments.length) return [];

    const ids = assessments.map((a) => a.id);

    const [submissionCounts, submittedSubs, essayQuestions, activeReopens] =
      await Promise.all([
        this.db.submission.groupBy({
          by: ['assessment_id', 'status'],
          where: { assessment_id: { in: ids } },
          _count: { id: true },
        }),
        this.db.submission.findMany({
          where: { assessment_id: { in: ids }, status: 'submitted' },
          select: { id: true, assessment_id: true },
        }),
        this.db.question.findMany({
          where: { assessment_id: { in: ids }, type: 'essay' },
          select: { id: true, assessment_id: true },
        }),
        this.db.submission.findMany({
          where: {
            assessment_id: { in: ids },
            reopened_until: { gt: new Date() },
          },
          select: { assessment_id: true, reopened_until: true },
          orderBy: { reopened_until: 'desc' },
        }),
      ]);

    const subToAssessment = new Map(
      submittedSubs.map((s) => [s.id, s.assessment_id]),
    );
    const essayQIds = essayQuestions.map((q) => q.id);

    const pendingEssaySubIds =
      submittedSubs.length && essayQIds.length
        ? await this.db.submissionAnswer.groupBy({
            by: ['submission_id'],
            where: {
              submission_id: { in: submittedSubs.map((s) => s.id) },
              question_id: { in: essayQIds },
              is_correct: null,
            },
            _count: { id: true },
          })
        : [];

    const pendingByAssessment = new Map<string, number>();
    for (const r of pendingEssaySubIds) {
      const assId = subToAssessment.get(r.submission_id);
      if (assId)
        pendingByAssessment.set(
          assId,
          (pendingByAssessment.get(assId) ?? 0) + 1,
        );
    }

    const submittedMap = new Map<string, number>();
    for (const s of submissionCounts) {
      if (s.status === 'submitted')
        submittedMap.set(s.assessment_id, s._count.id);
    }

    const reopenMap = new Map<string, Date>();
    for (const r of activeReopens) {
      if (!reopenMap.has(r.assessment_id))
        reopenMap.set(r.assessment_id, r.reopened_until!);
    }

    return assessments.map((a) => ({
      ...a,
      submittedCount: submittedMap.get(a.id) ?? 0,
      pendingEssayCount: pendingByAssessment.get(a.id) ?? 0,
      reopened_until: reopenMap.get(a.id) ?? null,
    }));
  }

  async findOne(id: string, orgId: string, educatorId: string) {
    const assessment = await this.core.findAssessmentOrThrow(id, orgId);
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const [questions, activeReopen] = await Promise.all([
      this.core.getQuestions(id),
      this.db.submission.findFirst({
        where: { assessment_id: id, reopened_until: { gt: new Date() } },
        select: { reopened_until: true },
        orderBy: { reopened_until: 'desc' },
      }),
    ]);
    return {
      ...assessment,
      questions,
      generationStatus:
        this.generation.getGenerationStatus(id)?.status ?? 'completed',
      reopenedUntil: activeReopen?.reopened_until ?? null,
    };
  }

  // ───────── UPDATE / DELETE ─────────

  async update(
    id: string,
    orgId: string,
    educatorId: string,
    dto: UpdateAssessmentDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(id, orgId);
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const updated = await this.repo.update(id, {
      releaseDate: dto.releaseDate ? new Date(dto.releaseDate) : undefined,
      endDate: dto.endDate ? new Date(dto.endDate) : undefined,
      type: dto.type,
      showBreakdown: dto.showBreakdown,
      gradingMode: dto.gradingMode,
      manualMaxScore: dto.manualMaxScore,
      weekNumber: dto.weekNumber,
    });
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_edited',
      entityType: 'class',
      entityId: assessment.class_id,
      metadata: { assessmentId: id },
    });
    return updated;
  }

  async delete(id: string, orgId: string, educatorId: string) {
    const assessment = await this.core.findAssessmentOrThrow(id, orgId);
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    await this.repo.softDelete(id);
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_deleted',
      entityType: 'class',
      entityId: assessment.class_id,
      metadata: { assessmentId: id },
    });
    if (assessment.term_id) {
      this.gradeService
        .computeGrades(
          assessment.class_id,
          assessment.term_id,
          orgId,
          educatorId,
        )
        .catch((err: Error) =>
          this.logger.error(
            `[Grade] Recompute failed after delete ${id}: ${err.message}`,
          ),
        );
    }
    return { success: true };
  }

  async updateQuestion(
    assessmentId: string,
    questionId: string,
    orgId: string,
    educatorId: string,
    dto: UpdateQuestionDto,
  ) {
    const assessment = await this.assertAssessmentEditable(assessmentId, orgId);
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const question = await this.repo.findQuestionById(questionId);
    if (!question || question.assessment_id !== assessmentId)
      throw new NotFoundException('Question not found.');
    return this.repo.updateQuestion(questionId, {
      questionText: dto.questionText,
      correctAnswer: dto.correctAnswer,
    });
  }

  // ───────── SUBMISSIONS ─────────

  async getSubmissions(
    assessmentId: string,
    orgId: string,
    educatorId: string,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    return this.submission.getSubmissions(assessment, orgId);
  }

  async updateSubmissionStatus(
    assessmentId: string,
    submissionId: string,
    orgId: string,
    educatorId: string,
    dto: UpdateSubmissionStatusDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const updated = await this.submission.updateSubmissionStatus(
      assessment,
      submissionId,
      orgId,
      dto,
    );
    if (assessment.term_id) {
      this.gradeService
        .computeGrades(
          assessment.class_id,
          assessment.term_id,
          orgId,
          educatorId,
        )
        .catch((err: Error) =>
          this.logger.error(
            `[Grade] Recompute failed after status change: ${err.message}`,
          ),
        );
    }
    return updated;
  }

  async gradeEssay(
    assessmentId: string,
    submissionId: string,
    orgId: string,
    educatorId: string,
    dto: GradeEssayDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    return this.submission.gradeEssay(assessment, submissionId, dto);
  }

  async assignStudents(
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: AssignStudentsDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const result = await this.submission.assignStudents(assessment, orgId, dto);
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'students_assigned_to_assessment',
      entityType: 'assessment',
      entityId: assessmentId,
      metadata: { assessmentId, studentIds: dto.studentIds },
    });
    return result;
  }

  async reopen(
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: ReopenAssessmentDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    const result = await this.submission.reopen(assessment, orgId, dto);
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_reopened',
      entityType: 'assessment',
      entityId: assessmentId,
      metadata: {
        assessmentId,
        studentIds: dto.studentIds,
        reopenedUntil: dto.reopenedUntil,
      },
    });
    return result;
  }

  // ───────── PUBLISH ─────────

  async publishScores(
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: PublishScoresDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    await this.repo.update(assessmentId, { isPublished: true });
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'score_published',
      entityType: 'class',
      entityId: assessment.class_id,
      metadata: { assessmentId, studentIds: dto.studentIds ?? 'all' },
    });
    await this.gradeService.registerAssessmentForAllStudents(
      assessmentId,
      assessment.class_id,
      orgId,
    );
    if (assessment.term_id) {
      this.gradeService
        .computeGrades(
          assessment.class_id,
          assessment.term_id,
          orgId,
          educatorId,
        )
        .catch((err: Error) =>
          this.logger.error(
            `[Grade] Recompute failed after publish: ${err.message}`,
          ),
        );
    }
    return { success: true };
  }

  async unpublishScores(
    assessmentId: string,
    orgId: string,
    educatorId: string,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    await this.repo.update(assessmentId, { isPublished: false });
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'score_unpublished',
      entityType: 'class',
      entityId: assessment.class_id,
      metadata: { assessmentId },
    });
    if (assessment.term_id) {
      this.gradeService
        .computeGrades(
          assessment.class_id,
          assessment.term_id,
          orgId,
          educatorId,
        )
        .catch((err: Error) =>
          this.logger.error(
            `[Grade] Recompute failed after unpublish: ${err.message}`,
          ),
        );
    }
    return { success: true };
  }

  async setGradeVisibility(
    classId: string,
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: SetGradeVisibilityDto,
  ) {
    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    await this.assertEducatorOwnsClass(assessment.class_id, orgId, educatorId);
    return this.repo.update(assessmentId, { showBreakdown: dto.showBreakdown });
  }

  // ───────── PREVIEW ─────────

  async generatePreview(
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    await this.creation.assertTypeMatchesScheme(classId, orgId, dto.type);
    const previewId = await this.generation.startPreview(
      classId,
      orgId,
      educatorId,
      dto,
    );
    return { previewId };
  }

  getPreview(previewId: string) {
    return this.generation.getPreview(previewId);
  }

  async confirmPreview(
    previewId: string,
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const result = this.generation.getPreviewResult(previewId);
    if (!result)
      throw new NotFoundException(
        'Preview not found or expired. Please generate again.',
      );
    const { questions: generated, dto } = result;
    if (!generated?.length)
      throw new NotFoundException('No questions in preview.');
    if (!dto.lessonId) throw new NotFoundException('lessonId is required.');

    const assessment = await this.creation.createAssessmentRecord(
      orgId,
      classId,
      dto,
      dto.gradingMode ?? GradingMode.SYSTEM,
    );
    await this.repo.createQuestions(
      generated.map((q, idx) => ({
        orgId,
        assessmentId: assessment.id,
        type: q.type,
        questionText: q.question,
        correctAnswer:
          q.answer ??
          q.correct_answer ??
          (q.type !== 'essay' && q.type !== 'manual'
            ? `Answer ${q.number}`
            : undefined),
        choices: q.choices?.length ? q.choices : undefined,
        order: q.number ?? idx + 1,
        isManual: q.type === 'manual',
      })),
    );

    this.generation.clearPreview(previewId);
    this.logger.log(
      `[Assessment] ${generated.length} questions confirmed for ${assessment.id}`,
    );
    return { ...assessment, questions: generated };
  }

  async cancelPreview(previewId: string) {
    this.generation.cancelPreview(previewId);
  }

  async onSubmissionFinished(data: {
    orgId: string;
    classId: string;
    studentId: string;
    submittedAt: Date;
  }) {
    this.attendanceService.markPresentFromSubmission(data).catch((err) => {
      this.logger.error(
        `[AttendanceService] Failed to auto-mark present for student ${data.studentId}: ${err}`,
      );
    });
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { AssessmentRepository } from '../core/assessment-core.repository';
import { LessonRepository } from '@/modules/lesson/lesson.repository';
import {
  AiService,
  QuestionBlueprint,
  GeneratedQuestion,
  GenerationProgress,
  ConceptBuild,
} from '@/core/ai/ai.service';
import { NotificationService } from '@/modules/notification/notification.service';
import { AuditLogService } from '@/modules/audit-log/audit-log.service';
import { CreateAssessmentDto } from '../dto/assessment.dto';

@Injectable()
export class AssessmentGenerationHelper {
  private readonly logger = new Logger(AssessmentGenerationHelper.name);

  readonly generationStatuses = new Map<string, GenerationProgress>();
  readonly previewResults = new Map<
    string,
    {
      questions: GeneratedQuestion[];
      orgId: string;
      educatorId: string;
      dto: CreateAssessmentDto;
      classId: string;
    }
  >();
  private readonly cancellationFlags = new Map<string, boolean>();

  constructor(
    private readonly repo: AssessmentRepository,
    private readonly lessonRepo: LessonRepository,
    private readonly aiService: AiService,
    private readonly notificationService: NotificationService,
    private readonly auditLog: AuditLogService,
  ) {}

  getGenerationStatus(assessmentId: string): GenerationProgress | null {
    return this.generationStatuses.get(assessmentId) ?? null;
  }

  async startGeneration(
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ) {
    this.generationStatuses.set(assessmentId, {
      status: 'generating',
      message: 'Starting generation...',
      chunksTotal: 0,
      chunksDone: 0,
    });
    this.generateQuestions(assessmentId, orgId, educatorId, dto);
  }

  async startPreview(
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ): Promise<string> {
    if (!dto.lessonId) throw new BadRequestException('lessonId is required.');
    const concept = await this.lessonRepo.findConcept(dto.lessonId);
    if (!concept) throw new BadRequestException('No concept build found.');
    if (!dto.ranges?.length)
      throw new BadRequestException('At least one range is required.');
    const rangeTotal = dto.ranges.reduce((sum, r) => {
      if (r.questionType === 'manual' && r.manualMaxScore != null)
        return sum + r.manualMaxScore;
      return sum + (r.to - r.from + 1);
    }, 0);
    if (rangeTotal !== dto.totalItems)
      throw new BadRequestException('Range total mismatch.');

    const previewId = crypto.randomUUID();
    this.generationStatuses.set(previewId, {
      status: 'generating',
      message: 'Starting...',
      chunksTotal: 0,
      chunksDone: 0,
    });
    this.generatePreviewQuestions(previewId, classId, orgId, educatorId, dto);
    return previewId;
  }

  getPreview(previewId: string) {
    const gen = this.generationStatuses.get(previewId);
    if (!gen)
      return {
        status: 'failed' as const,
        message: 'Preview not found or expired',
        chunksTotal: 0,
        chunksDone: 0,
      };
    const result = this.previewResults.get(previewId);
    return {
      status: gen.status,
      message: gen.message,
      chunksTotal: gen.chunksTotal,
      chunksDone: gen.chunksDone,
      questions: result?.questions,
    };
  }

  getPreviewResult(previewId: string) {
    return this.previewResults.get(previewId) ?? null;
  }

  cancelPreview(previewId: string) {
    this.cancellationFlags.set(previewId, true);
    this.generationStatuses.delete(previewId);
    this.previewResults.delete(previewId);
  }

  clearPreview(previewId: string) {
    this.generationStatuses.delete(previewId);
    this.previewResults.delete(previewId);
  }

  private setStatus(id: string, update: Partial<GenerationProgress>) {
    const current = this.generationStatuses.get(id) ?? {
      status: 'generating',
      message: '',
      chunksTotal: 0,
      chunksDone: 0,
    };
    this.generationStatuses.set(id, { ...current, ...update });
  }

  private async generateQuestions(
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ) {
    try {
      if (!dto.lessonId) throw new BadRequestException('lessonId is required.');
      const lesson = await this.lessonRepo.findById(dto.lessonId, orgId);
      if (!lesson) throw new NotFoundException('Lesson not found');
      const conceptRecord = await this.lessonRepo.findConcept(dto.lessonId);

      const blueprints = (dto.ranges ?? []).map((r) => ({
        type: r.questionType as QuestionBlueprint['type'],
        sections: r.conceptSections,
        numbers: `${r.from}-${r.to}`,
        count: r.to - r.from + 1,
      }));

      const generated = await this.aiService.generateQuestions(
        lesson.detail ?? '',
        blueprints,
        (progress) => this.setStatus(assessmentId, progress),
        undefined,
        (conceptRecord?.content as unknown as ConceptBuild) ?? undefined,
      );

      if (!generated?.length) throw new Error('AI returned no questions.');

      await this.repo.createQuestions(
        generated.map((q, idx) => ({
          orgId,
          assessmentId,
          type: q.type,
          questionText: q.question,
          correctAnswer:
            q.answer ??
            q.correct_answer ??
            (q.type !== 'essay' ? `Answer ${q.number}` : undefined),
          choices: q.choices?.length ? q.choices : undefined,
          order: q.number ?? idx + 1,
        })),
      );

      this.logger.log(
        `[Assessment] ${generated.length} questions generated for ${assessmentId}`,
      );
      this.setStatus(assessmentId, {
        status: 'completed',
        message: `Generated ${generated.length} questions`,
      });

      await this.notificationService.createNotification({
        orgId,
        accountId: educatorId,
        type: 'assessment_generation_completed',
        payload: { assessmentId },
      });
      await this.auditLog.logActivityEvent({
        orgId,
        actorId: educatorId,
        action: 'assessment_questions_generated',
        entityType: 'assessment',
        entityId: assessmentId,
        metadata: { assessmentId, questionsGenerated: generated.length },
      });
    } catch (err) {
      this.logger.error(`[Assessment] AI generation failed: ${err}`);
      this.setStatus(assessmentId, {
        status: 'failed',
        message: `Generation failed: ${err}`,
        error: String(err),
      });
      await this.repo.softDelete(assessmentId).catch(() => {});
    }
  }

  private async generatePreviewQuestions(
    previewId: string,
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateAssessmentDto,
  ) {
    try {
      if (this.cancellationFlags.get(previewId)) return;
      if (!dto.lessonId) throw new BadRequestException('lessonId is required.');
      const lesson = await this.lessonRepo.findById(dto.lessonId, orgId);
      if (!lesson) throw new NotFoundException('Lesson not found');

      const manualRanges = (dto.ranges ?? []).filter(
        (r) => r.questionType === 'manual',
      );
      const aiRanges = (dto.ranges ?? []).filter(
        (r) => r.questionType !== 'manual',
      );

      const manualQuestions: GeneratedQuestion[] = manualRanges
        .filter((r) => r.manualQuestionText?.trim())
        .map((r, i) => ({
          number: i + 1,
          type: 'manual' as const,
          section: '',
          question: r.manualQuestionText!.trim(),
        }));

      let aiQuestions: GeneratedQuestion[] = [];
      if (aiRanges.length > 0) {
        const ctrl = new AbortController();
        const cancelWatch = setInterval(() => {
          if (this.cancellationFlags.get(previewId)) ctrl.abort();
        }, 500);
        try {
          const generated = await this.aiService.generateQuestions(
            lesson.detail ?? '',
            aiRanges.map((r) => ({
              type: r.questionType as QuestionBlueprint['type'],
              sections: r.conceptSections ?? [],
              numbers: `${r.from}-${r.to}`,
              count: r.to - r.from + 1,
            })),
            (progress) => this.setStatus(previewId, progress),
            ctrl.signal,
          );
          if (this.cancellationFlags.get(previewId)) return;
          if (!generated?.length) throw new Error('AI returned no questions');
          aiQuestions = generated;
        } finally {
          clearInterval(cancelWatch);
        }
      }

      const allQuestions = [...aiQuestions, ...manualQuestions];
      if (!allQuestions.length) throw new Error('No questions to preview');

      this.previewResults.set(previewId, {
        questions: allQuestions,
        orgId,
        educatorId,
        dto,
        classId,
      });
      this.setStatus(previewId, {
        status: 'completed',
        message: `Generated ${allQuestions.length} questions — review and confirm`,
      });
      this.logger.log(
        `[Preview] ${allQuestions.length} questions ready (${previewId})`,
      );
    } catch (err) {
      const isCancelled =
        String(err).includes('cancelled') || String(err).includes('abort');
      if (isCancelled) {
        this.generationStatuses.delete(previewId);
        this.previewResults.delete(previewId);
      } else {
        this.logger.error(`[Preview] Generation failed: ${err}`);
        this.setStatus(previewId, {
          status: 'failed',
          message: `Generation failed: ${err}`,
          error: String(err),
        });
      }
    } finally {
      this.cancellationFlags.delete(previewId);
    }
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { AssessmentRepository } from '../../core/assessment-core.repository';
import { LessonRepository } from '@/modules/lesson/lesson.repository';
import { DatabaseService } from '@/core/database/database.provider';
import { CreateAssessmentDto, GradingMode } from '../../dto/assessment.dto';

@Injectable()
export class AssessmentCreationHelper {
  constructor(
    private readonly repo: AssessmentRepository,
    private readonly lessonRepo: LessonRepository,
    private readonly db: DatabaseService,
  ) {}

  async assertTypeMatchesScheme(classId: string, orgId: string, type: string) {
    const scheme = await this.db.gradingScheme.findFirst({
      where: { class_id: classId, org_id: orgId },
      include: { components: { select: { type: true } } },
    });
    if (!scheme) return;
    const validTypes = scheme.components.map((c) => c.type);
    if (!validTypes.includes(type)) {
      throw new BadRequestException(
        `Assessment type "${type}" is not in the class's grading scheme. Allowed: ${validTypes.join(', ')}`,
      );
    }
  }

  resolveGradingMode(dto: CreateAssessmentDto): GradingMode {
    const base = dto.gradingMode ?? GradingMode.SYSTEM;
    const hasManualSections =
      dto.ranges?.some((r) => r.questionType === 'manual') ?? false;
    if (base === GradingMode.SYSTEM && hasManualSections)
      return GradingMode.HYBRID;
    return base;
  }

  async validateSystemDto(dto: CreateAssessmentDto) {
    if (!dto.lessonId)
      throw new BadRequestException(
        'lessonId is required for system/hybrid assessments.',
      );
    const concept = await this.lessonRepo.findConcept(dto.lessonId);
    if (!concept)
      throw new BadRequestException(
        'No concept build found for this lesson. Run concept extraction first.',
      );
    if (!dto.ranges?.length)
      throw new BadRequestException(
        'At least one range is required for system/hybrid assessments.',
      );
    const rangeTotal = dto.ranges.reduce((sum, r) => {
      if (r.questionType === 'manual')
        return sum + (r.manualMaxScore ?? r.to - r.from + 1);
      return sum + (r.to - r.from + 1);
    }, 0);
    if (rangeTotal !== dto.totalItems) {
      throw new BadRequestException(
        `Item ranges total ${rangeTotal} but totalItems is ${dto.totalItems}. They must match.`,
      );
    }
  }

  async createAssessmentRecord(
    orgId: string,
    classId: string,
    dto: CreateAssessmentDto,
    effectiveGradingMode: GradingMode,
  ) {
    return this.repo.create({
      orgId,
      classId,
      lessonId: dto.lessonId || undefined,
      termId: dto.termId,
      type: dto.type,
      title: dto.title,
      totalItems: dto.totalItems,
      releaseDate: dto.releaseDate ? new Date(dto.releaseDate) : undefined,
      endDate: dto.endDate ? new Date(dto.endDate) : undefined,
      weekNumber: dto.weekNumber,
      gradingMode: effectiveGradingMode,
      manualMaxScore: dto.manualMaxScore,
      showBreakdown: dto.showBreakdown,
    });
  }

  async createManualQuestions(
    orgId: string,
    assessmentId: string,
    dto: CreateAssessmentDto,
  ) {
    if (dto.manualInstructions?.trim()) {
      await this.repo.createQuestions([
        {
          orgId,
          assessmentId,
          type: 'manual',
          questionText: dto.manualInstructions.trim(),
          order: 1,
          isManual: true,
        },
      ]);
    }
  }

  async createManualSectionQuestions(
    orgId: string,
    assessmentId: string,
    dto: CreateAssessmentDto,
  ) {
    const manualRanges = (dto.ranges ?? []).filter(
      (r) => r.questionType === 'manual',
    );
    if (!manualRanges.length) return;
    const manualQuestions = manualRanges
      .filter((r) => r.manualQuestionText?.trim())
      .map((r, idx) => ({
        orgId,
        assessmentId,
        type: 'manual',
        questionText: r.manualQuestionText!.trim(),
        order: idx + 1,
        isManual: true,
      }));
    if (manualQuestions.length > 0) {
      await this.repo.createQuestions(manualQuestions);
    }
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { AssessmentRepository } from '../../core/assessment-core.repository';
import { DatabaseService } from '@/core/database/database.provider';
import {
  UpdateSubmissionStatusDto,
  AssignStudentsDto,
  ReopenAssessmentDto,
  GradeEssayDto,
} from '../../dto/assessment.dto';

@Injectable()
export class AssessmentSubmissionHelper {
  constructor(
    private readonly repo: AssessmentRepository,
    private readonly db: DatabaseService,
  ) {}

  async getSubmissions(assessment: any, orgId: string) {
    const enrollments = await this.db.enrollment.findMany({
      where: {
        class_id: assessment.class_id,
        org_id: orgId,
        status: { not: 'removed' },
      },
      select: { student_id: true },
    });
    const studentIds = enrollments.map((e) => e.student_id);
    if (!studentIds.length) return [];

    const profiles = await this.db.profile.findMany({
      where: { account_id: { in: studentIds } },
      select: {
        account_id: true,
        full_name: true,
        account: { select: { email: true } },
      },
    });
    const profileMap = new Map(
      profiles.map((p) => [
        p.account_id,
        { name: p.full_name, email: p.account?.email ?? null },
      ]),
    );

    const submissions = await this.repo.findSubmissions(assessment.id, orgId);
    const submissionIds = submissions.map((s) => s.id);
    const answers = submissionIds.length
      ? await this.db.submissionAnswer.findMany({
          where: { submission_id: { in: submissionIds } },
          select: {
            id: true,
            submission_id: true,
            question_id: true,
            answer: true,
            is_correct: true,
          },
        })
      : [];

    const answerMap = new Map<string, typeof answers>();
    for (const a of answers) {
      const list = answerMap.get(a.submission_id) ?? [];
      list.push(a);
      answerMap.set(a.submission_id, list);
    }
    const subMap = new Map(submissions.map((s) => [s.student_id, s]));

    return studentIds.map((studentId) => {
      const profile = profileMap.get(studentId);
      const sub = subMap.get(studentId);
      const subAnswers = sub ? (answerMap.get(sub.id) ?? []) : [];
      return {
        id: sub?.id ?? `not_started_${studentId}`,
        assessment_id: assessment.id,
        student_id: studentId,
        student_name: profile?.name ?? 'Unknown',
        student_code: profile?.email ?? '',
        status: !sub ? 'not_started' : sub.status,
        score: sub?.score ?? null,
        manual_score: sub?.manual_score ?? null,
        total_points: assessment.total_items,
        is_published: assessment.is_published,
        essay_graded: false,
        answers: subAnswers.map((a) => ({
          id: a.id,
          questionId: a.question_id,
          answer: a.answer,
          isCorrect: a.is_correct,
        })),
        started_at: null,
        submitted_at: sub?.submitted_at ?? null,
        updated_at: sub?.submitted_at ?? null,
        system_section_score: sub?.system_section_score ?? null,
        manual_section_score: sub?.manual_section_score ?? null,
        is_missed: sub?.is_missed ?? false,
        is_exempted: sub?.is_exempted ?? false,
      };
    });
  }

  async updateSubmissionStatus(
    assessment: any,
    submissionId: string,
    orgId: string,
    dto: UpdateSubmissionStatusDto,
  ) {
    let submission = await this.repo.findSubmissionById(submissionId);

    if (!submission || submission.assessment_id !== assessment.id) {
      const prefix = 'not_started_';
      const studentId = submissionId.startsWith(prefix)
        ? submissionId.slice(prefix.length)
        : null;
      if (!studentId) throw new NotFoundException('Submission not found.');

      const enrollment = await this.db.enrollment.findFirst({
        where: {
          class_id: assessment.class_id,
          org_id: orgId,
          student_id: studentId,
          status: { not: 'removed' },
        },
      });
      if (!enrollment)
        throw new NotFoundException('Student not enrolled in this class.');

      submission = await this.db.submission.create({
        data: {
          org_id: orgId,
          assessment_id: assessment.id,
          student_id: studentId,
          status: 'draft',
        },
      });
    }

    if (dto.status === 'custom' && dto.manualScore === undefined) {
      throw new BadRequestException(
        'manualScore is required for custom status.',
      );
    }

    const updateData: any = {
      status: dto.status,
      manualScore: dto.manualScore,
    };
    if (dto.status === 'exempted') {
      updateData.isExempted = true;
      updateData.score = 0;
    }
    if (dto.status === 'missed') {
      updateData.status = 'custom';
      updateData.isMissed = true;
      updateData.score = 0;
    }

    return this.repo.updateSubmissionStatus(submission.id, updateData);
  }

  async gradeEssay(assessment: any, submissionId: string, dto: GradeEssayDto) {
    const submission = await this.repo.findSubmissionById(submissionId);
    if (!submission || submission.assessment_id !== assessment.id)
      throw new NotFoundException('Submission not found.');
    return this.repo.gradeEssay(submissionId, dto.score, dto.score);
  }

  async assignStudents(assessment: any, orgId: string, dto: AssignStudentsDto) {
    for (const studentId of dto.studentIds) {
      await this.repo
        .upsertSubmission({
          orgId,
          assessmentId: assessment.id,
          studentId,
          status: 'draft',
        })
        .catch(() => {});
    }
    return { success: true, assigned: dto.studentIds.length };
  }

  async reopen(assessment: any, orgId: string, dto: ReopenAssessmentDto) {
    const reopenedUntil = new Date(dto.reopenedUntil);
    for (const studentId of dto.studentIds) {
      const existing = await this.repo.findSubmissionByStudent(
        assessment.id,
        studentId,
      );
      if (existing) {
        await this.db.submissionAnswer.deleteMany({
          where: { submission_id: existing.id },
        });
        await this.db.submission.update({
          where: { id: existing.id },
          data: {
            status: 'draft',
            score: null,
            manual_score: null,
            submitted_at: null,
            reopened_until: reopenedUntil,
          },
        });
      } else {
        await this.db.submission.create({
          data: {
            org_id: orgId,
            assessment_id: assessment.id,
            student_id: studentId,
            status: 'draft',
            reopened_until: reopenedUntil,
          },
        });
      }
    }
    return { success: true, reopened: dto.studentIds.length };
  }
}

// @/modules/assessment/student/assessment-student.service.ts
import {
  Injectable,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { AssessmentCoreService } from '../core/assessment-core.service';
import { DatabaseService } from '@/core/database/database.provider';
import { EnrollmentRepository } from '@/modules/enrollment/enrollment.repository';
import { GradeRepository } from '@/modules/grade/grade.repository';

@Injectable()
export class AssessmentStudentService {
  constructor(
    private readonly core: AssessmentCoreService,
    private readonly db: DatabaseService,
    private readonly enrollmentRepo: EnrollmentRepository,
    private readonly gradeRepo: GradeRepository,
  ) {}

  private async assertStudentEnrolled(
    classId: string,
    studentId: string,
    orgId: string,
  ) {
    const enrollment = await this.enrollmentRepo.findOneByStudentAndClass(
      classId,
      studentId,
      orgId,
    );

    if (!enrollment) {
      throw new ForbiddenException('Not enrolled in this class.');
    }

    return enrollment;
  }

  async getAssessments(classId: string, orgId: string, studentId: string) {
    await this.assertStudentEnrolled(classId, studentId, orgId);

    const assessments = await this.core.findAssessmentsByClass(classId, orgId);
    if (!assessments.length) return [];

    const ids = assessments.map((a) => a.id);

    // Get this student's submission per assessment
    const submissions = await this.db.submission.findMany({
      where: { assessment_id: { in: ids }, student_id: studentId },
      select: {
        id: true,
        assessment_id: true,
        status: true,
        reopened_until: true,
      },
    });
    const subMap = new Map(submissions.map((s) => [s.assessment_id, s]));

    // Find active reopens for this student
    const now = new Date();

    return assessments.map((a) => {
      const submission = subMap.get(a.id) ?? null;
      const reopenedUntil = submission?.reopened_until;
      const isReopened = !!reopenedUntil && now <= new Date(reopenedUntil);

      const item = this.core.buildAssessmentListItem(a, submission);

      return {
        ...item,
        status: isReopened ? 'open' : item.submissionStatus,
        reopenedUntil: reopenedUntil ? reopenedUntil.toISOString() : null,
      };
    });
  }

  async getAssessmentDetail(
    classId: string,
    assessmentId: string,
    orgId: string,
    studentId: string,
  ) {
    await this.assertStudentEnrolled(classId, studentId, orgId);

    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    this.core.assertBelongsToClass(assessment, classId);

    if (!this.core.isReleased(assessment)) {
      return this.core.buildAssessmentDetail(assessment, null, true);
    }

    const questions = await this.core.getQuestions(assessmentId);

    return this.core.buildAssessmentDetail(assessment, questions, false);
  }

  async getResult(
    classId: string,
    assessmentId: string,
    orgId: string,
    studentId: string,
  ) {
    await this.assertStudentEnrolled(classId, studentId, orgId);

    const assessment = await this.core.findAssessmentOrThrow(
      assessmentId,
      orgId,
    );
    this.core.assertBelongsToClass(assessment, classId);

    const submission = await this.core.getSubmissionByStudent(
      assessmentId,
      studentId,
    );

    if (!submission) {
      throw new NotFoundException('No submission found.');
    }

    // TODO: wire real GradeLock
    const grade = await this.gradeRepo.findByStudent(
      studentId,
      classId,
      assessment.term_id,
      orgId,
    );

    const isLocked = grade?.is_locked ?? false;

    const questions = await this.core.getQuestions(assessmentId);
    const answers = await this.db.submissionAnswer.findMany({
      where: { submission_id: submission.id },
    });

    return this.core.buildResult(
      submission,
      assessment,
      isLocked,
      questions,
      answers,
    );
  }
}

