      id: 's1',
      class_id: 'c1',
    });

    db.enrollment.findMany.mockResolvedValue([{ student_id: 's1' }]);

    await service.bulkSetAttendance('c1', 's1', 'org1', 'actor1', {
      records: [{ studentId: 's1', status: 'P' }],
    } as any);

    expect(attendanceRepo.upsertRecord).toHaveBeenCalled();
  });

  // ─────────────────────────────────────────────
  // 6. UPDATE RECORD SAFETY
  // ─────────────────────────────────────────────

  it('rejects update when record does not belong to session', async () => {
    db.class.findFirst.mockResolvedValue({ id: 'c1' });

    attendanceRepo.findSessionById.mockResolvedValue({
      id: 's1',
      class_id: 'c1',
    });

    attendanceRepo.findRecordById.mockResolvedValue({
      id: 'r1',
      session_id: 'other-session',
    });

    await expect(
      service.updateRecord('c1', 's1', 'r1', 'org1', 'actor1', {
        status: 'P',
      } as any),
    ).rejects.toThrow(NotFoundException);
  });

  it('updates record when valid', async () => {
    db.class.findFirst.mockResolvedValue({ id: 'c1' });

    attendanceRepo.findSessionById.mockResolvedValue({
      id: 's1',
      class_id: 'c1',
    });

    attendanceRepo.findRecordById.mockResolvedValue({
      id: 'r1',
      session_id: 's1',
    });

    attendanceRepo.updateRecord.mockResolvedValue({
      id: 'r1',
      status: 'P',
    });

    const result = await service.updateRecord(
      'c1',
      's1',
      'r1',
      'org1',
      'actor1',
      { status: 'P' } as any,
    );

    expect(result.status).toBe('P');
  });

  // ─────────────────────────────────────────────
  // 7. AUTO MARK ATTENDANCE
  // ─────────────────────────────────────────────

  it('calls repo when marking present from submission', async () => {
    await service.markPresentFromSubmission({
      orgId: 'org1',
      classId: 'c1',
      studentId: 's1',
      submittedAt: new Date('2025-01-01'),
    });

    expect(attendanceRepo.markPresentFromSubmission).toHaveBeenCalled();
  });

  // ─────────────────────────────────────────────
  // 8. SESSION GROUPING LOGIC
  // ─────────────────────────────────────────────

  it('groups sessions by week number', async () => {
    db.class.findFirst.mockResolvedValue({ id: 'c1' });

    attendanceRepo.findSessionsByClass.mockResolvedValue([
      { week_number: 1 },
      { week_number: 1 },
      { week_number: 2 },
    ]);

    const result = await service.getSessions('c1', 'org1');

    expect(result.length).toBe(2);
  });
});

// @/modules/attendance/attendance.repository.ts
import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { AttendanceStatus } from './dto/attendance.dto';

@Injectable()
export class AttendanceRepository {
  constructor(private readonly db: DatabaseService) {}

  // ─── Sessions ────────────────────────────────────────────────

  async createManySessions(
    sessions: {
      org_id: string;
      class_id: string;
      date: Date;
      week_number: number;
      sub_index: number;
    }[],
  ) {
    return this.db.attendanceSession.createMany({
      data: sessions,
      skipDuplicates: true,
    });
  }

  async findSessionsByClass(classId: string, weekNumber?: number) {
    return this.db.attendanceSession.findMany({
      where: {
        class_id: classId,
        ...(weekNumber ? { week_number: weekNumber } : {}),
      },
      orderBy: [{ week_number: 'asc' }, { sub_index: 'asc' }],
    });
  }

  async findSessionById(id: string) {
    return this.db.attendanceSession.findUnique({ where: { id } });
  }

  // ─── Records ─────────────────────────────────────────────────

  async findRecordsBySession(sessionId: string) {
    return this.db.attendanceRecord.findMany({
      where: { session_id: sessionId },
    });
  }

  async findRecordById(id: string) {
    return this.db.attendanceRecord.findUnique({ where: { id } });
  }

  async findRecordBySessionAndStudent(sessionId: string, studentId: string) {
    return this.db.attendanceRecord.findFirst({
      where: { session_id: sessionId, student_id: studentId },
    });
  }

  async updateRecord(id: string, status: AttendanceStatus) {
    return this.db.attendanceRecord.update({
      where: { id },
      data: { status },
    });
  }

  async upsertRecord(data: {
    org_id: string;
    session_id: string;
    student_id: string;
    status: string;
  }) {
    const existing = await this.findRecordBySessionAndStudent(
      data.session_id,
      data.student_id,
    );

    if (existing) {
      return this.db.attendanceRecord.update({
        where: { id: existing.id },
        data: { status: data.status as any },
      });
    }

    return this.db.attendanceRecord.create({
      data: { ...data, status: data.status as any },
    });
  }

  async markPresentFromSubmission(data: {
    org_id: string;
    class_id: string;
    student_id: string;
    date: Date;
  }) {
    const dayStart = new Date(data.date);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(data.date);
    dayEnd.setHours(23, 59, 59, 999);

    const session = await this.db.attendanceSession.findFirst({
      where: {
        class_id: data.class_id,
        date: { gte: dayStart, lte: dayEnd },
      },
    });

    if (!session) return null;

    return this.upsertRecord({
      org_id: data.org_id,
      session_id: session.id,
      student_id: data.student_id,
      status: 'present',
    });
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';

import { DatabaseService } from '@/core/database/database.provider';
import { AttendanceRepository } from './attendance.repository';
import { AuditLogService } from '../audit-log/audit-log.service';
import {
  BulkSetAttendanceDto,
  UpdateAttendanceRecordDto,
} from './dto/attendance.dto';
import { LessonService } from '../lesson/lesson.service';

@Injectable()
export class AttendanceService {
  constructor(
    private readonly db: DatabaseService,
    private readonly attendanceRepo: AttendanceRepository,
    private readonly auditLog: AuditLogService,
    private readonly lessonService: LessonService,
  ) {}

  // =========================================================
  // 🔥 MAIN FIXED GENERATOR (SYNCED WITH LESSON LOGIC)
  // =========================================================
  async generateSessionsForClass(
    classId: string,
    orgId: string,
  ): Promise<void> {
    const cls = await this.db.class.findUnique({
      where: { id: classId },
      include: { schedules: true },
    });

    if (!cls || !cls.schedules.length) return;

    const subject = await this.db.subject.findFirst({
      where: { id: cls.subject_id },
      select: { program_id: true },
    });

    if (!subject?.program_id) return;

    const assignment = await this.db.programSemesterAssignment.findFirst({
      where: {
        program_id: subject.program_id,
        org_id: orgId,
      },
      include: {
        template: {
          include: {
            semesters: {
              include: {
                terms: true,
              },
            },
          },
        },
        termDates: true,
      },
    });

    if (!assignment) return;

    // -------------------------------
    // term date map (source of truth)
    // -------------------------------
    const termDatesMap = new Map<string, { start: Date; end: Date }>();

    for (const td of assignment.termDates ?? []) {
      termDatesMap.set(td.term_id, {
        start: new Date(td.start_date),
        end: new Date(td.end_date),
      });
    }

    // -------------------------------
    // blocked dates (holidays, etc.)
    // -------------------------------
    const calendarEvents = await this.db.academicCalendar.findMany({
      where: {
        org_id: orgId,
        school_year_id: cls.school_year_id,
        type: { in: ['holiday', 'no_class_day'] },
      },
    });

    const isBlockedDate = (date: Date): boolean => {
      return calendarEvents.some((event) => {
        const start = new Date(event.start_date);
        const end = new Date(event.end_date);

        start.setHours(0, 0, 0, 0);
        end.setHours(23, 59, 59, 999);

        return date >= start && date <= end;
      });
    };

    const scheduleWeekdays = cls.schedules
      .map((s) => s.weekday)
      .sort((a, b) => a - b);

    const sessions: {
      org_id: string;
      class_id: string;
      date: Date;
      week_number: number;
      sub_index: number;
    }[] = [];

    let globalWeek = 1;

    const semesters = assignment.template.semesters ?? [];

    // ── Scope to the class's semester only ──────────────────────────────
    // Find which template semester matches the class's actual semester
    // by checking date-range overlap.
    let classSemesterStart: Date | null = null;
    let classSemesterEnd: Date | null = null;
    if (cls.semester_id) {
      const actualSem = await this.db.semester.findUnique({
        where: { id: cls.semester_id },
        select: { start_date: true, end_date: true },
      });
      if (actualSem) {
        classSemesterStart = actualSem.start_date;
        classSemesterEnd = actualSem.end_date;
      }
    }

    // =========================================================
    // 🔥 CORE LOOP (SYNCED WITH LESSON SYSTEM)
    // =========================================================
    for (const sem of semesters) {
      // Skip semesters whose term date ranges don't overlap with the
      // class's actual semester date range
      if (classSemesterStart && classSemesterEnd) {
        const semTermDates = (sem.terms ?? [])
          .map((t: any) => termDatesMap.get(t.id))
          .filter(Boolean) as Array<{ start: Date; end: Date }>;

        const semStart =
          semTermDates.length > 0
            ? new Date(Math.min(...semTermDates.map((d) => d.start.getTime())))
            : null;
        const semEnd =
          semTermDates.length > 0
            ? new Date(Math.max(...semTermDates.map((d) => d.end.getTime())))
            : null;

        if (
          !semStart ||
          !semEnd ||
          semEnd < classSemesterStart ||
          semStart > classSemesterEnd
        )
          continue;
      }

      const terms = sem.terms ?? [];

      for (const term of terms) {
        const dates = termDatesMap.get(term.id);
        if (!dates) continue;

        for (const weekday of scheduleWeekdays) {
          const occurrences = this.getWeekdayOccurrences(
            dates.start,
            dates.end,
            weekday,
          );

          for (const date of occurrences) {
            if (isBlockedDate(date)) continue;

            sessions.push({
              org_id: orgId,
              class_id: classId,
              date,
              week_number: globalWeek,
              sub_index: scheduleWeekdays.indexOf(weekday) + 1,
            });

            globalWeek++;
          }
        }
      }
    }

    if (sessions.length > 0) {
      await this.attendanceRepo.createManySessions(sessions);
      await this.lessonService.syncLessonsFromAttendance(classId, orgId);
    }
  }

  // =========================================================
  // ATTENDANCE GRID (Excel-like spreadsheet)
  // =========================================================
  async getAttendanceGrid(classId: string, orgId: string) {
    await this.assertClassExists(classId, orgId);

    // All enrolled students
    const enrollments = await this.db.enrollment.findMany({
      where: { class_id: classId, status: 'active' },
      select: { student_id: true },
    });

    const studentIds = enrollments.map((e) => e.student_id);

    const accounts = await this.db.account.findMany({
      where: { id: { in: studentIds } },
      include: {
        profile: { select: { full_name: true } },
      },
    });

    const accountsMap = new Map(accounts.map((a) => [a.id, a]));

    const students = enrollments.map((e) => {
      const acc = accountsMap.get(e.student_id);
      return {
        id: e.student_id,
        name: acc?.profile?.full_name ?? acc?.email?.split('@')[0] ?? 'Unknown',
        code: acc?.email?.split('@')[0] ?? e.student_id.slice(0, 8),
      };
    });

    // All sessions
    const sessions = await this.attendanceRepo.findSessionsByClass(classId);

    // Fetch records for all sessions in batch
    const allRecords = await this.db.attendanceRecord.findMany({
      where: { session_id: { in: sessions.map((s) => s.id) } },
    });

    // Build a lookup: sessionId → { studentId → status }
    const recordsBySession = new Map<string, Map<string, string>>();
    for (const r of allRecords) {
      if (!recordsBySession.has(r.session_id)) {
        recordsBySession.set(r.session_id, new Map());
      }
      recordsBySession.get(r.session_id)!.set(r.student_id, r.status);
    }

    const sessionList = sessions.map((s) => ({
      id: s.id,
      date: s.date,
      weekNumber: s.week_number,
      subIndex: s.sub_index,
      records: Object.fromEntries(recordsBySession.get(s.id) ?? new Map()),
    }));

    return { students, sessions: sessionList };
  }

  // =========================================================
  // GET SESSIONS
  // =========================================================
  async getSessions(classId: string, orgId: string, weekNumber?: number) {
    await this.assertClassExists(classId, orgId);

    const sessions = await this.attendanceRepo.findSessionsByClass(
      classId,
      weekNumber,
    );

    const grouped: Record<number, typeof sessions> = {};

    for (const session of sessions) {
      if (!grouped[session.week_number]) {
        grouped[session.week_number] = [];
      }
      grouped[session.week_number].push(session);
    }

    return Object.entries(grouped).map(([week, items]) => ({
      week_number: Number(week),
      sessions: items,
    }));
  }

  // =========================================================
  // SINGLE SESSION
  // =========================================================
  async getSession(classId: string, sessionId: string, orgId: string) {
    await this.assertClassExists(classId, orgId);

    const session = await this.attendanceRepo.findSessionById(sessionId);

    if (!session || session.class_id !== classId) {
      throw new NotFoundException('Session not found.');
    }

    const records = await this.attendanceRepo.findRecordsBySession(sessionId);

    const enrollments = await this.db.enrollment.findMany({
      where: { class_id: classId, status: 'active' },
      select: { student_id: true },
    });

    const studentIds = enrollments.map((e) => e.student_id);

    const accounts = await this.db.account.findMany({
      where: { id: { in: studentIds } },
      include: {
        profile: { select: { full_name: true } },
      },
    });

    const accountsMap = new Map(accounts.map((a) => [a.id, a]));

    const students = enrollments.map((e) => {
      const acc = accountsMap.get(e.student_id);
      return {
        id: e.student_id,
        name: acc?.profile?.full_name ?? acc?.email?.split('@')[0] ?? 'Unknown',
        code: acc?.email?.split('@')[0] ?? e.student_id.slice(0, 8),
      };
    });

    return { ...session, records, students };
  }

  // =========================================================
  // BULK ATTENDANCE
  // =========================================================
  async bulkSetAttendance(
    classId: string,
    sessionId: string,
    orgId: string,
    actorId: string,
    dto: BulkSetAttendanceDto,
  ) {
    await this.assertClassExists(classId, orgId);

    const session = await this.attendanceRepo.findSessionById(sessionId);

    if (!session || session.class_id !== classId) {
      throw new NotFoundException('Session not found.');
    }

    const enrollments = await this.db.enrollment.findMany({
      where: { class_id: classId, status: 'active' },
      select: { student_id: true },
    });

    const enrolledIds = new Set(enrollments.map((e) => e.student_id));

    for (const entry of dto.records) {
      if (!enrolledIds.has(entry.studentId)) {
        throw new BadRequestException(
          `Student ${entry.studentId} is not actively enrolled in this class.`,
        );
      }
    }

    await Promise.all(
      dto.records.map((entry) =>
        this.attendanceRepo.upsertRecord({
          org_id: orgId,
          session_id: sessionId,
          student_id: entry.studentId,
          status: entry.status,
        }),
      ),
    );

    await this.auditLog.logActivityEvent({
      orgId,
      actorId,
      action: 'attendance_bulk_set',
      entityType: 'AttendanceSession',
      entityId: sessionId,
      metadata: { classId, count: dto.records.length },
    });

    return {
      message: 'Attendance saved.',
      count: dto.records.length,
    };
  }

  // =========================================================
  // UPDATE RECORD
  // =========================================================
  async updateRecord(
    classId: string,
    sessionId: string,
    recordId: string,
    orgId: string,
    actorId: string,
    dto: UpdateAttendanceRecordDto,
  ) {
    await this.assertClassExists(classId, orgId);

    const session = await this.attendanceRepo.findSessionById(sessionId);

    if (!session || session.class_id !== classId) {
      throw new NotFoundException('Session not found.');
    }

    const record = await this.attendanceRepo.findRecordById(recordId);

    if (!record || record.session_id !== sessionId) {
      throw new NotFoundException('Attendance record not found.');
    }

    const updated = await this.attendanceRepo.updateRecord(
      recordId,
      dto.status,
    );

    await this.auditLog.logActivityEvent({
      orgId,
      actorId,
      action: 'attendance_record_updated',
      entityType: 'AttendanceRecord',
      entityId: recordId,
      metadata: { status: dto.status, sessionId, classId },
    });

    return updated;
  }

  // =========================================================
  // AUTO MARK FROM SUBMISSION
  // =========================================================
  async markPresentFromSubmission(data: {
    orgId: string;
    classId: string;
    studentId: string;
    submittedAt: Date;
  }) {
    await this.attendanceRepo.markPresentFromSubmission({
      org_id: data.orgId,
      class_id: data.classId,
      student_id: data.studentId,
      date: data.submittedAt,
    });
  }

  // =========================================================
  // HELPERS
  // =========================================================
  private async assertClassExists(classId: string, orgId: string) {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
    });

    if (!cls) throw new NotFoundException('Class not found.');
    return cls;
  }

  private getWeekdayOccurrences(
    start: Date,
    end: Date,
    weekday: number,
  ): Date[] {
    const dates: Date[] = [];

    const current = new Date(start);

    const diff = (weekday - current.getDay() + 7) % 7;
    current.setDate(current.getDate() + diff);

    while (current <= end) {
      dates.push(new Date(current));
      current.setDate(current.getDate() + 7);
    }

    return dates;
  }
}

// src/modules/auth/admin-request-session.decorator.ts
// Mirrors the Enrollment Portal's session decorator, but for the admin-request
// session (type: 'admin-request'), reading from request.adminRequestSession.

import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const AdminRequestSession = createParamDecorator(
  (data: keyof any, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    const session = request.adminRequestSession;
    return data ? session?.[data] : session;
  },
);

// src/modules/auth/admin-request-session.guard.ts
// Mirrors the Enrollment Portal's short-lived session guard. The token is
// signed with the app-wide JWT secret but carries `type: 'admin-request'`
// claims (NOT an account `sub`), so it can never be used with the account
// AuthGuard.

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { AdminRequestSessionClaims } from './entity/admin-request-session.entity';

@Injectable()
export class AdminRequestSessionGuard implements CanActivate {
  constructor(private readonly jwtService: JwtService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const header: string | undefined = request.headers?.authorization;

    if (!header?.startsWith('Bearer ')) {
      throw new UnauthorizedException('Missing admin request session token');
    }

    try {
      const payload = this.jwtService.verify<AdminRequestSessionClaims>(
        header.slice('Bearer '.length),
      );

      if (payload?.type !== 'admin-request') {
        throw new Error('Not an admin request session token');
      }

      request.adminRequestSession = payload;
      return true;
    } catch {
      throw new UnauthorizedException(
        'Invalid or expired admin request session',
      );
    }
  }
}

// @/modules/auth/auth.controller.ts
import {
  Controller,
  Post,
  Get,
  Body,
  UseGuards,
  HttpCode,
  HttpStatus,
  Res,
  Req,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import type { Response, Request } from 'express';
import type { CookieOptions } from 'express-serve-static-core';
import { AuthService } from './auth.service';
import { LoginDto, RefreshTokenDto } from './dto/auth.dto';
import { RegisterDto, VerifyOtpDto, ResendOtpDto } from './dto/register.dto';
import {
  SendAdminRequestOtpDto,
  VerifyAdminRequestOtpDto,
  SubmitAdminRequestDto,
} from './dto/admin-request.dto';
import { AuthGuard } from '@/commons/guards/auth.guard';
import { CurrentUser } from '@/commons/decorators/current-user.decorator';
import { AdminRequestSessionGuard } from './admin-request-session.guard';
import { AdminRequestSession } from './admin-request-session.decorator';
import type { AdminRequestSessionClaims } from './entity/admin-request-session.entity';

@Controller('auth')
export class AuthController {
  constructor(
    private readonly authService: AuthService,
    private readonly jwtService: JwtService,
  ) {}

  @Post('login')
  @HttpCode(HttpStatus.OK)
  async login(
    @Body() dto: LoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const tokens = await this.authService.login(dto);

    // Set refresh token as HTTP-only cookie — NOT accessible to JS.
    // sameSite is 'none' in production because the frontend and backend live on
    // different Render subdomains (cross-site); 'none' is silently rejected by
    // browsers unless `secure: true`, which the helper sets in production.
    res.cookie('refreshToken', tokens.refreshToken, {
      ...this.getCookieOptions(),
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Only return access token in body (refresh token is cookie-only)
    return { accessToken: tokens.accessToken };
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  async refresh(
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const refreshToken =
      req.cookies?.refreshToken ?? this.getCookie(req, 'refreshToken');
    if (!refreshToken) {
      throw new UnauthorizedException('Refresh token not found');
    }

    const tokens = await this.authService.refresh(refreshToken);

    // Set new refresh token as HttpOnly cookie
    res.cookie('refreshToken', tokens.refreshToken, {
      ...this.getCookieOptions(),
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Return only access token in response body
    return {
      accessToken: tokens.accessToken,
    };
  }

  private getCookie(req: Request, name: string): string | undefined {
    const cookieHeader = req.headers.cookie;
    if (!cookieHeader) return undefined;

    const cookies = cookieHeader.split(';').map((cookie) => cookie.trim());
    const match = cookies.find((cookie) => cookie.startsWith(`${name}=`));

    if (!match) return undefined;
    return decodeURIComponent(match.slice(name.length + 1));
  }

  private getCookieOptions(): CookieOptions {
    const isProd = process.env.NODE_ENV === 'production';
    return {
      httpOnly: true,
      secure: isProd, // 'none' cookies are rejected by browsers without secure:true
      sameSite: isProd ? 'none' : 'lax',
      path: '/',
    };
  }

  @Post('logout')
  @HttpCode(HttpStatus.NO_CONTENT)
  async logout(@Req() req: Request, @Res({ passthrough: true }) res: Response) {
    // ALWAYS clear the refresh token cookie — even if access token is expired.
    // clearCookie MUST use the exact same sameSite/secure/path as the cookie
    // was set with, or the browser won't recognize it and won't delete it.
    res.clearCookie('refreshToken', this.getCookieOptions());

    // Also try to clear the server-side refresh token hash
    const refreshToken =
      req.cookies?.refreshToken ?? this.getCookie(req, 'refreshToken');
    if (refreshToken) {
      try {
        const payload = this.jwtService.decode(refreshToken);
        if (payload?.sub) {
          await this.authService.logout(payload.sub);
        }
      } catch {
        // Cookie is already cleared — that's sufficient
      }
    }
  }

  @Get('me')
  @UseGuards(AuthGuard)
  async getMe(@CurrentUser('id') accountId: string) {
    return this.authService.getMe(accountId);
  }

  @Post('register')
  @HttpCode(HttpStatus.OK)
  async register(@Body() dto: RegisterDto) {
    return this.authService.register(dto);
  }

  @Post('verify-otp')
  @HttpCode(HttpStatus.OK)
  async verifyOtp(@Body() dto: VerifyOtpDto) {
    return this.authService.verifyOtp(dto);
  }

  @Post('resend-otp')
  @HttpCode(HttpStatus.OK)
  async resendOtp(@Body() dto: ResendOtpDto) {
    return this.authService.resendOtp(dto);
  }

  // ─── Admin Request (public applicant side) ──────────────────────────────

  @Post('admin-request/otp')
  @HttpCode(HttpStatus.OK)
  async sendAdminRequestOtp(@Body() dto: SendAdminRequestOtpDto) {
    return this.authService.sendAdminRequestOtp(dto);
  }

  @Post('admin-request/verify')
  @HttpCode(HttpStatus.OK)
  async verifyAdminRequestOtp(@Body() dto: VerifyAdminRequestOtpDto) {
    return this.authService.verifyAdminRequestOtp(dto);
  }

  @Get('admin-request/me')
  @UseGuards(AdminRequestSessionGuard)
  async getAdminRequestMe(
    @AdminRequestSession() session: AdminRequestSessionClaims,
  ) {
    return this.authService.getAdminRequestMe(session);
  }

  @Post('admin-request/submit')
  @UseGuards(AdminRequestSessionGuard)
  @HttpCode(HttpStatus.OK)
  async submitAdminRequest(
    @AdminRequestSession() session: AdminRequestSessionClaims,
    @Body() dto: SubmitAdminRequestDto,
  ) {
    return this.authService.submitAdminRequest(session, dto);
  }
}

// @/modules/auth/auth.repository.ts
import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { OtpPurpose, Prisma } from '@prisma/client';

@Injectable()
export class AuthRepository {
  constructor(private readonly db: DatabaseService) {}

  async findAccountByEmail(email: string) {
    return this.db.account.findFirst({
      where: {
        email,
        deleted_at: null,
      },
      include: {
        profile: true,
      },
    });
  }

  async findAccountById(id: string) {
    return this.db.account.findUnique({
      where: { id },
      include: {
        profile: true,
      },
    });
  }

  /**
   * Finds an admin Account whose profile.personal_email matches the given
   * personal Gmail (case-insensitive). The login email is system-generated and
   * decoupled from the personal Gmail, so we must match on the profile's
   * personal_email — the record, not the (possibly changed) login email.
   */
  async findAdminAccountByPersonalEmail(email: string) {
    return this.db.account.findFirst({
      where: {
        role: 'admin',
        deleted_at: null,
        profile: {
          personal_email: { equals: email, mode: 'insensitive' },
        },
      },
    });
  }

  async saveRefreshToken(accountId: string, hashedToken: string) {
    return this.db.profile.upsert({
      where: { account_id: accountId },
      update: {
        metadata: { refreshToken: hashedToken },
      },
      create: {
        account_id: accountId,
        full_name: '',
        metadata: { refreshToken: hashedToken },
      },
    });
  }

  async getRefreshToken(accountId: string): Promise<string | null> {
    const profile = await this.db.profile.findUnique({
      where: { account_id: accountId },
      select: { metadata: true },
    });

    if (!profile?.metadata) return null;

    const meta = profile.metadata as Record<string, any>;
    return meta.refreshToken ?? null;
  }

  async clearRefreshToken(accountId: string) {
    return this.db.profile.update({
      where: { account_id: accountId },
      data: {
        metadata: {
          refreshToken: null,
        },
      },
    });
  }

  // ─── OTP ───────────────────────────────────────────────────────────────────

  async createOtp(data: {
    email: string;
    full_name?: string | null;
    code: string;
    plan: string | null;
    institution_name?: string | null;
    role?: string | null;
    student_count?: string | null;
    programs_departments?: string | null;
    expires_at: Date;
    purpose?: OtpPurpose;
    org_id?: string;
  }) {
    return this.db.otp.create({ data });
  }

  async findValidOtp(
    email: string,
    code: string,
    opts?: { purpose?: OtpPurpose; orgId?: string },
  ) {
    return this.db.otp.findFirst({
      where: {
        email,
        code,
        used_at: null,
        expires_at: { gte: new Date() },
        ...(opts?.purpose ? { purpose: opts.purpose } : {}),
        ...(opts?.orgId ? { org_id: opts.orgId } : {}),
      },
      orderBy: { created_at: 'desc' },
    });
  }

  async markOtpUsed(id: string) {
    return this.db.otp.update({
      where: { id },
      data: { used_at: new Date() },
    });
  }

  // ─── Registration Request ──────────────────────────────────────────────────

  async createRegistrationRequest(data: {
    email: string;
    full_name: string;
    plan: string | null;
    institution_name?: string | null;
    role?: string | null;
    student_count?: string | null;
    programs_departments?: string | null;
  }) {
    return this.db.registrationRequest.create({ data });
  }

  async findRegistrationRequestByEmail(email: string) {
    return this.db.registrationRequest.findFirst({
      where: { email: { equals: email, mode: 'insensitive' } },
      orderBy: { created_at: 'desc' },
    });
  }

  /**
   * Creates a fresh request if none exists for this email, otherwise updates
   * the existing row in place. On any resubmission the revision flags are
   * cleared entirely and status resets to 'pending' — full re-review, matching
   * the Concern Center's auto-reopen convention.
   */
  async submitRegistrationRequest(data: {
    email: string;
    full_name: string;
    plan: string | null;
    institution_name?: string | null;
    role?: string | null;
    student_count?: string | null;
    programs_departments?: string | null;
  }) {
    const existing = await this.findRegistrationRequestByEmail(data.email);

    if (existing) {
      return this.db.registrationRequest.update({
        where: { id: existing.id },
        data: {
          full_name: data.full_name,
          plan: data.plan,
          institution_name: data.institution_name ?? null,
          role: data.role ?? null,
          student_count: data.student_count ?? null,
          programs_departments: data.programs_departments ?? null,
          status: 'pending' as any,
          revision_notes: Prisma.JsonNull,
          reviewed_by: null,
          reviewed_at: null,
        },
      });
    }

    return this.db.registrationRequest.create({
      data: {
        email: data.email,
        full_name: data.full_name,
        plan: data.plan,
        institution_name: data.institution_name ?? null,
        role: data.role ?? null,
        student_count: data.student_count ?? null,
        programs_departments: data.programs_departments ?? null,
      },
    });
  }

  async findRegistrationRequests(params: {
    search?: string;
    status?: string;
    page: number;
    limit: number;
  }) {
    const where: any = {};

    if (params.search) {
      where.OR = [
        { email: { contains: params.search, mode: 'insensitive' } },
        { full_name: { contains: params.search, mode: 'insensitive' } },
      ];
    }

    if (params.status && params.status !== 'all') {
      where.status = params.status;
    }

    const [data, total] = await Promise.all([
      this.db.registrationRequest.findMany({
        where,
        orderBy: { created_at: 'desc' },
        skip: (params.page - 1) * params.limit,
        take: params.limit,
      }),
      this.db.registrationRequest.count({ where }),
    ]);

    return { data, total };
  }

  async updateRegistrationRequestStatus(id: string, status: string) {
    return this.db.registrationRequest.update({
      where: { id },
      data: { status: status as any },
    });
  }

  async findRegistrationRequestById(id: string) {
    return this.db.registrationRequest.findUnique({ where: { id } });
  }

  // ─── Account Creation ──────────────────────────────────────────────────────

  async createAccount(data: {
    email: string;
    password: string;
    full_name: string;
  }) {
    return this.db.account.create({
      data: {
        email: data.email,
        password: data.password,
        role: 'admin' as any,
        status: 'active' as any,
        profile: {
          create: { full_name: data.full_name },
        },
      },
      include: { profile: true },
    });
  }
}

// @/modules/auth/auth.service.ts
import {
  Injectable,
  UnauthorizedException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { AccountStatus, OtpPurpose } from '@prisma/client';

import { AuthRepository } from './auth.repository';
import { LoginDto } from './dto/auth.dto';
import { RegisterDto, VerifyOtpDto, ResendOtpDto } from './dto/register.dto';
import {
  SendAdminRequestOtpDto,
  VerifyAdminRequestOtpDto,
  SubmitAdminRequestDto,
} from './dto/admin-request.dto';
import { AuthTokens, TokenPayload } from './entity/auth.entity';
import {
  AdminRequestSessionClaims,
  RegistrationRequestView,
} from './entity/admin-request-session.entity';
import { comparePassword, hashPassword } from '@/commons/utils/hash.util';
import { MailService } from '@/modules/mail/mail.service';
import { PersonalEmailRegistryService } from '@/commons/services/personal-email-registry.service';

const SESSION_TTL = '2h';
const PERSONAL_EMAIL_IN_USE_MESSAGE =
  'This Gmail is already linked to an account in EduTool.';

@Injectable()
export class AuthService {
  constructor(
    private readonly authRepository: AuthRepository,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly mailService: MailService,
    private readonly personalEmailRegistry: PersonalEmailRegistryService,
  ) {}

  async login(dto: LoginDto): Promise<AuthTokens> {
    const account = await this.authRepository.findAccountByEmail(dto.email);

    if (!account) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const passwordMatch = await comparePassword(dto.password, account.password);
    if (!passwordMatch) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const blockedStatuses: AccountStatus[] = [
      AccountStatus.suspended,
      AccountStatus.dropped,
      AccountStatus.transferred,
      AccountStatus.graduated,
      AccountStatus.pending,
    ];

    if (blockedStatuses.includes(account.status)) {
      throw new ForbiddenException(
        `Account is ${account.status}. Contact your administrator.`,
      );
    }

    return this.generateTokens(
      account.id,
      account.org_id,
      account.role,
      account.email,
    );
  }

  async register(dto: RegisterDto): Promise<{ message: string }> {
    const existing = await this.authRepository.findAccountByEmail(dto.email);
    if (existing) {
      throw new BadRequestException('Email already registered');
    }

    const code = Math.floor(100000 + Math.random() * 900000).toString();

    await this.authRepository.createOtp({
      email: dto.email,
      full_name: dto.fullName,
      code,
      plan: dto.plan ?? null,
      institution_name: dto.institutionName ?? null,
      role: dto.role ?? null,
      student_count: dto.studentCount ?? null,
      programs_departments: dto.programsDepartments ?? null,
      expires_at: new Date(Date.now() + 10 * 60 * 1000),
    });

    await this.mailService.sendOtpEmail(dto.email, code);

    return { message: 'Verification code sent to your email' };
  }

  async verifyOtp(dto: VerifyOtpDto): Promise<{ message: string }> {
    const otp = await this.authRepository.findValidOtp(dto.email, dto.code);

    if (!otp) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (otp.used_at) {
      throw new BadRequestException('Verification code already used');
    }

    if (new Date() > otp.expires_at) {
      throw new BadRequestException('Verification code has expired');
    }

    await this.authRepository.markOtpUsed(otp.id);

    await this.authRepository.createRegistrationRequest({
      email: dto.email,
      full_name: otp.full_name ?? dto.email,
      plan: otp.plan ?? null,
      institution_name: otp.institution_name ?? null,
      role: otp.role ?? null,
      student_count: otp.student_count ?? null,
      programs_departments: otp.programs_departments ?? null,
    });

    return { message: 'Registration request submitted for review' };
  }

  async resendOtp(dto: ResendOtpDto): Promise<{ message: string }> {
    const code = Math.floor(100000 + Math.random() * 900000).toString();

    await this.authRepository.createOtp({
      email: dto.email,
      code,
      plan: null,
      expires_at: new Date(Date.now() + 10 * 60 * 1000),
    });

    await this.mailService.sendOtpEmail(dto.email, code);

    return { message: 'New verification code sent to your email' };
  }

  // ─── Enrollment Portal OTP (public applicants) ───────────────────────────
  // Same OTP write + send path as org registration, distinguished by
  // `purpose` + `org_id` so an applicant OTP can never satisfy an
  // org-registration verification (and vice versa).

  async sendEnrollmentOtp(
    email: string,
    orgId: string,
  ): Promise<{ message: string }> {
    const code = Math.floor(100000 + Math.random() * 900000).toString();

    await this.authRepository.createOtp({
      email,
      code,
      plan: null,
      purpose: OtpPurpose.enrollment_verification,
      org_id: orgId,
      expires_at: new Date(Date.now() + 10 * 60 * 1000),
    });

    await this.mailService.sendOtpEmail(email, code);

    return { message: 'Verification code sent to your email' };
  }

  async verifyEnrollmentOtp(
    email: string,
    code: string,
    orgId: string,
  ): Promise<void> {
    const otp = await this.authRepository.findValidOtp(email, code, {
      purpose: OtpPurpose.enrollment_verification,
      orgId,
    });

    if (!otp) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (otp.used_at) {
      throw new BadRequestException('Verification code already used');
    }

    if (new Date() > otp.expires_at) {
      throw new BadRequestException('Verification code has expired');
    }

    await this.authRepository.markOtpUsed(otp.id);
  }

  // ─── Admin Request (public applicant side) ───────────────────────────────
  // Lifts the existing org-registration OTP flow (same OtpPurpose.org_registration
  // mechanism) up to the Enrollment Portal's UX standard: personal-Gmail
  // lookup, a time-limited session, and per-field revision flagging.

  /**
   * Blocks re-application once the personal Gmail has already produced an
   * approved account. Detection is record-based (the RegistrationRequest row or
   * the Profile.personal_email), NOT the login email — admins can change the
   * generated login Gmail later, so we must track by the original record.
   */
  private async assertPersonalEmailNotAlreadyApproved(email: string) {
    const request =
      await this.authRepository.findRegistrationRequestByEmail(email);
    if (request?.status === 'approved') {
      throw new BadRequestException('You already have an approved account.');
    }

    const account =
      await this.authRepository.findAdminAccountByPersonalEmail(email);
    if (account) {
      throw new BadRequestException('You already have an approved account.');
    }
  }

  async sendAdminRequestOtp(
    dto: SendAdminRequestOtpDto,
  ): Promise<{ message: string }> {
    const code = Math.floor(100000 + Math.random() * 900000).toString();

    await this.authRepository.createOtp({
      email: dto.email,
      code,
      plan: null,
      expires_at: new Date(Date.now() + 10 * 60 * 1000),
    });

    await this.mailService.sendOtpEmail(dto.email, code);

    return { message: 'Verification code sent to your email' };
  }

  async verifyAdminRequestOtp(dto: VerifyAdminRequestOtpDto): Promise<
    | { blocked: true; message: string }
    | {
        token: string;
        mode: 'edit' | 'create';
        request?: RegistrationRequestView;
      }
  > {
    const otp = await this.authRepository.findValidOtp(dto.email, dto.code);

    if (!otp) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (otp.used_at) {
      throw new BadRequestException('Verification code already used');
    }

    if (new Date() > otp.expires_at) {
      throw new BadRequestException('Verification code has expired');
    }

    await this.authRepository.markOtpUsed(otp.id);

    // Global check across all accounts (not just admins) — blocks before any
    // session is issued or any existing application data is returned.
    if (await this.personalEmailRegistry.isPersonalEmailInUse(dto.email)) {
      return { blocked: true, message: PERSONAL_EMAIL_IN_USE_MESSAGE };
    }

    const existing = await this.authRepository.findRegistrationRequestByEmail(
      dto.email,
    );

    const session: AdminRequestSessionClaims = {
      type: 'admin-request',
      email: dto.email,
      requestId: existing?.id ?? null,
    };

    const token = this.jwtService.sign(session, { expiresIn: SESSION_TTL });

    return {
      token,
      mode: existing ? 'edit' : 'create',
      ...(existing ? { request: this.serializeRequest(existing) } : {}),
    };
  }

  async getAdminRequestMe(session: AdminRequestSessionClaims): Promise<{
    request: RegistrationRequestView | null;
  }> {
    if (!session.requestId) {
      return { request: null };
    }

    const request = await this.authRepository.findRegistrationRequestById(
      session.requestId,
    );

    return { request: request ? this.serializeRequest(request) : null };
  }

  async submitAdminRequest(
    session: AdminRequestSessionClaims,
    dto: SubmitAdminRequestDto,
  ): Promise<{ request: RegistrationRequestView }> {
    await this.assertPersonalEmailNotAlreadyApproved(session.email);

    const request = await this.authRepository.submitRegistrationRequest({
      email: session.email,
      full_name: dto.full_name,
      plan: dto.plan ?? null,
      institution_name: dto.institution_name ?? null,
      role: dto.role ?? null,
      student_count: dto.student_count ?? null,
      programs_departments: dto.programs_departments ?? null,
    });

    return { request: this.serializeRequest(request) };
  }

  private serializeRequest(request: any): RegistrationRequestView {
    return {
      id: request.id,
      email: request.email,
      full_name: request.full_name,
      plan: request.plan,
      institution_name: request.institution_name,
      role: request.role,
      student_count: request.student_count,
      programs_departments: request.programs_departments,
      status: request.status,
      revision_notes: (request.revision_notes ?? null) as Record<
        string,
        string
      > | null,
      reviewed_by: request.reviewed_by,
      reviewed_at: request.reviewed_at,
      created_at: request.created_at,
      updated_at: request.updated_at,
    };
  }

  async refresh(incomingRefreshToken: string): Promise<AuthTokens> {
    let accountId: string;
    try {
      const payload = this.jwtService.decode(incomingRefreshToken);
      if (!payload?.sub) throw new Error();
      accountId = payload.sub;
    } catch {
      throw new UnauthorizedException('Invalid refresh token');
    }

    const storedHash = await this.authRepository.getRefreshToken(accountId);
    if (!storedHash) {
      throw new UnauthorizedException('No active session');
    }

    const isValid = await comparePassword(incomingRefreshToken, storedHash);
    if (!isValid) {
      throw new UnauthorizedException('Invalid refresh token');
    }

    const account = await this.authRepository.findAccountById(accountId);
    if (!account) {
      throw new UnauthorizedException('Account not found');
    }

    return this.generateTokens(
      account.id,
      account.org_id,
      account.role,
      account.email,
    );
  }

  async logout(accountId: string): Promise<void> {
    await this.authRepository.clearRefreshToken(accountId);
  }

  async getMe(accountId: string) {
    const account = await this.authRepository.findAccountById(accountId);

    if (!account) {
      throw new UnauthorizedException('Account not found');
    }

    return {
      id: account.id,
      orgId: account.org_id,
      role: account.role,
      email: account.email,
      status: account.status,
      fullName: account.profile?.full_name ?? null,
      metadata: account.profile?.metadata ?? null,
      createdAt: account.created_at,
      personalEmail: account.profile?.personal_email ?? null,
      profileImage: account.profile?.profile_image ?? null,
      isRegistrar: account.is_registrar ?? false,
    };
  }

  private async generateTokens(
    accountId: string,
    org_id: string | null,
    role: any,
    email: string,
  ): Promise<AuthTokens> {
    const payload: TokenPayload = {
      sub: accountId,
      org_id,
      role,
      email,
    };

    const accessToken = this.jwtService.sign(payload, {
      expiresIn: this.configService.get<string>('jwt.expiresIn') ?? '1h',
    });

    const refreshToken = this.jwtService.sign(payload, {
      secret: this.configService.get<string>('jwt.secret'),
      expiresIn: '7d',
    });

    const hashedRefreshToken = await hashPassword(refreshToken);
    await this.authRepository.saveRefreshToken(accountId, hashedRefreshToken);

    return { accessToken, refreshToken };
  }
}

// @/modules/auth/strategies/jwt.strategy.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
import { AuthRepository } from '../auth.repository';
import { TokenPayload } from '../entity/auth.entity';
import { AccountStatus } from '@prisma/client';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy, 'jwt') {
  constructor(
    private readonly configService: ConfigService,
    private readonly authRepository: AuthRepository,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('jwt.secret'),
    });
  }

  async validate(payload: TokenPayload) {
    const account = await this.authRepository.findAccountById(payload.sub);

    if (!account) {
      throw new UnauthorizedException('Account not found');
    }

    if (account.status === AccountStatus.suspended) {
      throw new UnauthorizedException('Account is suspended');
    }

    if (
      account.status === AccountStatus.dropped ||
      account.status === AccountStatus.transferred ||
      account.status === AccountStatus.graduated
    ) {
      throw new UnauthorizedException('Account is no longer active');
    }

    // This becomes req.user in all downstream guards/controllers
    return {
      id: account.id,
      org_id: account.org_id,
      role: account.role,
      is_registrar: account.is_registrar,
      email: account.email,
      status: account.status,
      fullName: account.profile?.full_name,
      profileImage: account.profile?.profile_image,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { DatabaseService } from '@/core/database/database.provider';
import { resolveSubjectAcademicStructure } from '../enrollment/enrollment-eligibility.util';

@Injectable()
export class ClassRepository {
  constructor(private readonly db: DatabaseService) {}

  async create(data: {
    orgId: string;
    subjectId: string;
    educatorId: string;
    sectionId?: string;
    schoolYearId: string;
    semesterId: string;
    capacity: number;
  }) {
    return this.db.class.create({
      data: {
        org_id: data.orgId,
        subject_id: data.subjectId,
        educator_id: data.educatorId,
        section_id: data.sectionId ?? null,
        school_year_id: data.schoolYearId,
        semester_id: data.semesterId,
        capacity: data.capacity,
      },
      include: {
        schedules: true,
        educator: {
          include: {
            profile: { select: { full_name: true } },
          },
        },
      },
    });
  }

  async findAll(
    orgId: string,
    filters: {
      schoolYearId?: string;
      semesterId?: string;
      educatorId?: string;
      subjectId?: string;
      sectionId?: string;
      page?: number;
      limit?: number;
    },
  ) {
    const { page = 1, limit = 20 } = filters;

    const where = {
      org_id: orgId,
      deleted_at: null,
      ...(filters.schoolYearId && { school_year_id: filters.schoolYearId }),
      ...(filters.semesterId && { semester_id: filters.semesterId }),
      ...(filters.educatorId && { educator_id: filters.educatorId }),
      ...(filters.subjectId && { subject_id: filters.subjectId }),
      ...(filters.sectionId && { section_id: filters.sectionId }),
    };

    const include = {
      _count: {
        select: { enrollments: true },
      },
      schedules: true,
      gradingSchemes: {
        where: { template_id: { not: null } },
        orderBy: { created_at: 'desc' as const },
        take: 1,
        select: { template_id: true },
      },
      subject: {
        select: {
          id: true,
          name: true,
          program_id: true,
          course_id: true,
          strand_id: true,
          level_id: true,
          program: { select: { name: true } },
          course: {
            select: { name: true, program: { select: { name: true } } },
          },
          strand: {
            select: { name: true, program: { select: { name: true } } },
          },
          level: { select: { name: true } },
        },
      },
      educator: {
        include: {
          profile: {
            select: {
              full_name: true,
            },
          },
        },
      },
    };

    const [data, total] = await Promise.all([
      this.db.class.findMany({
        where,
        include,
        orderBy: { created_at: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.db.class.count({ where }),
    ]);

    return { data, total };
  }

  async findById(id: string, orgId: string) {
    return this.db.class.findFirst({
      where: { id, org_id: orgId, deleted_at: null },
      include: {
        _count: {
          select: { enrollments: true },
        },
        schedules: true,
        educator: {
          include: {
            profile: { select: { full_name: true } },
          },
        },
        subject: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    });
  }

  async update(
    id: string,
    data: {
      educatorId?: string;
      sectionId?: string | null;
      capacity?: number;
    },
  ) {
    return this.db.class.update({
      where: { id },
      data: {
        ...(data.educatorId !== undefined && { educator_id: data.educatorId }),
        ...(data.sectionId !== undefined && { section_id: data.sectionId }),
        ...(data.capacity !== undefined && { capacity: data.capacity }),
      },
      include: {
        schedules: true,
        educator: {
          include: {
            profile: { select: { full_name: true } },
          },
        },
      },
    });
  }

  /**
   * Returns a Map<educatorId, classCount> counting only non-deleted classes.
   * Empty input returns an empty Map (avoids a pointless `in: []` query).
   */
  async countAssignedClasses(
    orgId: string,
    educatorIds: string[],
  ): Promise<Map<string, number>> {
    if (educatorIds.length === 0) return new Map();

    const rows = await this.db.class.groupBy({
      by: ['educator_id'],
      where: {
        org_id: orgId,
        educator_id: { in: educatorIds },
        deleted_at: null,
      },
      _count: { _all: true },
    });

    return new Map(rows.map((r) => [r.educator_id, r._count._all]));
  }

  async findActiveClassesByEducator(educatorId: string, orgId: string) {
    return this.db.class.findMany({
      where: {
        org_id: orgId,
        educator_id: educatorId,
        deleted_at: null,
      },
      include: {
        educator: {
          include: {
            profile: { select: { full_name: true } },
          },
        },
      },
    });
  }

  async findEducatorSchedules(
    educatorId: string,
    orgId: string,
    schoolYearId: string,
  ) {
    return this.db.classSchedule.findMany({
      where: {
        org_id: orgId,
        class: {
          educator_id: educatorId,
          school_year_id: schoolYearId,
          deleted_at: null,
        },
      },
      include: {
        class: {
          include: {
            educator: {
              include: {
                profile: { select: { full_name: true } },
              },
            },
          },
        },
      },
    });
  }

  async findSchedulesByClass(classId: string) {
    return this.db.classSchedule.findMany({
      where: { class_id: classId },
    });
  }

  async findSectionSchedules(
    sectionId: string,
    orgId: string,
    schoolYearId: string,
  ) {
    return this.db.classSchedule.findMany({
      where: {
        org_id: orgId,
        class: {
          section_id: sectionId,
          school_year_id: schoolYearId,
          deleted_at: null,
        },
      },
      include: { class: true },
    });
  }

  async findBySchoolYear(schoolYearId: string, orgId: string) {
    return this.db.class.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
        deleted_at: null,
      },
      include: {
        educator: {
          include: {
            profile: { select: { full_name: true } },
          },
        },
      },
    });
  }

  async findEnrolledStudents(classId: string, orgId: string) {
    const enrollments = await this.db.enrollment.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
        status: { not: 'removed' },
      },
      select: { student_id: true },
    });

    const studentIds = enrollments.map((e) => e.student_id);
    if (!studentIds.length) return [];

    const profiles = await this.db.profile.findMany({
      where: { account_id: { in: studentIds } },
      select: {
        account_id: true,
        full_name: true,
        account: { select: { email: true } },
      },
    });

    return profiles.map((p) => ({
      id: p.account_id,
      fullName: p.full_name,
      email: p.account.email,
    }));
  }

  /**
   * Returns only students whose academic structure matches the class's subject
   * (same program, and same course/strand/level when the class requires them),
   * enrolled for the class's school year, not already enrolled in the class,
   * and whose account is active. Unused `search` filters by name / Student ID.
   */
  async findEligibleStudents(classId: string, orgId: string, search?: string) {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { school_year_id: true, section_id: true, subject_id: true },
    });
    if (!cls) return null;

    const subjectStructure = await resolveSubjectAcademicStructure(
      this.db,
      cls.subject_id,
      orgId,
    );
    if (!subjectStructure.programId) return [];

    const enrolled = await this.db.enrollment.findMany({
      where: { class_id: classId, org_id: orgId, status: { not: 'removed' } },
      select: { student_id: true },
    });
    const enrolledIds = new Set(enrolled.map((e) => e.student_id));

    const speWhere: Prisma.StudentProgramEnrollmentWhereInput = {
      org_id: orgId,
      status: 'active',
      program_id: subjectStructure.programId,
      ...(subjectStructure.courseIds.length > 0
        ? { course_id: { in: subjectStructure.courseIds } }
        : {}),
      ...(subjectStructure.strandIds.length > 0
        ? { strand_id: { in: subjectStructure.strandIds } }
        : {}),
      ...(subjectStructure.levelIds.length > 0
        ? { level_id: { in: subjectStructure.levelIds } }
        : {}),
      ...(cls.section_id ? { section_id: cls.section_id } : {}),
      studentSchoolYear: { school_year_id: cls.school_year_id },
    };

    const spEnrollments = await this.db.studentProgramEnrollment.findMany({
      where: speWhere,
      include: {
        studentSchoolYear: { select: { student_id: true } },
        program: { select: { name: true } },
        level: { select: { name: true } },
        course: { select: { name: true } },
        strand: { select: { name: true } },
        section: { select: { name: true } },
      },
    });

    // One record per student (dedupe across multiple program enrollments).
    const byStudent = new Map<string, (typeof spEnrollments)[number]>();
    for (const pe of spEnrollments) {
      const studentId = pe.studentSchoolYear.student_id;
      if (enrolledIds.has(studentId) || byStudent.has(studentId)) continue;
      byStudent.set(studentId, pe);
    }

    if (byStudent.size === 0) return [];

    const accounts = await this.db.account.findMany({
      where: {
        id: { in: [...byStudent.keys()] },
        org_id: orgId,
        role: 'student',
        status: 'active',
        deleted_at: null,
        ...(search
          ? {
              OR: [
                {
                  profile: {
                    full_name: { contains: search, mode: 'insensitive' },
                  },
                },
                {
                  profile: {
                    metadata: { path: ['studentId'], string_contains: search },
                  },
                },
              ],
            }
          : {}),
      },
      include: { profile: true },
      orderBy: { created_at: 'desc' },
    });

    return accounts.map((account) => {
      const meta = account.profile?.metadata;
      const metaObj =
        meta && typeof meta === 'object' && !Array.isArray(meta)
          ? (meta as Record<string, any>)
          : {};
      const pe = byStudent.get(account.id);
      return {
        id: account.id,
        orgId: account.org_id,
        email: account.email,
        status: account.status,
        fullName: account.profile?.full_name ?? null,
        studentId: metaObj['studentId'] ?? null,
        levelId: pe?.level_id ?? metaObj['levelId'] ?? null,
        levelName: pe?.level?.name ?? null,
        sectionId: pe?.section_id ?? metaObj['sectionId'] ?? null,
        sectionName: pe?.section?.name ?? null,
        programName: pe?.program?.name ?? null,
        courseName: pe?.course?.name ?? null,
        strandName: pe?.strand?.name ?? null,
        createdAt: account.created_at,
      };
    });
  }

  async replaceSchedules(
    orgId: string,
    classId: string,
    slots: Array<{ weekday: number; startTime: Date; endTime: Date }>,
  ) {
    await this.db.classSchedule.deleteMany({ where: { class_id: classId } });

    if (!slots.length) return [];

    return this.db.classSchedule.createMany({
      data: slots.map((s) => ({
        org_id: orgId,
        class_id: classId,
        weekday: s.weekday,
        start_time: s.startTime,
        end_time: s.endTime,
      })),
    });
  }

  async createOwnershipLog(data: any) {
    return this.db.classOwnershipLog.create({
      data: {
        org_id: data.orgId,
        class_id: data.classId,
        from_educator_id: data.fromEducatorId,
        to_educator_id: data.toEducatorId,
        reason: data.reason ?? null,
        reassigned_by: data.reassignedBy,
      },
    });
  }

  async findOwnershipHistory(classId: string, orgId: string) {
    return this.db.classOwnershipLog.findMany({
      where: { class_id: classId, org_id: orgId },
      orderBy: { reassigned_at: 'asc' },
    });
  }

  async lockGradingSchemeForClass(classId: string, orgId: string) {
    return this.db.gradingScheme.updateMany({
      where: {
        class_id: classId,
        org_id: orgId,
        is_locked: false,
      },
      data: {
        is_locked: true,
        locked_at: new Date(),
      },
    });
  }

  async softDelete(id: string) {
    return this.db.class.update({
      where: { id },
      data: {
        deleted_at: new Date(),
      },
    });
  }

  async findSubjectWithEducator(id: string) {
    const cls = await this.db.class.findUnique({
      where: { id },
      include: {
        subject: true,
        educator: {
          include: {
            profile: {
              select: {
                full_name: true,
              },
            },
          },
        },
      },
    });

    if (!cls) {
      throw new Error('Class not found');
    }

    return {
      subject: cls.subject,
      educatorProfile: cls.educator.profile,
    };
  }
}

// backend/src/modules/class/class.service.ts

import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { ClassRepository } from './class.repository';
import { EnrollmentService } from '../enrollment/enrollment.service';
import { AttendanceService } from '../attendance/attendance.service';
import { AuditLogService } from '../audit-log/audit-log.service';
import { GradingSchemeTemplateService } from '../grading-scheme-template/grading-scheme-template.service';
import { resolveProgramIdFromSubject } from '../program/program-type-resolver';
import { DatabaseService } from '@/core/database/database.provider';
import {
  CreateClassDto,
  UpdateClassDto,
  QueryClassDto,
  EnrollStudentDto,
  UpdateEnrollmentDto,
  ReassignEducatorDto,
  ScheduleSlotDto,
} from './dto/class.dto';
import {
  parseTimeToDate,
  slotsOverlap,
  toTimeSlot,
} from './class-schedule.util';

type TimeSlot = ReturnType<typeof toTimeSlot>;

@Injectable()
export class ClassService {
  constructor(
    private readonly classRepository: ClassRepository,
    private readonly enrollmentService: EnrollmentService,
    private readonly attendanceService: AttendanceService,
    private readonly auditLogService: AuditLogService,
    private readonly gradingSchemeTemplateService: GradingSchemeTemplateService,
    private readonly db: DatabaseService,
  ) {}

  // ---------------------------------------------------------------------------
  // Resolve semester automatically from schoolYearId
  // ---------------------------------------------------------------------------

  private async resolveSemesterId(
    schoolYearId: string,
    programId: string,
    orgId: string,
  ): Promise<string> {
    const assignment = await this.db.programSemesterAssignment.findFirst({
      where: { program_id: programId, org_id: orgId },
      include: {
        template: {
          include: {
            semesters: { orderBy: { order_index: 'asc' } },
          },
        },
      },
    });

    if (!assignment) {
      throw new BadRequestException(
        'No semester template is assigned to this program. Please assign one in Semester Settings before creating classes.',
      );
    }

    const firstTemplateSemester = assignment.template.semesters[0];

    if (!firstTemplateSemester) {
      throw new BadRequestException(
        'The assigned semester template has no semesters defined.',
      );
    }

    // Try matching by name first
    const semester = await this.db.semester.findFirst({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
        name: firstTemplateSemester.name,
      },
      orderBy: { start_date: 'asc' },
    });

    if (semester) return semester.id;

    // Fallback: any semester for this school year
    const fallback = await this.db.semester.findFirst({
      where: { org_id: orgId, school_year_id: schoolYearId },
      orderBy: { start_date: 'asc' },
    });

    if (!fallback) {
      throw new BadRequestException(
        'No semesters found for this school year. Please create semesters in Semester Settings first.',
      );
    }

    return fallback.id;
  }

  async create(orgId: string, dto: CreateClassDto, actorId: string) {
    const programId = await resolveProgramIdFromSubject(
      this.db,
      dto.subjectId,
      orgId,
    );

    if (!programId) {
      throw new BadRequestException(
        'Could not determine the program for this subject. Ensure the subject is properly linked.',
      );
    }

    const programType =
      (
        await this.db.program.findFirst({
          where: { id: programId, org_id: orgId },
          select: { type: true },
        })
      )?.type ?? '';

    const semesterId =
      dto.semesterId ??
      (await this.resolveSemesterId(dto.schoolYearId, programId, orgId));

    const slots = this.parseSlots(dto.schedules);
    await this.assertNoEducatorConflict(
      dto.educatorId,
      orgId,
      slots,
      dto.schoolYearId,
    );

    if (dto.sectionId) {
      await this.assertNoSectionConflict(
        dto.sectionId,
        orgId,
        slots,
        dto.schoolYearId,
      );
    }

    const cls = await this.classRepository.create({
      orgId,
      subjectId: dto.subjectId,
      educatorId: dto.educatorId,
      sectionId: dto.sectionId,
      schoolYearId: dto.schoolYearId,
      semesterId,
      capacity: dto.capacity,
    });

    await this.classRepository.replaceSchedules(orgId, cls.id, slots);

    // Auto-apply: if a grading-scheme template is in effect for the class's
    // program, stamp it onto the newly created class so it is inherited
    // immediately. Never blocks class creation on failure.
    try {
      await this.gradingSchemeTemplateService.autoApplyForNewClass(
        orgId,
        cls.id,
        programId,
        dto.schoolYearId,
        programType,
      );
    } catch (err) {
      console.error(
        `[ClassService] Failed to auto-apply grading scheme template for class ${cls.id}:`,
        err,
      );
    }

    this.attendanceService
      .generateSessionsForClass(cls.id, orgId)
      .catch((err) => {
        console.error(
          `[AttendanceService] Failed to generate sessions for class ${cls.id}:`,
          err,
        );
      });

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'class_created',
        entityType: 'class',
        entityId: cls.id,
        metadata: { subjectId: dto.subjectId, educatorId: dto.educatorId },
      })
      .catch(() => {});

    return this.classRepository.findById(cls.id, orgId);
  }

  // --- everything below is unchanged from your original ---

  async findAll(orgId: string, query: QueryClassDto) {
    const page = query.page ?? 1;
    const limit = query.limit ?? 20;

    const { data, total } = await this.classRepository.findAll(orgId, {
      schoolYearId: query.schoolYearId,
      semesterId: query.semesterId,
      educatorId: query.educatorId,
      subjectId: query.subjectId,
      sectionId: query.sectionId,
      page,
      limit,
    });

    return {
      data: data.map((cls) => {
        const subject = (cls as any).subject;
        const educator = (cls as any).educator;

        const programId =
          subject?.program_id ??
          subject?.course?.program_id ??
          subject?.strand?.program_id ??
          null;

        return {
          ...cls,
          program_id: programId,
          template_id: (cls as any).gradingSchemes?.[0]?.template_id ?? null,
          subject_name: subject?.name ?? null,
          program_name:
            subject?.program?.name ??
            subject?.course?.program?.name ??
            subject?.strand?.program?.name ??
            null,
          level_name: subject?.level?.name ?? null,
          course_name: subject?.course?.name ?? null,
          strand_name: subject?.strand?.name ?? null,

          // ✅ THIS IS THE FIX
          educatorName: educator?.profile?.full_name ?? null,
        };
      }),
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async findById(id: string, orgId: string) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return cls;
  }

  async update(id: string, orgId: string, dto: UpdateClassDto) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const newEducatorId = dto.educatorId ?? cls.educator_id;
    const newSectionId = dto.sectionId ?? cls.section_id ?? undefined;

    // Determine which schedules to validate against
    if (dto.schedules) {
      const slots = this.parseSlots(dto.schedules);
      await this.assertNoEducatorConflict(
        newEducatorId,
        orgId,
        slots,
        cls.school_year_id,
        id,
      );
      if (newSectionId)
        await this.assertNoSectionConflict(
          newSectionId,
          orgId,
          slots,
          cls.school_year_id,
          id,
        );
      await this.classRepository.replaceSchedules(orgId, id, slots);
    } else if (dto.educatorId && dto.educatorId !== cls.educator_id) {
      // Educator changed without schedule change — validate against existing schedules
      const schedules = await this.classRepository.findSchedulesByClass(id);
      const slots: TimeSlot[] = schedules.map((s) =>
        toTimeSlot({
          weekday: s.weekday,
          startTime: new Date(s.start_time),
          endTime: new Date(s.end_time),
        }),
      );
      await this.assertNoEducatorConflict(
        newEducatorId,
        orgId,
        slots,
        cls.school_year_id,
        id,
      );
    }

    return this.classRepository.update(id, {
      educatorId: dto.educatorId,
      sectionId: dto.sectionId,
      capacity: dto.capacity,
    });
  }

  async archive(id: string, orgId: string, actorId: string) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    await this.classRepository.softDelete(id);

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'class_archived',
        entityType: 'class',
        entityId: id,
      })
      .catch(() => {});
  }

  async enrollStudent(
    id: string,
    orgId: string,
    dto: EnrollStudentDto,
    actorId: string,
  ) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const result = await this.enrollmentService.enroll(
      id,
      cls.subject_id,
      cls.semester_id,
      cls.capacity,
      dto.studentId,
      orgId,
    );

    if (!('overflow' in result)) {
      const activeCount = await this.enrollmentService.countActive(id);
      if (activeCount === 1) {
        await this.classRepository.lockGradingSchemeForClass(id, orgId);
      }
    }

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'enrollment_created',
        entityType: 'class_enrollment',
        entityId: id,
        metadata: { studentId: dto.studentId },
      })
      .catch(() => {});

    return result;
  }

  async getEnrolledStudents(classId: string, orgId: string) {
    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return this.classRepository.findEnrolledStudents(classId, orgId);
  }

  async getEligibleStudents(classId: string, orgId: string, search?: string) {
    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return this.classRepository.findEligibleStudents(classId, orgId, search);
  }

  async getEnrollments(id: string, orgId: string) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return this.enrollmentService.findByClass(id, orgId);
  }

  async updateEnrollment(
    classId: string,
    enrollmentId: string,
    orgId: string,
    dto: UpdateEnrollmentDto,
  ) {
    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return this.enrollmentService.updateStatus(
      classId,
      enrollmentId,
      orgId,
      dto,
    );
  }

  async removeEnrollment(
    classId: string,
    enrollmentId: string,
    orgId: string,
    actorId: string,
  ) {
    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    const result = await this.enrollmentService.remove(
      classId,
      enrollmentId,
      orgId,
    );

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'enrollment_removed',
        entityType: 'class_enrollment',
        entityId: classId,
        metadata: { enrollmentId },
      })
      .catch(() => {});

    return result;
  }

  async reassignEducator(
    id: string,
    orgId: string,
    dto: ReassignEducatorDto,
    adminId: string,
  ) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    if (cls.educator_id === dto.educatorId) {
      throw new BadRequestException(
        'The class is already assigned to this educator.',
      );
    }

    const existingSchedules = cls.schedules as any[];
    const slots: TimeSlot[] = existingSchedules.map((s) =>
      toTimeSlot({
        weekday: s.weekday,
        startTime: new Date(s.start_time),
        endTime: new Date(s.end_time),
      }),
    );

    await this.assertNoEducatorConflict(
      dto.educatorId,
      orgId,
      slots,
      cls.school_year_id,
      id,
    );
    await this.classRepository.createOwnershipLog({
      orgId,
      classId: id,
      fromEducatorId: cls.educator_id,
      toEducatorId: dto.educatorId,
      reason: dto.reason,
      reassignedBy: adminId,
    });

    const updated = await this.classRepository.update(id, {
      educatorId: dto.educatorId,
    });

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId: adminId,
        action: 'class_reassigned',
        entityType: 'class',
        entityId: id,
        metadata: {
          fromEducatorId: cls.educator_id,
          toEducatorId: dto.educatorId,
          reason: dto.reason,
        },
      })
      .catch(() => {});

    return updated;
  }

  async getOwnershipHistory(id: string, orgId: string) {
    const cls = await this.classRepository.findById(id, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    return this.classRepository.findOwnershipHistory(id, orgId);
  }

  async hasActiveClasses(educatorId: string, orgId: string): Promise<boolean> {
    const classes = await this.classRepository.findActiveClassesByEducator(
      educatorId,
      orgId,
    );
    return classes.length > 0;
  }

  async getEducatorClassCounts(
    orgId: string,
    educatorIds: string[],
  ): Promise<Map<string, number>> {
    return this.classRepository.countAssignedClasses(orgId, educatorIds);
  }

  async getEducatorClasses(educatorId: string, orgId: string) {
    return this.classRepository.findActiveClassesByEducator(educatorId, orgId);
  }

  async getStudentClasses(studentId: string, orgId: string) {
    const enrollments = await this.enrollmentService.getStudentEnrollments(
      studentId,
      orgId,
    );
    return Promise.all(
      enrollments.map(async (enrollment) => {
        const cls = (enrollment as any).class;
        const { subject, educatorProfile } =
          await this.classRepository.findSubjectWithEducator(cls.id);
        return {
          enrollmentId: enrollment.id,
          enrollmentStatus: enrollment.status,
          class: {
            id: cls.id,
            subjectId: cls.subject_id,
            subjectName: subject?.name ?? null,
            educatorId: cls.educator_id,
            educatorName: educatorProfile?.full_name ?? null,
            sectionId: cls.section_id,
            schoolYearId: cls.school_year_id,
            semesterId: cls.semester_id,
            capacity: cls.capacity,
            schedules: cls.schedules,
          },
        };
      }),
    );
  }

  async getStudentClassById(classId: string, studentId: string, orgId: string) {
    const enrollment =
      await this.enrollmentService.getStudentEnrollmentForClass(
        classId,
        studentId,
        orgId,
      );
    const cls = (enrollment as any).class;
    const { subject, educatorProfile } =
      await this.classRepository.findSubjectWithEducator(cls.id);
    return {
      enrollmentId: enrollment.id,
      enrollmentStatus: enrollment.status,
      class: {
        id: cls.id,
        subjectId: cls.subject_id,
        subjectName: subject?.name ?? null,
        educatorId: cls.educator_id,
        educatorName: educatorProfile?.full_name ?? null,
        sectionId: cls.section_id,
        schoolYearId: cls.school_year_id,
        semesterId: cls.semester_id,
        capacity: cls.capacity,
        schedules: cls.schedules,
      },
    };
  }

  private parseSlots(schedules: ScheduleSlotDto[]): TimeSlot[] {
    return schedules.map((s) => {
      const start = parseTimeToDate(s.startTime);
      const end = parseTimeToDate(s.endTime);
      if (start >= end) {
        throw new BadRequestException(
          `Schedule weekday ${s.weekday}: start time must be before end time.`,
        );
      }
      return { weekday: s.weekday, startTime: start, endTime: end };
    });
  }

  private async assertNoEducatorConflict(
    educatorId: string,
    orgId: string,
    newSlots: TimeSlot[],
    schoolYearId: string,
    excludeClassId?: string,
  ) {
    const existing = await this.classRepository.findEducatorSchedules(
      educatorId,
      orgId,
      schoolYearId,
    );
    for (const existingSlot of existing) {
      if (excludeClassId && (existingSlot as any).class_id === excludeClassId)
        continue;
      const slot = toTimeSlot({
        weekday: existingSlot.weekday,
        startTime: new Date(existingSlot.start_time),
        endTime: new Date(existingSlot.end_time),
      });
      for (const newSlot of newSlots) {
        if (slotsOverlap(slot, newSlot)) {
          throw new ConflictException(
            `Educator already has a class on weekday ${slot.weekday} that overlaps with this time slot.`,
          );
        }
      }
    }
  }

  private async assertNoSectionConflict(
    sectionId: string,
    orgId: string,
    newSlots: TimeSlot[],
    schoolYearId: string,
    excludeClassId?: string,
  ) {
    const existing = await this.classRepository.findSectionSchedules(
      sectionId,
      orgId,
      schoolYearId,
    );
    for (const existingSlot of existing) {
      if (excludeClassId && (existingSlot as any).class_id === excludeClassId)
        continue;
      const slot = toTimeSlot({
        weekday: existingSlot.weekday,
        startTime: new Date(existingSlot.start_time),
        endTime: new Date(existingSlot.end_time),
      });
      for (const newSlot of newSlots) {
        if (slotsOverlap(slot, newSlot)) {
          throw new ConflictException(
            `Section already has a class on weekday ${slot.weekday} that overlaps with this time slot.`,
          );
        }
      }
    }
  }
}

