    updated_at: record.updated_at,
  };
}

import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import type { StudentAcademicStructure } from './enrollment-eligibility.util';

@Injectable()
export class EnrollmentRepository {
  constructor(private readonly db: DatabaseService) {}

  // Fetches the academic context of a class needed for eligibility checks.
  async findClassEnrollmentContext(classId: string, orgId: string) {
    return this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { subject_id: true, school_year_id: true, section_id: true },
    });
  }

  // Resolves a student's active program enrollment for a given school year.
  // Returns null when the student has no (or no complete) academic placement,
  // in which case they must be treated as ineligible.
  async findStudentAcademicStructure(
    studentId: string,
    orgId: string,
    schoolYearId: string,
  ): Promise<StudentAcademicStructure | null> {
    const ssy = await this.db.studentSchoolYear.findFirst({
      where: {
        org_id: orgId,
        student_id: studentId,
        school_year_id: schoolYearId,
      },
      include: {
        programEnrollments: {
          where: { status: 'active' },
        },
      },
    });

    const pe = ssy?.programEnrollments?.[0];
    if (!pe) return null;

    return {
      programId: pe.program_id,
      levelId: pe.level_id,
      courseId: pe.course_id,
      strandId: pe.strand_id,
      sectionId: pe.section_id,
    };
  }

  async create(data: {
    orgId: string;
    classId: string;
    studentId: string;
    status: string;
  }) {
    return this.db.enrollment.create({
      data: {
        org_id: data.orgId,
        class_id: data.classId,
        student_id: data.studentId,
        status: data.status as any,
      },
    });
  }

  async findByClass(classId: string, orgId: string) {
    const enrollments = await this.db.enrollment.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
        status: { not: 'removed' },
      },
      orderBy: { created_at: 'asc' },
    });

    if (enrollments.length === 0) return [];

    const studentIds = enrollments.map((e) => e.student_id);
    const accounts = await this.db.account.findMany({
      where: { id: { in: studentIds }, org_id: orgId, role: 'student' },
      select: {
        id: true,
        profile: { select: { full_name: true } },
      },
    });

    const nameMap = new Map(
      accounts.map((a) => [a.id, a.profile?.full_name ?? null]),
    );

    return enrollments.map((e) => ({
      ...e,
      student_name: nameMap.get(e.student_id) ?? null,
    }));
  }

  async findById(id: string, orgId: string) {
    return this.db.enrollment.findFirst({
      where: { id, org_id: orgId },
    });
  }

  async findByStudent(classId: string, studentId: string, orgId: string) {
    return this.db.enrollment.findFirst({
      where: { class_id: classId, student_id: studentId, org_id: orgId },
    });
  }

  // Checks if student is already enrolled in the same subject within the same semester
  // Prevents duplicate enrollment across parallel classes for the same subject
  async findDuplicate(
    studentId: string,
    subjectId: string,
    semesterId: string,
    orgId: string,
  ) {
    return this.db.enrollment.findFirst({
      where: {
        org_id: orgId,
        student_id: studentId,
        status: { not: 'removed' },
        class: {
          subject_id: subjectId,
          semester_id: semesterId,
          deleted_at: null,
        },
      },
    });
  }

  async countActive(classId: string): Promise<number> {
    return this.db.enrollment.count({
      where: { class_id: classId, status: 'active' },
    });
  }

  async updateStatus(id: string, status: string) {
    return this.db.enrollment.update({
      where: { id },
      data: { status: status as any },
    });
  }

  async remove(id: string) {
    return this.db.enrollment.update({
      where: { id },
      data: { status: 'removed' as any },
    });
  }

  async findByStudentAcrossOrg(studentId: string, orgId: string) {
    return this.db.enrollment.findMany({
      where: {
        student_id: studentId,
        org_id: orgId,
        status: 'active',
        class: { deleted_at: null },
      },
      include: {
        class: {
          include: {
            schedules: true,
            subject: { select: { id: true, name: true } },
          },
        },
      },
      orderBy: { created_at: 'asc' },
    });
  }

  async findOneByStudentAndClass(
    classId: string,
    studentId: string,
    orgId: string,
  ) {
    return this.db.enrollment.findFirst({
      where: {
        class_id: classId,
        student_id: studentId,
        org_id: orgId,
        status: 'active',
        class: { deleted_at: null },
      },
      include: {
        class: {
          include: { schedules: true },
        },
      },
    });
  }

  // Fetches all prerequisite subjects + the student's locked Grade records for them
  // Used by the eligibility check before enrollment is allowed
  async getPrerequisitesWithGrades(
    subjectId: string,
    studentId: string,
    orgId: string,
  ) {
    const prereqs = await this.db.subjectPrerequisite.findMany({
      where: { subject_id: subjectId, org_id: orgId },
      include: {
        prerequisite: {
          select: { id: true, name: true },
        },
      },
    });

    if (prereqs.length === 0) return [];

    const prereqSubjectIds = prereqs.map((p) => p.prerequisite_id);

    const grades = await this.db.grade.findMany({
      where: {
        org_id: orgId,
        student_id: studentId,
        is_locked: true,
        class: {
          subject_id: { in: prereqSubjectIds },
        },
      },
      include: {
        class: { select: { subject_id: true } },
      },
    });

    return prereqs.map((p) => ({
      subject_id: p.prerequisite_id,
      subject_name: p.prerequisite.name,
      grade:
        grades.find((g) => g.class.subject_id === p.prerequisite_id) ?? null,
    }));
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { GradeRepository } from '../grade/grade.repository';
import PDFDocument from 'pdfkit';

interface SchemeComponent {
  name: string;
  type: string; // explicit field — no more name.toLowerCase() fallback
  weight: number;
}

@Injectable()
export class ExportService {
  constructor(private readonly gradeRepo: GradeRepository) {}

  // ── GET /classes/:classId/export/csv ───────────────────────────────────────

  async buildClassCsv(classId: string, orgId: string): Promise<string> {
    const cls = await this.gradeRepo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const terms = await this.gradeRepo.findTermsBySemester(cls.semester_id);
    const scheme = await this.gradeRepo.findGradingSchemeForClass(
      classId,
      orgId,
    );
    const components = (scheme?.components ?? []) as SchemeComponent[];
    const enrolledStudentIds: string[] = cls.enrollments.map(
      (e: any) => e.student_id,
    );

    // Build header row
    const termHeaders: string[] = [];
    for (const term of terms) {
      for (const comp of components) {
        termHeaders.push(`${term.name} - ${comp.name}`);
      }
      termHeaders.push(`${term.name} - Final Score`);
      termHeaders.push(`${term.name} - Final Grade`);
    }

    const headers = ['Student ID', 'Full Name', ...termHeaders, 'Remark'];
    const rows: string[][] = [headers];

    for (const studentId of enrolledStudentIds) {
      const profile = await this.gradeRepo['db'].profile.findFirst({
        where: { account: { id: studentId } },
        select: { full_name: true, metadata: true },
      });

      const meta = (profile?.metadata as Record<string, any>) ?? {};
      const fullName = profile?.full_name ?? 'Unknown';
      const studentIdLabel = meta.studentId ?? studentId;

      const row: string[] = [studentIdLabel, fullName];
      let overallRemark = '';

      for (const term of terms) {
        const [submissions, manualScores, grade] = await Promise.all([
          this.gradeRepo.findSubmissionsForTerm(classId, term.id, orgId),
          this.gradeRepo.findManualScores(classId, term.id, orgId, studentId),
          this.gradeRepo.findByStudent(studentId, classId, term.id, orgId),
        ]);

        const studentSubs = submissions.filter(
          (s: any) => s.student_id === studentId,
        );

        for (const comp of components) {
          if (comp.type === 'manual') {
            // Match by component type — explicit, no name fallback
            const manual = manualScores.find(
              (m: any) => m.category === comp.type,
            );
            row.push(manual ? String(manual.score) : '');
          } else {
            const compSubs = studentSubs.filter(
              (s: any) => s.assessment.type === comp.type,
            );
            if (compSubs.length === 0) {
              row.push('');
            } else {
              const earned = compSubs.reduce(
                (sum: number, s: any) => sum + (s.manual_score ?? s.score ?? 0),
                0,
              );
              const total = compSubs.reduce(
                (sum: number, s: any) => sum + s.assessment.total_items,
                0,
              );
              row.push(`${earned}/${total}`);
            }
          }
        }

        row.push(grade ? String(grade.final_score) : '');
        row.push(grade ? grade.final_grade : '');
        if (grade) overallRemark = grade.final_grade;
      }

      row.push(overallRemark);
      rows.push(row);
    }

    return rows
      .map((r) =>
        r.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(','),
      )
      .join('\n');
  }

  // ── GET /classes/:classId/students/:studentId/card ─────────────────────────

  async buildClassCard(
    classId: string,
    studentId: string,
    orgId: string,
  ): Promise<Buffer> {
    const cls = await this.gradeRepo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const enrollment = cls.enrollments.find(
      (e: any) => e.student_id === studentId,
    );
    if (!enrollment)
      throw new NotFoundException('Student not enrolled in this class.');

    const terms = await this.gradeRepo.findTermsBySemester(cls.semester_id);
    const scheme = await this.gradeRepo.findGradingSchemeForClass(
      classId,
      orgId,
    );
    const components = (scheme?.components ?? []) as SchemeComponent[];

    const profile = await this.gradeRepo['db'].profile.findFirst({
      where: { account: { id: studentId } },
      select: { full_name: true, metadata: true },
    });
    const meta = (profile?.metadata as Record<string, any>) ?? {};
    const fullName = profile?.full_name ?? 'Unknown';
    const studentIdLabel = meta.studentId ?? studentId;

    const educatorProfile = await this.gradeRepo['db'].profile.findFirst({
      where: { account: { id: cls.educator_id } },
      select: { full_name: true },
    });

    const subjectRecord = await this.gradeRepo['db'].subject.findFirst({
      where: { id: cls.subject_id },
      select: { name: true },
    });

    const schoolYear = await this.gradeRepo['db'].schoolYear.findFirst({
      where: { id: cls.school_year_id },
      select: { name: true },
    });

    const org = await this.gradeRepo['db'].organization.findFirst({
      where: { id: orgId },
      select: { name: true },
    });

    return this.buildClassCardSync(
      classId,
      studentId,
      orgId,
      cls,
      terms,
      components,
      fullName,
      studentIdLabel,
      educatorProfile?.full_name ?? '',
      subjectRecord?.name ?? '',
      schoolYear?.name ?? '',
      org?.name ?? 'Relief-ED',
    );
  }

  // ── PDF builder (fully sync after data fetch) ──────────────────────────────

  private async buildClassCardSync(
    classId: string,
    studentId: string,
    orgId: string,
    cls: any,
    terms: any[],
    components: SchemeComponent[],
    fullName: string,
    studentIdLabel: string,
    educatorName: string,
    subjectName: string,
    schoolYearName: string,
    orgName: string,
  ): Promise<Buffer> {
    const termData = await Promise.all(
      terms.map(async (term) => {
        const [submissions, manualScores, grade] = await Promise.all([
          this.gradeRepo.findSubmissionsForTerm(classId, term.id, orgId),
          this.gradeRepo.findManualScores(classId, term.id, orgId, studentId),
          this.gradeRepo.findByStudent(studentId, classId, term.id, orgId),
        ]);
        return {
          term,
          submissions: submissions.filter(
            (s: any) => s.student_id === studentId,
          ),
          manualScores,
          grade,
        };
      }),
    );

    return new Promise((resolve, reject) => {
      const doc = new PDFDocument({ margin: 40, size: 'A4' });
      const buffers: Buffer[] = [];

      doc.on('data', (chunk) => buffers.push(chunk));
      doc.on('end', () => resolve(Buffer.concat(buffers)));
      doc.on('error', reject);

      // ── Header ────────────────────────────────────────────────────────────
      doc
        .fontSize(16)
        .font('Helvetica-Bold')
        .text(orgName, { align: 'center' });
      doc
        .fontSize(12)
        .font('Helvetica')
        .text('Class Grade Card', { align: 'center' });
      doc
        .fontSize(10)
        .text(`School Year: ${schoolYearName}`, { align: 'center' });
      doc.moveDown(1);

      // ── Student info ──────────────────────────────────────────────────────
      doc.fontSize(10).font('Helvetica-Bold').text('Student Information');
      doc.moveTo(40, doc.y).lineTo(555, doc.y).stroke();
      doc.moveDown(0.3);
      doc.font('Helvetica').fontSize(10);
      doc.text(`Name: ${fullName}     Student ID: ${studentIdLabel}`);
      doc.text(`Subject: ${subjectName}     Educator: ${educatorName}`);
      doc.moveDown(1);

      // ── Term grades ───────────────────────────────────────────────────────
      for (const { term, submissions, manualScores, grade } of termData) {
        doc.fontSize(10).font('Helvetica-Bold').text(term.name);
        doc.moveTo(40, doc.y).lineTo(555, doc.y).stroke();
        doc.moveDown(0.3);
        doc.font('Helvetica').fontSize(9);

        for (const comp of components) {
          let scoreText = 'N/A';

          if (comp.type === 'manual') {
            // Use comp.type for exact match — no name.toLowerCase() guessing
            const manual = manualScores.find(
              (m: any) => m.category === comp.type,
            );
            scoreText = manual ? `${manual.score}` : 'N/A';
          } else {
            const compSubs = submissions.filter(
              (s: any) => s.assessment.type === comp.type,
            );
            if (compSubs.length > 0) {
              const earned = compSubs.reduce(
                (sum: number, s: any) => sum + (s.manual_score ?? s.score ?? 0),
                0,
              );
              const total = compSubs.reduce(
                (sum: number, s: any) => sum + s.assessment.total_items,
                0,
              );
              scoreText = `${earned} / ${total}`;
            }
          }

          doc.text(`  ${comp.name} (${comp.weight}%):  ${scoreText}`, {
            indent: 10,
          });
        }

        doc.moveDown(0.3);
        doc.font('Helvetica-Bold').fontSize(9);
        doc.text(
          `  Final Score: ${grade ? grade.final_score : 'N/A'}   ` +
            `Final Grade: ${grade ? grade.final_grade : 'N/A'}`,
          { indent: 10 },
        );
        doc.moveDown(0.8);
      }

      // ── Overall ───────────────────────────────────────────────────────────
      const lastGrade = termData[termData.length - 1]?.grade;
      doc.moveTo(40, doc.y).lineTo(555, doc.y).stroke();
      doc.moveDown(0.3);
      doc.fontSize(10).font('Helvetica-Bold');
      doc.text(
        `Overall Grade: ${lastGrade?.final_grade ?? 'N/A'}   ` +
          `Remark: ${lastGrade?.final_grade ?? 'N/A'}`,
      );

      doc.end();
    });
  }
}

import { GradeLockOperationsService } from '../grade-lock-operations.service';
import { GradeLockAutoService } from '../grade-lock-auto.service';
import { GradeLockRequestsService } from '../grade-lock-requests.service';
import { GradeLockRepository } from '../grade-lock.repository';

describe('Grade-lock chain — proof tests (Lane 1 item 3)', () => {
  const auditLog = {
    logActivityEvent: jest.fn().mockResolvedValue(undefined),
    logAdminAction: jest.fn().mockResolvedValue(undefined),
  };

  describe('(a) auto-lock never locks the grading scale (manual lock does)', () => {
    it('PROOF: auto lock passes ONLY setLocked, never lockGradingScaleForClass', async () => {
      const repo = {
        findExpiredUnlockedLocks: jest.fn().mockResolvedValue([
          {
            class_id: 'c1',
            setting: { lock_deadline: new Date(Date.now() - 60_000) },
          },
        ]),
        findUnlockedLocksWithSchoolYear: jest.fn().mockResolvedValue([]),
        setLocked: jest
          .fn()
          .mockResolvedValue({ class_id: 'c1', is_locked: true }),
        createEvent: jest.fn().mockResolvedValue({}),
        lockGradingScaleForClass: jest.fn().mockResolvedValue(undefined),
      };

      const auto = new GradeLockAutoService(repo as any, auditLog as any);
      await auto.autoLockExpiredClasses('org-1');

      // Correct behavior: locking a class must also lock the grading scale it
      // was computed with, exactly like the manual lockClass path does
      // (grade-lock-operations.service.ts:78-79).
      expect(repo.lockGradingScaleForClass).toHaveBeenCalled();
    });

    it('sanity: manual lockClass DOES call lockGradingScaleForClass', async () => {
      const validator = {
        validateReadiness: jest
          .fn()
          .mockResolvedValue({ ready: true, issues: [] }),
      };
      const repo = {
        findClassById: jest
          .fn()
          .mockResolvedValue({ id: 'c1', educator_id: 'e1', deleted_at: null }),
        findLockByClassId: jest.fn().mockResolvedValue({
          is_locked: false,
          setting: {
            lock_deadline: new Date(Date.now() + 60_000),
            deadlineDays: null,
          },
        }),
        resolveDeadline: undefined,
        setLocked: jest.fn().mockResolvedValue({ class_id: 'c1' }),
        lockGradingScaleForClass: jest.fn().mockResolvedValue(undefined),
        createEvent: jest.fn().mockResolvedValue({}),
      };

      const ops = new GradeLockOperationsService(
        repo as any,
        validator as any,
        auditLog as any,
      );
      await ops.lockClass('c1', 'e1', 'org-1', {});

      expect(repo.lockGradingScaleForClass).toHaveBeenCalledWith('c1', 'org-1');
    });
  });

  describe('(b) scale resolved via level.school_year_id vs class.school_year_id', () => {
    it('PROOF: lockGradingScaleForClass keys the assignment off the LEVEL school year, not the class', async () => {
      let capturedWhere: any = null;

      const fakeDb = {
        class: {
          // Class lives in school year 2027...
          findUnique: jest.fn().mockResolvedValue({
            id: 'c1',
            school_year_id: 'sy-2027',
            subject: { level_id: 'lv-1' },
          }),
        },
        level: {
          // ...but its subject's LEVEL row is pinned to school year 2026.
          findUnique: jest.fn().mockResolvedValue({
            id: 'lv-1',
            program_id: 'p-1',
            school_year_id: 'sy-2026',
          }),
        },
        gradingScaleAssignment: {
          findFirst: jest.fn().mockImplementation(async (args: any) => {
            capturedWhere = args.where;
            return { grading_scale_id: 'gs-1' };
          }),
        },
        gradingScale: {
          update: jest.fn().mockResolvedValue({ id: 'gs-1' }),
        },
      };

      const repo = new GradeLockRepository(fakeDb as any);
      await repo.lockGradingScaleForClass('c1', 'org-1');

      // Correct behavior: grade computation (grade-educator.service.ts:405)
      // resolves the scale with cls.school_year_id = sy-2027, so the lock must
      // target the same scale — the assignment lookup must use sy-2027.
      expect(capturedWhere).toEqual(
        expect.objectContaining({
          program_id: 'p-1',
          school_year_id: 'sy-2027',
        }),
      );
    });
  });

  describe('(c) grantUnlock writes metadata.new_deadline but never updates the setting', () => {
    it('PROOF: granting with a newDeadline does NOT persist it onto the GradeLockSetting', async () => {
      // Setting's lock_deadline is already in the past -> the hourly sweep will
      // select this lock again AFTER it has been unlocked by the grant.
      const setting = {
        id: 's1',
        lock_deadline: new Date(Date.now() - 60_000),
        deadlineDays: null,
      };

      const repo = {
        findClassById: jest
          .fn()
          .mockResolvedValue({ id: 'c1', educator_id: 'e1' }),
        findLockByClassId: jest
          .fn()
          .mockResolvedValue({ is_locked: true, setting }),
        setUnlocked: jest
          .fn()
          .mockResolvedValue({ class_id: 'c1', is_locked: false, setting }),
        createEvent: jest.fn().mockResolvedValue({}),
        updateSetting: jest.fn().mockResolvedValue(undefined),
      };

      const requests = new GradeLockRequestsService(
        repo as any,
        auditLog as any,
      );
      const future = new Date(Date.now() + 30 * 60 * 1000).toISOString();

      await requests.grantUnlock('c1', 'u1', 'org-1', {
        reason: 'allow regrade',
        newDeadline: future,
      });

      // Correct behavior: a granted newDeadline must be written to the SETTING
      // (keyed by the setting's id, not the class id) so the auto-lock sweep
      // does not re-lock the class within the hour.
      expect(repo.updateSetting).toHaveBeenCalledWith(
        's1',
        expect.objectContaining({ lock_deadline: future }),
      );
    });
  });

  describe('(d) a resolved grant/deny still blocks future requests (no resolved marker)', () => {
    it('PROOF: requestUnlock throws Conflict even though the earlier request was already GRANTED', async () => {
      const repo = {
        findClassById: jest
          .fn()
          .mockResolvedValue({ id: 'c1', educator_id: 'e1' }),
        findLockByClassId: jest.fn().mockResolvedValue({
          is_locked: true,
          setting: { lock_deadline: new Date(Date.now() + 60_000) },
        }),
        findEventsByClassId: jest.fn().mockResolvedValue([
          {
            type: 'unlock_request',
            created_at: new Date(Date.now() - 3_600_000),
          },
          {
            type: 'grant_unlock',
            created_at: new Date(Date.now() - 3_500_000),
          },
        ]),
        createEvent: jest.fn().mockResolvedValue({}),
      };

      const requests = new GradeLockRequestsService(
        repo as any,
        auditLog as any,
      );

      // Correct behavior: the earlier request was RESOLVED by a grant, so a
      // fresh unlock request for the same class must be permitted.
      await expect(
        requests.requestUnlock('c1', 'e1', 'org-1', {
          reason: 'regrade again',
        }),
      ).resolves.toEqual({ success: true });
    });
  });
});

import { Injectable } from '@nestjs/common';
import { GradeLockRepository } from './grade-lock.repository';
import { AuditLogService } from '../audit-log/audit-log.service';

@Injectable()
export class GradeLockAutoService {
  constructor(
    private readonly repo: GradeLockRepository,
    private readonly auditLogService: AuditLogService,
  ) {}

  async autoLockExpiredClasses(orgId: string) {
    const now = new Date();
    let lockedCount = 0;

    const deadlineLocks = await this.repo.findExpiredUnlockedLocks(orgId, now);
    for (const lock of deadlineLocks) {
      await this.repo.setLocked(lock.class_id, 'system');
      await this.repo.lockGradingScaleForClass(lock.class_id, orgId);
      await this.repo.createEvent({
        org_id: orgId,
        class_id: lock.class_id,
        actor_id: 'system',
        type: 'lock',
        reason: 'Auto-locked: deadline passed',
        metadata: { lock_deadline: lock.setting.lock_deadline },
      });

      this.auditLogService
        .logAdminAction({
          orgId,
          actorId: 'system',
          action: 'AUTO_GRADE_LOCK',
          entityType: 'class',
          entityId: lock.class_id,
          metadata: {
            reason: 'deadline_passed',
            lock_deadline: lock.setting.lock_deadline,
          },
        })
        .catch(() => {});

      lockedCount++;
    }

    const relativeLocks =
      await this.repo.findUnlockedLocksWithSchoolYear(orgId);
    for (const lock of relativeLocks) {
      const endDate = (lock.class as any).schoolYear?.end_date;
      if (!endDate || lock.setting.deadlineDays == null) continue;

      const deadline = new Date(endDate);
      deadline.setDate(deadline.getDate() - lock.setting.deadlineDays);

      if (now >= deadline) {
        await this.repo.setLocked(lock.class_id, 'system');
        await this.repo.lockGradingScaleForClass(lock.class_id, orgId);
        await this.repo.createEvent({
          org_id: orgId,
          class_id: lock.class_id,
          actor_id: 'system',
          type: 'lock',
          reason: 'Auto-locked: relative deadline passed',
          metadata: {
            computed_deadline: deadline.toISOString(),
            deadlineDays: lock.setting.deadlineDays,
          },
        });

        this.auditLogService
          .logAdminAction({
            orgId,
            actorId: 'system',
            action: 'AUTO_GRADE_LOCK',
            entityType: 'class',
            entityId: lock.class_id,
            metadata: {
              reason: 'relative_deadline_passed',
              computed_deadline: deadline.toISOString(),
              deadlineDays: lock.setting.deadlineDays,
            },
          })
          .catch(() => {});

        lockedCount++;
      }
    }

    return { success: true, lockedCount };
  }
}

