export function resolveDeadline(setting: {
  lock_deadline?: Date | null;
  deadlineDays?: number | null;
}): { isExpired: boolean; deadline: Date | null } {
  if (setting.lock_deadline) {
    return {
      isExpired: new Date() > setting.lock_deadline,
      deadline: setting.lock_deadline,
    };
  }
  return { isExpired: false, deadline: null };
}

export async function hydrateLocks(
  locks: any[],
  orgId: string,
  findProfilesByAccountIds: (
    accountIds: string[],
  ) => Promise<{ account_id: string; full_name: string | null }[]>,
) {
  const educatorIds = [...new Set(locks.map((l) => l.class.educator_id))];
  const profiles = await findProfilesByAccountIds(educatorIds);
  const educatorMap = new Map(
    profiles.map((p) => [p.account_id, p.full_name ?? 'Unknown Educator']),
  );

  return locks.map((lock) => mapLock(lock, orgId, educatorMap));
}

function mapLock(lock: any, orgId: string, educatorMap: Map<string, string>) {
  const setting = lock.setting ?? null;

  const educatorName =
    educatorMap.get(lock.class.educator_id) ?? 'Unknown Educator';

  const subjectName = lock.class.subject?.name ?? 'Unknown Subject';

  const lockStatus = lock.is_locked
    ? lock.locked_by === 'system'
      ? 'auto_locked'
      : 'locked'
    : 'unlocked';

  const { deadline } = setting ? resolveDeadline(setting) : { deadline: null };

  return {
    id: lock.id,
    org_id: orgId,
    class_id: lock.class_id,
    is_locked: lock.is_locked,
    locked_by: lock.locked_by,
    locked_at: lock.locked_at,
    created_at: lock.created_at,
    lockStatus,
    deadline,

    setting: setting
      ? {
          id: setting.id,
          name: setting.name,
          lockType: setting.lockType,
          allowOverride: setting.allowOverride,
        }
      : null,

    className: subjectName,
    educatorName,

    class: {
      id: lock.class.id,
      subject_id: lock.class.subject_id,
      educator_id: lock.class.educator_id,
      school_year_id: lock.class.school_year_id,
      subject: lock.class.subject ?? null,
    },
  };
}

import { Injectable, ForbiddenException } from '@nestjs/common';
import { GradeLockRepository } from './grade-lock.repository';
import { GradeRepository } from '../grade/grade.repository';

export interface GradeEditCheckResult {
  allowed: boolean;
  reason?: string;
}

export interface GradeEditCheckInput {
  classId: string;
  userId: string;
  userRole: string; // 'admin' | 'educator' | 'student'
  orgId: string;
}

export interface ReadinessIssue {
  type: 'missing_submission' | 'missing_category_assessment';
  termId?: string;
  termName?: string;
  studentId?: string;
  studentName?: string;
  studentCode?: string;
  assessmentId?: string;
  assessmentTitle?: string;
  category?: string;
}

export interface ReadinessValidationResult {
  ready: boolean;
  issues: ReadinessIssue[];
}

@Injectable()
export class GradeLockValidator {
  constructor(
    private readonly repo: GradeLockRepository,
    private readonly gradeRepo: GradeRepository,
  ) {}

  async canEditGrades(
    input: GradeEditCheckInput,
  ): Promise<GradeEditCheckResult> {
    const { classId, userRole } = input;

    const gradeLock = await this.repo.findLockByClassId(classId);

    // No lock assigned — editing always allowed
    if (!gradeLock) return { allowed: true };

    if (gradeLock.is_locked) {
      if (userRole === 'admin') return { allowed: true };
      return { allowed: false, reason: 'Class is locked by administrator' };
    }

    const { setting } = gradeLock;

    // Check absolute deadline
    if (setting.lock_deadline) {
      const deadlinePassed = new Date() > setting.lock_deadline;
      if (deadlinePassed) {
        if (userRole === 'admin') return { allowed: true };
        return {
          allowed: false,
          reason: `Grading deadline has passed (${setting.lock_deadline.toISOString()}). Contact administrator for override.`,
        };
      }
    }

    return { allowed: true };
  }

  async assertCanEditGrades(input: GradeEditCheckInput): Promise<void> {
    const result = await this.canEditGrades(input);
    if (!result.allowed) {
      throw new ForbiddenException(
        result.reason ?? 'Cannot edit grades at this time',
      );
    }
  }

  async validateReadiness(
    classId: string,
    orgId: string,
  ): Promise<ReadinessValidationResult> {
    const issues: ReadinessIssue[] = [];

    // 1. Class & enrollments
    const cls = await this.gradeRepo.findClassWithSubject(classId, orgId);
    if (!cls) return { ready: true, issues: [] };

    const enrolledIds = cls.enrollments.map((e: any) => e.student_id);

    // 2. Build student name map
    const nameMap =
      enrolledIds.length > 0
        ? await this.gradeRepo.findStudentProfiles(enrolledIds)
        : new Map<string, { name: string; code: string }>();

    // 3. Grading scheme components (non-optional)
    const scheme = await this.gradeRepo.findGradingSchemeForClass(
      classId,
      orgId,
    );
    const nonOptionalComponents =
      scheme?.components?.filter((c: any) => !c.is_optional) ?? [];

    // 4. All terms for this class
    const terms = await this.gradeRepo.findTemplateTermsByClass(classId, orgId);

    // 5. Track which component categories have at least one assessment
    const coveredCategories = new Set<string>();

    for (const term of terms) {
      const assessments = await this.gradeRepo.findAssessmentsForTerm(
        classId,
        term.id,
        orgId,
      );
      if (assessments.length === 0) continue;

      // Mark covered categories
      for (const a of assessments) {
        coveredCategories.add(a.type);
      }

      // Build assessment id → title map
      const assessmentMap = new Map(assessments.map((a: any) => [a.id, a]));

      // Get submissions for this term
      const submissions = await this.gradeRepo.findSubmissionsForTerm(
        classId,
        term.id,
        orgId,
      );

      // Group non-draft submissions by (student_id, assessment_id)
      const nonDraftSubs = new Set<string>();
      for (const s of submissions) {
        if (s.status !== 'draft') {
          nonDraftSubs.add(`${s.student_id}|${s.assessment_id}`);
        }
      }

      // Check each student has a submission for each assessment
      for (const studentId of enrolledIds) {
        const studentInfo = nameMap.get(studentId);
        const studentName = studentInfo?.name ?? 'Unknown';
        const studentCode = studentInfo?.code ?? '';

        for (const assessment of assessments) {
          if (!nonDraftSubs.has(`${studentId}|${assessment.id}`)) {
            issues.push({
              type: 'missing_submission',
              termId: term.id,
              termName: term.name,
              studentId,
              studentName,
              studentCode,
              assessmentId: assessment.id,
              assessmentTitle: assessment.title ?? '',
            });
          }
        }
      }
    }

    // 6. Check non-optional grading scheme categories have at least one assessment
    for (const component of nonOptionalComponents) {
      if (!coveredCategories.has(component.type)) {
        issues.push({
          type: 'missing_category_assessment',
          category: component.type,
        });
      }
    }

    return { ready: issues.length === 0, issues };
  }
}

import { GradeEducatorService } from '../educator/grade-educator.service';
import { GradeCoreService } from '../core/grade-core.service';

describe('GradeEducatorService — locked recompute skip audit (Lane 1 item 2)', () => {
  let service: GradeEducatorService;

  const repo = {
    findClassWithSubject: jest.fn(),
    findGradingSchemeForClass: jest.fn(),
    findSubmissionsForTerm: jest.fn(),
    findAssessmentsForTerm: jest.fn(),
    findManualScores: jest.fn(),
    findByStudent: jest.fn(),
    upsert: jest.fn(),
    findEnrollmentDatesByClass: jest.fn(),
    findGradingOverridesByClass: jest.fn(),
  };

  const auditLog = { logActivityEvent: jest.fn().mockResolvedValue(undefined) };

  beforeEach(() => {
    jest.clearAllMocks();
    service = new GradeEducatorService(
      repo as any,
      new GradeCoreService(),
      auditLog as any,
    );
  });

  it('PROOF: skipping a locked grade writes a grade_recompute_skipped_locked audit entry with the preserved grade shape', async () => {
    repo.findClassWithSubject.mockResolvedValue({
      id: 'class-1',
      subject_id: 'subj-1',
      school_year_id: 'sy-1',
      educator_id: 'e-1',
      enrollments: [],
    });
    repo.findByStudent.mockResolvedValue({
      is_locked: true,
      final_score: 88,
      final_grade: 'Pass',
      locked_at: new Date(),
    });

    await service.recomputeStudentGrade('class-1', 'term-1', 's-1', 'org-1');

    expect(auditLog.logActivityEvent).toHaveBeenCalledTimes(1);
    expect(auditLog.logActivityEvent).toHaveBeenCalledWith({
      orgId: 'org-1',
      actorId: 'system',
      action: 'grade_recompute_skipped_locked',
      entityType: 'class',
      entityId: 'class-1',
      metadata: {
        termId: 'term-1',
        studentId: 's-1',
        existingFinalScore: 88,
        existingFinalGrade: 'Pass',
      },
    });
    // The locked grade is preserved — nothing is recomputed or overwritten.
    expect(repo.upsert).not.toHaveBeenCalled();
    // The lock short-circuits before the expensive parallel fetch.
    expect(repo.findGradingSchemeForClass).not.toHaveBeenCalled();
    expect(repo.findSubmissionsForTerm).not.toHaveBeenCalled();
    expect(repo.findAssessmentsForTerm).not.toHaveBeenCalled();
  });
});

import { GradeEducatorService } from '../educator/grade-educator.service';
import { GradeCoreService } from '../core/grade-core.service';

describe('GradeEducatorService — proof tests (Lane 1 item 2)', () => {
  let service: GradeEducatorService;

  const repo = {
    findClassWithSubject: jest.fn(),
    findGradingSchemeForClass: jest.fn(),
    findSubmissionsForTerm: jest.fn(),
    findAssessmentsForTerm: jest.fn(),
    findManualScores: jest.fn(),
    findByStudent: jest.fn(),
    upsert: jest.fn(),
    findEnrollmentDatesByClass: jest.fn().mockResolvedValue([]),
    findGradingOverridesByClass: jest.fn().mockResolvedValue([]),
  };

  const auditLog = { logActivityEvent: jest.fn().mockResolvedValue(undefined) };

  beforeEach(() => {
    jest.clearAllMocks();
    service = new GradeEducatorService(
      repo as any,
      new GradeCoreService(),
      auditLog as any,
    );
    jest.spyOn(service as any, 'resolveGradingScale').mockResolvedValue({
      ranges: [
        {
          minPercent: 75,
          maxPercent: 100,
          gradeValue: 'Pass',
          remark: '',
          isPassing: true,
        },
        {
          minPercent: 50,
          maxPercent: 74,
          gradeValue: 'Fail',
          remark: '',
          isPassing: false,
        },
      ],
    });
  });

  it('PROOF: recomputeStudentGrade overwrites an existing LOCKED grade row (no lock guard)', async () => {
    const cls = {
      id: 'class-1',
      subject_id: 'subj-1',
      school_year_id: 'sy-1',
      educator_id: 'e-1',
      enrollments: [],
    };
