      components: [
        { name: 'Quiz', type: 'quiz', weight: 50, max_score: 20 },
        { name: 'Exam', type: 'exam', weight: 50, max_score: 20 },
      ],
    };
    const assessments = [
      { id: 'a1', type: 'quiz', total_items: 20 },
      { id: 'a2', type: 'exam', total_items: 20 },
    ];
    const subs = [
      {
        student_id: 's-1',
        assessment_id: 'a1',
        status: 'graded',
        score: 10,
        manual_score: 10,
      },
      {
        student_id: 's-1',
        assessment_id: 'a2',
        status: 'graded',
        score: 15,
        manual_score: 15,
