    repo.findSubmissionsForTerm.mockResolvedValue(subs);
    repo.findAssessmentsForTerm.mockResolvedValue(assessments);
    repo.findManualScores.mockResolvedValue([]);

    // The published, LOCKED grade that already exists for this student/class/term.
    repo.findByStudent.mockResolvedValue({
      is_locked: true,
      final_score: 88,
      final_grade: 'Pass',
      locked_at: new Date(),
    });

    await service.recomputeStudentGrade('class-1', 'term-1', 's-1', 'org-1');

    // Correct behavior: before writing, the service must consult the existing
    // row's lock state. It does not — the existing locked row is never read.
    expect(repo.findByStudent).toHaveBeenCalledWith(
      's-1',
      'class-1',
      'term-1',
      'org-1',
    );
  });

  it('PROOF: recompute upserts a NEW final score into the locked row (88 Pass -> recomputed 62.5 Fail)', async () => {
    const cls = {
      id: 'class-1',
      subject_id: 'subj-1',
      school_year_id: 'sy-1',
      educator_id: 'e-1',
      enrollments: [],
    };
    const scheme = {
      components: [
        { name: 'Quiz', type: 'quiz', weight: 50, max_score: 20 },
        { name: 'Exam', type: 'exam', weight: 50, max_score: 20 },
      ],
    };
    const assessments = [
      { id: 'a1', type: 'quiz', total_items: 20 },
      { id: 'a2', type: 'exam', total_items: 20 },
    ];
    const subs = [
      {
        student_id: 's-1',
        assessment_id: 'a1',
        status: 'graded',
        score: 10,
        manual_score: 10,
      },
      {
        student_id: 's-1',
        assessment_id: 'a2',
        status: 'graded',
        score: 15,
        manual_score: 15,
      },
    ];

    repo.findClassWithSubject.mockResolvedValue(cls);
    repo.findGradingSchemeForClass.mockResolvedValue(scheme);
    repo.findSubmissionsForTerm.mockResolvedValue(subs);
    repo.findAssessmentsForTerm.mockResolvedValue(assessments);
    repo.findManualScores.mockResolvedValue([]);
    repo.findByStudent.mockResolvedValue({
      is_locked: true,
      final_score: 88,
      final_grade: 'Pass',
    });

    await service.recomputeStudentGrade('class-1', 'term-1', 's-1', 'org-1');

    // Correct behavior: a locked grade (88 / Pass) must NOT be overwritten.
    // The recompute currently rewrites it to the recomputed 62.5 / Fail.
    expect(repo.upsert).not.toHaveBeenCalled();
  });
});

import { Injectable } from '@nestjs/common';

export interface SchemeCategory {
  name: string;
  type: string;
  weight: number;
  maxScore?: number | null;
}

export type RubricCategory = SchemeCategory;

export interface GradeRange {
  minPercent: number;
  maxPercent: number;
  gradeValue: string;
  remark: string;
  isPassing: boolean;
}

export interface GradeComputationOptions {
  /**
   * Assessment ids excluded by the late-enrollment rule (Phase 2).
   * Excluded assessments are treated like exempted ones for averaging: they
   * contribute no percentage and do not count toward the category's active
   * status, so when every assessment in a category is excluded the category
   * drops out and the remaining weights renormalize. This is deliberately a
   * separate check from is_missed/is_exempted — it only decides presence in
   * the computation, never a score.
   */
  excludedAssessmentIds?: Set<string>;
}

@Injectable()
export class GradeCoreService {
  /**
   * Compute weighted score for a student considering ALL assessments in the term.
   * Missing assessments (no submission or draft) count as 0.
   * Exempted submissions are skipped entirely; if a category's submissions are
   * all exempted, the category is excluded and the remaining weights renormalize.
   * Assessment ids in options.excludedAssessmentIds (late-enrollment rule) are
   * likewise skipped without penalty, mirroring the exempted pattern.
   * Per-assessment percentages are bounded at 100 (hybrid scores are summed).
   * Hybrid assessments use system_section_score + manual_section_score.
   */
  computeWeightedScore(
    studentSubmissions: any[],
    studentManualScores: any[],
    allAssessments: any[],
    categories: SchemeCategory[],
    options?: GradeComputationOptions,
  ): number {
    let totalWeightedScore = 0;
    let totalWeight = 0;

    for (const category of categories) {
      const weight = category.weight;

      if (category.type === 'manual') {
        const manual = studentManualScores.find(
          (m) => m.category.toLowerCase() === category.name.toLowerCase(),
        );
        if (manual !== undefined) {
          totalWeightedScore += manual.score * weight;
          totalWeight += weight;
        }
      } else {
        const categoryAssessments = allAssessments.filter(
          (a) => a.type === category.type,
        );
        if (categoryAssessments.length === 0) continue;

        const percentages: number[] = [];
        let hasCounted = false;

        for (const assessment of categoryAssessments) {
          // Late-enrollment exclusion: skipped like an exempted submission —
          // no percentage pushed, doesn't keep the category "active".
          if (options?.excludedAssessmentIds?.has(assessment.id)) continue;
          const sub = studentSubmissions.find(
            (s) => s.assessment_id === assessment.id,
          );
          if (!sub) {
            // Missing assessment counts as zero instead of being dropped from
            // the average — handed-out assessments are not optional work.
            hasCounted = true;
            percentages.push(0);
            continue;
          }
          if (sub.status === 'exempted' || sub.is_exempted) continue;
          if (sub.is_missed) {
            hasCounted = true;
            percentages.push(0);
            continue;
          }
          hasCounted = true;
          const pct = this.percentageOfMerge(sub, assessment);
          percentages.push(pct);
        }

        // A category whose submissions are all exempted contributes nothing so
        // the remaining weights renormalize — it is never penalty-scored as 0
        // at its full weight.
        if (hasCounted) {
          const average =
            percentages.reduce((sum, p) => sum + p, 0) / percentages.length;
          totalWeightedScore += average * weight;
          totalWeight += weight;
        }
      }
    }

    if (totalWeight === 0) return 0;
    return Math.round((totalWeightedScore / totalWeight) * 100) / 100;
  }

  /**
   * Merge hybrid scores: for hybrid grading, use system + manual section scores.
   * Otherwise use manual_score ?? score.
   */
  mergeHybridScores(submission: any): number {
    if (
      submission.assessment?.grading_mode === 'hybrid' ||
      submission.manual_section_score != null
    ) {
      return (
        (submission.system_section_score ?? 0) +
        (submission.manual_section_score ?? 0)
      );
    }
    return submission.manual_score ?? submission.score ?? 0;
  }

  /**
   * Convert a single submission into a per-assessment percentage of its total.
   * Bounding at 100 keeps hybrid system+manual sums (or over-full manual
   * scores) from inflating the weighted average past a perfect score.
   */
  private percentageOfMerge(submission: any, assessment: any): number {
    const rawScore = this.mergeHybridScores(submission);
    const effectiveTotal =
      assessment.grading_mode === 'manual'
        ? (assessment.manual_max_score ?? assessment.total_items ?? 1)
        : assessment.total_items;
    if (!effectiveTotal || effectiveTotal <= 0) return 0;
    return Math.min(100, (rawScore / effectiveTotal) * 100);
  }

  buildCategoryBreakdown(
    studentSubmissions: any[],
    studentManualScores: any[],
    allAssessments: any[],
    categories: SchemeCategory[],
    totalActiveWeight: number,
    options?: GradeComputationOptions,
  ) {
    return categories.map((category) => {
      let rawAverage = 0;
      let manualScore: number | null = null;
      let isAllExempted = false;

      if (category.type === 'manual') {
        const manual = studentManualScores.find(
          (m) => m.category.toLowerCase() === category.name.toLowerCase(),
        );
        manualScore = manual?.score ?? null;
        if (manualScore != null) {
          rawAverage = manualScore;
        } else {
          isAllExempted = true;
        }
      } else {
        const categoryAssessments = allAssessments.filter(
          (a) => a.type === category.type,
        );
        if (categoryAssessments.length > 0) {
          if (category.maxScore != null && category.maxScore > 0) {
            let totalRawScore = 0;
            let hasActive = false;
            for (const assessment of categoryAssessments) {
              // Late-enrollment exclusion mirrors the exempted skip below.
              if (options?.excludedAssessmentIds?.has(assessment.id)) continue;
              const sub = studentSubmissions.find(
                (s) => s.assessment_id === assessment.id,
              );
              if (!sub) continue;
              if (sub.status === 'exempted' || sub.is_exempted) continue;
              if (sub.is_missed) continue;
              totalRawScore += this.mergeHybridScores(sub);
              hasActive = true;
            }
            if (hasActive) {
              rawAverage = (totalRawScore / category.maxScore) * 100;
            } else if (categoryAssessments.length > 0) {
              isAllExempted = true;
            }
          } else {
            const percentages: number[] = [];
            let anyNonExemptedFound = false;

            for (const assessment of categoryAssessments) {
              // Late-enrollment exclusion mirrors the exempted skip below.
              if (options?.excludedAssessmentIds?.has(assessment.id)) continue;
              const sub = studentSubmissions.find(
                (s) => s.assessment_id === assessment.id,
              );
              if (!sub) {
                // No submission at all — cannot contribute a score
                continue;
              }
              if (sub.status === 'exempted' || sub.is_exempted) {
                continue;
              }
              if (sub.is_missed) {
                anyNonExemptedFound = true;
                percentages.push(0);
              } else {
                anyNonExemptedFound = true;
                const rawScore = this.mergeHybridScores(sub);
                const effectiveTotal =
                  assessment.grading_mode === 'manual'
                    ? (assessment.manual_max_score ??
                      assessment.total_items ??
                      1)
                    : assessment.total_items;
                const pct =
                  effectiveTotal > 0 ? (rawScore / effectiveTotal) * 100 : 0;
                percentages.push(pct);
              }
            }

            if (anyNonExemptedFound) {
              rawAverage =
                percentages.reduce((sum, p) => sum + p, 0) / percentages.length;
            } else if (categoryAssessments.length > 0) {
              isAllExempted = true;
            }
          }
        } else {
          // No assessments of this type — treat as non-contributing
          isAllExempted = true;
        }
      }

      const effectiveWeight =
        totalActiveWeight > 0 && !isAllExempted
          ? Math.round((category.weight / totalActiveWeight) * 10000) / 100
          : null;

      return {
        category: category.name,
        type: category.type,
        weight: category.weight,
        rawAverage: isAllExempted ? null : Math.round(rawAverage * 100) / 100,
        manualScore,
        weightedScore: isAllExempted
          ? null
          : Math.round(rawAverage * category.weight * 100) / 100,
        isAllExempted,
        effectiveWeight,
      };
    });
  }

  resolveGrade(score: number, ranges: GradeRange[]): string {
    // Ranges are configured as contiguous integer bands (e.g. 75-79, 80-84).
    // Scores are floating point, so a boundary fraction like 79.95 would fall
    // between two bands; round to the nearest integer before matching so it
    // resolves inside the valid range instead of silently yielding 'N/A'.
    const rounded = Math.round(score);
    const match = ranges.find(
      (r) => rounded >= r.minPercent && rounded <= r.maxPercent,
    );
    return match?.gradeValue ?? 'N/A';
  }
}

// src/modules/grade/dto/grade.dto.ts
import { IsString, IsNumber, IsOptional, Min, Max } from 'class-validator';
import { Type } from 'class-transformer';

// PATCH /classes/:classId/grades/:termId/students/:studentId/manual
export class SetManualScoreDto {
  @IsString()
  category: string;

  @IsNumber()
  @Min(0)
  @Max(100)
  @Type(() => Number)
  score: number;
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { GradeRepository } from '../grade.repository';
import { GradeCoreService, GradeRange } from '../core/grade-core.service';
import {
  resolveAssessmentInclusion,
  AssessmentInclusionReason,
} from '../core/assessment-inclusion.util';
import { AuditLogService } from 'src/modules/audit-log/audit-log.service';
import {
  SetManualScoreDto,
  SetGradeVisibilityDto,
  SetAssessmentStatusOverrideDto,
} from './dto/grade-educator.dto';

function componentsToCategories(components: any[]) {
  return components.map((c) => ({
    name: c.name,
    type: c.type ?? c.name.toLowerCase(),
    weight: c.weight,
    maxScore: c.max_score ?? c.maxScore ?? null,
  }));
}

@Injectable()
export class GradeEducatorService {
  constructor(
    private readonly repo: GradeRepository,
    private readonly core: GradeCoreService,
    private readonly auditLog: AuditLogService,
  ) {}

  async setGradeVisibility(
    classId: string,
    assessmentId: string,
    orgId: string,
    educatorId: string,
    dto: SetGradeVisibilityDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const updated = await this.repo.setAssessmentVisibility(
      assessmentId,
      dto.showBreakdown,
    );

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'grade_visibility_set',
      entityType: 'class',
      entityId: classId,
      metadata: { assessmentId, showBreakdown: dto.showBreakdown },
    });

    return updated;
  }

  async publishAllByClass(classId: string, orgId: string) {
    return this.repo.publishByClass(classId, orgId);
  }

  async unlockAllByClass(classId: string, orgId: string) {
    return this.repo.unlockByClass(classId, orgId);
  }

  async publishByStudent(
    classId: string,
    termId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    return this.repo.publishByStudent(studentId, termId, orgId);
  }

  async unlockByStudent(
    classId: string,
    termId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    return this.repo.unlockByStudent(studentId, termId, orgId);
  }

  // ───────── ASSESSMENT STATUS / OVERRIDE (Phase 3) ─────────

  /**
   * Resolve the effective grading status of every assessment in a class for a
   * single student: the submission-derived status, whether it counts toward
   * the grade (Phase 2 inclusion rule ∩ countable states), the reason from the
   * Phase 2 enum, and the override row if one exists. Status model per Phase 3:
   * MISSING/PENDING/SUBMITTED/EXEMPTED mapped onto the include boolean override.
   */
  async getAssessmentStatuses(
    classId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);

    const enrollment = await this.repo.getActiveEnrollment(
      classId,
      studentId,
      orgId,
    );
    if (!enrollment) {
      throw new NotFoundException(
        'Student is not actively enrolled in this class.',
      );
    }

    const [assessments, submissions, overrides] = await Promise.all([
      this.repo.findClassAssessments(classId, orgId),
      this.repo.findSubmissionsByStudentInClass(classId, studentId, orgId),
      this.repo.findGradingOverridesByClass(classId, orgId),
    ]);

    const subByAssessment = new Map(
      submissions.map((s) => [s.assessment_id, s]),
    );
    const overrideByAssessment = new Map(
      overrides.map((o) => [o.assessment_id, o]),
    );

    return assessments.map((assessment) => {
      const override = overrideByAssessment.get(assessment.id);
      const inclusion = resolveAssessmentInclusion({
        assessmentEffectiveDate:
          assessment.release_date ?? assessment.created_at,
        enrollmentDate: enrollment.created_at,
        override: override ?? null,
        assessmentDeletedAt: null,
      });

      const status = this.resolveAssessmentStatus(
        assessment,
        subByAssessment.get(assessment.id),
      );
      const countsTowardGrade =
        inclusion.included && (status === 'MISSING' || status === 'SUBMITTED');

      const result: any = {
        assessmentId: assessment.id,
        title: assessment.title ?? null,
        effectiveDate: assessment.release_date ?? assessment.created_at,
        status,
        countsTowardGrade,
        reason: inclusion.reason,
      };

      if (override) {
        result.overrideId = override.id;
        result.overrideStatus = override.include ? 'MISSING' : 'EXEMPTED';
        result.overrideReason = override.reason ?? null;
        result.overriddenBy = override.created_by;
        result.overriddenAt = override.updated_at ?? override.created_at;
      }

      return result;
    });
  }

  /**
   * Upsert an override for (assessment, student). EXEMPTED maps to
   * include=false (excluded from grading), MISSING maps to include=true
   * (forces inclusion, counted as 0 if not submitted). PENDING and SUBMITTED
   * are rejected by the DTO — they are system-driven states.
   */
  async setAssessmentStatusOverride(
    classId: string,
    assessmentId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
    dto: SetAssessmentStatusOverrideDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);

    const assessment = await this.repo.findAssessmentInClass(
      assessmentId,
      classId,
      orgId,
    );
    if (!assessment)
      throw new NotFoundException('Assessment not found in this class.');

    const enrollment = await this.repo.getActiveEnrollment(
      classId,
      studentId,
      orgId,
    );
    if (!enrollment)
      throw new NotFoundException(
        'Student is not actively enrolled in this class.',
      );

    const previous = await this.repo.findAssessmentOverride(
      assessmentId,
      studentId,
      orgId,
    );
    const previousStatus = previous
      ? previous.include
        ? 'MISSING'
        : 'EXEMPTED'
      : null;

    // MISSING forces inclusion; EXEMPTED excludes — mirroring Phase 3 rules.
    const include = dto.overrideStatus === 'MISSING';
    const saved = await this.repo.upsertAssessmentOverride({
      orgId,
      assessmentId,
      studentId,
      include,
      reason: dto.reason ?? null,
      createdBy: educatorId,
    });

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_status_override',
      entityType: 'class',
      entityId: classId,
      metadata: {
        assessmentId,
        studentId,
        previousStatus,
        newStatus: dto.overrideStatus,
        reason: dto.reason ?? null,
      },
    });

    return {
      overrideId: saved.id,
      overrideStatus: saved.include ? 'MISSING' : 'EXEMPTED',
      overrideReason: saved.reason ?? null,
      overriddenBy: saved.created_by,
      overriddenAt: saved.updated_at ?? saved.created_at,
    };
  }

  async deleteAssessmentStatusOverride(
    classId: string,
    assessmentId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);

    const enrollment = await this.repo.getActiveEnrollment(
      classId,
      studentId,
      orgId,
    );
    if (!enrollment)
      throw new NotFoundException(
        'Student is not actively enrolled in this class.',
      );

    const previous = await this.repo.findAssessmentOverride(
      assessmentId,
      studentId,
      orgId,
    );
    const previousStatus = previous
      ? previous.include
        ? 'MISSING'
        : 'EXEMPTED'
      : null;

    const deleted = await this.repo.deleteAssessmentOverride(
      assessmentId,
      studentId,
      orgId,
    );

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'assessment_status_override_deleted',
      entityType: 'class',
      entityId: classId,
      metadata: {
        assessmentId,
        studentId,
        previousStatus,
        newStatus: null,
        reason: previous?.reason ?? null,
      },
    });

    return { deleted: deleted.count };
  }

  /**
   * Map a submission (+ assessment dates) onto the Phase 3 status model.
   * Draft / not-yet-released work is PENDING; overdue non-submission is
   * MISSING; exempted/missed/custom/submitted states follow their row flags.
   */
  private resolveAssessmentStatus(
    assessment: any,
    submission?: any,
    now: Date = new Date(),
  ): 'MISSING' | 'PENDING' | 'SUBMITTED' | 'EXEMPTED' {
    if (!submission) {
      if (assessment.end_date && now > new Date(assessment.end_date))
        return 'MISSING';
      return 'PENDING';
    }
    if (submission.is_exempted || submission.status === 'exempted')
      return 'EXEMPTED';
    if (submission.is_missed) return 'MISSING';
    if (
      submission.status === 'submitted' ||
      submission.status === 'custom' ||
      submission.score != null ||
      submission.manual_score != null ||
      submission.manual_section_score != null ||
      submission.system_section_score != null
    ) {
      return 'SUBMITTED';
    }
    return 'PENDING'; // draft in progress
  }

  async registerAssessmentForAllStudents(
    assessmentId: string,
    classId: string,
    orgId: string,
  ) {
    return this.repo.registerAssessmentForAllStudents(
      assessmentId,
      classId,
      orgId,
    );
  }

  async computeAndSaveGrade(data: {
    orgId: string;
    studentId: string;
    classId: string;
    termId: string;
    finalScore: number;
    finalGrade: string;
  }) {
    return this.repo.upsert(data);
  }

  async getClassGrades(classId: string, orgId: string) {
    return this.repo.findByClass(classId, orgId);
  }

  async getGradesByClass(classId: string, orgId: string, educatorId: string) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const terms = await this.repo.findTemplateTermsByClass(classId, orgId);
    const results: any[] = [];

    for (const term of terms) {
      const termResult = await this.buildTermResult(
        classId,
        term.id,
        term.name,
        orgId,
        cls,
        { id: term.semesterIndex.toString(), name: term.semesterName },
      );
      results.push(termResult);
    }

    return results;
  }

  async getTermOptions(classId: string, orgId: string, educatorId: string) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const terms = await this.repo.findTemplateTermsByClass(classId, orgId);
    return terms.map((t) => ({
      termId: t.id,
      termName: t.name,
      semesterName: t.semesterName,
    }));
  }

  async getGradesByTerm(
    classId: string,
    termId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const terms = await this.repo.findTemplateTermsByClass(classId, orgId);
    const term = terms.find((t) => t.id === termId);

    return this.buildTermResult(
      classId,
      termId,
      term?.name ?? '',
      orgId,
      cls,
      term
        ? { id: term.semesterIndex.toString(), name: term.semesterName }
        : undefined,
    );
  }

  /**
   * Recompute grade for a single student after submission.
   * Called automatically on submission finish.
   */
  async recomputeStudentGrade(
    classId: string,
    termId: string,
    studentId: string,
    orgId: string,
  ) {
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) return;

    const existing = await this.repo.findByStudent(
      studentId,
      classId,
      termId,
      orgId,
    );
    if (existing?.is_locked) {
      await this.auditLog.logActivityEvent({
        orgId,
        actorId: 'system',
        action: 'grade_recompute_skipped_locked',
        entityType: 'class',
        entityId: classId,
        metadata: {
          termId,
          studentId,
          existingFinalScore: existing.final_score,
          existingFinalGrade: existing.final_grade,
        },
      });
      return;
    }

    const [
      scheme,
      submissions,
      allAssessments,
      manualScores,
      enrollmentDates,
      overrides,
    ] = await Promise.all([
      this.repo.findGradingSchemeForClass(classId, orgId),
      this.repo.findSubmissionsForTerm(classId, termId, orgId),
      this.repo.findAssessmentsForTerm(classId, termId, orgId),
      this.repo.findManualScores(classId, termId, orgId, studentId),
      this.repo.findEnrollmentDatesByClass(classId, orgId),
      this.repo.findGradingOverridesByClass(classId, orgId),
    ]);

    if (!scheme) return;

    const categories = componentsToCategories(scheme.components);

    const gradingScale = await this.resolveGradingScale(cls, orgId);
    if (!gradingScale) return;
    const ranges = gradingScale.ranges as unknown as GradeRange[];

    const studentSubmissions = submissions.filter(
      (s: any) => s.student_id === studentId,
    );

    const { excludedAssessmentIds } = this.buildInclusionMaps(
      allAssessments,
      new Map(enrollmentDates.map((e) => [e.student_id, e.created_at])),
      new Map(overrides.map((o) => [`${o.assessment_id}:${o.student_id}`, o])),
      studentId,
    );

    const finalScore = this.core.computeWeightedScore(
      studentSubmissions,
      manualScores,
      allAssessments,
      categories,
      { excludedAssessmentIds },
    );
    const finalGrade = this.core.resolveGrade(finalScore, ranges);

    await this.repo.upsert({
      orgId,
      studentId,
      classId,
      termId,
      finalScore,
      finalGrade,
    });
  }

  async computeGrades(
    classId: string,
    termId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const enrolledStudentIds = cls.enrollments.map((e: any) => e.student_id);
    if (enrolledStudentIds.length === 0) {
      return { computed: 0, message: 'No active enrollments.' };
    }

    const scheme = await this.repo.findGradingSchemeForClass(classId, orgId);
    if (!scheme)
      throw new NotFoundException('No grading scheme found for this class.');
    const categories = componentsToCategories(scheme.components);

    const gradingScale = await this.resolveGradingScale(cls, orgId);
    if (!gradingScale)
      throw new NotFoundException('No grading scale found for this class.');
    const ranges = gradingScale.ranges as unknown as GradeRange[];

    const [
      submissions,
      allAssessments,
      manualScores,
      enrollmentDates,
      overrides,
    ] = await Promise.all([
      this.repo.findSubmissionsForTerm(classId, termId, orgId),
      this.repo.findAssessmentsForTerm(classId, termId, orgId),
      this.repo.findManualScores(classId, termId, orgId),
      this.repo.findEnrollmentDatesByClass(classId, orgId),
      this.repo.findGradingOverridesByClass(classId, orgId),
    ]);

    let computed = 0;
    for (const studentId of enrolledStudentIds) {
      const studentSubmissions = submissions.filter(
        (s: any) => s.student_id === studentId,
      );
      const studentManuals = manualScores.filter(
        (m: any) => m.student_id === studentId,
      );

      const { excludedAssessmentIds } = this.buildInclusionMaps(
        allAssessments,
        new Map(enrollmentDates.map((e) => [e.student_id, e.created_at])),
        new Map(
          overrides.map((o) => [`${o.assessment_id}:${o.student_id}`, o]),
        ),
        studentId,
      );

      const finalScore = this.core.computeWeightedScore(
        studentSubmissions,
        studentManuals,
        allAssessments,
        categories,
        { excludedAssessmentIds },
      );
      const finalGrade = this.core.resolveGrade(finalScore, ranges);

      await this.repo.upsert({
        orgId,
        studentId,
        classId,
        termId,
        finalScore,
        finalGrade,
      });
      computed++;
    }

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'grades_computed',
      entityType: 'class',
      entityId: classId,
      metadata: { termId, studentsComputed: computed },
    });

    return { computed, message: `Grades computed for ${computed} student(s).` };
  }

  async setManualScore(
    classId: string,
    termId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
    dto: SetManualScoreDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);

    const grade = await this.repo.findByStudent(
      studentId,
      classId,
      termId,
      orgId,
    );
    if (grade?.is_locked) {
      throw new ForbiddenException(
        'Grade is locked. Admin must unlock before manual scores can be changed.',
      );
    }

    const saved = await this.repo.upsertManualScore({
      orgId,
      classId,
      studentId,
      termId,
      category: dto.category,
      score: dto.score,
    });

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'manual_score_set',
      entityType: 'class',
      entityId: classId,
      metadata: { termId, studentId, category: dto.category, score: dto.score },
    });

    return saved;
  }

  // Resolve which assessments are excluded for a single student by the
  // late-enrollment rule. Returns the ids to drop from grading plus the
  // per-assessment reason (Phase 2) for display in the UI.
  private buildInclusionMaps(
    allAssessments: any[],
    enrollmentDatesByStudent: Map<string, Date>,
    overridesByKey: Map<string, { include: boolean }>,
    studentId: string,
  ): {
    excludedAssessmentIds: Set<string>;
    reasons: Map<string, AssessmentInclusionReason>;
  } {
    const excludedAssessmentIds = new Set<string>();
    const reasons = new Map<string, AssessmentInclusionReason>();

    for (const assessment of allAssessments) {
      const decision = resolveAssessmentInclusion({
        assessmentEffectiveDate:
          assessment.release_date ?? assessment.created_at,
        enrollmentDate: enrollmentDatesByStudent.get(studentId),
        override: overridesByKey.get(`${assessment.id}:${studentId}`) ?? null,
        assessmentDeletedAt: assessment.deleted_at ?? null,
      });
      reasons.set(assessment.id, decision.reason);
      if (!decision.included) excludedAssessmentIds.add(assessment.id);
    }

    return { excludedAssessmentIds, reasons };
  }

  private async buildTermResult(
    classId: string,
    termId: string,
    termName: string,
    orgId: string,
    cls: any,
    semesterInfo?: { id: string; name: string },
  ) {
    const enrolledStudentIds: string[] = cls.enrollments.map(
      (e: any) => e.student_id,
    );
    const [
      submissions,
      grades,
      manualScores,
      allAssessments,
      scheme,
      studentProfiles,
      enrollmentDates,
      overrides,
    ] = await Promise.all([
      this.repo.findSubmissionsForTerm(classId, termId, orgId),
      this.repo.findByClassAndTerm(classId, termId, orgId),
      this.repo.findManualScores(classId, termId, orgId),
      this.repo.findAssessmentsForTerm(classId, termId, orgId),
      this.repo.findGradingSchemeForClass(classId, orgId),
      this.repo.findStudentProfiles(enrolledStudentIds),
      this.repo.findEnrollmentDatesByClass(classId, orgId),
      this.repo.findGradingOverridesByClass(classId, orgId),
    ]);

    const enrollmentDateByStudent = new Map(
      enrollmentDates.map((e) => [e.student_id, e.created_at]),
    );
    const overridesByKey = new Map(
      overrides.map((o) => [`${o.assessment_id}:${o.student_id}`, o]),
    );

    const categories = scheme ? componentsToCategories(scheme.components) : [];
    const gradeMap = new Map(grades.map((g) => [g.student_id, g]));

    const students = enrolledStudentIds.map((studentId) => {
      const profile = studentProfiles.get(studentId);
      const studentSubs = submissions.filter(
        (s: any) => s.student_id === studentId,
      );
      const studentManuals = manualScores.filter(
        (m: any) => m.student_id === studentId,
      );

      const submittedAssessmentIds = new Set(
        studentSubs.map((s: any) => s.assessment_id),
      );

      const assessmentScores: any[] = studentSubs.map((s: any) => ({
        assessmentId: s.assessment_id,
        submissionId: s.id,
        type: s.assessment.type,
        title: s.assessment.title ?? null,
        score: s.score,
        manualScore: s.manual_score,
        totalItems: s.assessment.total_items,
        status: s.status,
        gradingMode: s.assessment?.grading_mode ?? 'system',
        systemSectionScore: s.system_section_score ?? null,
        manualSectionScore: s.manual_section_score ?? null,
        isMissed: s.is_missed ?? false,
        isExempted: s.is_exempted ?? false,
        created_at: s.assessment.created_at ?? null,
      }));

      // Include all non-deleted assessments the student hasn't submitted to
      for (const assessment of allAssessments) {
        if (!submittedAssessmentIds.has(assessment.id)) {
          assessmentScores.push({
            assessmentId: assessment.id,
            submissionId: null,
            type: assessment.type,
            title: assessment.title ?? null,
            score: null,
            manualScore: null,
            totalItems: assessment.total_items ?? 0,
            status: 'not_started',
            gradingMode: assessment.grading_mode ?? 'system',
            systemSectionScore: null,
            manualSectionScore: null,
            isMissed: false,
            isExempted: false,
            created_at: assessment.created_at ?? null,
          });
        }
      }

      // Late-enrollment rule: which assessments count for this student, and why.
      const { excludedAssessmentIds, reasons } = this.buildInclusionMaps(
        allAssessments,
        enrollmentDateByStudent,
        overridesByKey,
        studentId,
      );
      for (const scoreEntry of assessmentScores) {
        scoreEntry.included = !excludedAssessmentIds.has(
          scoreEntry.assessmentId,
        );
        scoreEntry.inclusionReason =
          reasons.get(scoreEntry.assessmentId) ?? 'included';
      }

      // Compute total active weight (sum of weights of categories with at least one valid score)
      const totalActiveWeight = categories.reduce((sum, cat) => {
        if (cat.type === 'manual') {
          return studentManuals.some(
            (m) => m.category.toLowerCase() === cat.name.toLowerCase(),
          )
            ? sum + cat.weight
            : sum;
        }
        const catAssessments = allAssessments.filter(
          (a) => a.type === cat.type,
        );
        const hasActive = catAssessments.some((a) =>
          studentSubs.some(
            (s) =>
              s.assessment_id === a.id &&
              s.status !== 'exempted' &&
              !s.is_exempted,
          ),
        );
        return hasActive ? sum + cat.weight : sum;
      }, 0);

      const categoryBreakdown = this.core.buildCategoryBreakdown(
        studentSubs,
        studentManuals,
        allAssessments,
        categories,
        totalActiveWeight,
        { excludedAssessmentIds },
      );

      return {
        studentId,
        studentName: profile?.name ?? 'Unknown',
        studentCode: profile?.code ?? '',
        grade: gradeMap.get(studentId) ?? null,
        assessmentScores,
        categoryBreakdown,
      };
    });

    return {
      termId,
      termName,
      students,
      ...(semesterInfo
        ? { semesterId: semesterInfo.id, semesterName: semesterInfo.name }
        : {}),
    };
  }

  private async resolveGradingScale(cls: any, orgId: string) {
    const subject = await this.repo.findSubjectLevel(cls.subject_id, orgId);
    if (!subject) return null;

    const programId = subject.program_id;
    if (programId) {
      return this.repo.findGradingScale(programId, cls.school_year_id, orgId);
    }

    throw new NotFoundException(
      'Subject has no program. Cannot determine grading scale.',
    );
  }

  private async assertEducatorOwnsClass(
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const cls = await this.repo['db'].class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
    });
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }
    return cls;
  }
}

// src/modules/grade/grade.repository.ts
import { Injectable } from '@nestjs/common';
import { DatabaseService } from 'src/core/database/database.provider';
import { Prisma } from '@prisma/client';

type GradingSchemeWithComponents = Prisma.GradingSchemeGetPayload<{
  include: { components: true };
}>;
@Injectable()
export class GradeRepository {
  constructor(private db: DatabaseService) {}

  // ───────── FIND / QUERY ─────────

  async findByClass(classId: string, orgId: string) {
    return this.db.grade.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
      },
    });
  }

  async findByClassAndTerm(classId: string, termId: string, orgId: string) {
    return this.db.grade.findMany({
      where: {
        class_id: classId,
        term_id: termId,
        org_id: orgId,
      },
    });
  }

  async findByStudent(
    studentId: string,
    classId: string,
    termId: string,
    orgId: string,
  ) {
    return this.db.grade.findFirst({
      where: {
        student_id: studentId,
        class_id: classId,
        term_id: termId,
        org_id: orgId,
      },
    });
  }

  // ───────── UPSERT GRADE ─────────

  async upsert(data: {
    orgId: string;
    studentId: string;
    classId: string;
    termId: string;
    finalScore: number;
    finalGrade: string;
  }) {
    return this.db.grade.upsert({
      where: {
        org_id_student_id_class_id_term_id: {
          org_id: data.orgId,
          student_id: data.studentId,
          class_id: data.classId,
          term_id: data.termId,
        },
      },
      update: {
        final_score: data.finalScore,
        final_grade: data.finalGrade,
      },
      create: {
        org_id: data.orgId,
        student_id: data.studentId,
        class_id: data.classId,
        term_id: data.termId,
        final_score: data.finalScore,
        final_grade: data.finalGrade,
      },
    });
  }

  // ───────── LOCK / UNLOCK ─────────

  async publishByClass(classId: string, orgId: string) {
    return this.db.grade.updateMany({
      where: { class_id: classId, org_id: orgId },
      data: { is_locked: true, locked_at: new Date() },
    });
  }

  async unlockByClass(classId: string, orgId: string) {
    return this.db.grade.updateMany({
      where: { class_id: classId, org_id: orgId },
      data: { is_locked: false, locked_at: null },
    });
  }

  async publishByStudent(studentId: string, termId: string, orgId: string) {
    return this.db.grade.updateMany({
      where: { student_id: studentId, term_id: termId, org_id: orgId },
      data: { is_locked: true, locked_at: new Date() },
    });
  }

  async unlockByStudent(studentId: string, termId: string, orgId: string) {
    return this.db.grade.updateMany({
      where: { student_id: studentId, term_id: termId, org_id: orgId },
      data: { is_locked: false, locked_at: null },
    });
  }

  // ───────── ASSESSMENTS (for computation) ─────────

  async findAssessmentsForTerm(classId: string, termId: string, orgId: string) {
    return this.db.assessment.findMany({
      where: {
        org_id: orgId,
        class_id: classId,
        term_id: termId,
        deleted_at: null,
      },
      select: {
        id: true,
        type: true,
        title: true,
        total_items: true,
        grading_mode: true,
        show_breakdown: true,
        is_published: true,
        manual_max_score: true,
        release_date: true,
        created_at: true,
      },
      orderBy: { created_at: 'asc' },
    });
  }

  async registerAssessmentForAllStudents(
    assessmentId: string,
    classId: string,
    orgId: string,
  ) {
    const enrollments = await this.db.enrollment.findMany({
      where: { class_id: classId, org_id: orgId, status: 'active' },
      select: { student_id: true },
    });
    if (enrollments.length === 0) return 0;

    const existing = await this.db.submission.findMany({
      where: { assessment_id: assessmentId },
      select: { student_id: true },
    });
    const existingIds = new Set(existing.map((s: any) => s.student_id));

    const newSubs: any[] = enrollments
      .filter((e) => !existingIds.has(e.student_id))
      .map((e) => ({
        org_id: orgId,
        assessment_id: assessmentId,
        student_id: e.student_id,
        status: 'draft',
        score: null,
        manual_score: null,
        submitted_at: null,
      }));

    if (newSubs.length > 0) {
      await this.db.submission.createMany({ data: newSubs });
    }
    return newSubs.length;
  }

  // ───────── SUBMISSIONS (for computation) ─────────

  async findSubmissionsForTerm(classId: string, termId: string, orgId: string) {
    return this.db.submission.findMany({
      where: {
        org_id: orgId,
        assessment: {
          class_id: classId,
          term_id: termId,
        },
      },
      include: {
        assessment: {
          select: {
            id: true,
            type: true,
            title: true,
            total_items: true,
            term_id: true,
            grading_mode: true,
            created_at: true,
          },
        },
      },
    });
  }

  // ───────── GRADING SCHEME (for weights) ─────────

  async findGradingSchemeForClass(
    classId: string,
    orgId: string,
  ): Promise<GradingSchemeWithComponents | null> {
    const classScheme = await this.db.gradingScheme.findFirst({
      where: { class_id: classId, org_id: orgId },
      include: { components: true },
    });
    if (classScheme) return classScheme;

    return this.db.gradingScheme.findFirst({
      where: { org_id: orgId, is_default: true },
      include: { components: true },
    });
  }

  // ───────── GRADING SCALE ─────────

  async findGradingScale(
    programId: string,
    schoolYearId: string,
    orgId: string,
  ) {
    const assignment = await this.db.gradingScaleAssignment.findFirst({
      where: {
        org_id: orgId,
        program_id: programId,
        school_year_id: schoolYearId,
      },
      include: { grading_scale: true },
    });
    return assignment?.grading_scale ?? null;
  }

  // ───────── CLASS INFO ─────────

  async findClassWithSubject(classId: string, orgId: string) {
    return this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      include: {
        enrollments: {
          where: { status: 'active' },
          select: { student_id: true },
        },
      },
    });
  }

  // Class-level enrollment dates — Enrollment.created_at is "when did this
  // student enroll into the class", the field GradeCoreService needs for the
  // late-enrollment exclusion rule. Always org-scoped.
  async findEnrollmentDatesByClass(
    classId: string,
    orgId: string,
  ): Promise<{ student_id: string; created_at: Date }[]> {
    return this.db.enrollment.findMany({
      where: { class_id: classId, org_id: orgId, status: 'active' },
      select: { student_id: true, created_at: true },
    });
  }

  // Educator inclusion/exclusion overrides for every assessment in a class.
  // Always org-scoped per the Phase 1 constraint.
  async findGradingOverridesByClass(classId: string, orgId: string) {
    return this.db.assessmentGradingOverride.findMany({
      where: {
        org_id: orgId,
        assessment: { class_id: classId },
      },
    });
  }

  // ───────── OVERRIDE API (Phase 3) ─────────

  // Every non-deleted assessment in a class across all terms, with the dates
  // needed to resolve effective date and status. Org-scoped.
  async findClassAssessments(classId: string, orgId: string) {
    return this.db.assessment.findMany({
      where: { class_id: classId, org_id: orgId, deleted_at: null },
      select: {
        id: true,
        title: true,
        type: true,
        total_items: true,
        grading_mode: true,
        release_date: true,
        end_date: true,
        created_at: true,
      },
      orderBy: { created_at: 'asc' },
    });
  }

  // Active enrollment row for a student in a class (soft-deleted rows are
  // excluded by filtering status). Org-scoped.
  async getActiveEnrollment(classId: string, studentId: string, orgId: string) {
    return this.db.enrollment.findFirst({
      where: {
        class_id: classId,
        student_id: studentId,
        org_id: orgId,
        status: 'active',
      },
    });
  }

  async findAssessmentOverride(
    assessmentId: string,
    studentId: string,
    orgId: string,
  ) {
    return this.db.assessmentGradingOverride.findFirst({
      where: {
        assessment_id: assessmentId,
        student_id: studentId,
        org_id: orgId,
      },
    });
  }

  async findAssessmentInClass(
    assessmentId: string,
    classId: string,
    orgId: string,
  ) {
    return this.db.assessment.findFirst({
      where: {
        id: assessmentId,
        class_id: classId,
        org_id: orgId,
        deleted_at: null,
      },
      select: { id: true, title: true },
    });
  }

  async upsertAssessmentOverride(data: {
    orgId: string;
    assessmentId: string;
    studentId: string;
    include: boolean;
    reason?: string | null;
    createdBy: string;
  }) {
    return this.db.assessmentGradingOverride.upsert({
      where: {
        assessment_id_student_id: {
          assessment_id: data.assessmentId,
          student_id: data.studentId,
        },
      },
      create: {
        org_id: data.orgId,
        assessment_id: data.assessmentId,
        student_id: data.studentId,
        include: data.include,
        reason: data.reason ?? null,
        created_by: data.createdBy,
      },
      update: {
        include: data.include,
        reason: data.reason ?? null,
        created_by: data.createdBy,
      },
    });
  }

  async deleteAssessmentOverride(
    assessmentId: string,
    studentId: string,
    orgId: string,
  ) {
    return this.db.assessmentGradingOverride.deleteMany({
      where: {
        assessment_id: assessmentId,
        student_id: studentId,
        org_id: orgId,
      },
    });
  }

  // A student's submissions across every assessment in a class. Org-scoped.
  async findSubmissionsByStudentInClass(
    classId: string,
    studentId: string,
    orgId: string,
  ) {
    return this.db.submission.findMany({
      where: {
        org_id: orgId,
        student_id: studentId,
        assessment: { class_id: classId, deleted_at: null },
      },
      include: {
        assessment: {
          select: {
            id: true,
            type: true,
            title: true,
            total_items: true,
            grading_mode: true,
            release_date: true,
            end_date: true,
            created_at: true,
          },
        },
      },
    });
  }

  async findSubjectLevel(subjectId: string, orgId: string) {
    return this.db.subject.findFirst({
      where: { id: subjectId, org_id: orgId },
      select: { level_id: true, program_id: true },
    });
  }

  async findSemestersBySchoolYear(schoolYearId: string) {
    return this.db.semester.findMany({
      where: { school_year_id: schoolYearId },
      orderBy: { start_date: 'asc' },
    });
  }

  async findTemplateTermsByClass(classId: string, orgId: string) {
    // Get the class → subject → program → semester template assignment → terms with date ranges
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { subject_id: true, semester_id: true },
    });
    if (!cls) return [];

    const subject = await this.db.subject.findFirst({
      where: { id: cls.subject_id },
      select: { program_id: true },
    });
    if (!subject?.program_id) return [];

    const assignment = await this.db.programSemesterAssignment.findUnique({
      where: { program_id: subject.program_id },
      include: {
        template: {
          include: {
            semesters: {
              orderBy: { order_index: 'asc' },
              include: {
                terms: { orderBy: { order_index: 'asc' } },
              },
            },
          },
        },
        termDates: true,
      },
    });
    if (!assignment) return [];

    // Scope to the class's actual semester date range
    let classSemStart: Date | null = null;
    let classSemEnd: Date | null = null;
    if (cls.semester_id) {
      const actualSem = await this.db.semester.findUnique({
        where: { id: cls.semester_id },
        select: { start_date: true, end_date: true },
      });
      if (actualSem) {
        classSemStart = actualSem.start_date;
        classSemEnd = actualSem.end_date;
      }
    }

    const termDatesMap = new Map<string, { start: Date; end: Date }>();
    for (const td of assignment.termDates) {
      termDatesMap.set(td.term_id, {
        start: new Date(td.start_date),
        end: new Date(td.end_date),
      });
    }

    const result: {
      id: string;
      name: string;
      semesterName: string;
      semesterIndex: number;
    }[] = [];

    for (let si = 0; si < assignment.template.semesters.length; si++) {
      const sem = assignment.template.semesters[si];

      // Filter to semesters overlapping the class's actual semester
      if (classSemStart && classSemEnd) {
        const semDates = sem.terms
          .map((t) => termDatesMap.get(t.id))
          .filter(Boolean) as { start: Date; end: Date }[];

        if (semDates.length === 0) continue;

        const semStart = new Date(
          Math.min(...semDates.map((d) => d.start.getTime())),
        );
        const semEnd = new Date(
          Math.max(...semDates.map((d) => d.end.getTime())),
        );

        if (semEnd < classSemStart || semStart > classSemEnd) continue;
      }

      for (const term of sem.terms) {
        result.push({
          id: term.id,
          name: term.name,
          semesterName: sem.name,
          semesterIndex: si + 1,
        });
      }
    }

    return result;
  }

  // ───────── MANUAL SCORES ─────────

  async findManualScores(
    classId: string,
    termId: string,
    orgId: string,
    studentId?: string,
  ) {
    return this.db.manualScore.findMany({
      where: {
        class_id: classId,
        term_id: termId,
        org_id: orgId,
        ...(studentId ? { student_id: studentId } : {}),
      },
    });
  }

  async upsertManualScore(data: {
    orgId: string;
    classId: string;
    studentId: string;
    termId: string;
    category: string;
    score: number;
  }) {
    return this.db.manualScore.upsert({
      where: {
        org_id_class_id_student_id_term_id_category: {
          org_id: data.orgId,
          class_id: data.classId,
          student_id: data.studentId,
          term_id: data.termId,
          category: data.category,
        },
      },
      update: { score: data.score },
      create: {
        org_id: data.orgId,
        class_id: data.classId,
        student_id: data.studentId,
        term_id: data.termId,
        category: data.category,
        score: data.score,
      },
    });
  }

  // ───────── TERMS ─────────

  async findTermsBySemester(semesterId: string) {
    const semester = await this.db.semester.findUnique({
      where: { id: semesterId },
      include: { terms: { orderBy: { order_index: 'asc' } } },
    });
    return semester?.terms ?? [];
  }

  async setAssessmentVisibility(assessmentId: string, showBreakdown: boolean) {
    return this.db.assessment.update({
      where: { id: assessmentId },
      data: { show_breakdown: showBreakdown },
    });
  }

  async findStudentProfiles(
    studentIds: string[],
  ): Promise<Map<string, { name: string; code: string }>> {
    const accounts = await this.db.account.findMany({
      where: { id: { in: studentIds } },
      include: { profile: true },
    });

    const map = new Map<string, { name: string; code: string }>();
    for (const account of accounts) {
      const meta = (account.profile?.metadata ?? {}) as Record<string, any>;
      map.set(account.id, {
        name: account.profile?.full_name ?? 'Unknown',
        code: meta.studentId ?? '',
      });
    }
    return map;
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { GradeRepository } from './grade.repository';
import { AuditLogService } from '../audit-log/audit-log.service';
import { SetManualScoreDto } from './dto/grade.dto';

// TODO: Add a `type` column to GradingSchemeComponent in schema.prisma
// (e.g. type String @default("manual")) so components can map to assessment.type.
// Until then, component.name.toLowerCase() is used as the type discriminator.
interface SchemeCategory {
  name: string; // e.g. "Quiz", "Exam", "Activity"
  type: string; // maps to assessment.type: quiz | exam | activity | manual
  weight: number; // e.g. 0.3 = 30%
  maxScore?: number | null;
  is_optional: boolean;
}

interface GradeRange {
  minPercent: number;
  maxPercent: number;
  gradeValue: string;
  remark: string;
  isPassing: boolean;
}

function componentsToCategories(components: any[]): SchemeCategory[] {
  return components.map((c) => ({
    name: c.name,
    type: c.type ?? c.name.toLowerCase(), // use explicit type if present, else derive from name
    weight: c.weight,
    maxScore: c.max_score ?? c.maxScore ?? null,
    is_optional: c.is_optional,
  }));
}

@Injectable()
export class GradeService {
  constructor(
    private readonly repo: GradeRepository,
    private readonly auditLog: AuditLogService,
  ) {}

  async publishAllByClass(classId: string, orgId: string) {
    return this.repo.publishByClass(classId, orgId);
  }

  async unlockAllByClass(classId: string, orgId: string) {
    return this.repo.unlockByClass(classId, orgId);
  }

  async computeAndSaveGrade(data: {
    orgId: string;
    studentId: string;
    classId: string;
    termId: string;
    finalScore: number;
    finalGrade: string;
  }) {
    return this.repo.upsert(data);
  }

  async getClassGrades(classId: string, orgId: string) {
    return this.repo.findByClass(classId, orgId);
  }

  async getGradesByClass(classId: string, orgId: string, educatorId: string) {
    console.log('[GradeService] getGradesByClass called — new path');
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const terms = await this.repo.findTemplateTermsByClass(classId, orgId);
    console.log(
      '[GradeService] terms from template:',
      terms.map((t) => ({ id: t.id, name: t.name })),
    );

    const results: any[] = [];

    for (const term of terms) {
      const termResult = await this.buildTermResult(
        classId,
        term.id,
        term.name,
        orgId,
        cls,
        { id: term.semesterIndex.toString(), name: term.semesterName },
      );
      results.push(termResult);
    }

    return results;
  }

  async getGradesByTerm(
    classId: string,
    termId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const terms = await this.repo.findTemplateTermsByClass(classId, orgId);
    const term = terms.find((t) => t.id === termId);

    return this.buildTermResult(
      classId,
      termId,
      term?.name ?? '',
      orgId,
      cls,
      term
        ? { id: term.semesterIndex.toString(), name: term.semesterName }
        : undefined,
    );
  }

  async computeGrades(
    classId: string,
    termId: string,
    orgId: string,
    educatorId: string,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);
    const cls = await this.repo.findClassWithSubject(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const enrolledStudentIds = cls.enrollments.map((e) => e.student_id);
    if (enrolledStudentIds.length === 0) {
      return { computed: 0, message: 'No active enrollments.' };
    }

    const scheme = await this.repo.findGradingSchemeForClass(classId, orgId);
    if (!scheme)
      throw new NotFoundException('No grading scheme found for this class.');
    const categories = componentsToCategories(scheme.components);

    const gradingScale = await this.resolveGradingScale(cls, orgId);
    if (!gradingScale)
      throw new NotFoundException('No grading scale found for this class.');
    const ranges = gradingScale.ranges as unknown as GradeRange[];

    const submissions = await this.repo.findSubmissionsForTerm(
      classId,
      termId,
      orgId,
    );
    const manualScores = await this.repo.findManualScores(
      classId,
      termId,
      orgId,
    );

    let computed = 0;
    for (const studentId of enrolledStudentIds) {
      const studentSubmissions = submissions.filter(
        (s) => s.student_id === studentId,
      );
      const studentManuals = manualScores.filter(
        (m) => m.student_id === studentId,
      );

      const finalScore = this.computeWeightedScore(
        studentSubmissions,
        studentManuals,
        categories,
      );
      const finalGrade = this.resolveGrade(finalScore, ranges);

      await this.repo.upsert({
        orgId,
        studentId,
        classId,
        termId,
        finalScore,
        finalGrade,
      });
      computed++;
    }

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'grades_computed',
      entityType: 'class',
      entityId: classId,
      metadata: { termId, studentsComputed: computed },
    });

    return { computed, message: `Grades computed for ${computed} student(s).` };
  }

  async setManualScore(
    classId: string,
    termId: string,
    studentId: string,
    orgId: string,
    educatorId: string,
    dto: SetManualScoreDto,
  ) {
    await this.assertEducatorOwnsClass(classId, orgId, educatorId);

    const grade = await this.repo.findByStudent(
      studentId,
      classId,
      termId,
      orgId,
    );
    if (grade?.is_locked) {
      throw new ForbiddenException(
        'Grade is locked. Admin must unlock before manual scores can be changed.',
      );
    }

    const saved = await this.repo.upsertManualScore({
      orgId,
      classId,
      studentId,
      termId,
      category: dto.category,
      score: dto.score,
    });

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'manual_score_set',
      entityType: 'class',
      entityId: classId,
      metadata: { termId, studentId, category: dto.category, score: dto.score },
    });

    return saved;
  }

  private async buildTermResult(
    classId: string,
    termId: string,
    termName: string,
    orgId: string,
    cls: any,
    semesterInfo?: { id: string; name: string },
  ) {
    const enrolledStudentIds: string[] = cls.enrollments.map(
      (e: any) => e.student_id,
    );

    const [
      submissions,
      grades,
      manualScores,
      scheme,
      studentProfiles,
      termAssessments,
    ] = await Promise.all([
      this.repo.findSubmissionsForTerm(classId, termId, orgId),
      this.repo.findByClassAndTerm(classId, termId, orgId),
      this.repo.findManualScores(classId, termId, orgId),
      this.repo.findGradingSchemeForClass(classId, orgId),
      this.repo.findStudentProfiles(enrolledStudentIds),
      this.repo.findAssessmentsForTerm(classId, termId, orgId), // was dropped before
    ]);

    const categories = scheme ? componentsToCategories(scheme.components) : [];
    const gradeMap = new Map(grades.map((g) => [g.student_id, g]));

    // Key: `${studentId}:${assessmentId}` → submission row
    const subLookup = new Map<string, any>();
    for (const s of submissions) {
      subLookup.set(`${s.student_id}:${s.assessment_id}`, s);
    }

    const students = enrolledStudentIds.map((studentId) => {
      const profile = studentProfiles.get(studentId);
      const studentSubs = submissions.filter((s) => s.student_id === studentId);
      const studentManuals = manualScores.filter(
        (m) => m.student_id === studentId,
      );

      // Build one entry per term assessment regardless of submission existence
      const assessmentScores = termAssessments.map((a) => {
        const s = subLookup.get(`${studentId}:${a.id}`);
        return {
          assessmentId: a.id,
          type: a.type,
          title: a.title ?? null,
          score: s?.score ?? null,
          manualScore: s?.manual_score ?? null,
          totalItems: a.total_items,
          status: s?.status ?? 'not_started',
          isMissed: s?.is_missed ?? false,
          isExempted: s?.is_exempted ?? false,
          created_at: a.created_at,
          submissionId: s?.id ?? undefined,
        };
      });

      const totalActiveWeight = categories.reduce((sum, cat) => {
        if (cat.type === 'manual') {
          return studentManuals.some(
            (m) => m.category.toLowerCase() === cat.name.toLowerCase(),
          )
            ? sum + cat.weight
            : sum;
        }
        const hasActive = studentSubs.some(
          (s) =>
            s.assessment.type === cat.type &&
            s.status !== 'exempted' &&
            !s.is_exempted,
        );
        return hasActive ? sum + cat.weight : sum;
      }, 0);

      const categoryBreakdown = this.buildCategoryBreakdown(
        studentSubs,
        studentManuals,
        categories,
        totalActiveWeight,
      );

      return {
        studentId,
        studentName: profile?.name ?? 'Unknown',
        studentCode: profile?.code ?? '',
        grade: gradeMap.get(studentId) ?? null,
        assessmentScores,
        categoryBreakdown,
      };
    });

    return {
      termId,
      termName,
      students,
      ...(semesterInfo
        ? { semesterId: semesterInfo.id, semesterName: semesterInfo.name }
        : {}),
    };
  }

  private computeWeightedScore(
    submissions: any[],
    manualScores: any[],
    categories: SchemeCategory[],
  ): number {
    let totalWeightedScore = 0;
    let totalWeight = 0;

    for (const category of categories) {
      const weight = category.weight;

      if (category.type === 'manual') {
        const manual = manualScores.find(
          (m) => m.category.toLowerCase() === category.name.toLowerCase(),
        );
        if (manual !== undefined) {
          totalWeightedScore += manual.score * weight;
          totalWeight += weight;
        }
      } else {
        const categorySubs = submissions.filter(
          (s) =>
            s.assessment.type === category.type &&
            !s.is_exempted &&
            s.status !== 'exempted',
        );
        if (categorySubs.length === 0) {
          const anyExempted = submissions.some(
            (s) =>
              s.assessment.type === category.type &&
              (s.is_exempted || s.status === 'exempted'),
          );
          if (!anyExempted) continue;
          continue;
        }

        const percentages = categorySubs.map((s) => {
          const rawScore = s.manual_score ?? s.score ?? 0;
          const totalItems = s.assessment.total_items;
          return totalItems > 0 ? (rawScore / totalItems) * 100 : 0;
        });
        const average =
          percentages.reduce((sum, p) => sum + p, 0) / percentages.length;
        totalWeightedScore += average * weight;
        totalWeight += weight;
      }
    }

    if (totalWeight === 0) return 0;
    return Math.round((totalWeightedScore / totalWeight) * 100) / 100;
  }

  private buildCategoryBreakdown(
    submissions: any[],
    manualScores: any[],
    categories: SchemeCategory[],
    totalActiveWeight: number,
  ) {
    return categories.map((category) => {
      let rawAverage = 0;
      let manualScore: number | null = null;
      let isAllExempted = false;

      if (category.type === 'manual') {
        const manual = manualScores.find(
          (m) => m.category.toLowerCase() === category.name.toLowerCase(),
        );
        manualScore = manual?.score ?? null;
        if (manualScore != null) {
          rawAverage = manualScore;
        } else {
          isAllExempted = true;
        }
      } else {
        const categorySubs = submissions.filter(
          (s) => s.assessment.type === category.type,
        );

        const nonExemptedSubs = categorySubs.filter(
          (s) => !s.is_exempted && s.status !== 'exempted',
        );
        const exemptedCount = categorySubs.length - nonExemptedSubs.length;

        if (nonExemptedSubs.length > 0) {
          const percentages = nonExemptedSubs.map((s) => {
            const rawScore = s.manual_score ?? s.score ?? 0;
            return s.assessment.total_items > 0
              ? (rawScore / s.assessment.total_items) * 100
              : 0;
          });
          rawAverage =
            percentages.reduce((sum, p) => sum + p, 0) / percentages.length;
        }

        if (exemptedCount > 0 && nonExemptedSubs.length === 0) {
          isAllExempted = true;
        }
      }

      const effectiveWeight =
        totalActiveWeight > 0 && !isAllExempted
          ? Math.round((category.weight / totalActiveWeight) * 10000) / 100
          : null;

      return {
        category: category.name,
        type: category.type,
        weight: category.weight,
        rawAverage: isAllExempted ? null : Math.round(rawAverage * 100) / 100,
        manualScore,
        weightedScore: isAllExempted
          ? null
          : Math.round(rawAverage * category.weight * 100) / 100,
        isAllExempted,
        effectiveWeight,
      };
    });
  }

  private resolveGrade(score: number, ranges: GradeRange[]): string {
    const match = ranges.find(
      (r) => score >= r.minPercent && score <= r.maxPercent,
    );
    return match?.gradeValue ?? 'N/A';
  }

  private async resolveGradingScale(cls: any, orgId: string) {
    const subject = await this.repo.findSubjectLevel(cls.subject_id, orgId);
    if (!subject) return null;

    const programId = subject.program_id;
    if (programId) {
      return this.repo.findGradingScale(programId, cls.school_year_id, orgId);
    }

    throw new NotFoundException(
      'Subject has no program. Cannot determine grading scale.',
    );
  }

  private async resolveTerms(semesterId: string) {
    return this.repo.findTermsBySemester(semesterId);
  }

  private async assertEducatorOwnsClass(
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const cls = await this.repo['db'].class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
    });
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }
    return cls;
  }
}

import {
  Injectable,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { GradeRepository } from '../grade.repository';
import { EnrollmentRepository } from 'src/modules/enrollment/enrollment.repository';
import { GradeCoreService, SchemeCategory } from '../core/grade-core.service';

function componentsToCategories(components: any[]): SchemeCategory[] {
  return components.map((c) => ({
    name: c.name,
    type: c.type ?? c.name.toLowerCase(),
    weight: c.weight,
    maxScore: c.max_score ?? c.maxScore ?? null,
  }));
}

@Injectable()
export class GradeStudentService {
  constructor(
    private readonly gradeRepo: GradeRepository,
    private readonly enrollmentRepo: EnrollmentRepository,
    private readonly core: GradeCoreService,
  ) {}

  async getMyGrades(classId: string, studentId: string, orgId: string) {
    const enrollment = await this.enrollmentRepo.findOneByStudentAndClass(
      classId,
      studentId,
      orgId,
    );

    if (!enrollment) {
      throw new ForbiddenException('Not enrolled in this class.');
    }

    const cls = await this.gradeRepo.findClassWithSubject(classId, orgId);
    if (!cls) {
      throw new NotFoundException('Class not found.');
    }

    const terms = await this.gradeRepo.findTemplateTermsByClass(classId, orgId);

    // If the template has no terms (or can't be resolved), fall back to showing
    // whatever grade rows exist for this student (legacy behavior).
    if (terms.length === 0) {
      const grades = await this.gradeRepo.findByClass(classId, orgId);
      return grades
        .filter((g) => g.student_id === studentId)
        .map((g) => ({
          termId: g.term_id,
          termName: '',
          finalScore: g.final_score,
          finalGrade: g.is_locked ? g.final_grade : null,
          isReleased: g.is_locked,
          categoryBreakdown: [] as any[],
        }));
    }

    const results = await Promise.all(
      terms.map(async (term) => {
        const [grade, submissions, manualScores, assessments, scheme] =
          await Promise.all([
            this.gradeRepo.findByStudent(studentId, classId, term.id, orgId),
            this.gradeRepo.findSubmissionsForTerm(classId, term.id, orgId),
            this.gradeRepo.findManualScores(classId, term.id, orgId),
            this.gradeRepo.findAssessmentsForTerm(classId, term.id, orgId),
            this.gradeRepo.findGradingSchemeForClass(classId, orgId),
          ]);

        const studentSubs = submissions.filter(
          (s) => s.student_id === studentId,
        );
        const studentManuals = manualScores.filter(
          (m) => m.student_id === studentId,
        );

        const categories = scheme
          ? componentsToCategories(scheme.components)
          : [];

        const totalActiveWeight = categories.reduce((sum, cat) => {
          if (cat.type === 'manual') {
            return studentManuals.some(
              (m) => m.category.toLowerCase() === cat.name.toLowerCase(),
            )
              ? sum + cat.weight
              : sum;
          }
          const catAssessments = assessments.filter((a) => a.type === cat.type);
          const hasActive = catAssessments.some((a) =>
            studentSubs.some(
              (s) =>
                s.assessment_id === a.id &&
                s.status !== 'exempted' &&
                !s.is_exempted,
            ),
          );
          return hasActive ? sum + cat.weight : sum;
        }, 0);

        const categoryBreakdown = this.core.buildCategoryBreakdown(
          studentSubs,
          studentManuals,
          assessments,
          categories,
          totalActiveWeight,
        );

        return {
          termId: term.id,
          termName: term.name,
          semesterName: term.semesterName,
          semesterIndex: term.semesterIndex,
          finalScore: grade?.final_score ?? null,
          finalGrade: grade?.is_locked ? grade.final_grade : null,
          isReleased: grade?.is_locked ?? false,
          categoryBreakdown,
        };
      }),
    );

    return results;
  }
}

