import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { GradingSchemeComponentDto } from './dto/grading-scheme.dto';

const COMPONENTS_INCLUDE = {
  components: { orderBy: { created_at: 'asc' as const } },
};

function mapComponent(c: any) {
  return {
    id: c.id,
    orgId: c.org_id,
    gradingSchemeId: c.grading_scheme_id,
    name: c.name,
    type: c.type,
    weight: c.weight,
    maxScore: c.max_score,
    isOptional: c.is_optional,
    createdAt: c.created_at,
  };
}

function mapScheme(s: any) {
  return {
    id: s.id,
    orgId: s.org_id,
    classId: s.class_id,
    templateId: s.template_id,
    name: s.name,
    isLocked: s.is_locked,
    lockedAt: s.locked_at,
    createdAt: s.created_at,
    components: s.components?.map(mapComponent) ?? [],
  };
}

@Injectable()
export class GradingSchemeRepository {
  constructor(private readonly db: DatabaseService) {}

  async findByClassId(classId: string, orgId: string) {
    const scheme = await this.db.gradingScheme.findFirst({
      where: { class_id: classId, org_id: orgId },
      include: COMPONENTS_INCLUDE,
    });
    return scheme ? mapScheme(scheme) : null;
  }

  async findById(id: string, orgId: string) {
    const scheme = await this.db.gradingScheme.findFirst({
      where: { id, org_id: orgId },
      include: COMPONENTS_INCLUDE,
    });
    return scheme ? mapScheme(scheme) : null;
  }

  async create(
    orgId: string,
    classId: string,
    templateId: string | undefined,
    name: string,
    components: GradingSchemeComponentDto[],
  ) {
    const scheme = await this.db.gradingScheme.create({
      data: {
        org_id: orgId,
        class_id: classId,
        template_id: templateId ?? null,
        name,
        is_locked: false,
        locked_at: null,
        components: {
          create: components.map((c) => ({
            org_id: orgId,
            name: c.name,
            type: c.type,
            weight: c.weight,
            max_score: c.maxScore ?? null,
            is_optional: c.isOptional ?? false,
          })),
        },
      },
      include: COMPONENTS_INCLUDE,
    });
    return mapScheme(scheme);
  }

  async update(
    id: string,
    orgId: string,
    data: {
      name?: string;
      components?: GradingSchemeComponentDto[];
      templateId?: string | null;
    },
  ) {
    const updated = await this.db.$transaction(async (tx) => {
      if (data.name !== undefined) {
        await tx.gradingScheme.update({
          where: { id },
          data: { name: data.name },
        });
      }

      if (data.templateId !== undefined) {
        await tx.gradingScheme.update({
          where: { id },
          data: { template_id: data.templateId },
        });
      }

      if (data.components !== undefined) {
        await tx.gradingSchemeComponent.deleteMany({
          where: { grading_scheme_id: id },
        });
        await tx.gradingSchemeComponent.createMany({
          data: data.components.map((c) => ({
            org_id: orgId,
            grading_scheme_id: id,
            name: c.name,
            type: c.type,
            weight: c.weight,
            max_score: c.maxScore ?? null,
            is_optional: c.isOptional ?? false,
          })),
        });
      }

      return tx.gradingScheme.findUnique({
        where: { id },
        include: COMPONENTS_INCLUDE,
      });
    });

    return updated ? mapScheme(updated) : null;
  }

  async upsertForClass(
    orgId: string,
    classId: string,
    templateId: string | undefined,
    name: string,
    components: GradingSchemeComponentDto[],
  ) {
    const existing = await this.findByClassId(classId, orgId);

    if (existing) {
      return this.update(existing.id, orgId, {
        name,
        components,
        templateId,
      });
    }

    return this.create(orgId, classId, templateId, name, components);
  }

  async findClassIdsByProgram(
    programId: string,
    orgId: string,
    schoolYearId?: string,
  ): Promise<string[]> {
    // Resolve all course/strand/level IDs that belong to this program
    const [courses, strands, levels] = await Promise.all([
      this.db.course.findMany({
        where: { org_id: orgId, program_id: programId },
        select: { id: true },
      }),
      this.db.strand.findMany({
        where: { org_id: orgId, program_id: programId },
        select: { id: true },
      }),
      this.db.level.findMany({
        where: { org_id: orgId, program_id: programId },
        select: { id: true },
      }),
    ]);

    const courseIds = courses.map((c) => c.id);
    const strandIds = strands.map((s) => s.id);
    const levelIds = levels.map((l) => l.id);

    // Find all subjects linked to this program directly or via course/strand/level
    const subjects = await this.db.subject.findMany({
      where: {
        org_id: orgId,
        OR: [
          { program_id: programId },
          ...(courseIds.length ? [{ course_id: { in: courseIds } }] : []),
          ...(strandIds.length ? [{ strand_id: { in: strandIds } }] : []),
          ...(levelIds.length ? [{ level_id: { in: levelIds } }] : []),
        ],
      },
      select: { id: true },
    });

    const subjectIds = subjects.map((s) => s.id);
    if (subjectIds.length === 0) return [];

    const classes = await this.db.class.findMany({
      where: {
        org_id: orgId,
        deleted_at: null,
        subject_id: { in: subjectIds },
        ...(schoolYearId ? { school_year_id: schoolYearId } : {}),
      },
      select: { id: true },
    });

    return classes.map((c) => c.id);
  }

  async lockByClassId(classId: string) {
    return this.db.gradingScheme.updateMany({
      where: { class_id: classId },
      data: { is_locked: true, locked_at: new Date() },
    });
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { GradingSchemeRepository } from './grading-scheme.repository';
import { GradingSchemeTemplateService } from '@/modules/grading-scheme-template/grading-scheme-template.service';
import {
  CreateGradingSchemeDto,
  UpdateGradingSchemeDto,
  ApplyTemplateToClassDto,
  ApplyTemplateToProgramDto,
  GradingSchemeComponentDto,
} from './dto/grading-scheme.dto';

@Injectable()
export class GradingSchemeService {
  constructor(
    private readonly repo: GradingSchemeRepository,
    private readonly templateService: GradingSchemeTemplateService,
  ) {}

  private validateWeights(components: GradingSchemeComponentDto[]): void {
    if (components.length === 0) {
      throw new BadRequestException(
        'At least one grading scheme component is required.',
      );
    }

    const required = components.filter((c) => !c.isOptional);
    const total = required.reduce((sum, c) => sum + c.weight, 0);

    if (Math.round(total) !== 100) {
      throw new BadRequestException(
        `Required component weights must total exactly 100%. Current total: ${total}%.`,
      );
    }
  }

  async findByClass(classId: string, orgId: string) {
    return this.repo.findByClassId(classId, orgId);
  }

  async create(orgId: string, dto: CreateGradingSchemeDto) {
    const existing = await this.repo.findByClassId(dto.classId, orgId);

    if (existing) {
      throw new BadRequestException(
        'This class already has a grading scheme. Use update instead.',
      );
    }

    this.validateWeights(dto.components);

    return this.repo.create(
      orgId,
      dto.classId,
      dto.templateId,
      dto.name,
      dto.components,
    );
  }

  async update(id: string, orgId: string, dto: UpdateGradingSchemeDto) {
    const scheme = await this.repo.findById(id, orgId);

    if (!scheme) throw new NotFoundException('Grading scheme not found.');

    if (scheme.isLocked)
      throw new BadRequestException(
        'This grading scheme is locked and cannot be modified.',
      );

    if (dto.components) this.validateWeights(dto.components);

    const updated = await this.repo.update(id, orgId, {
      name: dto.name,
      components: dto.components,
    });

    if (!updated) throw new NotFoundException('Grading scheme not found.');

    return updated;
  }

  async applyTemplateToClass(orgId: string, dto: ApplyTemplateToClassDto) {
    const template = await this.templateService.findById(dto.templateId, orgId);

    const components: GradingSchemeComponentDto[] = template.components.map(
      (c) => ({
        name: c.name,
        type: c.type,
        weight: c.weight,
        maxScore: c.maxScore ?? undefined,
      }),
    );

    this.validateWeights(components);

    return this.repo.upsertForClass(
      orgId,
      dto.classId,
      dto.templateId,
      dto.name ?? template.name,
      components,
    );
  }

  async applyTemplateToProgram(orgId: string, dto: ApplyTemplateToProgramDto) {
    const template = await this.templateService.findById(dto.templateId, orgId);

    const classIds = await this.repo.findClassIdsByProgram(
      dto.programId,
      orgId,
    );

    if (classIds.length === 0) {
      throw new BadRequestException('No classes found under this program.');
    }

    const components: GradingSchemeComponentDto[] = template.components.map(
      (c) => ({
        name: c.name,
        type: c.type,
        weight: c.weight,
        maxScore: c.maxScore ?? undefined,
      }),
    );

    this.validateWeights(components);

    const results = await Promise.allSettled(
      classIds.map((classId) =>
        this.repo.upsertForClass(
          orgId,
          classId,
          dto.templateId,
          template.name,
          components,
        ),
      ),
    );

    const applied = results.filter((r) => r.status === 'fulfilled').length;
    const skipped = results.filter((r) => r.status === 'rejected').length;

    return { applied, skipped, total: classIds.length };
  }

  async lockForClass(classId: string) {
    return this.repo.lockByClassId(classId);
  }

  async getAllowedAssessmentTypes(
    classId: string,
    orgId: string,
  ): Promise<string[]> {
    const scheme = await this.repo.findByClassId(classId, orgId);
    if (!scheme) return [];
    return scheme.components.map((c) => c.type);
  }
}

