import {
  WebSocketGateway,
  WebSocketServer,
  OnGatewayConnection,
  OnGatewayDisconnect,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { DatabaseService } from '@/core/database/database.provider';
import { GroupyRepository } from './groupy.repository';

interface AuthPayload {
  sub: string;
  org_id: string | null;
  role: string;
  email: string;
}

@WebSocketGateway({
  namespace: 'groupy',
  cors: { origin: '*', credentials: true },
})
export class GroupyGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer() server: Server;
  private readonly logger = new Logger(GroupyGateway.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly config: ConfigService,
    private readonly groupyRepo: GroupyRepository,
    private readonly db: DatabaseService,
  ) {}

  private roomName(classId: string) {
    return `class:${classId}`;
  }

  // ── Connection ────────────────────────────────────────────────────────────

  async handleConnection(client: Socket) {
    try {
      const token =
        (client.handshake.auth?.token as string) ??
        (client.handshake.headers?.authorization as string)?.replace(
          'Bearer ',
          '',
        );

      if (!token) return this.kick(client, 'Missing token');

      const payload = this.verifyToken(token);
      if (!payload) return this.kick(client, 'Invalid token');
      if (!payload.org_id) return this.kick(client, 'Missing org');

      const classId = client.handshake.query?.classId as string;
      if (!classId) return this.kick(client, 'Missing classId');

      // Membership check — reject non-members before they join the room.
      const isMember = await this.groupyRepo.isClassMember(
        payload.sub,
        classId,
        payload.org_id,
      );
      if (!isMember) return this.kick(client, 'Not a member of this class');

      // Resolve display name
      const account = await this.db.account.findFirst({
        where: { id: payload.sub },
        include: { profile: true },
      });
      const name = account?.profile?.full_name ?? payload.email ?? 'Unknown';

      // Store auth on socket
      client.data.auth = payload;
      client.data.classId = classId;
      client.data.name = name;

      // Join socket.io room
      await client.join(this.roomName(classId));

      this.logger.log(
        `[groupy:${classId}] ${name} (${payload.role}) connected`,
      );
    } catch (err) {
      this.logger.error('handleConnection error', err);
      this.kick(client, 'Internal error');
    }
  }

  async handleDisconnect(client: Socket) {
    const classId = client.data?.classId;
    if (!classId) return;
    await client.leave(this.roomName(classId));
  }

  // ── Meeting join announcements (called by MeetingGateway) ─────────────────

  // Persist a "[name] joined" system message on the Groupy stream and push it
  // to anyone currently watching the class chat. Used when a student joins a
  // Groupy (ephemeral) meeting so everyone in the chat sees who is coming in.
  async announceMemberJoined(
    classId: string,
    orgId: string,
    accountId: string,
    name: string,
  ) {
    const message = await this.groupyRepo.createMessage({
      orgId,
      classId,
      senderAccountId: accountId,
      senderRole: 'student',
      senderName: name,
      type: 'system',
      body: `${name} joined`,
    });
    this.emitMessageNew(message);
    return message;
  }

  // ── Broadcast helpers (called by GroupyService) ───────────────────────────

  emitMessageNew(message: { class_id: string } & Record<string, unknown>) {
    this.server
      .to(this.roomName(message.class_id))
      .emit('groupy:message:new', message);
  }

  emitMessageDeleted(message: { id: string; class_id: string }) {
    this.server
      .to(this.roomName(message.class_id))
      .emit('groupy:message:deleted', { id: message.id });
  }

  emitReactionUpdated(args: {
    classId: string;
    messageId: string;
    accountId: string;
    reactionType: string;
  }) {
    this.server
      .to(this.roomName(args.classId))
      .emit('groupy:reaction:updated', {
        messageId: args.messageId,
        accountId: args.accountId,
        reactionType: args.reactionType,
      });
  }

  emitReactionRemoved(args: {
    classId: string;
    messageId: string;
    accountId: string;
  }) {
    this.server
      .to(this.roomName(args.classId))
      .emit('groupy:reaction:removed', {
        messageId: args.messageId,
        accountId: args.accountId,
      });
  }

  emitPollVoteUpdated(args: {
    classId: string;
    pollId: string;
    resultsSummary: unknown;
  }) {
    this.server
      .to(this.roomName(args.classId))
      .emit('groupy:poll:vote-updated', {
        pollId: args.pollId,
        resultsSummary: args.resultsSummary,
      });
  }

  emitPollClosed(args: { classId: string; pollId: string }) {
    this.server
      .to(this.roomName(args.classId))
      .emit('groupy:poll:closed', { pollId: args.pollId });
  }

  emitReadUpdated(args: {
    classId: string;
    accountId: string;
    lastReadMessageId: string;
  }) {
    this.server.to(this.roomName(args.classId)).emit('groupy:read:updated', {
      classId: args.classId,
      accountId: args.accountId,
      lastReadMessageId: args.lastReadMessageId,
    });
  }

  // ── Private helpers ───────────────────────────────────────────────────────

  private verifyToken(token: string): AuthPayload | null {
    try {
      return this.jwtService.verify<AuthPayload>(token, {
        secret: this.config.get<string>('JWT_SECRET'),
      });
    } catch {
      return null;
    }
  }

  private kick(client: Socket, reason: string) {
    client.emit('error', { message: reason });
    client.disconnect(true);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { GroupyMessageType, GroupyReactionType, Role } from '@prisma/client';

@Injectable()
export class GroupyRepository {
  constructor(private readonly db: DatabaseService) {}

  // ── Membership ──────────────────────────────────────────────────────────────
  // Live membership derived from Class.educator_id + active Enrollment rows.
  async isClassMember(
    accountId: string,
    classId: string,
    orgId: string,
  ): Promise<boolean> {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { educator_id: true },
    });
    if (!cls) return false;
    if (cls.educator_id === accountId) return true;

    const enrollment = await this.db.enrollment.findFirst({
      where: {
        class_id: classId,
        org_id: orgId,
        student_id: accountId,
        status: 'active',
      },
    });
    return !!enrollment;
  }

  // ── Messages ────────────────────────────────────────────────────────────────

  async createMessage(data: {
    orgId: string;
    classId: string;
    senderAccountId: string;
    senderRole: Role;
    senderName: string;
    senderProfileImage?: string | null;
    type: GroupyMessageType;
    body?: string;
    gifUrl?: string;
    stickerId?: string;
    pollId?: string;
  }) {
    return this.db.groupyMessage.create({
      data: {
        org_id: data.orgId,
        class_id: data.classId,
        sender_account_id: data.senderAccountId,
        sender_role: data.senderRole,
        sender_name: data.senderName,
        sender_profile_image: data.senderProfileImage ?? null,
        type: data.type,
        body: data.body ?? null,
        gif_url: data.gifUrl ?? null,
        sticker_id: data.stickerId ?? null,
        poll_id: data.pollId ?? null,
      },
      include: { reactions: true },
    });
  }

  async findMessages(args: {
    classId: string;
    orgId: string;
    cursorDate?: Date;
    limit: number;
  }) {
    return this.db.groupyMessage.findMany({
      where: {
        class_id: args.classId,
        org_id: args.orgId,
        ...(args.cursorDate ? { created_at: { lt: args.cursorDate } } : {}),
      },
      orderBy: { created_at: 'desc' },
      take: args.limit,
      include: { reactions: true },
    });
  }

  async findMessageById(id: string, orgId: string) {
    return this.db.groupyMessage.findFirst({
      where: { id, org_id: orgId },
      include: { reactions: true },
    });
  }

  async deleteMessage(id: string) {
    return this.db.groupyMessage.delete({ where: { id } });
  }

  // ── Reactions ───────────────────────────────────────────────────────────────

  async upsertReaction(args: {
    orgId: string;
    messageId: string;
    accountId: string;
    reactionType: GroupyReactionType;
  }) {
    return this.db.groupyReaction.upsert({
      where: {
        message_id_account_id: {
          message_id: args.messageId,
          account_id: args.accountId,
        },
      },
      create: {
        org_id: args.orgId,
        message_id: args.messageId,
        account_id: args.accountId,
        reaction_type: args.reactionType,
      },
      update: { reaction_type: args.reactionType },
    });
  }

  async deleteReaction(messageId: string, accountId: string) {
    return this.db.groupyReaction.deleteMany({
      where: { message_id: messageId, account_id: accountId },
    });
  }

  // ── Polls ───────────────────────────────────────────────────────────────────

  async createPoll(args: {
    orgId: string;
    classId: string;
    createdBy: string;
    senderRole: Role;
    senderName: string;
    senderProfileImage?: string | null;
    question: string;
    options: string[];
  }) {
    return this.db.$transaction(async (tx) => {
      const poll = await tx.groupyPoll.create({
        data: {
          org_id: args.orgId,
          class_id: args.classId,
          created_by: args.createdBy,
          question: args.question,
          is_closed: false,
        },
      });

      await tx.groupyPollOption.createMany({
        data: args.options.map((label, i) => ({
          poll_id: poll.id,
          label,
          order_index: i,
        })),
      });

      return tx.groupyMessage.create({
        data: {
          org_id: args.orgId,
          class_id: args.classId,
          sender_account_id: args.createdBy,
          sender_role: args.senderRole,
          sender_name: args.senderName,
          sender_profile_image: args.senderProfileImage ?? null,
          type: 'poll',
          body: null,
          poll_id: poll.id,
        },
        include: { reactions: true },
      });
    });
  }

  async findPollById(pollId: string, orgId: string) {
    return this.db.groupyPoll.findFirst({
      where: { id: pollId, org_id: orgId },
      include: {
        options: { orderBy: { order_index: 'asc' } },
      },
    });
  }

  async findVote(pollId: string, accountId: string) {
    return this.db.groupyPollVote.findFirst({
      where: { poll_id: pollId, account_id: accountId },
    });
  }

  async upsertVote(args: {
    pollId: string;
    optionId: string;
    accountId: string;
  }) {
    return this.db.groupyPollVote.upsert({
      where: {
        poll_id_account_id: {
          poll_id: args.pollId,
          account_id: args.accountId,
        },
      },
      create: {
        poll_id: args.pollId,
        option_id: args.optionId,
        account_id: args.accountId,
      },
      update: { option_id: args.optionId },
    });
  }

  async getPollResults(pollId: string) {
    return this.db.groupyPollOption.findMany({
      where: { poll_id: pollId },
      orderBy: { order_index: 'asc' },
      include: { _count: { select: { votes: true } } },
    });
  }

  async closePoll(pollId: string) {
    return this.db.groupyPoll.update({
      where: { id: pollId },
      data: { is_closed: true },
    });
  }

  // ── Meeting / read receipts ───────────────────────────────────────────────
  // Newest running groupy meeting for the class (ephemeral, not ended/deleted).
  async findActiveMeeting(classId: string, orgId: string) {
    return this.db.meeting.findFirst({
      where: {
        class_id: classId,
        org_id: orgId,
        is_ephemeral: true,
        deleted_at: null,
        status: { not: 'ended' },
      },
      orderBy: { created_at: 'desc' },
      select: { id: true, title: true },
    });
  }

  // One pointer per (class, account): the newest message that member has seen.
  async upsertReadReceipt(args: {
    orgId: string;
    classId: string;
    accountId: string;
    lastReadMessageId: string;
  }) {
    return this.db.groupyReadReceipt.upsert({
      where: {
        class_id_account_id: {
          class_id: args.classId,
          account_id: args.accountId,
        },
      },
      create: {
        org_id: args.orgId,
        class_id: args.classId,
        account_id: args.accountId,
        last_read_message_id: args.lastReadMessageId,
      },
      update: { last_read_message_id: args.lastReadMessageId },
    });
  }

  async getReadReceipt(classId: string, accountId: string) {
    return this.db.groupyReadReceipt.findUnique({
      where: {
        class_id_account_id: { class_id: classId, account_id: accountId },
      },
    });
  }

  // Roster: the class's educator + currently-active students, each with the
  // profile fields needed to render avatars and each one's last-read pointer.
  async listMembers(classId: string, orgId: string) {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { educator_id: true },
    });
    if (!cls) return [];

    const educator = await this.db.profile.findFirst({
      where: { account_id: cls.educator_id },
      select: {
        account_id: true,
        full_name: true,
        profile_image: true,
      },
    });

    const enrollments = await this.db.enrollment.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
        status: 'active',
      },
      select: { student_id: true },
    });

    const studentIds = enrollments
      .map((e) => e.student_id)
      .filter((sid) => sid !== cls.educator_id);
    const students = studentIds.length
      ? await this.db.profile.findMany({
          where: { account_id: { in: studentIds } },
          select: { account_id: true, full_name: true, profile_image: true },
        })
      : [];

    const profiles = educator
      ? [
          {
            account_id: educator.account_id,
            full_name: educator.full_name,
            profile_image: educator.profile_image,
            role: 'educator',
          },
          ...students.map((p) => ({
            account_id: p.account_id,
            full_name: p.full_name,
            profile_image: p.profile_image,
            role: 'student' as const,
          })),
        ]
      : students.map((p) => ({
          account_id: p.account_id,
          full_name: p.full_name,
          profile_image: p.profile_image,
          role: 'student' as const,
        }));

    if (!profiles.length) return [];

    const receipts = await this.db.groupyReadReceipt.findMany({
      where: {
        class_id: classId,
        org_id: orgId,
        account_id: { in: profiles.map((p) => p.account_id) },
      },
      select: { account_id: true, last_read_message_id: true },
    });
    const receiptByAccount = new Map(
      receipts.map((r) => [r.account_id, r.last_read_message_id]),
    );

    return profiles.map((p) => ({
      account_id: p.account_id,
      role: p.role,
      full_name: p.full_name,
      profile_image: p.profile_image,
      last_read_message_id: receiptByAccount.get(p.account_id) ?? null,
    }));
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { MeetingService } from '../meeting/meeting.service';
import { CreateMeetingDto } from '../meeting/dto/meeting.dto';
import { GroupyRepository } from './groupy.repository';
import { GroupyGateway } from './groupy.gateway';
import { GROUPY_STICKERS, getGroupyStickerById } from './data/stickers.data';
import { SendGroupyMessageDto, CreatePollDto } from './dto/groupy.dto';

interface CurrentUser {
  id: string;
  org_id?: string;
  role?: string;
  email?: string;
}

@Injectable()
export class GroupyService {
  constructor(
    private readonly groupyRepo: GroupyRepository,
    private readonly gateway: GroupyGateway,
    private readonly db: DatabaseService,
    private readonly meetingService: MeetingService,
  ) {}

  // ── Membership helper (used by every endpoint AND gateway event) ──────────

  isClassMember(accountId: string, classId: string, orgId: string) {
    return this.groupyRepo.isClassMember(accountId, classId, orgId);
  }

  private async assertMember(
    accountId: string,
    classId: string,
    orgId: string,
  ) {
    const isMember = await this.isClassMember(accountId, classId, orgId);
    if (!isMember) {
      throw new ForbiddenException('You are not a member of this class chat.');
    }
  }

  // ── GET /groupy/:classId/messages ─────────────────────────────────────────

  async listMessages(
    classId: string,
    orgId: string,
    accountId: string,
    cursor?: string,
    limit?: number,
  ) {
    await this.assertMember(accountId, classId, orgId);

    const l = limit ?? 50;
    let cursorDate: Date | undefined;
    if (cursor) {
      const c = await this.groupyRepo.findMessageById(cursor, orgId);
      if (!c || c.class_id !== classId) {
        throw new BadRequestException('Invalid cursor.');
      }
      cursorDate = c.created_at;
    }

    const messages = await this.groupyRepo.findMessages({
      classId,
      orgId,
      cursorDate,
      limit: l,
    });

    return {
      messages,
      nextCursor:
        messages.length === l ? messages[messages.length - 1].id : null,
      hasMore: messages.length === l,
    };
  }

  // ── POST /groupy/:classId/messages ────────────────────────────────────────

  async sendMessage(
    classId: string,
    orgId: string,
    user: CurrentUser,
    dto: SendGroupyMessageDto,
  ) {
    await this.assertMember(user.id, classId, orgId);

    const account = await this.db.account.findUnique({
      where: { id: user.id },
      include: { profile: true },
    });
    const senderName = account?.profile?.full_name ?? user.email ?? 'Unknown';
    const senderProfileImage = account?.profile?.profile_image ?? null;
    const senderRole = (user.role ?? 'student') as any;

    const type = dto.type ?? 'text';

    // Type-specific validation.
    let body: string | undefined;
    let gifUrl: string | undefined;
    let stickerId: string | undefined;
    if (type === 'text') {
      if (!dto.body) throw new BadRequestException('Message body is required.');
      body = dto.body;
    } else if (type === 'gif') {
      if (!dto.gifUrl) {
        throw new BadRequestException('gifUrl is required for GIF messages.');
      }
      gifUrl = dto.gifUrl;
    } else if (type === 'sticker') {
      if (!dto.stickerId) {
        throw new BadRequestException(
          'stickerId is required for sticker messages.',
        );
      }
      if (!getGroupyStickerById(dto.stickerId)) {
        throw new BadRequestException('Unknown sticker.');
      }
      stickerId = dto.stickerId;
    } else {
      throw new BadRequestException('Unsupported message type.');
    }

    const message = await this.groupyRepo.createMessage({
      orgId,
      classId,
      senderAccountId: user.id,
      senderRole,
      senderName,
      senderProfileImage,
      type,
      body,
      gifUrl,
      stickerId,
    });

    this.gateway.emitMessageNew(message);
    return message;
  }

  getStickers() {
    return GROUPY_STICKERS;
  }

  // ── Start Meeting ───────────────────────────────────────────────────────────

  async startMeeting(
    classId: string,
    orgId: string,
    user: CurrentUser,
    invitedStudentIds?: string[],
  ) {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { educator_id: true },
    });
    if (!cls) throw new NotFoundException('Class not found.');

    // Educator only — students cannot start a meeting.
    if (cls.educator_id !== user.id) {
      throw new ForbiddenException('Only the educator can start a meeting.');
    }

    const account = await this.db.account.findUnique({
      where: { id: user.id },
      include: { profile: true },
    });
    const senderName = account?.profile?.full_name ?? user.email ?? 'Unknown';
    const senderProfileImage = account?.profile?.profile_image ?? null;

    // Reuse the existing meeting creation path. An empty/undefined invitedStudentIds
    // array makes MeetingService auto-invite the class's active roster. Ephemeral
    // meetings are NOT shown on the meetings pages and are deleted when they end.
    const dto: CreateMeetingDto = {
      title: 'Class Meeting',
      startTime: new Date().toISOString(),
      invitedStudentIds,
      ephemeral: true,
    };
    const meeting = await this.meetingService.create(
      classId,
      orgId,
      user.id,
      dto,
    );
    if (!meeting) {
      throw new NotFoundException('Could not create the meeting.');
    }

    // Announce it as a system message on the Groupy stream. The body carries a
    // JSON payload so the frontend can render a "Join" button from meetingId.
    const message = await this.groupyRepo.createMessage({
      orgId,
      classId,
      senderAccountId: user.id,
      senderRole: (user.role ?? 'educator') as any,
      senderName,
      senderProfileImage,
      type: 'system',
      body: JSON.stringify({ meetingId: meeting.id, title: meeting.title }),
    });

    this.gateway.emitMessageNew(message);

    return { meetingId: meeting.id, message };
  }

  // ── DELETE /groupy/messages/:id ───────────────────────────────────────────

  async deleteMessage(messageId: string, orgId: string, accountId: string) {
    const message = await this.groupyRepo.findMessageById(messageId, orgId);
    if (!message) throw new NotFoundException('Message not found.');

    await this.assertMember(accountId, message.class_id, orgId);

    if (message.sender_account_id !== accountId) {
      throw new ForbiddenException('You can only delete your own messages.');
    }

    await this.groupyRepo.deleteMessage(messageId);
    this.gateway.emitMessageDeleted({
      id: message.id,
      class_id: message.class_id,
    });
    return { success: true };
  }

  // ── Reactions ───────────────────────────────────────────────────────────────

  async setReaction(
    messageId: string,
    orgId: string,
    accountId: string,
    reactionType: any,
  ) {
    const message = await this.groupyRepo.findMessageById(messageId, orgId);
    if (!message) throw new NotFoundException('Message not found.');

    await this.assertMember(accountId, message.class_id, orgId);

    await this.groupyRepo.upsertReaction({
      orgId,
      messageId,
      accountId,
      reactionType,
    });

    this.gateway.emitReactionUpdated({
      classId: message.class_id,
      messageId,
      accountId,
      reactionType,
    });

    return { success: true };
  }

  async removeReaction(messageId: string, orgId: string, accountId: string) {
    const message = await this.groupyRepo.findMessageById(messageId, orgId);
    if (!message) throw new NotFoundException('Message not found.');

    await this.assertMember(accountId, message.class_id, orgId);

    // No-op if the caller had no reaction.
    await this.groupyRepo.deleteReaction(messageId, accountId);
    this.gateway.emitReactionRemoved({
      classId: message.class_id,
      messageId,
      accountId,
    });

    return { success: true };
  }

  // ── Polls ───────────────────────────────────────────────────────────────────

  async createPoll(
    classId: string,
    orgId: string,
    user: CurrentUser,
    dto: CreatePollDto,
  ) {
    const cls = await this.db.class.findFirst({
      where: { id: classId, org_id: orgId, deleted_at: null },
      select: { educator_id: true },
    });
    if (!cls) throw new NotFoundException('Class not found.');

    // Educator only — students cannot create polls.
    if (cls.educator_id !== user.id) {
      throw new ForbiddenException('Only the educator can create polls.');
    }

    const account = await this.db.account.findUnique({
      where: { id: user.id },
      include: { profile: true },
    });
    const senderName = account?.profile?.full_name ?? user.email ?? 'Unknown';
    const senderProfileImage = account?.profile?.profile_image ?? null;

    const message = await this.groupyRepo.createPoll({
      orgId,
      classId,
      createdBy: user.id,
      senderRole: (user.role ?? 'educator') as any,
      senderName,
      senderProfileImage,
      question: dto.question,
      options: dto.options,
    });

    // Ride on the normal new-message stream.
    this.gateway.emitMessageNew(message);
    return message;
  }

  async vote(
    pollId: string,
    orgId: string,
    accountId: string,
    optionId: string,
  ) {
    const poll = await this.groupyRepo.findPollById(pollId, orgId);
    if (!poll) throw new NotFoundException('Poll not found.');

    await this.assertMember(accountId, poll.class_id, orgId);

    // Compute effective closed state at request time.
    const isClosed =
      poll.is_closed ||
      (poll.closes_at !== null && poll.closes_at.getTime() < Date.now());
    if (isClosed) {
      throw new BadRequestException('This poll is closed.');
    }

    const option = poll.options.find((o) => o.id === optionId);
    if (!option) throw new BadRequestException('Invalid option.');

    await this.groupyRepo.upsertVote({ pollId, optionId, accountId });

    const summary = await this.buildPollResults(pollId);
    this.gateway.emitPollVoteUpdated({
      classId: poll.class_id,
      pollId,
      resultsSummary: summary,
    });

    return summary;
  }

  async closePoll(pollId: string, orgId: string, accountId: string) {
    const poll = await this.groupyRepo.findPollById(pollId, orgId);
    if (!poll) throw new NotFoundException('Poll not found.');

    // Poll creator (educator) only.
    if (poll.created_by !== accountId) {
      throw new ForbiddenException('Only the poll creator can close it.');
    }

    await this.groupyRepo.closePoll(pollId);
    this.gateway.emitPollClosed({ classId: poll.class_id, pollId });

    return { success: true };
  }

  async getPollResults(pollId: string, orgId: string, accountId: string) {
    const poll = await this.groupyRepo.findPollById(pollId, orgId);
    if (!poll) throw new NotFoundException('Poll not found.');

    await this.assertMember(accountId, poll.class_id, orgId);

    return this.buildPollResults(pollId);
  }

  async getPollDetail(pollId: string, orgId: string, accountId: string) {
    const poll = await this.groupyRepo.findPollById(pollId, orgId);
    if (!poll) throw new NotFoundException('Poll not found.');

    await this.assertMember(accountId, poll.class_id, orgId);

    const counts = await this.groupyRepo.getPollResults(pollId);
    const myVote = await this.groupyRepo.findVote(pollId, accountId);
    const isEffectiveClosed =
      poll.is_closed ||
      (poll.closes_at !== null && poll.closes_at.getTime() < Date.now());
    const totalVotes = counts.reduce((sum, o) => sum + o._count.votes, 0);

    return {
      id: poll.id,
      class_id: poll.class_id,
      question: poll.question,
      closes_at: poll.closes_at,
      is_closed: poll.is_closed,
      isClosed: isEffectiveClosed,
      created_by: poll.created_by,
      totalVotes,
      options: counts.map((o) => ({
        id: o.id,
        label: o.label,
        order_index: o.order_index,
        voteCount: o._count.votes,
      })),
      myVoteOptionId: myVote?.option_id ?? null,
    };
  }

  // ── Read receipts + unread flag ────────────────────────────────────────────

  // Newest running groupy meeting for the class (if any), so the chat can show
  // the Messenger-style active-call banner and mark ended meeting messages.
  async getActiveMeeting(classId: string, orgId: string, accountId: string) {
    await this.assertMember(accountId, classId, orgId);

    const meeting = await this.groupyRepo.findActiveMeeting(classId, orgId);
    if (!meeting) return { meeting: null };

    return {
      meeting: {
        meetingId: meeting.id,
        title: meeting.title,
      },
    };
  }

  // Record that the caller has seen the chat up to a specific message, then
  // broadcast so everyone's "seen by" row updates in real time.
  async reportRead(
    classId: string,
    orgId: string,
    accountId: string,
    lastMessageId: string,
  ) {
    await this.assertMember(accountId, classId, orgId);

    // Only accept pointers to a real message in this class.
    const msg = await this.groupyRepo.findMessageById(lastMessageId, orgId);
    if (!msg || msg.class_id !== classId) {
      throw new BadRequestException('Invalid lastMessageId.');
    }

    await this.groupyRepo.upsertReadReceipt({
      orgId,
      classId,
      accountId,
      lastReadMessageId: lastMessageId,
    });

    this.gateway.emitReadUpdated({
      classId,
      accountId,
      lastReadMessageId: lastMessageId,
    });

    return { lastReadMessageId: lastMessageId };
  }

  // Roster of members (educator + active students) with profile images and each
  // one's last-read pointer — used to render the messenger-style "seen by" row.
  async getMembers(classId: string, orgId: string, accountId: string) {
    await this.assertMember(accountId, classId, orgId);

    const members = await this.groupyRepo.listMembers(classId, orgId);
    const me = members.find((m) => m.account_id === accountId) ?? null;
    const others = members.filter((m) => m.account_id !== accountId);

    return { me, members: others };
  }

  // Lightweight unread check for the Class Chat entry badge. True when there is
  // at least one message the caller hasn't read yet.
  async getUnreadStatus(classId: string, orgId: string, accountId: string) {
    await this.assertMember(accountId, classId, orgId);

    const [latest, receipt] = await Promise.all([
      this.groupyRepo.findMessages({ classId, orgId, limit: 1 }),
      this.groupyRepo.getReadReceipt(classId, accountId),
    ]);

    const lastMessage = latest[0] ?? null;
    if (!lastMessage) return { hasUnread: false };

    const hasUnread = receipt?.last_read_message_id !== lastMessage.id;
    return { hasUnread };
  }

  private async buildPollResults(pollId: string) {
    const options = await this.groupyRepo.getPollResults(pollId);
    const totalVotes = options.reduce((sum, o) => sum + o._count.votes, 0);
    return {
      options: options.map((o) => ({
        id: o.id,
        label: o.label,
        votes: o._count.votes,
      })),
      totalVotes,
    };
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { ClassRepository } from '../class/class.repository';
import { SemesterTemplateRepository } from '../semester-template/semester-template.repository';

type WeekSlot = {
  label: string;
  value: number;
  globalWeek: number;
  termWeek: number;
  semesterWeek: number;
  termName: string;
  termId: string;
  semesterName: string;
  semesterIndex: number;
  date: string;
};

@Injectable()
export class LessonWeekStructureService {
  constructor(
    private readonly classRepo: ClassRepository,
    private readonly semesterTemplateRepo: SemesterTemplateRepository,
  ) {}

  async getWeekStructure(classId: string, orgId: string): Promise<WeekSlot[]> {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    if (!cls.schedules || cls.schedules.length === 0) {
      throw new BadRequestException('Class has no schedule configured.');
    }

    const classWeekday = cls.schedules[0].weekday;

    const subject = await this.classRepo['db'].subject.findFirst({
      where: { id: cls.subject_id },
      select: { program_id: true },
    });

    if (!subject?.program_id) {
      throw new BadRequestException(
        'Class subject is not linked to a program.',
      );
    }

    const assignment = await this.semesterTemplateRepo.findAssignmentByProgram(
      subject.program_id,
      orgId,
    );

    if (!assignment) {
      throw new BadRequestException(
        'No semester template assigned to this program.',
      );
    }

    const termDatesMap = new Map<string, { start: Date; end: Date }>();

    for (const td of (assignment as any).termDates ?? []) {
      termDatesMap.set(td.term_id, {
        start: new Date(td.start_date),
        end: new Date(td.end_date),
      });
    }

    const result: WeekSlot[] = [];

    const semesters = (assignment.template.semesters ?? []).sort(
      (a: any, b: any) => a.order_index - b.order_index,
    );

    let classSemesterStart: Date | null = null;
    let classSemesterEnd: Date | null = null;
    if (cls.semester_id) {
      const actualSem = await this.classRepo['db'].semester.findUnique({
        where: { id: cls.semester_id },
        select: { start_date: true, end_date: true },
      });
      if (actualSem) {
        classSemesterStart = actualSem.start_date;
        classSemesterEnd = actualSem.end_date;
      }
    }

    let globalWeek = 1;

    for (let si = 0; si < semesters.length; si++) {
      const sem = semesters[si];

      if (classSemesterStart && classSemesterEnd) {
        const semTermDates = (sem.terms ?? [])
          .map((t: any) => termDatesMap.get(t.id))
          .filter(Boolean) as Array<{ start: Date; end: Date }>;

        const semStart =
          semTermDates.length > 0
            ? new Date(Math.min(...semTermDates.map((d) => d.start.getTime())))
            : null;
        const semEnd =
          semTermDates.length > 0
            ? new Date(Math.max(...semTermDates.map((d) => d.end.getTime())))
            : null;

        if (
          !semStart ||
          !semEnd ||
          semEnd < classSemesterStart ||
          semStart > classSemesterEnd
        )
          continue;
      }

      const terms = (sem.terms ?? []).sort(
        (a: any, b: any) => a.order_index - b.order_index,
      );

      let semesterWeek = 1;

      for (const term of terms) {
        const dates = termDatesMap.get(term.id);

        if (!dates) {
          throw new BadRequestException(
            `Term "${term.name}" in semester "${sem.name}" has no date range configured.`,
          );
        }

        const occurrences = this.getWeekdayOccurrences(
          dates.start,
          dates.end,
          classWeekday,
        );

        let termWeek = 1;

        for (const date of occurrences) {
          result.push({
            label: String(globalWeek),
            value: globalWeek,
            globalWeek,
            termWeek,
            semesterWeek,
            termName: term.name,
            termId: term.id,
            semesterName: sem.name,
            semesterIndex: si + 1,
            date: date.toISOString(),
          });

          globalWeek++;
          termWeek++;
          semesterWeek++;
        }
      }
    }

    return result;
  }

  private getWeekdayOccurrences(
    start: Date,
    end: Date,
    weekday: number,
  ): Date[] {
    const dates: Date[] = [];
    const current = new Date(start);

    const diff = (weekday - current.getDay() + 7) % 7;
    current.setDate(current.getDate() + diff);

    while (current <= end) {
      dates.push(new Date(current));
      current.setDate(current.getDate() + 7);
    }

    return dates;
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { LessonRepository } from './lesson.repository';
import { AuditLogService } from '../audit-log/audit-log.service';
import { ClassRepository } from '../class/class.repository';
import { AttendanceRepository } from '../attendance/attendance.repository';
import { LessonConceptService } from './lesson-concept.service';
import { LessonWeekStructureService } from './lesson-week-structure.service';
import { LessonStudentService } from './lesson-student.service';
import {
  CreateLessonDto,
  UpdateLessonDto,
  QueryLessonDto,
} from './dto/lesson.dto';

const MIN_DETAIL_WORDS = 10;

function countWords(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

@Injectable()
export class LessonService {
  constructor(
    private readonly lessonRepo: LessonRepository,
    private readonly classRepo: ClassRepository,
    private readonly auditLog: AuditLogService,
    private readonly attendanceRepo: AttendanceRepository,
    private readonly conceptService: LessonConceptService,
    private readonly weekStructureService: LessonWeekStructureService,
    private readonly studentService: LessonStudentService,
  ) {}

  async create(
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateLessonDto,
  ) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }

    if (countWords(dto.detail) < MIN_DETAIL_WORDS) {
      throw new BadRequestException('Lesson detail must be at least 10 words.');
    }

    const existing = await this.lessonRepo.findByClassAndWeek(
      classId,
      orgId,
      dto.weekNumber,
      dto.subIndex,
    );
    if (existing) {
      throw new BadRequestException(
        `A lesson already exists at Week ${dto.weekNumber}, Sub-index ${dto.subIndex}.`,
      );
    }

    const lesson = await this.lessonRepo.create({
      orgId,
      classId,
      title: dto.title,
      description: dto.description,
      weekNumber: dto.weekNumber,
      subIndex: dto.subIndex,
      detail: dto.detail,
    });

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'lesson_created',
      entityType: 'class',
      entityId: classId,
      metadata: { lessonId: lesson.id, title: lesson.title },
    });

    this.conceptService
      .triggerConceptExtraction(lesson.id, orgId, educatorId, dto.detail)
      .catch(() => {});

    return lesson;
  }

  async findAll(
    classId: string,
    orgId: string,
    educatorId: string,
    query: QueryLessonDto,
  ) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }
    return this.lessonRepo.findAll(classId, orgId, query.weekNumber);
  }

  async findOne(id: string, orgId: string, educatorId: string) {
    const lesson = await this.lessonRepo.findById(id, orgId);
    if (!lesson) throw new NotFoundException('Lesson not found.');
    const cls = await this.classRepo.findById(lesson.class_id, orgId);
    if (cls?.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }
    const concept = await this.lessonRepo.findConcept(id);
    return { ...lesson, concept: concept ?? null };
  }

  async update(
    id: string,
    orgId: string,
    educatorId: string,
    dto: UpdateLessonDto,
  ) {
    const lesson = await this.lessonRepo.findById(id, orgId);
    if (!lesson) throw new NotFoundException('Lesson not found.');
    const cls = await this.classRepo.findById(lesson.class_id, orgId);
    if (cls?.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }

    if (dto.detail !== undefined && countWords(dto.detail) < MIN_DETAIL_WORDS) {
      throw new BadRequestException('Lesson detail must be at least 10 words.');
    }

    if (dto.weekNumber !== undefined || dto.subIndex !== undefined) {
      const newWeek = dto.weekNumber ?? lesson.week_number;
      const newSub = dto.subIndex ?? lesson.sub_index;
      const conflict = await this.lessonRepo.findByClassAndWeek(
        lesson.class_id,
        orgId,
        newWeek,
        newSub,
      );
      if (conflict && conflict.id !== id) {
        throw new BadRequestException(
          `A lesson already exists at Week ${newWeek}, Sub-index ${newSub}.`,
        );
      }
    }

    const updated = await this.lessonRepo.update(id, {
      title: dto.title,
      description: dto.description,
      detail: dto.detail,
      weekNumber: dto.weekNumber,
      subIndex: dto.subIndex,
    });

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'lesson_updated',
      entityType: 'class',
      entityId: lesson.class_id,
      metadata: { lessonId: id },
    });

    return updated;
  }

  async delete(id: string, orgId: string, educatorId: string) {
    const lesson = await this.lessonRepo.findById(id, orgId);
    if (!lesson) throw new NotFoundException('Lesson not found.');
    const cls = await this.classRepo.findById(lesson.class_id, orgId);
    if (cls?.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }
    await this.lessonRepo.delete(id);
    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'lesson_deleted',
      entityType: 'class',
      entityId: lesson.class_id,
      metadata: { lessonId: id, action: 'deleted' },
    });
    return { success: true };
  }

  async getConcept(id: string, orgId: string, educatorId: string) {
    return this.conceptService.getConcept(id, orgId, educatorId);
  }

  async reExtractConcept(
    id: string,
    orgId: string,
    educatorId: string,
    detail: string,
  ) {
    return this.conceptService.reExtractConcept(id, orgId, educatorId, detail);
  }

  async conceptBuild(
    id: string,
    orgId: string,
    educatorId: string,
    detail: string,
  ) {
    return this.conceptService.conceptBuild(id, orgId, educatorId, detail);
  }

  async getStudentLessons(
    classId: string,
    studentId: string,
    orgId: string,
    weekNumber?: number,
  ) {
    return this.studentService.getStudentLessons(
      classId,
      studentId,
      orgId,
      weekNumber,
    );
  }

  async getStudentLesson(
    classId: string,
    lessonId: string,
    studentId: string,
    orgId: string,
  ) {
    return this.studentService.getStudentLesson(
      classId,
      lessonId,
      studentId,
      orgId,
    );
  }

  async getWeekStructure(classId: string, orgId: string, _educatorId?: string) {
    return this.weekStructureService.getWeekStructure(classId, orgId);
  }

  async syncLessonsFromAttendance(classId: string, orgId: string) {
    const sessions = await this.attendanceRepo.findSessionsByClass(classId);

    if (!sessions.length) return;

    const existingLessons = await this.lessonRepo.findAll(classId, orgId);

    const lessonMap = new Map(
      existingLessons.map((l) => [`${l.week_number}-${l.sub_index}`, l]),
    );

    for (const session of sessions) {
      const key = `${session.week_number}-${session.sub_index}`;

      const existing = lessonMap.get(key);

      if (!existing) {
        await this.lessonRepo.create({
          orgId,
          classId,
          title: `Lesson Week ${session.week_number}`,
          description: `Auto-generated from attendance session`,
          detail: `Auto-generated lesson aligned with attendance schedule.`,
          weekNumber: session.week_number,
          subIndex: session.sub_index,
        });
      } else {
        await this.lessonRepo.update(existing.id, {
          weekNumber: session.week_number,
          subIndex: session.sub_index,
        });
      }
    }
  }
}

import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { buildLevelDefs } from '@/modules/org-seeder/data/levels.data';

@Injectable()
export class LevelRepository {
  constructor(private readonly db: DatabaseService) {}

  async findBySchoolYear(orgId: string, schoolYearId: string) {
    return this.db.level.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
      },
      orderBy: [{ program_id: 'asc' }, { name: 'asc' }],
    });
  }

  async findByProgramAndSchoolYear(
    orgId: string,
    programId: string,
    schoolYearId: string,
  ) {
    return this.db.level.findMany({
      where: {
        org_id: orgId,
        program_id: programId,
        school_year_id: schoolYearId,
        course_id: null,
        strand_id: null,
      },
      orderBy: { name: 'asc' },
    });
  }

  async seedFromDefaults(
    orgId: string,
    schoolYearId: string,
    programMap: Record<string, string>, // programKey → programId
  ) {
    const levelDefs = buildLevelDefs().filter(
      (l) => !!programMap[l.programKey],
    );
    if (levelDefs.length === 0) return [];

    const created: any[] = [];
    for (const lvl of levelDefs) {
      const level = await this.db.level.create({
        data: {
          org_id: orgId,
          school_year_id: schoolYearId,
          program_id: programMap[lvl.programKey],
          name: lvl.name,
        },
      });
      created.push(level);
    }
    return created;
  }

  async findById(id: string, orgId: string) {
    return this.db.level.findFirst({
      where: { id, org_id: orgId },
    });
  }

  async update(id: string, data: { name?: string }) {
    return this.db.level.update({
      where: { id },
      data,
    });
  }

  async create(
    orgId: string,
    data: {
      programId: string;
      schoolYearId: string;
      name: string;
      courseId?: string;
      strandId?: string;
    },
  ) {
    return this.db.level.create({
      data: {
        org_id: orgId,
        school_year_id: data.schoolYearId,
        program_id: data.programId,
        course_id: data.courseId ?? null,
        strand_id: data.strandId ?? null,
        name: data.name,
      },
    });
  }

  async delete(id: string) {
    return this.db.level.delete({
      where: { id },
    });
  }

  async findAll(orgId: string, schoolYearId?: string) {
    return this.db.level.findMany({
      where: {
        org_id: orgId,
        ...(schoolYearId ? { school_year_id: schoolYearId } : {}),
      },
      orderBy: [{ program_id: 'asc' }, { name: 'asc' }],
    });
  }

  async deleteByProgramAndSchoolYear(
    orgId: string,
    programId: string,
    schoolYearId: string,
    courseId?: string,
    strandId?: string,
  ): Promise<void> {
    await this.db.level.deleteMany({
      where: {
        org_id: orgId,
        program_id: programId,
        school_year_id: schoolYearId,
        course_id: courseId ?? null,
        strand_id: strandId ?? null,
      },
    });
  }

  async bulkCreate(
    levels: Array<{
      orgId: string;
      programId: string;
      schoolYearId: string;
      name: string;
      courseId?: string;
      strandId?: string;
    }>,
  ) {
    await this.db.level.createMany({
      data: levels.map((l) => ({
        org_id: l.orgId,
        school_year_id: l.schoolYearId,
        program_id: l.programId,
        course_id: l.courseId ?? null,
        strand_id: l.strandId ?? null,
        name: l.name,
      })),
    });
    return this.db.level.findMany({
      where: {
        org_id: levels[0].orgId,
        program_id: levels[0].programId,
        school_year_id: levels[0].schoolYearId,
        course_id: levels[0].courseId ?? null,
        strand_id: levels[0].strandId ?? null,
      },
      orderBy: { name: 'asc' },
    });
  }

  async findByCourseAndSchoolYear(
    orgId: string,
    schoolYearId: string,
    courseId: string,
  ) {
    return this.db.level.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
        course_id: courseId,
      },
      orderBy: { name: 'asc' },
    });
  }

  async findByStrandAndSchoolYear(
    orgId: string,
    schoolYearId: string,
    strandId: string,
  ) {
    return this.db.level.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
        strand_id: strandId,
      },
      orderBy: { name: 'asc' },
    });
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
  ConnectedSocket,
  MessageBody,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { forwardRef, Inject, Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { MeetingRepository } from './meeting.repository';
import { DatabaseService } from '@/core/database/database.provider';
import { GroupyGateway } from '../groupy/groupy.gateway';

// ── Types ─────────────────────────────────────────────────────────────────────

interface AuthPayload {
  sub: string;
  org_id: string | null;
  role: string;
  email: string;
}

interface RoomParticipant {
  socketId: string;
  userId: string;
  orgId: string;
  role: string;
  name: string;
  handRaised: boolean;
  joinedAt: Date;
}

interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  message: string;
  createdAt: string;
}

// ── In-memory room state ───────────────────────────────────────────────────────

class RoomState {
  participants = new Map<string, RoomParticipant>(); // socketId → participant
  chatHistory: ChatMessage[] = [];
  currentSlide = 0; // lesson presentation sync
  isPresenting = false;
  presentationId?: string;
  // Students already announced in the class chat for this meeting session.
  // Guards against re-announcing on socket reconnect / page refresh.
  announcedJoins = new Set<string>();

  getParticipantList() {
    return Array.from(this.participants.values()).map((p) => ({
      userId: p.userId,
      name: p.name,
      role: p.role,
      handRaised: p.handRaised,
      joinedAt: p.joinedAt,
    }));
  }
}

// ── Gateway ───────────────────────────────────────────────────────────────────

@WebSocketGateway({
  namespace: 'meeting',
  cors: { origin: '*', credentials: true },
})
export class MeetingGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer() server: Server;
  private readonly logger = new Logger(MeetingGateway.name);

  // meetingId → RoomState
  private rooms = new Map<string, RoomState>();

  constructor(
    private readonly jwtService: JwtService,
    private readonly config: ConfigService,
    private readonly meetingRepo: MeetingRepository,
    private readonly db: DatabaseService,
    @Inject(forwardRef(() => GroupyGateway))
    private readonly groupyGateway: GroupyGateway,
  ) {}

  // ── Connection ────────────────────────────────────────────────────────────

  async handleConnection(client: Socket) {
    try {
      const token =
        (client.handshake.auth?.token as string) ??
        (client.handshake.headers?.authorization as string)?.replace(
          'Bearer ',
          '',
        );

      if (!token) return this.kick(client, 'Missing token');

      const payload = this.verifyToken(token);
      if (!payload) return this.kick(client, 'Invalid token');
      if (!payload.org_id) return this.kick(client, 'Missing org');

      const meetingId = client.handshake.query?.meetingId as string;
      if (!meetingId) return this.kick(client, 'Missing meetingId');

      const meeting = await this.meetingRepo.findById(
        meetingId,
        payload.org_id,
      );
      if (!meeting) return this.kick(client, 'Meeting not found');
      if (meeting.status === 'ended')
        return this.kick(client, 'Meeting has ended');

      // Access check
      const isEducator =
        payload.role === 'educator' && meeting.educator_id === payload.sub;
      const isInvited =
        payload.role === 'student' &&
        (await this.meetingRepo.isStudentInvited(meetingId, payload.sub));

      if (!isEducator && !isInvited) {
        return this.kick(client, 'Not authorized for this meeting');
      }

      // Resolve display name
      const account = await this.db.account.findFirst({
        where: { id: payload.sub },
        include: { profile: true },
      });
      const name = account?.profile?.full_name ?? payload.email ?? 'Unknown';

      // Store auth on socket
      client.data.auth = payload;
      client.data.meetingId = meetingId;
      client.data.name = name;

      // Join socket.io room
      await client.join(meetingId);

      // Lifecycle: a created meeting becomes "active" once someone joins.
      if (meeting.status === 'scheduled') {
        await this.meetingRepo.updateStatus(meetingId, 'active');
      }

      // Update in-memory state
      if (!this.rooms.has(meetingId))
        this.rooms.set(meetingId, new RoomState());
      const room = this.rooms.get(meetingId)!;
      room.participants.set(client.id, {
        socketId: client.id,
        userId: payload.sub,
        orgId: payload.org_id,
        role: payload.role,
        name,
        handRaised: false,
        joinedAt: new Date(),
      });

      // Groupy (ephemeral) meetings: announce the student in the class chat so
      // everyone sees "[name] joined". Best-effort — a failure here must never
      // break the meeting join, so it is isolated from the shared try/catch.
      if (payload.role === 'student' && meeting.is_ephemeral) {
        if (!room.announcedJoins.has(payload.sub)) {
          room.announcedJoins.add(payload.sub);
          try {
            await this.groupyGateway.announceMemberJoined(
              meeting.class_id,
              payload.org_id,
              payload.sub,
              name,
            );
          } catch (err) {
            this.logger.error(
              `[${meetingId}] failed to announce join for ${name}: ${err}`,
            );
          }
        }
      }

      // Send room state to the joining client
      client.emit('room:state', {
        participants: room.getParticipantList(),
        chatHistory: room.chatHistory.slice(-50),
        currentSlide: room.currentSlide,
        isPresenting: room.isPresenting,
        presentationId: room.presentationId,
      });

      // Notify others
      this.server.to(meetingId).emit('room:participant_joined', {
        userId: payload.sub,
        name,
        role: payload.role,
        participants: room.getParticipantList(),
      });

      this.logger.log(`[${meetingId}] ${name} (${payload.role}) connected`);
    } catch (err) {
      this.logger.error('handleConnection error', err);
      this.kick(client, 'Internal error');
    }
  }

  async handleDisconnect(client: Socket) {
    const meetingId = client.data?.meetingId;
    if (!meetingId) return;

    const room = this.rooms.get(meetingId);
    if (!room) return;

    const participant = room.participants.get(client.id);
    room.participants.delete(client.id);

    if (participant) {
      this.server.to(meetingId).emit('room:participant_left', {
        userId: participant.userId,
        name: participant.name,
        participants: room.getParticipantList(),
      });
      this.logger.log(`[${meetingId}] ${participant.name} disconnected`);
    }

    // Clean up empty rooms
    if (room.participants.size === 0) {
      this.rooms.delete(meetingId);

      // Ephemeral (Groupy) meetings are discarded once everyone leaves.
      const auth = client.data?.auth as AuthPayload | undefined;
      if (auth?.org_id) {
        const meeting = await this.meetingRepo.findById(meetingId, auth.org_id);
        if (meeting?.is_ephemeral) {
          await this.meetingRepo.hardDelete(meetingId);
        }
      }
    }
  }

  // ── Chat ──────────────────────────────────────────────────────────────────

  @SubscribeMessage('chat:send')
  async handleChatSend(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { message: string },
  ) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth || !auth.org_id) return;

    const text = (data?.message ?? '').trim();
    if (!text) return;

    // Persist to DB
    const saved = await this.db.meetingChatMessage.create({
      data: {
        org_id: auth.org_id,
        meeting_id: meetingId,
        sender_id: auth.sub,
        sender_name: client.data.name,
        message: text,
      },
    });

    const msg: ChatMessage = {
      id: saved.id,
      senderId: auth.sub,
      senderName: client.data.name,
      message: text,
      createdAt: saved.created_at.toISOString(),
    };

    // Cache in room state
    const room = this.rooms.get(meetingId);
    if (room) room.chatHistory.push(msg);

    // Broadcast to all in room
    this.server.to(meetingId).emit('chat:message', msg);
  }

  // ── Raise hand ────────────────────────────────────────────────────────────

  @SubscribeMessage('hand:raise')
  handleRaiseHand(@ConnectedSocket() client: Socket) {
    this.setHandState(client, true);
  }

  @SubscribeMessage('hand:lower')
  handleLowerHand(@ConnectedSocket() client: Socket) {
    this.setHandState(client, false);
  }

  private setHandState(client: Socket, raised: boolean) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth) return;

    const room = this.rooms.get(meetingId);
    const participant = room?.participants.get(client.id);
    if (!participant) return;

    participant.handRaised = raised;

    this.server.to(meetingId).emit('hand:update', {
      userId: auth.sub,
      name: client.data.name,
      handRaised: raised,
      participants: room!.getParticipantList(),
    });
  }

  // ── Reactions ─────────────────────────────────────────────────────────────

  @SubscribeMessage('reaction:send')
  handleReaction(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { emoji: string },
  ) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth) return;

    const allowed = ['👍', '👏', '❤️', '😂', '😮', '🎉'];
    const emoji = data?.emoji;
    if (!allowed.includes(emoji)) return;

    this.server.to(meetingId).emit('reaction:received', {
      userId: auth.sub,
      name: client.data.name,
      emoji,
    });
  }

  // ── WebRTC signaling ──────────────────────────────────────────────────────
  // Peer-to-peer signaling relay. Each client sends offer/answer/ICE
  // addressed to a specific targetUserId. The gateway looks up that user's
  // current socket and forwards the payload directly.

  @SubscribeMessage('webrtc:offer')
  handleOffer(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { targetUserId: string; offer: RTCSessionDescriptionInit },
  ) {
    this.relayToUser(client, data.targetUserId, 'webrtc:offer', {
      fromUserId: client.data.auth?.sub,
      offer: data.offer,
    });
  }

  @SubscribeMessage('webrtc:answer')
  handleAnswer(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { targetUserId: string; answer: RTCSessionDescriptionInit },
  ) {
    this.relayToUser(client, data.targetUserId, 'webrtc:answer', {
      fromUserId: client.data.auth?.sub,
      answer: data.answer,
    });
  }

  @SubscribeMessage('webrtc:ice')
  handleIce(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { targetUserId: string; candidate: RTCIceCandidateInit },
  ) {
    this.relayToUser(client, data.targetUserId, 'webrtc:ice', {
      fromUserId: client.data.auth?.sub,
      candidate: data.candidate,
    });
  }

  // ── Lesson presentation sync ──────────────────────────────────────────────
  // Only the educator can control the slide. Students receive sync events.

  @SubscribeMessage('lesson:slide_change')
  handleSlideChange(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { slide: number },
  ) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth) return;
    if (auth.role !== 'educator') return; // students cannot control slides

    const room = this.rooms.get(meetingId);
    if (!room) return;

    room.currentSlide = data.slide;
    this.server.to(meetingId).emit('lesson:slide_sync', {
      slide: data.slide,
      controlledBy: auth.sub,
    });
  }

  @SubscribeMessage('lesson:presentation_start')
  handlePresentationStart(
    @ConnectedSocket() client: Socket,
    @MessageBody() data?: { presentationId?: string },
  ) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || auth?.role !== 'educator') return;

    const room = this.rooms.get(meetingId);
    if (!room) return;

    room.isPresenting = true;
    room.presentationId = data?.presentationId ?? room.presentationId;
    this.server.to(meetingId).emit('lesson:presentation_started', {
      educatorId: auth.sub,
      currentSlide: room.currentSlide,
      presentationId: room.presentationId,
    });
  }

  @SubscribeMessage('lesson:presentation_stop')
  handlePresentationStop(@ConnectedSocket() client: Socket) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || auth?.role !== 'educator') return;

    const room = this.rooms.get(meetingId);
    if (!room) return;

    room.isPresenting = false;
    room.presentationId = undefined;
    this.server.to(meetingId).emit('lesson:presentation_stopped', {
      educatorId: auth.sub,
    });
  }

  // ── Screen share signaling ────────────────────────────────────────────────
  // Screen share is handled via WebRTC (same offer/answer/ICE flow above).
  // These events just broadcast awareness that someone started/stopped sharing.

  @SubscribeMessage('screen:share_started')
  handleScreenShareStart(@ConnectedSocket() client: Socket) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth) return;

    this.server.to(meetingId).emit('screen:sharing', {
      userId: auth.sub,
      name: client.data.name,
      sharing: true,
    });
  }

  @SubscribeMessage('screen:share_stopped')
  handleScreenShareStop(@ConnectedSocket() client: Socket) {
    const meetingId = client.data?.meetingId;
    const auth: AuthPayload = client.data?.auth;
    if (!meetingId || !auth) return;

    this.server.to(meetingId).emit('screen:sharing', {
      userId: auth.sub,
      name: client.data.name,
      sharing: false,
    });
  }

  // ── Private helpers ───────────────────────────────────────────────────────

  private verifyToken(token: string): AuthPayload | null {
    try {
      return this.jwtService.verify<AuthPayload>(token, {
        secret: this.config.get<string>('JWT_SECRET'),
      });
    } catch {
      return null;
    }
  }

  private kick(client: Socket, reason: string) {
    client.emit('error', { message: reason });
    client.disconnect(true);
  }

  private relayToUser(
    sender: Socket,
    targetUserId: string,
    event: string,
    payload: object,
  ) {
    const meetingId = sender.data?.meetingId;
    if (!meetingId) return;

    const room = this.rooms.get(meetingId);
    if (!room) return;

    // Find the target's socketId
    for (const [socketId, p] of room.participants.entries()) {
      if (p.userId === targetUserId) {
        this.server.to(socketId).emit(event, payload);
        return;
      }
    }
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { MeetingRepository } from './meeting.repository';
import { MeetingGateway } from './meeting.gateway';
import { ClassRepository } from '../class/class.repository';
import { EnrollmentRepository } from '../enrollment/enrollment.repository';
import { NotificationService } from '../notification/notification.service';
import { AuditLogService } from '../audit-log/audit-log.service';
import {
  CreateMeetingDto,
  UpdateMeetingDto,
  RespondJoinRequestDto,
} from './dto/meeting.dto';

@Injectable()
export class MeetingService {
  constructor(
    private readonly meetingRepo: MeetingRepository,
    private readonly classRepo: ClassRepository,
    private readonly enrollmentRepo: EnrollmentRepository,
    private readonly notificationService: NotificationService,
    private readonly auditLog: AuditLogService,
    private readonly meetingGateway: MeetingGateway,
  ) {}

  // ── POST /classes/:classId/meetings ───────────────────────────────────────

  async create(
    classId: string,
    orgId: string,
    educatorId: string,
    dto: CreateMeetingDto,
  ) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }

    const meeting = await this.meetingRepo.create({
      orgId,
      classId,
      educatorId,
      title: dto.title,
      description: dto.description,
      startTime: new Date(dto.startTime),
      isEphemeral: dto.ephemeral ?? false,
    });

    // Resolve invited student IDs
    // If none provided → invite all active enrollments
    let invitedIds = dto.invitedStudentIds ?? [];
    if (invitedIds.length === 0) {
      const enrollments = await this.enrollmentRepo.findByClass(classId, orgId);
      invitedIds = enrollments.map((e: any) => e.student_id);
    }

    await this.meetingRepo.createInvites(orgId, meeting.id, invitedIds);

    // Notify all invited students
    await this.notificationService.createBulkNotifications(
      invitedIds.map((studentId) => ({
        orgId,
        accountId: studentId,
        type: 'meeting_created',
        payload: {
          meetingId: meeting.id,
          title: meeting.title,
          startTime: meeting.start_time,
          classId,
        },
      })),
    );

    await this.auditLog.logActivityEvent({
      orgId,
      actorId: educatorId,
      action: 'meeting_created',
      entityType: 'class',
      entityId: classId,
      metadata: { meetingId: meeting.id, title: meeting.title },
    });

    return this.meetingRepo.findById(meeting.id, orgId);
  }

  // ── GET /classes/:classId/meetings ────────────────────────────────────────

  async findAll(classId: string, orgId: string, educatorId: string) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }

    return this.meetingRepo.findAll(classId, orgId);
  }

  // ── GET /classes/:classId/meetings/:id ───────────────────────────────────

  async findOne(
    id: string,
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const cls = await this.classRepo.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');
    if (cls.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this class.');
    }

    const meeting = await this.meetingRepo.findById(id, orgId);
    if (!meeting || meeting.class_id !== classId) {
      throw new NotFoundException('Meeting not found.');
    }

    return meeting;
  }

  // ── PATCH /classes/:classId/meetings/:id ─────────────────────────────────

  async update(
    id: string,
    classId: string,
    orgId: string,
    educatorId: string,
    dto: UpdateMeetingDto,
  ) {
    const meeting = await this.assertEducatorOwnsMeeting(
      id,
      classId,
      orgId,
      educatorId,
    );

    if (meeting.status === 'ended') {
      throw new BadRequestException('Cannot update an ended meeting.');
    }

    if (dto.invitedStudentIds !== undefined) {
      await this.meetingRepo.replaceInvites(orgId, id, dto.invitedStudentIds);
    }

    return this.meetingRepo.update(id, {
      title: dto.title,
      description: dto.description,
      startTime: dto.startTime ? new Date(dto.startTime) : undefined,
    });
  }

  // ── DELETE /classes/:classId/meetings/:id ────────────────────────────────

  async remove(id: string, classId: string, orgId: string, educatorId: string) {
    await this.assertEducatorOwnsMeeting(id, classId, orgId, educatorId);
    return this.meetingRepo.softDelete(id);
  }

  // ── POST /classes/:classId/meetings/:id/end ──────────────────────────────

  async endMeeting(
    id: string,
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    let meeting;
    try {
      meeting = await this.assertEducatorOwnsMeeting(
        id,
        classId,
        orgId,
        educatorId,
      );
    } catch (err) {
      // Already gone — e.g. an ephemeral Groupy meeting hard-deleted the
      // moment its room emptied, or a duplicate end call raced in. Ending an
      // already-ended meeting is a no-op, so treat it as success instead of
      // surfacing a 404 to the client.
      if (err instanceof NotFoundException) {
        return { success: true, message: 'Meeting already ended.' };
      }
      throw err;
    }

    if (meeting.status === 'ended') {
      return { success: true, message: 'Meeting already ended.' };
    }

    // Ephemeral (Groupy) meetings are fully removed when ended — they aren't
    // stored on the meetings pages and have no post-meeting record.
    if (meeting.is_ephemeral) {
      await this.meetingRepo.hardDelete(id);
    } else {
      await this.meetingRepo.updateStatus(id, 'ended');

      await this.auditLog.logActivityEvent({
        orgId,
        actorId: educatorId,
        action: 'meeting_ended',
        entityType: 'class',
        entityId: classId,
        metadata: { meetingId: id },
      });
    }

    // Kick everyone still connected out of the room so no one lingers in a
    // session that no longer exists (or is now closed).
    this.meetingGateway.server.to(id).emit('meeting:ended', { meetingId: id });

    return { success: true, message: 'Meeting ended.' };
  }

  // ── POST /meetings/:id/join-request (student) ─────────────────────────────

  async requestJoin(id: string, orgId: string, studentId: string) {
    const meeting = await this.meetingRepo.findById(id, orgId);
    if (!meeting) throw new NotFoundException('Meeting not found.');

    if (meeting.status === 'ended') {
      throw new BadRequestException('This meeting has already ended.');
    }

    // Check if student is already invited — no need to request
    const isInvited = await this.meetingRepo.isStudentInvited(id, studentId);
    if (isInvited) {
      throw new ConflictException('You are already invited to this meeting.');
    }

    // Check for existing pending request
    const existing = await this.meetingRepo.findJoinRequest(id, studentId);
    if (existing) {
      throw new ConflictException(
        'You already have a pending join request for this meeting.',
      );
    }

    const request = await this.meetingRepo.createJoinRequest(
      orgId,
      id,
      studentId,
    );

    // Notify educator
    await this.notificationService.createNotification({
      orgId,
      accountId: meeting.educator_id,
      type: 'meeting_join_request',
      payload: {
        meetingId: id,
        studentId,
        requestId: request.id,
        title: meeting.title,
      },
    });

    return request;
  }

  // ── PATCH /meetings/:id/join-request/:reqId (educator) ───────────────────

  async respondToJoinRequest(
    id: string,
    reqId: string,
    orgId: string,
    educatorId: string,
    dto: RespondJoinRequestDto,
  ) {
    const meeting = await this.meetingRepo.findById(id, orgId);
    if (!meeting) throw new NotFoundException('Meeting not found.');

    if (meeting.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this meeting.');
    }

    const request = await this.meetingRepo.findJoinRequestById(reqId);
    if (!request || request.meeting_id !== id) {
      throw new NotFoundException('Join request not found.');
    }

    if (request.status !== 'pending') {
      throw new BadRequestException(
        'This request has already been responded to.',
      );
    }

    const updated = await this.meetingRepo.updateJoinRequest(reqId, dto.status);

    // If accepted → add student as invite so they can enter
    if (dto.status === 'accepted') {
      await this.meetingRepo.createInvites(orgId, id, [request.student_id]);

      await this.notificationService.createNotification({
        orgId,
        accountId: request.student_id,
        type: 'meeting_join_accepted',
        payload: { meetingId: id, title: meeting.title },
      });
    }

    return updated;
  }

  // ── GET /student/classes/:classId/meetings ────────────────────────────────

  async findAllForStudent(classId: string, orgId: string, studentId: string) {
    await this.assertStudentEnrolled(classId, studentId, orgId);

    const meetings = await this.meetingRepo.findAll(classId, orgId);

    // For each meeting mark if student is invited or has a join request
    return meetings.map((m) => ({
      id: m.id,
      title: m.title,
      description: m.description,
      startTime: m.start_time,
      status: m.status,
      isInvited: m.invites.some((i: any) => i.student_id === studentId),
      joinRequest:
        m.join_requests.find((r: any) => r.student_id === studentId) ?? null,
    }));
  }

  // ── GET /student/classes/:classId/meetings/:id ────────────────────────────

  async findOneForStudent(
    id: string,
    classId: string,
    orgId: string,
    studentId: string,
  ) {
    await this.assertStudentEnrolled(classId, studentId, orgId);

    const meeting = await this.meetingRepo.findById(id, orgId);
    if (!meeting || meeting.class_id !== classId) {
      throw new NotFoundException('Meeting not found.');
    }

    return {
      id: meeting.id,
      title: meeting.title,
      description: meeting.description,
      startTime: meeting.start_time,
      status: meeting.status,
      isInvited: meeting.invites.some((i: any) => i.student_id === studentId),
      joinRequest:
        meeting.join_requests.find((r: any) => r.student_id === studentId) ??
        null,
    };
  }

  // ── Private helpers ───────────────────────────────────────────────────────

  private async assertEducatorOwnsMeeting(
    id: string,
    classId: string,
    orgId: string,
    educatorId: string,
  ) {
    const meeting = await this.meetingRepo.findById(id, orgId);
    if (!meeting || meeting.class_id !== classId) {
      throw new NotFoundException('Meeting not found.');
    }
    if (meeting.educator_id !== educatorId) {
      throw new ForbiddenException('You do not own this meeting.');
    }
    return meeting;
  }

  private async assertStudentEnrolled(
    classId: string,
    studentId: string,
    orgId: string,
  ) {
    const enrollment = await this.enrollmentRepo.findOneByStudentAndClass(
      classId,
      studentId,
      orgId,
    );
    if (!enrollment) {
      throw new ForbiddenException('You are not enrolled in this class.');
    }
  }
}

