import {
  Injectable,
  ConflictException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { OrganizationRepository } from './organization.repository';
import { OrgSeederService } from '../org-seeder/org-seeder.service';
import { AuditLogService } from '../audit-log/audit-log.service';
import { DatabaseService } from '@/core/database/database.provider';
import {
  CreateOrganizationDto,
  UpdateOrganizationDto,
  SeedOrganizationDto,
} from './dto/organization.dto';
import { getDefaultEnabledKeys } from '@/modules/academic-calendar/data/holidays.data';

@Injectable()
export class OrganizationService {
  constructor(
    private readonly orgRepository: OrganizationRepository,
    private readonly orgSeeder: OrgSeederService,
    private readonly auditLogService: AuditLogService,
    private readonly db: DatabaseService,
  ) {}

  async create(adminId: string, dto: CreateOrganizationDto) {
    const alreadyExists = await this.orgRepository.existsForAdmin(adminId);
    if (alreadyExists) {
      throw new ConflictException(
        'An organization already exists for this account.',
      );
    }

    try {
      const org = await this.orgRepository.create({
        name: dto.name,
        description: dto.description,
        address: dto.address,
      });
      await this.orgRepository.linkToAdmin(adminId, org.id);

      this.auditLogService
        .logAdminAction({
          orgId: org.id,
          actorId: adminId,
          action: 'org_created',
          entityType: 'organization',
          entityId: org.id,
          metadata: { name: dto.name },
        })
        .catch(() => {});

      return org;
    } catch (e: any) {
      if (e?.code === 'P2002' && e?.meta?.target?.includes('email_extension')) {
        throw new ConflictException(
          'This email extension is already in use by another organization.',
        );
      }
      throw e;
    }
  }

  async getOwn(orgId: string | null) {
    if (!orgId) return null;
    const org = await this.orgRepository.findById(orgId);
    if (!org) return null;
    return {
      id: org.id,
      name: org.name,
      description: org.description,
      address: org.address,
      logoUrl: org.logo_url ?? null,
      emailExtension: org.email_extension ?? null,
    };
  }

  async update(orgId: string, dto: UpdateOrganizationDto, actorId: string) {
    const org = await this.orgRepository.findById(orgId);
    if (!org) throw new NotFoundException('Organization not found.');

    try {
      const updated = await this.orgRepository.update(orgId, {
        name: dto.name,
        description: dto.description,
        address: dto.address,
        ...(dto.emailExtension !== undefined && {
          email_extension: dto.emailExtension ?? undefined,
        }),
      });

      this.auditLogService
        .logAdminAction({
          orgId,
          actorId,
          action: 'org_updated',
          entityType: 'organization',
          entityId: orgId,
          metadata: { name: dto.name },
        })
        .catch(() => {});

      return updated;
    } catch (e: any) {
      if (e?.code === 'P2002' && e?.meta?.target?.includes('email_extension')) {
        throw new ConflictException(
          'This email extension is already in use by another organization.',
        );
      }
      throw e;
    }
  }

  async seed(orgId: string, dto: SeedOrganizationDto, actorId: string) {
    if (!orgId)
      throw new BadRequestException('No organization found for this account.');
    const org = await this.orgRepository.findById(orgId);
    if (!org) throw new NotFoundException('Organization not found.');

    const result = await this.orgSeeder.seedOrg({
      orgId,
      actorId,
      schoolYearId: dto.schoolYearId,
      programs: dto.programs,
      courses: dto.courses,
      strands: dto.strands,
      excludedLevels: dto.excludedLevels,
      excludedSubjects: dto.excludedSubjects,
      excludedLevelSubjects: dto.excludedLevelSubjects,
      levelConfigs: dto.levelConfigs,
      sectionConfigs: dto.sectionConfigs,
      gradingScales: dto.gradingScales,
      seedGradingScales: dto.seedGradingScales,
      seedGradingSchemes: dto.seedGradingSchemes,
      seedSemesterTemplates: dto.seedSemesterTemplates,
      seedProgramCalendars: dto.seedProgramCalendars,
      programCalendars: dto.programCalendars,
    });

    // Seed org-global holiday config with default Philippine holidays
    await this.db.orgHolidayConfig.upsert({
      where: { org_id: orgId },
      create: {
        org_id: orgId,
        enabled_keys: getDefaultEnabledKeys(),
        custom_holidays: [],
      },
      update: {}, // don't overwrite if already exists
    });

    return { success: true, message: 'Seed completed successfully.', result };
  }

  async getAllOrganizations() {
    return this.orgRepository.findAll();
  }

  // ========================================================================
  // ✅ NEW: Email Extension Validation & Account Check Methods
  // ========================================================================

  /**
   * ✅ NEW: Check if email extension is unique across all organizations
   *
   * @param extension - The extension to check (e.g., "@example.com")
   * @param excludeOrgId - Optional: exclude this org from the check (for editing)
   * @returns true if unique, false if already in use
   */
  async isEmailExtensionUnique(
    extension: string,
    excludeOrgId?: string,
  ): Promise<boolean> {
    const cleaned = extension.trim().replace(/^@/, '');
    const fullExtension = `@${cleaned}`;

    const existing = await this.db.organization.findFirst({
      where: {
        email_extension: fullExtension,
        ...(excludeOrgId && { NOT: { id: excludeOrgId } }),
      },
    });

    return !existing;
  }

  /**
   * ✅ NEW: Count accounts in organization (excluding platform_owner)
   *
   * Useful for preventing email extension changes when accounts exist
   *
   * @param orgId - The organization ID
   * @returns Number of accounts (educators, students, admins)
   */
  async countAccounts(orgId: string): Promise<number> {
    const count = await this.db.account.count({
      where: {
        org_id: orgId,
        role: { in: ['educator', 'student'] },
      },
    });
    return count;
  }

  /**
   * ✅ NEW: Count accounts by role for detailed reporting
   *
   * @param orgId - The organization ID
   * @returns Breakdown of accounts by role
   */
  async countAccountsByRole(orgId: string): Promise<{
    educators: number;
    students: number;
    admins: number;
    total: number;
  }> {
    const [educators, students, admins] = await Promise.all([
      this.db.account.count({ where: { org_id: orgId, role: 'educator' } }),
      this.db.account.count({ where: { org_id: orgId, role: 'student' } }),
      this.db.account.count({ where: { org_id: orgId, role: 'admin' } }),
    ]);

    return {
      educators,
      students,
      admins,
      total: educators + students + admins,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';
import { Prisma } from '@prisma/client';

@Injectable()
export class PlatformRegistrationRepository {
  constructor(private readonly db: DatabaseService) {}

  async findMany(params: {
    search?: string;
    status?: string;
    page: number;
    limit: number;
  }) {
    const where: any = {};

    if (params.search) {
      where.OR = [
        { email: { contains: params.search, mode: 'insensitive' } },
        { full_name: { contains: params.search, mode: 'insensitive' } },
      ];
    }

    if (params.status && params.status !== 'all') {
      where.status = params.status;
    }

    const [data, total] = await Promise.all([
      this.db.registrationRequest.findMany({
        where,
        orderBy: { created_at: 'desc' },
        skip: (params.page - 1) * params.limit,
        take: params.limit,
      }),
      this.db.registrationRequest.count({ where }),
    ]);

    return { data, total };
  }

  async findById(id: string) {
    return this.db.registrationRequest.findUnique({ where: { id } });
  }

  async updateStatus(id: string, status: string) {
    return this.db.registrationRequest.update({
      where: { id },
      data: { status: status as any },
    });
  }

  async markReviewed(
    id: string,
    status: 'approved' | 'rejected',
    reviewedBy: string,
  ) {
    return this.db.registrationRequest.update({
      where: { id },
      data: {
        status: status as any,
        reviewed_by: reviewedBy,
        reviewed_at: new Date(),
      },
    });
  }

  async markRequestRevision(
    id: string,
    fieldNotes: Record<string, string>,
    reviewedBy: string,
  ) {
    return this.db.registrationRequest.update({
      where: { id },
      data: {
        status: 'needs_revision' as any,
        revision_notes: fieldNotes,
        reviewed_by: reviewedBy,
        reviewed_at: new Date(),
      },
    });
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { hashPassword } from '@/commons/utils/hash.util';
import { generatePassword } from '@/commons/utils/password.util';
import { generateAdminLoginEmail } from '@/commons/utils/admin-login-email.util';
import { DatabaseService } from '@/core/database/database.provider';
import { PlatformRegistrationRepository } from './platform-registration.repository';
import { MailService } from '@/modules/mail/mail.service';
import {
  RequestRevisionDto,
  RejectRequestDto,
} from './dto/approve-request.dto';

/**
 * Field names on RegistrationRequest that an applicant may be asked to revise.
 * Used to reject unknown keys in a request-revision's fieldNotes rather than
 * silently persisting garbage.
 */
const REQUEST_FIELDS = new Set([
  'full_name',
  'institution_name',
  'role',
  'student_count',
  'programs_departments',
  'plan',
]);

@Injectable()
export class PlatformRegistrationService {
  constructor(
    private readonly repo: PlatformRegistrationRepository,
    private readonly db: DatabaseService,
    private readonly mailService: MailService,
  ) {}

  async list(params: {
    search?: string;
    status?: string;
    page: number;
    limit: number;
  }) {
    return this.repo.findMany(params);
  }

  async approve(id: string, reviewedBy: string) {
    const request = await this.repo.findById(id);
    if (!request) {
      throw new NotFoundException('Registration request not found');
    }

    if (request.status !== 'pending') {
      throw new BadRequestException(`Request is already ${request.status}`);
    }

    // Login email is system-generated, decoupled from the personal Gmail.
    const loginEmail = generateAdminLoginEmail(request.email);

    const existing = await this.db.account.findFirst({
      where: { email: loginEmail, deleted_at: null },
    });
    if (existing) {
      throw new BadRequestException(
        `An account with email ${loginEmail} already exists`,
      );
    }

    const password = generatePassword();
    const hashedPassword = await hashPassword(password);

    // Approval creates the Account + Profile only. No Organization is
    // auto-created — the admin sets one up themselves after first login
    // (org_id stays null, which drives the existing org-setup guard).
    const account = await this.db.account.create({
      data: {
        email: loginEmail,
        password: hashedPassword,
        role: 'admin' as any,
        status: 'active' as any,
        profile: {
          create: {
            full_name: request.full_name,
            personal_email: request.email,
          },
        },
      },
      include: { profile: true },
    });

    await this.repo.markReviewed(id, 'approved', reviewedBy);

    // Send credentials immediately while the plaintext password is in memory.
    // Sent to the applicant's Gmail but shows the generated login email.
    await this.mailService.sendCredentialsEmail(
      request.email,
      account.email,
      password,
    );

    return {
      email: account.email,
      fullName: account.profile?.full_name ?? '',
      password,
    };
  }

  async reject(id: string, reviewedBy: string, dto: RejectRequestDto) {
    const request = await this.repo.findById(id);
    if (!request) {
      throw new NotFoundException('Registration request not found');
    }

    if (request.status !== 'pending') {
      throw new BadRequestException(`Request is already ${request.status}`);
    }

    await this.repo.markReviewed(id, 'rejected', reviewedBy);

    // Notify the applicant at their Gmail; reason is included when provided.
    await this.mailService.sendRejectionEmail(request.email, dto.reason);

    return { message: 'Request rejected', reason: dto.reason ?? null };
  }

  async requestRevision(
    id: string,
    reviewedBy: string,
    dto: RequestRevisionDto,
  ) {
    const request = await this.repo.findById(id);
    if (!request) {
      throw new NotFoundException('Registration request not found');
    }

    if (request.status !== 'pending') {
      throw new BadRequestException(`Request is already ${request.status}`);
    }

    const unknownFields = Object.keys(dto.fieldNotes ?? {}).filter(
      (field) => !REQUEST_FIELDS.has(field),
    );
    if (unknownFields.length > 0) {
      throw new BadRequestException(
        `Unknown field name(s): ${unknownFields.join(', ')}`,
      );
    }

    await this.repo.markRequestRevision(id, dto.fieldNotes, reviewedBy);

    // Notify the applicant at their Gmail, listing every flagged field + note.
    await this.mailService.sendRevisionNeededEmail(
      request.email,
      dto.fieldNotes,
    );

    return { message: 'Revision requested' };
  }

  async sendCredentials(id: string) {
    const request = await this.repo.findById(id);
    if (!request) {
      throw new NotFoundException('Registration request not found');
    }

    if (request.status !== 'approved') {
      throw new BadRequestException(
        'Cannot send credentials for a non-approved request',
      );
    }

    throw new BadRequestException(
      'Credentials were already sent at approval time. The password cannot be resent as it is not stored in plaintext.',
    );
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';

@Injectable()
export class PlatformOwnerGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user || user.role !== 'platform_owner') {
      throw new ForbiddenException('Platform owner only');
    }

    return true;
  }
}

