import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';

const PROGRAM_LIST_INCLUDE = {
  courses: {
    select: { id: true, name: true, code: true },
    orderBy: { name: 'asc' as const },
  },
  strands: {
    select: { id: true, name: true },
    orderBy: { name: 'asc' as const },
  },
};

const PROGRAM_STATS_INCLUDE_COLLEGE = {
  courses: {
    orderBy: { name: 'asc' as const },
    include: {
      subjects: {
        select: {
          id: true,
          name: true,
          year_level: true,
          term_label: true,
          is_locked: true,
        },
        orderBy: [
          { year_level: 'asc' as const },
          { term_label: 'asc' as const },
          { name: 'asc' as const },
        ],
      },
    },
  },
};

const PROGRAM_STATS_INCLUDE_SENIOR_HIGH = {
  strands: {
    orderBy: { name: 'asc' as const },
    include: {
      subjects: {
        select: {
          id: true,
          name: true,
          year_level: true,
          term_label: true,
          is_locked: true,
        },
        orderBy: [
          { year_level: 'asc' as const },
          { term_label: 'asc' as const },
          { name: 'asc' as const },
        ],
      },
    },
  },
};

const PROGRAM_STATS_INCLUDE_DEFAULT = {
  levels: {
    select: { id: true, name: true },
    orderBy: { name: 'asc' as const },
  },
};

const PROGRAM_DETAIL_INCLUDE = {
  courses: {
    orderBy: { name: 'asc' as const },
    include: {
      subjects: {
        select: {
          id: true,
          name: true,
          year_level: true,
          term_label: true,
          is_locked: true,
        },
        orderBy: [
          { year_level: 'asc' as const },
          { term_label: 'asc' as const },
          { name: 'asc' as const },
        ],
      },
    },
  },
  strands: {
    orderBy: { name: 'asc' as const },
    include: {
      subjects: {
        select: {
          id: true,
          name: true,
          year_level: true,
          term_label: true,
          is_locked: true,
        },
        orderBy: [
          { year_level: 'asc' as const },
          { term_label: 'asc' as const },
          { name: 'asc' as const },
