};

@Injectable()
export class ProgramRepository {
  constructor(private readonly db: DatabaseService) {}

  async create(data: {
    orgId: string;
    schoolYearId: string;
    name: string;
    type: string;
  }) {
    return this.db.program.create({
      data: {
        org_id: data.orgId,
        school_year_id: data.schoolYearId,
        name: data.name,
        type: data.type,
      },
      include: PROGRAM_LIST_INCLUDE,
    });
  }

  async findAll(
    orgId: string,
    schoolYearId: string,
    includeAssignment = false,
  ) {
    return this.db.program.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
      },
      include: {
        ...PROGRAM_LIST_INCLUDE,

        // ✅ conditional include
        ...(includeAssignment && {
          semesterAssignment: {
            include: {
              template: {
                select: { id: true, name: true },
              },
            },
          },
        }),
      },
      orderBy: { name: 'asc' },
    });
  }

  async findAllWithStats(
    orgId: string,
    schoolYearId: string,
    includeAssignment = false,
  ) {
    const programs = await this.db.program.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
      },
      select: {
        id: true,
        org_id: true,
        school_year_id: true,
        name: true,
        type: true,
      },
      orderBy: { name: 'asc' },
    });

    // Fetch related data based on program type
    const programIds = programs.map((p) => p.id);

    const [levels, courses, strands] = await Promise.all([
      this.db.level.findMany({
        where: { program_id: { in: programIds } },
        select: { id: true, name: true, program_id: true },
        orderBy: { name: 'asc' },
      }),
      this.db.course.findMany({
        where: { program_id: { in: programIds } },
        select: { id: true, name: true, code: true, program_id: true },
        orderBy: { name: 'asc' },
      }),
      this.db.strand.findMany({
        where: { program_id: { in: programIds } },
        select: { id: true, name: true, program_id: true },
        orderBy: { name: 'asc' },
      }),
    ]);

    // Group related data by program_id
    const levelsByProgram = levels.reduce(
      (acc, level) => {
        if (!acc[level.program_id]) acc[level.program_id] = [];
        acc[level.program_id].push(level);
        return acc;
      },
      {} as Record<string, any[]>,
    );

    const coursesByProgram = courses.reduce(
      (acc, course) => {
        if (!acc[course.program_id]) acc[course.program_id] = [];
        acc[course.program_id].push(course);
        return acc;
      },
      {} as Record<string, any[]>,
    );

    const strandsByProgram = strands.reduce(
      (acc, strand) => {
        if (!acc[strand.program_id]) acc[strand.program_id] = [];
        acc[strand.program_id].push(strand);
        return acc;
      },
      {} as Record<string, any[]>,
    );

    // Combine programs with their stats
    return programs.map((program) => ({
      ...program,
      levels: levelsByProgram[program.id] || [],
      courses: coursesByProgram[program.id] || [],
      strands: strandsByProgram[program.id] || [],
    }));
  }

  async findById(id: string, orgId: string) {
    return this.db.program.findFirst({
      where: { id, org_id: orgId },
      include: PROGRAM_DETAIL_INCLUDE,
    });
  }

  async findByNameAndYear(name: string, orgId: string, schoolYearId: string) {
    return this.db.program.findFirst({
      where: { name, org_id: orgId, school_year_id: schoolYearId },
      select: { id: true },
    });
  }

  async update(id: string, data: { name?: string; type?: string }) {
    return this.db.program.update({
      where: { id },
      data: {
        ...(data.name !== undefined ? { name: data.name } : {}),
        ...(data.type !== undefined ? { type: data.type } : {}),
      },
      include: PROGRAM_LIST_INCLUDE,
    });
  }

  async delete(id: string) {
    return this.db.program.delete({ where: { id } });
  }

  async hasLevels(programId: string): Promise<boolean> {
    const count = await this.db.level.count({
      where: { program_id: programId },
    });
    return count > 0;
  }

  async hasCourses(programId: string): Promise<boolean> {
    const count = await this.db.course.count({
      where: { program_id: programId },
    });
    return count > 0;
  }

  async hasStrands(programId: string): Promise<boolean> {
    const count = await this.db.strand.count({
      where: { program_id: programId },
    });
    return count > 0;
  }
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { ProgramRepository } from './program.repository';
import { DatabaseService } from '@/core/database/database.provider';
import { AuditLogService } from '../audit-log/audit-log.service';
import { CreateProgramDto, UpdateProgramDto } from './dto/program.dto';

@Injectable()
export class ProgramService {
  constructor(
    private readonly programRepository: ProgramRepository,
    private readonly db: DatabaseService,
    private readonly auditLogService: AuditLogService,
  ) {}

  async create(orgId: string, dto: CreateProgramDto, actorId: string) {
    const nameTaken = await this.programRepository.findByNameAndYear(
      dto.name,
      orgId,
      dto.schoolYearId,
    );

    if (nameTaken) {
      throw new ConflictException(
        `A program named "${dto.name}" already exists for this school year.`,
      );
    }

    const program = await this.programRepository.create({
      orgId,
      schoolYearId: dto.schoolYearId,
      name: dto.name,
      type: dto.type,
    });

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'program_created',
        entityType: 'program',
        entityId: program.id,
        metadata: { name: dto.name, type: dto.type },
      })
      .catch(() => {});

    return program;
  }

  // ✅ UPDATED: added includeAssignment flag
  async findAll(
    orgId: string,
    schoolYearId: string,
    includeAssignment = false,
  ) {
    return this.programRepository.findAll(
      orgId,
      schoolYearId,
      includeAssignment,
    );
  }

  // ✅ NEW: fetch programs with stats data
  async findAllWithStats(
    orgId: string,
    schoolYearId: string,
    includeAssignment = false,
  ) {
    return this.programRepository.findAllWithStats(
      orgId,
      schoolYearId,
      includeAssignment,
    );
  }

  async findById(id: string, orgId: string) {
    const program = await this.programRepository.findById(id, orgId);
    if (!program) throw new NotFoundException('Program not found.');
    return program;
  }

  async update(
    id: string,
    orgId: string,
    dto: UpdateProgramDto,
    actorId: string,
  ) {
    const program = await this.programRepository.findById(id, orgId);
    if (!program) throw new NotFoundException('Program not found.');

    const updated = await this.programRepository.update(id, {
      name: dto.name,
      type: dto.type,
    });

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'program_updated',
        entityType: 'program',
        entityId: id,
        metadata: { name: dto.name },
      })
      .catch(() => {});

    return updated;
  }

  async getSemesters(programId: string, schoolYearId: string, orgId: string) {
    // Find the semester template assignment for this program
    const assignment = await this.db.programSemesterAssignment.findFirst({
      where: { program_id: programId, org_id: orgId },
      include: {
        template: {
          include: {
            semesters: { orderBy: { order_index: 'asc' as const } },
          },
        },
      },
    });

    if (!assignment) return [];

    const templateSemesterNames = new Set(
      assignment.template.semesters.map((s: { name: string }) => s.name),
    );

    // Find actual Semester records matching those names + school year
    const semesters = await this.db.semester.findMany({
      where: {
        org_id: orgId,
        school_year_id: schoolYearId,
        name: { in: [...templateSemesterNames] },
      },
      include: {
        terms: { orderBy: { order_index: 'asc' as const } },
      },
      orderBy: { start_date: 'asc' as const },
    });

    return semesters.map((s) => ({
      id: s.id,
      school_year_id: s.school_year_id,
      name: s.name,
      start_date: s.start_date,
      end_date: s.end_date,
      terms: (s.terms ?? []).map((t: any) => ({
        id: t.id,
        name: t.name,
        order_index: t.order_index,
        start_date: t.start_date,
        end_date: t.end_date,
      })),
    }));
  }

  async remove(id: string, orgId: string, actorId: string) {
    const program = await this.programRepository.findById(id, orgId);
    if (!program) throw new NotFoundException('Program not found.');

    const [hasLevels, hasCourses, hasStrands] = await Promise.all([
      this.programRepository.hasLevels(id),
      this.programRepository.hasCourses(id),
      this.programRepository.hasStrands(id),
    ]);

    const blockers: string[] = [];
    if (hasLevels) blockers.push('levels');
    if (hasCourses) blockers.push('courses');
    if (hasStrands) blockers.push('strands');

    if (blockers.length > 0) {
      throw new ConflictException(
        `Cannot delete this program — it still has ${blockers.join(', ')} assigned to it.`,
      );
    }

    await this.programRepository.delete(id);

    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'program_deleted',
        entityType: 'program',
        entityId: id,
        metadata: { name: program.name },
      })
      .catch(() => {});
  }
}

// @/modules/registrar/registrar.repository.ts
import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { DatabaseService } from '@/core/database/database.provider';

@Injectable()
export class RegistrarRepository {
  constructor(private readonly db: DatabaseService) {}

  async create(data: {
    orgId: string;
    email: string;
    hashedPassword: string;
    username: string;
    fullName?: string;
  }) {
    return this.db.account.create({
      data: {
        org_id: data.orgId,
        email: data.email,
        password: data.hashedPassword,
        role: 'admin',
        status: 'active',
        is_registrar: true,
        profile: {
          create: {
            full_name: data.fullName?.trim() || data.username,
            metadata: {
              registrarUsername: data.username,
            },
          },
        },
      },
      include: { profile: true },
    });
  }

  async findAll(
    orgId: string,
    filters: {
      search?: string;
      status?: string;
      page?: number;
      limit?: number;
    },
  ) {
    const { search, status, page = 1, limit = 20 } = filters;

    const where: Prisma.AccountWhereInput = {
      org_id: orgId,
      role: 'admin',
      is_registrar: true,
      deleted_at: null,
      ...(status ? { status: status as any } : {}),
      ...(search
        ? {
            OR: [
              {
                profile: {
                  full_name: { contains: search, mode: 'insensitive' },
                },
              },
              {
                profile: {
                  metadata: {
                    path: ['registrarUsername'],
                    string_contains: search,
                  },
                },
              },
              { email: { contains: search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };

    const [data, total] = await Promise.all([
      this.db.account.findMany({
        where,
        include: { profile: true },
        orderBy: { created_at: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.db.account.count({ where }),
    ]);

    return { data, total };
  }

  async findById(id: string, orgId: string) {
    return this.db.account.findFirst({
      where: {
        id,
        org_id: orgId,
        role: 'admin',
        is_registrar: true,
        deleted_at: null,
      },
      include: { profile: true },
    });
  }

  async findByEmail(email: string, orgId: string) {
    return this.db.account.findFirst({
      where: {
        email,
        org_id: orgId,
        role: 'admin',
        is_registrar: true,
        deleted_at: null,
      },
    });
  }

  async updateStatus(accountId: string, status: string) {
    return this.db.account.update({
      where: { id: accountId },
      data: { status: status as any },
      include: { profile: true },
    });
  }

  async updatePassword(accountId: string, hashedPassword: string) {
    return this.db.account.update({
      where: { id: accountId },
      data: { password: hashedPassword },
    });
  }

  /** Soft delete — sets deleted_at on the Account row. */
  async softDelete(accountId: string) {
    return this.db.account.update({
      where: { id: accountId },
      data: { deleted_at: new Date() },
    });
  }
}

// @/modules/registrar/registrar.service.ts
import {
  Injectable,
  ConflictException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { RegistrarRepository } from './registrar.repository';
import {
  CreateRegistrarDto,
  QueryRegistrarDto,
  UpdateRegistrarStatusDto,
} from './dto/registrar.dto';
import { generateSystemPassword } from './registrar.utils';
import { hashPassword } from '@/commons/utils/hash.util';
import { OrganizationService } from '../organization/organization.service';

@Injectable()
export class RegistrarService {
  constructor(
    private readonly registrarRepository: RegistrarRepository,
    private readonly organizationService: OrganizationService,
  ) {}

  // ── POST /registrars ─────────────────────────────────────────────────────────

  async create(orgId: string, dto: CreateRegistrarDto) {
    const email = await this.buildOrgEmail(orgId, dto.username);

    const existing = await this.registrarRepository.findByEmail(email, orgId);
    if (existing) {
      throw new ConflictException(
        'An account with this username already exists in the organization.',
      );
    }

    const plainPassword = generateSystemPassword();
    const hashedPassword = await hashPassword(plainPassword);

    const account = await this.registrarRepository.create({
      orgId,
      email,
      hashedPassword,
      username: dto.username,
      fullName: dto.fullName,
    });

    return {
      id: account.id,
      orgId: account.org_id,
      email: account.email,
      status: account.status,
      username: dto.username,
      fullName: account.profile?.full_name ?? dto.username,
      plainPassword,
      createdAt: account.created_at,
    };
  }

  // ── GET /registrars ──────────────────────────────────────────────────────────

  async findAll(orgId: string, query: QueryRegistrarDto) {
    const page = query.page ?? 1;
    const limit = query.limit ?? 20;

    const { data, total } = await this.registrarRepository.findAll(orgId, {
      search: query.search,
      status: query.status,
      page,
      limit,
    });

    return {
      data: data.map((a) => this.formatAccount(a)),
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  // ── PATCH /registrars/:id/status ──────────────────────────────────────────────

  async updateStatus(id: string, orgId: string, dto: UpdateRegistrarStatusDto) {
    const account = await this.registrarRepository.findById(id, orgId);
    if (!account) {
      throw new NotFoundException('Registrar not found.');
    }

    const updated = await this.registrarRepository.updateStatus(id, dto.status);
    return this.formatAccount(updated);
  }

  // ── DELETE /registrars/:id ───────────────────────────────────────────────────

  async remove(id: string, orgId: string) {
    const account = await this.registrarRepository.findById(id, orgId);
    if (!account) {
      throw new NotFoundException('Registrar not found.');
    }

    await this.registrarRepository.softDelete(id);
  }

  // ── POST /registrars/:id/reset-password ──────────────────────────────────────

  async resetPassword(id: string, orgId: string) {
    const account = await this.registrarRepository.findById(id, orgId);
    if (!account) {
      throw new NotFoundException('Registrar not found.');
    }

    const plainPassword = generateSystemPassword();
    const hashedPassword = await hashPassword(plainPassword);

    await this.registrarRepository.updatePassword(id, hashedPassword);

    return { id, plainPassword };
  }

  // ── Utility ─────────────────────────────────────────────────────────────────

  /**
   * Builds an org-scoped email for a registrar using the org email extension.
   * Registrars live on their own subdomain segment (e.g. registrar.school.edu.ph)
   * so they can never collide with student/educator accounts.
   */
  private async buildOrgEmail(orgId: string, username: string) {
    const org = await this.organizationService.getOwn(orgId);
    const extension = org?.emailExtension?.trim();
    if (!extension) {
      throw new BadRequestException(
        'Set the organization email extension before creating registrar accounts.',
      );
    }

    const localPart = username.trim().replace(/^@+/, '').toLowerCase();
    if (!localPart || localPart.includes('@')) {
      throw new BadRequestException(
        'Username must not include an email extension.',
      );
    }

    const base = extension
      .replace(/^@/, '')
      .replace(/\.(student|educator|registrar)\./g, '.')
      .trim();

    const dotIdx = base.indexOf('.');
    const domain =
      dotIdx >= 0
        ? `${base.slice(0, dotIdx)}.registrar${base.slice(dotIdx)}`
        : `registrar.${base}`;

    return `${localPart}@${domain}`.toLowerCase();
  }

  private formatAccount(account: any) {
    const meta = account.profile?.metadata as Record<string, any> | null;
    return {
      id: account.id,
      orgId: account.org_id,
      email: account.email,
      status: account.status,
      username: meta?.registrarUsername ?? account.profile?.full_name ?? null,
      fullName: account.profile?.full_name ?? null,
      createdAt: account.created_at,
    };
  }
}

// backend/src/modules/school-year/school-year-readiness.service.ts

import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';

export type ReadinessSeverity = 'blocking' | 'warning';

export interface ReadinessIssue {
  code: string;
  severity: ReadinessSeverity;
  message: string;
  /** How many entities are affected by this issue (absent on legacy per-entity issues). */
  count?: number;
  /** Optional detail list of affected entities, capped (see pushList). */
  entities?: { id: string; name: string }[];
  ref?: {
    type: 'program' | 'course' | 'strand' | 'level' | 'subject';
    id: string;
    name: string;
  };
}

export interface ReadinessResult {
  ready: boolean;
  blockingCount: number;
  warningCount: number;
  issues: ReadinessIssue[];
}

export interface ReadinessSummary {
  schoolYearId: string;
  ready: boolean;
  blockingCount: number;
  warningCount: number;
}

/** Per code, the maximum number of issue entries included in a detail result. */
const MAX_ISSUES_PER_CODE = 20;

@Injectable()
export class SchoolYearReadinessService {
  constructor(private readonly db: DatabaseService) {}

  /**
   * Full readiness detail for a single school year.
   * Throws 404 when the school year does not exist in the org.
   */
  async detail(orgId: string, schoolYearId: string): Promise<ReadinessResult> {
    const schoolYear = await this.db.schoolYear.findFirst({
      where: { id: schoolYearId, org_id: orgId },
      select: {
        id: true,
        name: true,
        start_date: true,
        status: true,
      },
    });

    if (!schoolYear) {
      throw new NotFoundException('School year not found.');
    }

    const issues: ReadinessIssue[] = [];

    if (!schoolYear.start_date) {
      issues.push({
        code: 'missing_start_date',
        severity: 'blocking',
        message: `School year "${schoolYear.name}" has no start date and cannot be used.`,
      });
    }

    const programs = await this.db.program.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId },
      orderBy: { name: 'asc' },
      select: {
        id: true,
        name: true,
        type: true,
        _count: { select: { levels: true, courses: true, strands: true } },
      },
    });

    if (programs.length === 0) {
      issues.push({
        code: 'no_programs',
        severity: 'blocking',
        message: `School year "${schoolYear.name}" has no programs.`,
      });
    }

    for (const program of programs) {
      this.push(issues, {
        code: 'program_no_levels',
        severity: 'blocking',
        ref: { type: 'program', id: program.id, name: program.name },
        message: `Program "${program.name}" has no levels.`,
        when: program._count.levels === 0,
      });

      if (program.type === 'college') {
        const courses = await this.db.course.findMany({
          where: { program_id: program.id, org_id: orgId },
          orderBy: { name: 'asc' },
          select: {
            id: true,
            name: true,
            _count: { select: { levels: true } },
          },
        });
        for (const course of courses) {
          this.push(issues, {
            code: 'course_no_level',
            severity: 'blocking',
            ref: { type: 'course', id: course.id, name: course.name },
            message: `Course "${course.name}" has no levels.`,
            when: course._count.levels === 0,
          });
        }
      } else if (program.type === 'senior_high') {
        const strands = await this.db.strand.findMany({
          where: { program_id: program.id, org_id: orgId },
          orderBy: { name: 'asc' },
          select: {
            id: true,
            name: true,
            _count: { select: { levels: true } },
          },
        });
        for (const strand of strands) {
          this.push(issues, {
            code: 'strand_no_level',
            severity: 'blocking',
            ref: { type: 'strand', id: strand.id, name: strand.name },
            message: `Strand "${strand.name}" has no levels.`,
            when: strand._count.levels === 0,
          });
        }
      }
    }

    const levels = await this.db.level.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId },
      orderBy: { name: 'asc' },
      select: {
        id: true,
        name: true,
        _count: {
          select: {
            sections: { where: { deleted_at: null } },
            subjects: true,
          },
        },
      },
    });

    for (const level of levels) {
      this.push(issues, {
        code: 'level_no_sections',
        severity: 'blocking',
        ref: { type: 'level', id: level.id, name: level.name },
        message: `Level "${level.name}" has no sections.`,
        when: level._count.sections === 0,
      });

      this.push(issues, {
        code: 'level_no_subjects',
        severity: 'blocking',
        ref: { type: 'level', id: level.id, name: level.name },
        message: `Level "${level.name}" has no subjects.`,
        when: level._count.subjects === 0,
      });
    }

    // ----------------------------------------------------------------------
    // Overview's hard-block checklist (all blocking, no override).
    // Empty-school-year rule: a year with zero programs already fails via
    // `no_programs` above, so a year with nothing configured is NOT ready —
    // this is deliberate, not an oversight.
    // ----------------------------------------------------------------------

    const levelIds = levels.map((l) => l.id);
    const programIds = programs.map((p) => p.id);
    const courses = await this.db.course.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId },
      select: { id: true, name: true },
    });
    const strands = await this.db.strand.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId },
      select: { id: true, name: true },
    });
    const courseIds = courses.map((c) => c.id);
    const strandIds = strands.map((s) => s.id);

    // 1. Every subject scoped to this school year (via level/program/course/strand)
    //    has at least one Class.
    const subjects = await this.db.subject.findMany({
      where: {
        org_id: orgId,
        OR: [
          { level_id: { in: levelIds } },
          { program_id: { in: programIds } },
          { course_id: { in: courseIds } },
          { strand_id: { in: strandIds } },
        ],
      },
      select: {
        id: true,
        name: true,
        _count: { select: { classes: { where: { deleted_at: null } } } },
      },
    });
    this.pushList(issues, {
      code: 'subject_no_class',
      items: subjects
        .filter((s) => s._count.classes === 0)
        .map((s) => ({ id: s.id, name: s.name })),
      message: (count) =>
        `${count} subject(s) in this school year have no class created.`,
    });

    // 2. Every Section (school_year_id = this year) has at least one Class.
    //    Section has no Class relation in the schema, so use a count comparison.
    const sectionClassCounts = await this.db.class.groupBy({
      by: ['section_id'],
      where: { org_id: orgId, deleted_at: null },
      _count: { _all: true },
    });
    const sectionsWithClasses = new Set<string>(
      sectionClassCounts
        .filter((r) => r.section_id !== null)
        .map((r) => r.section_id as string),
    );
    const sections = await this.db.section.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId, deleted_at: null },
      select: { id: true, name: true },
      orderBy: { name: 'asc' },
    });
    this.pushList(issues, {
      code: 'section_no_class',
      items: sections.filter((s) => !sectionsWithClasses.has(s.id)),
      message: (count) =>
        `${count} section(s) in this school year have no class created.`,
    });

    // 3. Every Program in this school year has a ProgramCalendar.
    const programsWithoutCalendar = await this.db.program.findMany({
      where: {
        school_year_id: schoolYearId,
        org_id: orgId,
        programCalendars: { none: {} },
      },
      select: { id: true, name: true },
      orderBy: { name: 'asc' },
    });
    this.pushList(issues, {
      code: 'program_no_calendar',
      items: programsWithoutCalendar,
      message: (count) =>
        `${count} program(s) have no academic calendar set up.`,
    });

    // 5. Every Program in this school year has a GradingScaleAssignment.
    const programsWithoutScale = await this.db.program.findMany({
      where: {
        school_year_id: schoolYearId,
        org_id: orgId,
        gradingScaleAssignments: { none: {} },
      },
      select: { id: true, name: true },
      orderBy: { name: 'asc' },
    });
    this.pushList(issues, {
      code: 'program_no_grading_scale',
      items: programsWithoutScale,
      message: (count) => `${count} program(s) have no grading scale assigned.`,
    });

    // 4. Every Program has a ProgramSemesterAssignment, AND every term in that
    //    assignment's template has a ProgramSemesterTermDate with dates filled.
    //    (ProgramSemesterTermDate.start_date/end_date are non-null, so "has a
    //    date, filled" reduces to "has a term-date row for every template term".)
    const programSem = await this.db.program.findMany({
      where: { school_year_id: schoolYearId, org_id: orgId },
      select: {
        id: true,
        name: true,
        semesterAssignment: {
          select: {
            id: true,
            template: {
              select: {
                semesters: { select: { terms: { select: { id: true } } } },
              },
            },
          },
        },
      },
    });
    const termDateCounts = await this.db.programSemesterTermDate.groupBy({
      by: ['assignment_id'],
      where: { org_id: orgId },
      _count: { _all: true },
    });
    const termDateByAssignment = new Map<number | string, number>();
    for (const row of termDateCounts)
      termDateByAssignment.set(row.assignment_id, row._count._all);
    const noAssignment: { id: string; name: string }[] = [];
    const incompleteDates: { id: string; name: string }[] = [];
    for (const prog of programSem) {
      const assignment = prog.semesterAssignment;
      if (!assignment) {
        noAssignment.push({ id: prog.id, name: prog.name });
        continue;
      }
      const requiredTerms = assignment.template.semesters.reduce(
        (sum, sem) => sum + sem.terms.length,
        0,
      );
      const presentDates = termDateByAssignment.get(assignment.id) ?? 0;
      if (presentDates < requiredTerms) {
        incompleteDates.push({ id: prog.id, name: prog.name });
      }
    }
    this.pushList(issues, {
      code: 'program_no_semester_assignment',
      items: noAssignment,
      message: (count) =>
        `${count} program(s) have no semester template assigned.`,
    });
    this.pushList(issues, {
      code: 'program_semester_dates_incomplete',
      items: incompleteDates,
      message: (count) =>
        `${count} program(s) have incomplete semester term dates.`,
    });

    // 6. Every Class in this school year has at least one GradingScheme.
    const classesWithoutScheme = await this.db.class.findMany({
      where: {
        school_year_id: schoolYearId,
        org_id: orgId,
        deleted_at: null,
        gradingSchemes: { none: {} },
      },
      select: { id: true, subject: { select: { name: true } } },
      orderBy: { created_at: 'asc' },
    });
    this.pushList(issues, {
      code: 'class_no_grading_scheme',
      items: classesWithoutScheme.map((c) => ({
        id: c.id,
        name: c.subject?.name ?? c.id,
      })),
      message: (count) => `${count} class(es) have no grading scheme.`,
    });

    // 7. Educator assignment is structurally guaranteed by the non-nullable
    //    Class.educator_id column, so no runtime check is required.

    return this.buildResult(issues);
  }

  /**
   * Lightweight per-year summary for the org-wide list page.
   * Exactly one school year per org entry is analyzed in a small constant number
   * of grouped queries (no unbounded sub-iteration).
   */
  async summarizeAll(orgId: string): Promise<Record<string, ReadinessSummary>> {
    const schoolYears = await this.db.schoolYear.findMany({
      where: { org_id: orgId },
      select: { id: true, name: true, start_date: true },
    });

    const programCounts = await this.db.program.groupBy({
      by: ['school_year_id'],
      where: { org_id: orgId },
      _count: { _all: true },
    });
    const levelCounts = await this.db.level.groupBy({
      by: ['school_year_id'],
      where: { org_id: orgId },
      _count: { _all: true },
    });
    const sectionCounts = await this.db.section.groupBy({
      by: ['school_year_id'],
      where: { org_id: orgId, deleted_at: null },
      _count: { _all: true },
    });

    const programByYear = this.toMap(programCounts, 'school_year_id');
    const levelByYear = this.toMap(levelCounts, 'school_year_id');
    const sectionByYear = this.toMap(sectionCounts, 'school_year_id');

    const summaries: Record<string, ReadinessSummary> = {};
    for (const sy of schoolYears) {
      const blockingCount = this.summaryBlockingCount(
        sy,
        programByYear,
        levelByYear,
        sectionByYear,
      );
      summaries[sy.id] = {
        schoolYearId: sy.id,
        ready: blockingCount === 0,
        blockingCount,
        warningCount: 0,
      };
    }

    return summaries;
  }

  /**
   * Convenience guard used by other services: resolves readiness WITHOUT throwing
   * on the school year's absence — returns a ready=false result instead.
   */
  async assertReady(orgId: string, schoolYearId: string): Promise<void> {
    let result: ReadinessResult;
    try {
      result = await this.detail(orgId, schoolYearId);
    } catch (err) {
      if (err instanceof NotFoundException) {
        throw new BadRequestException('School year not found.');
      }
      throw err;
    }

    if (!result.ready) {
      const messages = result.issues
        .filter((i) => i.severity === 'blocking')
        .slice(0, MAX_ISSUES_PER_CODE)
        .map((i) => i.message);
      throw new BadRequestException({
        statusCode: 400,
        error: 'SCHOOL_YEAR_NOT_READY',
        message: `School year is not ready to be used: ${messages.join(' ')}`,
        issues: result.issues,
      });
    }
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  private buildResult(issues: ReadinessIssue[]): ReadinessResult {
    const blockingCount = issues.filter(
      (i) => i.severity === 'blocking',
    ).length;
    return {
      ready: blockingCount === 0,
      blockingCount,
      warningCount: issues.length - blockingCount,
      issues,
    };
  }

  private push(
    issues: ReadinessIssue[],
    candidate: ReadinessIssue & { when: boolean },
  ): void {
    if (!candidate.when) return;
    const { when, ...issue } = candidate;
    const count = issues.filter((i) => i.code === issue.code).length;
    if (count >= MAX_ISSUES_PER_CODE) return;
    issues.push(issue);
  }

  /**
   * Pushes a single aggregated blocking issue from a list of affected entities,
   * carrying the total `count` and a capped `entities` detail list.
   */
  private pushList(
    issues: ReadinessIssue[],
    args: {
      code: string;
      message: (count: number) => string;
      items: { id: string; name: string }[];
    },
    cap = 10,
  ): void {
    if (args.items.length === 0) return;
    issues.push({
      code: args.code,
      severity: 'blocking',
      message: args.message(args.items.length),
      count: args.items.length,
      entities: args.items.slice(0, cap),
    });
  }

  private toMap(
    rows: Array<Record<string, any>>,
    key: string,
  ): Map<string, number> {
    const map = new Map<string, number>();
    for (const row of rows) {
      const count = row._count?._all ?? row._count;
      map.set(row[key], Number(count));
    }
    return map;
  }

  /** Fast approximate blocking count for the summary view. */
  private summaryBlockingCount(
    sy: { id: string; start_date: Date | null },
    programByYear: Map<string, number>,
    levelByYear: Map<string, number>,
    sectionByYear: Map<string, number>,
  ): number {
    let count = 0;
    if (!sy.start_date) count += 1;
    if ((programByYear.get(sy.id) ?? 0) === 0) count += 1;
    if ((levelByYear.get(sy.id) ?? 0) === 0) count += 1;
    if ((sectionByYear.get(sy.id) ?? 0) === 0) count += 1;
    return count;
  }
}

import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';

@Injectable()
export class SchoolYearRepository {
  constructor(private readonly db: DatabaseService) {}

  async create(data: {
    orgId: string;
    name: string;
    start_date?: string;
    end_date?: string;
  }) {
    return this.db.schoolYear.create({
      data: {
        org_id: data.orgId,
        name: data.name,
        status: 'pending',
        start_date: data.start_date ? new Date(data.start_date) : null,
        end_date: data.end_date ? new Date(data.end_date) : null,
      },
    });
  }

  async findAll(orgId: string) {
    return this.db.schoolYear.findMany({
      where: { org_id: orgId },
      orderBy: { name: 'desc' },
    });
  }

  async findById(id: string, orgId: string) {
    return this.db.schoolYear.findFirst({
      where: { id, org_id: orgId },
    });
  }

  async findActive(orgId: string) {
    return this.db.schoolYear.findFirst({
      where: { org_id: orgId, status: 'active' },
    });
  }

  async countActive(orgId: string): Promise<number> {
    return this.db.schoolYear.count({
      where: { org_id: orgId, status: 'active' },
    });
  }

  async updateStatus(id: string, status: 'pending' | 'active' | 'ended') {
    return this.db.schoolYear.update({
      where: { id },
      data: { status },
    });
  }

  async update(
    id: string,
    data: {
      name?: string;
      start_date?: string | null;
      end_date?: string | null;
    },
  ) {
    return this.db.schoolYear.update({
      where: { id },
      data: {
        ...(data.name !== undefined && { name: data.name }),
        ...(data.start_date !== undefined && {
          start_date: data.start_date ? new Date(data.start_date) : null,
        }),
        ...(data.end_date !== undefined && {
          end_date: data.end_date ? new Date(data.end_date) : null,
        }),
      },
    });
  }

  /**
   * Counts, per school year, how many scoped child rows exist across the
   * models that reference SchoolYear via school_year_id. Used to determine
   * whether a school year is "in use" (i.e. not just created and unused).
   * Enrollment is intentionally omitted because it implies an existing Class,
   * which is already counted.
   */
  private usageModels() {
    return [
      'program',
      'course',
      'strand',
      'level',
      'section',
      'studentSchoolYear',
      'semester',
      'class',
      'academicCalendar',
      'programCalendar',
      'gradingScaleAssignment',
      'enrollmentPeriod',
      'enrollmentApplication',
    ] as const;
  }

  async usageCountsBySchoolYear(
    orgId: string,
  ): Promise<Record<string, number>> {
    const counts: Record<string, number> = {};

    const results = await Promise.all(
      this.usageModels().map(async (model) => {
        const groups = await (this.db[model] as any).groupBy({
          by: ['school_year_id'],
          where: { org_id: orgId },
          _count: { _all: true },
        });
        return groups.map(
          (g: { school_year_id: string; _count: { _all: number } }) => ({
            schoolYearId: g.school_year_id,
            count: g._count._all,
          }),
        );
      }),
    );

    for (const rows of results) {
      for (const row of rows) {
        counts[row.schoolYearId] = (counts[row.schoolYearId] ?? 0) + row.count;
      }
    }

    return counts;
  }

  async hasUsage(id: string): Promise<boolean> {
    const counts = await Promise.all(
      this.usageModels().map((model) =>
        (this.db[model] as any).count({
          where: { school_year_id: id },
        }),
      ),
    );
    return counts.some((count) => count > 0);
  }

  async delete(id: string) {
    return this.db.schoolYear.delete({ where: { id } });
  }

  /** Find all school years whose end_date has passed and are still active */
  async findExpiredActive(): Promise<{ id: string; org_id: string }[]> {
    return this.db.schoolYear.findMany({
      where: {
        status: 'active',
        end_date: { lt: new Date() },
      },
      select: { id: true, org_id: true },
    });
  }

  async unenrollAllStudents(schoolYearId: string, orgId: string) {
    const [classResult, studentResult] = await this.db.$transaction([
      this.db.enrollment.updateMany({
        where: {
          org_id: orgId,
          status: 'active',
          class: { school_year_id: schoolYearId, deleted_at: null },
        },
        data: { status: 'removed' },
      }),
      this.db.studentSchoolYear.updateMany({
        where: {
          org_id: orgId,
          school_year_id: schoolYearId,
          status: 'active',
        },
        data: {
          status: 'unenrolled',
          unenrolled_at: new Date(),
        },
      }),
    ]);

    return {
      classEnrollments: classResult.count,
      students: studentResult.count,
    };
  }
}

