import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { DatabaseService } from '@/core/database/database.provider';

@Injectable()
export class StudentRepository {
  constructor(private readonly db: DatabaseService) {}

  async create(
    data: {
      orgId: string;
      email: string;
      hashedPassword: string;
      status: string;
      fullName: string;
      studentId: string;
      levelId?: string;
      sectionId?: string;
      personalEmail?: string | null;
    },
    tx?: Prisma.TransactionClient,
  ) {
    const client = tx ?? this.db;
    return client.account.create({
      data: {
        org_id: data.orgId,
        email: data.email,
        password: data.hashedPassword,
        role: 'student',
        status: data.status as any,
        profile: {
          create: {
            full_name: data.fullName,
            personal_email: data.personalEmail ?? null,
            metadata: {
              studentId: data.studentId,
              levelId: data.levelId,
              sectionId: data.sectionId ?? null,
            },
          },
        },
      },
      include: { profile: true },
    });
  }

  async findAll(
    orgId: string,
    filters: {
      search?: string;
      status?: string;
      schoolYearId?: string;
      programId?: string;
      courseId?: string;
      strandId?: string;
      levelId?: string;
      sectionId?: string;
      page?: number;
      limit?: number;
    },
  ) {
    const {
      search,
      status,
      schoolYearId,
      programId,
      courseId,
      strandId,
      levelId,
      sectionId,
      page = 1,
      limit = 20,
    } = filters;

    const hasHierarchyFilter =
      schoolYearId || programId || courseId || strandId || levelId || sectionId;

    // Account has no Prisma relation to StudentSchoolYear (student_id is a plain String,
    // no @relation declared on Account). We resolve matching student_ids first via a
    // two-step query, then filter Account with id IN [...].
    let matchingStudentIds: string[] | null = null;

    if (hasHierarchyFilter) {
      const matchingSSY = await this.db.studentSchoolYear.findMany({
        where: {
          org_id: orgId,
          ...(schoolYearId ? { school_year_id: schoolYearId } : {}),
          programEnrollments: {
            some: {
              org_id: orgId,
              ...(programId ? { program_id: programId } : {}),
              ...(courseId ? { course_id: courseId } : {}),
              ...(strandId ? { strand_id: strandId } : {}),
              ...(levelId ? { level_id: levelId } : {}),
              ...(sectionId ? { section_id: sectionId } : {}),
            },
          },
        },
        select: { student_id: true },
      });

      matchingStudentIds = matchingSSY.map((r) => r.student_id);

      // Fallback: if only sectionId is provided and enrollment table returned nothing,
      // check profile.metadata directly — students enrolled via simple profile update
      // are stored there instead of in StudentProgramEnrollment.
      if (
        matchingStudentIds.length === 0 &&
        sectionId &&
        !schoolYearId &&
        !programId &&
        !courseId &&
        !strandId &&
        !levelId
      ) {
        const metaMatches = await this.db.profile.findMany({
          where: {
            metadata: { path: ['sectionId'], equals: sectionId },
            account: { org_id: orgId, role: 'student', deleted_at: null },
          },
          select: { account_id: true },
        });

        matchingStudentIds = metaMatches.map((r) => r.account_id);
      }

      if (matchingStudentIds.length === 0) return { data: [], total: 0 };
    }

    const where: Prisma.AccountWhereInput = {
      org_id: orgId,
      role: 'student',
      deleted_at: null,
      ...(matchingStudentIds !== null
        ? { id: { in: matchingStudentIds } }
        : {}),
      ...(status ? { status: status as any } : {}),
      ...(search
        ? {
            OR: [
              {
                profile: {
                  full_name: { contains: search, mode: 'insensitive' },
                },
              },
              {
                profile: {
                  metadata: { path: ['studentId'], string_contains: search },
                },
              },
            ],
          }
        : {}),
    };

    const [data, total] = await Promise.all([
      this.db.account.findMany({
        where,
        include: { profile: true },
        orderBy: { created_at: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.db.account.count({ where }),
    ]);

    return { data, total };
  }

  async findById(id: string, orgId: string) {
    return this.db.account.findFirst({
      where: { id, org_id: orgId, role: 'student', deleted_at: null },
      include: { profile: true },
    });
  }

  async findByEmail(email: string, orgId: string) {
    return this.db.account.findFirst({
      where: { email, org_id: orgId, deleted_at: null },
    });
  }

  async findByStudentId(studentId: string, orgId: string) {
    return this.db.profile.findFirst({
      where: {
        metadata: { path: ['studentId'], equals: studentId },
        account: { org_id: orgId, deleted_at: null },
      },
      include: { account: true },
    });
  }

  async updateProfile(
    accountId: string,
    data: {
      fullName?: string;
      email?: string;
      personal_email?: string | null;
      levelId?: string;
      sectionId?: string;
      profileImage?: string;
    },
  ) {
    return this.db.$transaction(async (tx) => {
      if (data.email) {
        await tx.account.update({
          where: { id: accountId },
          data: { email: data.email },
        });
      }

      const current = await tx.profile.findUnique({
        where: { account_id: accountId },
        select: { metadata: true, full_name: true, personal_email: true },
      });

      const currentMeta =
        current?.metadata &&
        typeof current.metadata === 'object' &&
        !Array.isArray(current.metadata)
          ? (current.metadata as Record<string, any>)
          : {};

      await tx.profile.update({
        where: { account_id: accountId },
        data: {
          ...(data.fullName ? { full_name: data.fullName } : {}),
          ...(data.personal_email !== undefined
            ? { personal_email: data.personal_email ?? null }
            : {}),
          ...(data.profileImage !== undefined
            ? { profile_image: data.profileImage }
            : {}),
          metadata: {
            ...currentMeta,
            ...(data.levelId !== undefined ? { levelId: data.levelId } : {}),
            ...(data.sectionId !== undefined
              ? { sectionId: data.sectionId }
              : {}),
          },
        },
      });

      return tx.account.findUnique({
        where: { id: accountId },
        include: { profile: true },
      });
    });
  }

  async updateStatus(accountId: string, status: string) {
    return this.db.account.update({
      where: { id: accountId },
      data: { status: status as any },
      include: { profile: true },
    });
  }

  async updatePassword(accountId: string, hashedPassword: string) {
    return this.db.account.update({
      where: { id: accountId },
      data: { password: hashedPassword },
    });
  }

  async findAllForExport(orgId: string) {
    return this.db.account.findMany({
      where: { org_id: orgId, role: 'student', deleted_at: null },
      include: { profile: true },
      orderBy: { created_at: 'asc' },
    });
  }

  async findEnrollments(studentId: string, orgId: string) {
    return this.db.enrollment.findMany({
      where: {
        student_id: studentId,
        org_id: orgId,
        status: { not: 'removed' },
        class: { deleted_at: null },
      },
      include: { class: { include: { schedules: true } } },
      orderBy: { created_at: 'asc' },
    });
  }

  async findEnrollmentById(id: string, orgId: string) {
    return this.db.enrollment.findFirst({ where: { id, org_id: orgId } });
  }

  async removeEnrollment(enrollmentId: string) {
    return this.db.enrollment.update({
      where: { id: enrollmentId },
      data: { status: 'removed' as any },
    });
  }

  async findEmailsInBatch(emails: string[], orgId: string): Promise<string[]> {
    if (emails.length === 0) return [];
    const accounts = await this.db.account.findMany({
      where: { email: { in: emails }, org_id: orgId, deleted_at: null },
      select: { email: true },
    });
    return accounts.map((a) => a.email);
  }

  async findStudentIdsInBatch(
    studentIds: string[],
    orgId: string,
  ): Promise<string[]> {
    if (studentIds.length === 0) return [];
    const profiles = await this.db.profile.findMany({
      where: { account: { org_id: orgId, deleted_at: null } },
      select: { metadata: true },
    });
    const existingSet = new Set(
      profiles
        .map((p) => {
          const meta = p.metadata as Record<string, unknown> | null;
          return typeof meta?.['studentId'] === 'string'
            ? meta['studentId']
            : null;
        })
        .filter((id): id is string => id !== null),
    );
    return studentIds.filter((id) => existingSet.has(id));
  }
}

// @/modules/student/student.service.ts
import {
  Injectable,
  ConflictException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { StudentRepository } from './student.repository';
import { SectionService } from '@/modules/section/section.service';
import {
  CreateStudentDto,
  UpdateStudentDto,
  UpdateStudentStatusDto,
  QueryStudentDto,
  StudentStatus,
  BulkCreateStudentDto,
} from './dto/student.dto';
import {
  generateSystemPassword,
  parseCsv,
  buildCredentialsCsv,
} from './student.utils';
import { hashPassword } from '@/commons/utils/hash.util';
import { Prisma } from '@prisma/client';
import { DatabaseService } from '@/core/database/database.provider';
import { ClassRepository } from '../class/class.repository';
import { EnrollmentRepository } from '../enrollment/enrollment.repository';
import {
  resolveSubjectAcademicStructure,
  isEligibleForClassStructure,
} from '../enrollment/enrollment-eligibility.util';
import { AuditLogService } from '../audit-log/audit-log.service';
import { OrganizationService } from '../organization/organization.service';

const IRREVERSIBLE_STATUSES: StudentStatus[] = [
  StudentStatus.DROPPED,
  StudentStatus.TRANSFERRED,
  StudentStatus.GRADUATED,
];

@Injectable()
export class StudentService {
  constructor(
    private readonly studentRepository: StudentRepository,
    private readonly sectionService: SectionService,
    private readonly classRepository: ClassRepository,
    private readonly enrollmentRepo: EnrollmentRepository,
    private readonly auditLogService: AuditLogService, // ← INJECTED
    private readonly organizationService: OrganizationService,
    private readonly db: DatabaseService,
  ) {}

  private extractMeta(account: Record<string, any>): Record<string, any> {
    const raw = account?.profile?.metadata;
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
    return raw as Record<string, any>;
  }

  formatAccount(account: Record<string, any>) {
    const meta = this.extractMeta(account);
    return {
      id: account.id as string,
      orgId: account.org_id as string,
      email: account.email as string,
      status: account.status as string,
      fullName: (account.profile?.full_name ?? null) as string | null,
      studentId: (meta['studentId'] ?? null) as string | null,
      levelId: (meta['levelId'] ?? null) as string | null,
      sectionId: (meta['sectionId'] ?? null) as string | null,
      createdAt: account.created_at as Date,
      personalEmail: (account.profile?.personal_email ?? null) as string | null,
      profileImage: (account.profile?.profile_image ?? null) as string | null,
    };
  }

  private async buildOrgEmail(orgId: string, emailName: string) {
    const org = await this.organizationService.getOwn(orgId);
    const extension = org?.emailExtension?.trim();
    if (!extension) {
      throw new BadRequestException(
        'Set the organization email extension before creating student accounts.',
      );
    }

    const localPart = emailName.trim().replace(/^@+/, '');
    if (!localPart || localPart.includes('@')) {
      throw new BadRequestException(
        'Email name must not include an email extension.',
      );
    }

    const base = extension
      .replace(/^@/, '')
      .replace(/\.(student|educator)\./g, '.')
      .trim();
    const dotIdx = base.indexOf('.');
    const domain =
      dotIdx >= 0
        ? `${base.slice(0, dotIdx)}.student${base.slice(dotIdx)}`
        : `student.${base}`;

    return `${localPart}@${domain}`.toLowerCase();
  }

  // ── POST /students/bulk ──────────────────────────────────────────────────────

  async bulkCreate(
    orgId: string,
    entries: Array<{ fullName: string; id: string }>,
  ) {
    const sanitized = entries
      .map((e) => ({
        fullName: this.sanitizeName(e.fullName),
        id: e.id.trim(),
      }))
      .filter((e) => e.fullName.length >= 2 && e.id.length >= 1);

    if (sanitized.length === 0) {
      throw new BadRequestException('No valid entries provided.');
    }

    const usedEmailNames = new Set<string>();
    const withEmailName = sanitized.map((e) => {
      const emailName = this.generateEmailName(e.fullName, usedEmailNames);
      usedEmailNames.add(emailName);
      return { ...e, emailName };
    });

    const withEmails = await Promise.all(
      withEmailName.map(async (e) => ({
        ...e,
        email: await this.buildOrgEmail(orgId, e.emailName),
      })),
    );

    const allEmails = withEmails.map((e) => e.email);
    const existing = await this.studentRepository.findEmailsInBatch(
      allEmails,
      orgId,
    );
    if (existing.length > 0) {
      throw new ConflictException(
        `Emails already exist: ${existing.join(', ')}. Remove duplicates and retry.`,
      );
    }

    const created: Array<{
      fullName: string;
      email: string;
      studentId: string;
      plainPassword: string;
    }> = [];

    for (const { fullName, email, id } of withEmails) {
      const plainPassword = generateSystemPassword();
      const hashedPassword = await hashPassword(plainPassword);

      await this.studentRepository.create({
        orgId,
        email,
        hashedPassword,
        status: StudentStatus.PENDING,
        fullName,
        studentId: id,
      });

      created.push({ fullName, email, studentId: id, plainPassword });
    }

    return created;
  }

  private sanitizeName(name: string): string {
    return name
      .replace(/[^a-zA-Z\s]/g, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  private generateEmailName(fullName: string, used: Set<string>): string {
    let candidate = fullName.toLowerCase().replace(/\s+/g, '');
    if (!candidate) candidate = 'student';
    let emailName = candidate;
    let counter = 1;
    while (used.has(emailName)) {
      emailName = `${candidate}${counter}`;
      counter++;
    }
    return emailName;
  }

  async create(
    orgId: string,
    dto: CreateStudentDto,
    tx?: Prisma.TransactionClient,
  ) {
    const email = await this.buildOrgEmail(orgId, dto.emailName);

    const emailTaken = await this.studentRepository.findByEmail(email, orgId);
    if (emailTaken) {
      throw new ConflictException(
        'An account with this email already exists in the organization.',
      );
    }

    const idTaken = await this.studentRepository.findByStudentId(
      dto.studentId,
      orgId,
    );
    if (idTaken) {
      throw new ConflictException(
        'A student with this Student ID already exists in the organization.',
      );
    }

    const plainPassword = generateSystemPassword();
    const hashedPassword = await hashPassword(plainPassword);

    const account = await this.studentRepository.create(
      {
        orgId,
        email,
        hashedPassword,
        status: dto.status ?? StudentStatus.PENDING,
        fullName: dto.fullName,
        studentId: dto.studentId,
        levelId: dto.levelId,
        sectionId: dto.sectionId,
        personalEmail: dto.personalEmail ?? null,
      },
      tx,
    );

    return { ...this.formatAccount(account), plainPassword };
  }

  async findAll(orgId: string, query: QueryStudentDto) {
    const page = query.page ?? 1;
    const limit = query.limit ?? 20;

    const { data, total } = await this.studentRepository.findAll(orgId, {
      search: query.search,
      status: query.status,
      schoolYearId: query.schoolYearId,
      programId: query.programId,
      courseId: query.courseId,
      strandId: query.strandId,
      levelId: query.levelId,
      sectionId: query.sectionId,
      page,
      limit,
    });

    return {
      data: data.map((a) => this.formatAccount(a as Record<string, any>)),
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async findById(id: string, orgId: string) {
    const account = await this.studentRepository.findById(id, orgId);
    if (!account) throw new NotFoundException('Student not found.');
    return this.formatAccount(account as Record<string, any>);
  }

  // actorId added — the admin performing the action, threaded from controller
  async update(
    id: string,
    orgId: string,
    dto: UpdateStudentDto,
    actorId: string,
  ) {
    const account = await this.studentRepository.findById(id, orgId);
    if (!account) throw new NotFoundException('Student not found.');

    if (dto.email && dto.email !== account.email) {
      const emailTaken = await this.studentRepository.findByEmail(
        dto.email,
        orgId,
      );
      if (emailTaken) {
        throw new ConflictException(
          'An account with this email already exists in the organization.',
        );
      }
    }

    if (dto.sectionId) {
      const section = await this.sectionService.findById(dto.sectionId, orgId);
      const currentCount = await this.sectionService.countStudentsInSection(
        dto.sectionId,
      );
      if (currentCount >= section.capacity) {
        throw new BadRequestException(
          `Section has reached its capacity of ${section.capacity} students.`,
        );
      }
    }

    const updated = await this.studentRepository.updateProfile(id, {
      fullName: dto.fullName,
      email: dto.email,
      levelId: dto.levelId,
      sectionId: dto.sectionId,
      profileImage: dto.profileImage,
    });

    // ── Audit log ──────────────────────────────────────────────────────────
    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'student_profile_changed',
        entityType: 'student',
        entityId: id,
        metadata: {
          changes: Object.fromEntries(
            Object.entries(dto).filter(([, v]) => v !== undefined),
          ),
        },
      })
      .catch(() => {
        /* fire-and-forget — never block the response */
      });

    return this.formatAccount(updated as Record<string, any>);
  }

  // actorId added
  async updateStatus(
    id: string,
    orgId: string,
    dto: UpdateStudentStatusDto,
    actorId: string,
  ) {
    const account = await this.studentRepository.findById(id, orgId);
    if (!account) throw new NotFoundException('Student not found.');

    const currentStatus = account.status as StudentStatus;
    const newStatus = dto.status;

    if (
      IRREVERSIBLE_STATUSES.includes(currentStatus) &&
      newStatus === StudentStatus.ACTIVE
    ) {
      if (!dto.reason) {
        throw new BadRequestException(
          `Reversing a "${currentStatus}" status back to active requires a reason. ` +
            `This action will be logged in the audit trail.`,
        );
      }
    }

    const updated = await this.studentRepository.updateStatus(id, newStatus);

    // ── Audit log ──────────────────────────────────────────────────────────
    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'student_status_changed',
        entityType: 'student',
        entityId: id,
        metadata: {
          from: currentStatus,
          to: newStatus,
          reason: dto.reason ?? null,
        },
      })
      .catch(() => {});

    return this.formatAccount(updated as Record<string, any>);
  }

  async bulkImport(orgId: string, csvContent: string) {
    const rows = parseCsv(csvContent);
    if (rows.length === 0) {
      throw new BadRequestException('CSV file is empty or malformed.');
    }

    const emails = rows.map((r) => r['Email']).filter(Boolean);
    const studentIds = rows.map((r) => r['Student ID']).filter(Boolean);

    const [existingEmails, existingStudentIds] = await Promise.all([
      this.studentRepository.findEmailsInBatch(emails, orgId),
      this.studentRepository.findStudentIdsInBatch(studentIds, orgId),
    ]);

    const takenEmailSet = new Set(existingEmails);
    const takenIdSet = new Set(existingStudentIds);

    const validationReport: Array<{
      row: number;
      data: Record<string, string>;
      errors: string[];
    }> = [];
    const validRows: Array<{ row: number; data: Record<string, string> }> = [];

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const errors: string[] = [];
      const rowNum = i + 2;

      if (!row['Full Name']) errors.push('Full Name is required.');
      if (!row['Student ID']) errors.push('Student ID is required.');
      if (!row['Email']) errors.push('Email is required.');
      if (row['Email'] && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row['Email'])) {
        errors.push('Email format is invalid.');
      }
      if (row['Email'] && takenEmailSet.has(row['Email'])) {
        errors.push(`Email "${row['Email']}" already exists.`);
      }
      if (row['Student ID'] && takenIdSet.has(row['Student ID'])) {
        errors.push(`Student ID "${row['Student ID']}" already exists.`);
      }

      if (errors.length > 0) {
        validationReport.push({ row: rowNum, data: row, errors });
      } else {
        validRows.push({ row: rowNum, data: row });
      }
    }

    if (validationReport.length > 0) {
      return {
        status: 'validation_failed',
        totalRows: rows.length,
        validCount: validRows.length,
        invalidCount: validationReport.length,
        errors: validationReport,
        message:
          'Fix the errors and re-upload, or proceed with valid rows only.',
      };
    }

    const created: Array<
      ReturnType<typeof this.formatAccount> & { plainPassword: string }
    > = [];

    for (const { data } of validRows) {
      const plainPassword = generateSystemPassword();
      const hashedPassword = await hashPassword(plainPassword);

      const account = await this.studentRepository.create({
        orgId,
        email: data['Email'],
        hashedPassword,
        status: StudentStatus.PENDING,
        fullName: data['Full Name'],
        studentId: data['Student ID'],
        levelId: data['Level ID'] || undefined,
        sectionId: data['Section ID'] || undefined,
      });

      created.push({ ...this.formatAccount(account), plainPassword });
    }

    return {
      status: 'success',
      totalCreated: created.length,
      students: created,
    };
  }

  // actorId added
  async resetPassword(id: string, orgId: string, actorId: string) {
    const account = await this.studentRepository.findById(id, orgId);
    if (!account) throw new NotFoundException('Student not found.');

    const plainPassword = generateSystemPassword();
    const hashedPassword = await hashPassword(plainPassword);

    await this.studentRepository.updatePassword(id, hashedPassword);

    // ── Audit log ──────────────────────────────────────────────────────────
    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'password_reset',
        entityType: 'student',
        entityId: id,
        metadata: undefined,
      })
      .catch(() => {});

    return { id, plainPassword };
  }

  async getCredentialsCsv(orgId: string): Promise<string> {
    const accounts = await this.studentRepository.findAllForExport(orgId);
    const rows = accounts.map((a) => {
      const meta = this.extractMeta(a as Record<string, any>);
      return {
        fullName: a.profile?.full_name ?? '',
        studentId: (meta['studentId'] ?? '') as string,
        email: a.email,
        plainPassword: '••••••••••',
        levelId: (meta['levelId'] ?? '') as string,
        sectionId: (meta['sectionId'] ?? '') as string,
        status: a.status,
      };
    });
    return buildCredentialsCsv(rows);
  }

  getImportTemplate(): string {
    const headers = [
      'Full Name',
      'Student ID',
      'Email',
      'Level ID',
      'Section ID',
    ];
    const example = [
      'Juan Dela Cruz',
      'STU-2024-001',
      'juan@school.edu',
      'level-uuid-here (optional)',
      'section-uuid-here (optional)',
    ];
    return [headers.join(','), example.join(',')].join('\n');
  }

  async getEnrollments(studentId: string, orgId: string) {
    const account = await this.studentRepository.findById(studentId, orgId);
    if (!account) throw new NotFoundException('Student not found.');
    return this.enrollmentRepo.findByStudentAcrossOrg(studentId, orgId);
  }

  async addEnrollment(
    studentId: string,
    orgId: string,
    classId: string,
    actorId: string,
  ) {
    const account = await this.studentRepository.findById(studentId, orgId);
    if (!account) throw new NotFoundException('Student not found.');

    if (account.status !== 'active') {
      throw new BadRequestException(
        'Only active students can be enrolled in a class.',
      );
    }

    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    // ── Academic structure gate ──────────────────────────────────────────
    // Strict: student must belong to the class's program, course/strand, and level.
    const [subjectStructure, studentStructure] = await Promise.all([
      resolveSubjectAcademicStructure(this.db, cls.subject_id, orgId),
      this.enrollmentRepo.findStudentAcademicStructure(
        studentId,
        orgId,
        cls.school_year_id,
      ),
    ]);

    if (
      !isEligibleForClassStructure(
        subjectStructure,
        studentStructure,
        cls.section_id,
      )
    ) {
      const reason = !studentStructure
        ? 'The student has no active academic placement for this school year.'
        : 'The student does not belong to the same program, course/strand, or level assigned to this class.';
      throw new BadRequestException(
        `Student is not eligible for this class. ${reason}`,
      );
    }

    const duplicate = await this.enrollmentRepo.findDuplicate(
      studentId,
      cls.subject_id,
      cls.semester_id,
      orgId,
    );
    if (duplicate) {
      throw new ConflictException(
        'Student is already enrolled in a class for this subject in the same semester.',
      );
    }

    const existing = await this.enrollmentRepo.findByStudent(
      classId,
      studentId,
      orgId,
    );
    if (existing && existing.status !== 'removed') {
      throw new ConflictException('Student is already enrolled in this class.');
    }

    if (cls.capacity > 0) {
      const activeCount = await this.enrollmentRepo.countActive(classId);
      if (activeCount >= cls.capacity) {
        // ── Audit: capacity overflow ──────────────────────────────────────
        this.auditLogService
          .logAdminAction({
            orgId,
            actorId,
            action: 'class_capacity_overflow',
            entityType: 'class',
            entityId: classId,
            metadata: { studentId, capacity: cls.capacity },
          })
          .catch(() => {});

        return {
          overflow: true,
          message: `Class is at full capacity (${cls.capacity} students).`,
          classId,
          studentId,
        };
      }
    }

    const enrollment = await this.enrollmentRepo.create({
      orgId,
      classId,
      studentId,
      status: 'active',
    });

    // ── Audit: enrollment created ─────────────────────────────────────────
    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'enrollment_created',
        entityType: 'enrollment',
        entityId: (enrollment as any).id,
        metadata: { studentId, classId },
      })
      .catch(() => {});

    return enrollment;
  }

  async deleteEnrollment(
    studentId: string,
    enrollmentId: string,
    orgId: string,
    actorId: string,
  ) {
    const account = await this.studentRepository.findById(studentId, orgId);
    if (!account) throw new NotFoundException('Student not found.');

    const enrollment = await this.enrollmentRepo.findById(enrollmentId, orgId);
    if (!enrollment || enrollment.student_id !== studentId) {
      throw new NotFoundException('Enrollment not found.');
    }
    if (enrollment.status === 'removed') {
      throw new ConflictException('Enrollment is already removed.');
    }

    const result = await this.enrollmentRepo.updateStatus(
      enrollmentId,
      'removed',
    );

    // ── Audit: enrollment removed ─────────────────────────────────────────
    this.auditLogService
      .logAdminAction({
        orgId,
        actorId,
        action: 'enrollment_removed',
        entityType: 'enrollment',
        entityId: enrollmentId,
        metadata: { studentId, classId: enrollment.class_id },
      })
      .catch(() => {});

    return result;
  }

  async getEducatorClasses(educatorId: string, orgId: string) {
    const { data: classes } = await this.classRepository.findAll(orgId, {
      educatorId,
    });
    return Promise.all(
      classes.map(async (cls) => {
        const { subject } = await this.classRepository.findSubjectWithEducator(
          cls.id,
        );
        return {
          id: cls.id,
          subjectId: cls.subject_id,
          subjectName: subject?.name ?? null,
          sectionId: cls.section_id,
          schoolYearId: cls.school_year_id,
          semesterId: cls.semester_id,
          capacity: cls.capacity,
          schedules: cls.schedules,
        };
      }),
    );
  }

  async removeEnrollment(classId: string, enrollmentId: string, orgId: string) {
    const cls = await this.classRepository.findById(classId, orgId);
    if (!cls) throw new NotFoundException('Class not found.');

    const enrollment = await this.enrollmentRepo.findById(enrollmentId, orgId);
    if (!enrollment || enrollment.class_id !== classId) {
      throw new NotFoundException('Enrollment not found.');
    }
    if (enrollment.status === 'removed') {
      throw new BadRequestException('Enrollment is already removed.');
    }

    return this.enrollmentRepo.updateStatus(enrollmentId, 'removed');
  }
}

import { SubjectPrerequisiteService } from '../subject-prerequisite.service';
import { SubjectPrerequisiteRepository } from '../subject-prerequisite.repository';

describe('Subject prerequisite - proof tests (Lane 1 item 5)', () => {
  describe('(a) bulkCreate is not atomic - a failed import wipes existing prerequisite links', () => {
    it('PROOF: when the bulk insert FALTERS, the earlier delete must NOT have torn out the old links', async () => {
      // In-memory stand-in for the DB: the two pre-existing prerequisite links
      // for subject s1 that must survive a failed re-import.
      const rows: {
        subject_id: string;
        prerequisite_id: string;
        org_id: string;
      }[] = [
        { subject_id: 's1', prerequisite_id: 'p-old-1', org_id: 'org-1' },
        { subject_id: 's1', prerequisite_id: 'p-old-2', org_id: 'org-1' },
      ];

      // Faithful to the repository contract (subject-prerequisite.repository.ts):
      //  - deleteAllForSubject -> deleteMany (commits, no transaction)
      //  - bulkCreate          -> createMany (can throw mid-batch, e.g. FK error)
      const fault = new Error('createMany failed: foreign key constraint');
      const repo = {
        deleteAllForSubject: jest.fn(async (subject_id: string) => {
          const survivors = rows.filter((r) => r.subject_id !== subject_id);
          rows.length = 0;
          rows.push(...survivors);
        }),
        bulkCreate: jest.fn(async () => {
          throw fault;
        }),
        getPrerequisitesWithGrades: jest.fn(async () => []),
        findOne: jest.fn().mockResolvedValue(null),
        create: jest.fn(),
        findBySubject: jest.fn().mockResolvedValue([]),
        delete: jest.fn(),
      };

      const service = new SubjectPrerequisiteService(repo as any);

      // Simulate a re-import that starts (delete) then dies mid-insert.
      await expect(
        service.bulkCreate('org-1', {
          subject_id: 's1',
          prerequisite_ids: ['p-new-1', 'p-new-2'],
        }),
      ).rejects.toThrow('createMany failed: foreign key constraint');

      // Correct behavior: the whole replace must be a single transaction, so on
      // failure the two pre-existing links survive intact. Current code
      // (service L38-39) runs deleteAllForSubject THEN bulkCreate with no tx,
      // so the delete is already committed when the insert throws -> zero links
      // remain. A correct implementation leaves length 2 here.
      expect(rows.filter((r) => r.subject_id === 's1').length).toBe(2);
    });

    it('PROOF: an interrupted import silently makes checkEligibility approve every candidate', async () => {
      // Downstream half of the same bug: after the torn import above the
      // subject has zero prerequisite rows persisted, so checkEligibility (L71)
      // sees rows.length === 0 and returns fully eligible.
      const repo = {
        getPrerequisitesWithGrades: jest.fn().mockResolvedValue([]),
        deleteAllForSubject: jest.fn().mockResolvedValue({ count: 2 }),
        bulkCreate: jest.fn().mockResolvedValue({ count: 2 }),
        findOne: jest.fn().mockResolvedValue(null),
        create: jest.fn(),
        // The subject's prerequisite definitions still exist — only the
        // grade-enriched join is empty after the interrupted import.
        findBySubject: jest.fn().mockResolvedValue([
          {
            id: 'l1',
            subject_id: 's1',
            prerequisite_id: 'p-math',
            prerequisite: { id: 'p-math', name: 'Math' },
          },
          {
            id: 'l2',
            subject_id: 's1',
            prerequisite_id: 'p-sci',
            prerequisite: { id: 'p-sci', name: 'Science' },
          },
        ]),
        delete: jest.fn(),
      };

      const service = new SubjectPrerequisiteService(repo as any);

      // Correct behavior: a student who has never completed the prerequisite
      // must still be DENIED if the subject has prerequisites defined. After an
      // interrupted import the subject's requirements silently vanish and every
      // candidate becomes eligible - that silent downgrade is the bug.
      const result = await service.checkEligibility('s1', 'stu-1', 'org-1');
      expect(result).toEqual({ eligible: false, missing: expect.any(Array) });
    });
  });

  describe('(b) getPrerequisitesWithGrades picks with grades.find and no orderBy', () => {
    it('PROOF: two locked grades for the same prereq must resolve to the LATEST one', async () => {
      // Real repository query (L80-94) fetches grades WITHOUT orderBy, then
      // grades.find((g) => g.class.subject_id === p.prerequisite_id) (L100)
      // blindly takes the FIRST row the DB happens to return. Across two school
      // years a student legitimately owns two locked grades for one subject; the
      // correct resolution is deterministic "latest grade wins".
      //
      // Here the DB (mock) happens to return the OLD grade first. A repo that
      // ordered by the effective period would pick the 90 (latest) and pass.
      const fakeDb = {
        subjectPrerequisite: {
          findMany: jest.fn().mockResolvedValue([
            {
              prerequisite_id: 'p-math',
              prerequisite: { id: 'p-math', name: 'Math' },
            },
          ]),
        },
        grade: {
          findMany: jest.fn().mockResolvedValue([
            // old school year, failed: arrives first from this unordered query
            {
              id: 'g-old',
              class: { subject_id: 'p-math' },
              final_score: 40,
              is_locked: true,
            },
            // latest school year, passed
            {
              id: 'g-new',
              class: { subject_id: 'p-math' },
              final_score: 90,
              is_locked: true,
            },
          ]),
        },
      };

      const repo = new SubjectPrerequisiteRepository(fakeDb as any);
      const service = new SubjectPrerequisiteService(repo);

      // Correct behavior: the latest locked grade (90) is selected -> eligible.
      const result = await service.checkEligibility('s1', 'stu-1', 'org-1');
      expect(result).toEqual({ eligible: true, missing: [] });
    });

    it('sanity control: a single locked passing grade resolves correctly', async () => {
      const fakeDb = {
        subjectPrerequisite: {
          findMany: jest.fn().mockResolvedValue([
            {
              prerequisite_id: 'p-math',
              prerequisite: { id: 'p-math', name: 'Math' },
            },
          ]),
        },
        grade: {
          findMany: jest.fn().mockResolvedValue([
            {
              id: 'g-new',
              class: { subject_id: 'p-math' },
              final_score: 90,
              is_locked: true,
            },
          ]),
        },
      };

      const repo = new SubjectPrerequisiteRepository(fakeDb as any);
      const service = new SubjectPrerequisiteService(repo);

      const result = await service.checkEligibility('s1', 'stu-1', 'org-1');
      expect(result).toEqual({ eligible: true, missing: [] });
    });
  });
});

import { IsString, IsNotEmpty, IsArray, IsUUID } from 'class-validator';

export class CreatePrerequisiteDto {
  @IsUUID()
  subject_id: string;

  @IsUUID()
  prerequisite_id: string;
}

export class BulkCreatePrerequisiteDto {
  @IsUUID()
  subject_id: string;

  @IsArray()
  @IsString({ each: true })
  prerequisite_ids: string[];
}

export class PrerequisiteCheckDto {
  @IsUUID()
  subject_id: string;

  @IsUUID()
  student_id: string;
}

export class PrerequisiteCheckResultDto {
  eligible: boolean;
  missing: {
    subject_id: string;
    subject_name: string;
    reason: 'not_taken' | 'not_passed' | 'not_locked';
  }[];
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common'; // ✅ added semicolon

import { SubjectPrerequisiteRepository } from './subject-prerequisite.repository';
import {
  CreatePrerequisiteDto,
  BulkCreatePrerequisiteDto,
  PrerequisiteCheckResultDto,
} from './dto/subject-prerequisite.dto';

// Minimum passing grade — adjust to match your org's grading scale
const PASSING_SCORE = 75;

@Injectable()
export class SubjectPrerequisiteService {
  constructor(
    private readonly prereqRepository: SubjectPrerequisiteRepository,
  ) {}

  async create(orgId: string, dto: CreatePrerequisiteDto) {
    if (dto.subject_id === dto.prerequisite_id) {
      throw new BadRequestException(
        'A subject cannot be a prerequisite of itself',
      );
    }

    const existing = await this.prereqRepository.findOne(
      dto.subject_id,
      dto.prerequisite_id,
      orgId,
    );

    if (existing) {
      throw new ConflictException('This prerequisite link already exists');
    }

    return this.prereqRepository.create(orgId, dto);
  }

  async bulkCreate(orgId: string, dto: BulkCreatePrerequisiteDto) {
    if (dto.prerequisite_ids.includes(dto.subject_id)) {
      throw new BadRequestException(
        'A subject cannot be a prerequisite of itself',
      );
    }

    return this.prereqRepository.bulkCreate(
      orgId,
      dto.subject_id,
      dto.prerequisite_ids,
    );
  }

  async findBySubject(subject_id: string, org_id: string) {
    return this.prereqRepository.findBySubject(subject_id, org_id);
  }

  async remove(id: string, subject_id: string, org_id: string) {
    const existing = await this.prereqRepository.findOne(
      subject_id,
      id,
      org_id,
    );

    if (!existing) {
      throw new NotFoundException('Prerequisite link not found');
    }

    return this.prereqRepository.delete(existing.id);
  }

  async checkEligibility(
    subject_id: string,
    student_id: string,
    org_id: string,
  ): Promise<PrerequisiteCheckResultDto> {
    let rows = await this.prereqRepository.getPrerequisitesWithGrades(
      subject_id,
      student_id,
      org_id,
    );

    if (rows.length === 0) {
      const defined = await this.prereqRepository.findBySubject(
        subject_id,
        org_id,
      );

      if (defined.length > 0) {
        rows = defined.map((d) => ({
          subject_id: d.prerequisite_id,
          subject_name: (d as any).prerequisite?.name ?? d.prerequisite_id,
          grade: null,
        }));
      }
    }

    if (rows.length === 0) {
      return { eligible: true, missing: [] };
    }

    const missing: PrerequisiteCheckResultDto['missing'] = [];

    for (const row of rows) {
      if (!row.grade) {
        missing.push({
          subject_id: row.subject_id,
          subject_name: row.subject_name,
          reason: 'not_taken',
        });
        continue;
      }

      if (!row.grade.is_locked) {
        missing.push({
          subject_id: row.subject_id,
          subject_name: row.subject_name,
          reason: 'not_locked',
        });
        continue;
      }

      if (row.grade.final_score < PASSING_SCORE) {
        missing.push({
          subject_id: row.subject_id,
          subject_name: row.subject_name,
          reason: 'not_passed',
        });
      }
    }

    return {
      eligible: missing.length === 0,
      missing,
    };
  }
}

