import { Injectable } from '@nestjs/common';
import { DatabaseService } from '@/core/database/database.provider';

@Injectable()
export class SubmissionRepository {
  constructor(private readonly db: DatabaseService) {}

  // ───────── SUBMISSION ─────────

  async findByStudent(assessmentId: string, studentId: string) {
    return this.db.submission.findFirst({
      where: { assessment_id: assessmentId, student_id: studentId },
    });
  }

  async findById(id: string) {
    return this.db.submission.findFirst({ where: { id } });
  }

  async create(data: {
    orgId: string;
    assessmentId: string;
    studentId: string;
    status: string;
  }) {
    return this.db.submission.create({
      data: {
        org_id: data.orgId,
        assessment_id: data.assessmentId,
        student_id: data.studentId,
        status: data.status as any,
        score: null,
        manual_score: null,
        manual_section_score: null,
        system_section_score: null,
        is_missed: false,
        is_exempted: false,
        submitted_at: null,
      },
    });
  }

  async updateStatus(
    id: string,
    data: {
      status: string;
      score?: number;
      systemSectionScore?: number;
      submittedAt?: Date;
    },
  ) {
    return this.db.submission.update({
      where: { id },
      data: {
        status: data.status as any,
        ...(data.score !== undefined ? { score: data.score } : {}),
        ...(data.systemSectionScore !== undefined
          ? { system_section_score: data.systemSectionScore }
          : {}),
        ...(data.submittedAt !== undefined
          ? { submitted_at: data.submittedAt }
          : {}),
      },
    });
  }

  // ───────── ANSWERS ─────────

  async findAnswers(submissionId: string) {
    return this.db.submissionAnswer.findMany({
      where: { submission_id: submissionId },
    });
  }

  async upsertAnswers(
    submissionId: string,
    orgId: string,
    answers: Array<{ questionId: string; answer: string }>,
  ) {
    // Delete existing answers then recreate — cleanest upsert for bulk
    await this.db.submissionAnswer.deleteMany({
      where: { submission_id: submissionId },
    });

    if (answers.length === 0) return [];

    await this.db.submissionAnswer.createMany({
      data: answers.map((a) => ({
        org_id: orgId,
        submission_id: submissionId,
        question_id: a.questionId,
        answer: a.answer,
        is_correct: null, // graded on finish
      })),
    });

    return this.db.submissionAnswer.findMany({
      where: { submission_id: submissionId },
    });
  }

  async gradeAnswers(
    submissionId: string,
    gradedAnswers: Array<{ id: string; isCorrect: boolean }>,
  ) {
    // Update each answer's is_correct flag
    await Promise.all(
      gradedAnswers.map((a) =>
        this.db.submissionAnswer.update({
          where: { id: a.id },
          data: { is_correct: a.isCorrect },
        }),
      ),
    );
  }

  // ───────── QUESTIONS (for auto-grading) ─────────

  async findQuestionsByAssessment(assessmentId: string) {
    return this.db.question.findMany({
      where: { assessment_id: assessmentId },
    });
  }

  // ───────── REOPEN ─────────

  async clearReopenedUntil(submissionId: string) {
    return this.db.submission.update({
      where: { id: submissionId },
      data: { reopened_until: null },
    });
  }

  // ───────── AUTO-CLOSE DRAFTS ─────────

  async closeExpiredDrafts(assessmentId: string) {
    return this.db.submission.updateMany({
      where: {
        assessment_id: assessmentId,
        status: 'draft',
      },
      data: {
        status: 'submitted',
        submitted_at: new Date(),
      },
    });
  }
}

// @/modules/submission/submission.service.ts
import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { SubmissionRepository } from './submission.repository';
import { AssessmentRepository } from '../assessment/core/assessment-core.repository';
import { AttendanceService } from '../attendance/attendance.service';
import { GradeEducatorService } from '../grade/educator/grade-educator.service';
import { SaveDraftDto, FinishSubmissionDto } from './dto/submission.dto';

@Injectable()
export class SubmissionService {
  constructor(
    private readonly submissionRepo: SubmissionRepository,
    private readonly assessmentRepo: AssessmentRepository,
    private readonly attendanceService: AttendanceService,
    private readonly gradeService: GradeEducatorService,
  ) {}

  // ── Helpers ───────────────────────────────────────────────────────────────

  private async assertAssessmentOpen(
    assessmentId: string,
    orgId: string,
    studentId?: string,
  ) {
    const assessment = await this.assessmentRepo.findById(assessmentId, orgId);
    if (!assessment) throw new NotFoundException('Assessment not found.');

    const now = new Date();

    // Must be past release date
    if (assessment.release_date && now < new Date(assessment.release_date)) {
      throw new ForbiddenException('Assessment has not been released yet.');
    }

    // Check end date — skip if student has a reopened_until extension
    if (assessment.end_date && now > new Date(assessment.end_date)) {
      if (studentId) {
        const submission = await this.submissionRepo.findByStudent(
          assessmentId,
          studentId,
        );
        if (
          submission?.reopened_until &&
          now < new Date(submission.reopened_until)
        ) {
          return assessment; // extension is still valid
        }
      }
      throw new ForbiddenException('Assessment deadline has passed.');
    }

    return assessment;
  }

  // ── START / RESUME attempt ────────────────────────────────────────────────

  async startOrResume(assessmentId: string, orgId: string, studentId: string) {
    const assessment = await this.assertAssessmentOpen(
      assessmentId,
      orgId,
      studentId,
    );

    // Check existing attempt
    const existing = await this.submissionRepo.findByStudent(
      assessmentId,
      studentId,
    );

    if (existing) {
      if (existing.status === 'submitted') {
        throw new ForbiddenException(
          'You have already submitted this assessment.',
        );
      }
      // Resume draft — return existing with saved answers
      const answers = await this.submissionRepo.findAnswers(existing.id);
      return { ...existing, answers };
    }

    // Create new draft attempt
    const submission = await this.submissionRepo.create({
      orgId,
      assessmentId,
      studentId,
      status: 'draft',
    });

    return { ...submission, answers: [] };
  }

  // ── SAVE DRAFT ────────────────────────────────────────────────────────────

  async saveDraft(
    assessmentId: string,
    orgId: string,
    studentId: string,
    dto: SaveDraftDto,
  ) {
    await this.assertAssessmentOpen(assessmentId, orgId, studentId);

    const submission = await this.submissionRepo.findByStudent(
      assessmentId,
      studentId,
    );

    if (!submission) {
      throw new NotFoundException(
        'No active attempt found. Start the assessment first.',
      );
    }

    if (submission.status === 'submitted') {
      throw new ForbiddenException('Assessment already submitted.');
    }

    // Validate all questionIds belong to this assessment
    const questions =
      await this.submissionRepo.findQuestionsByAssessment(assessmentId);
    const validIds = new Set(questions.map((q) => q.id));

    for (const answer of dto.answers) {
      if (!validIds.has(answer.questionId)) {
        throw new BadRequestException(
          `Question ${answer.questionId} does not belong to this assessment.`,
        );
      }
    }

    const answers = await this.submissionRepo.upsertAnswers(
      submission.id,
      orgId,
      dto.answers,
    );

    return { submissionId: submission.id, savedAnswers: answers.length };
  }

  // ── FINISH / SUBMIT ───────────────────────────────────────────────────────

  async finish(
    assessmentId: string,
    orgId: string,
    studentId: string,
    dto: FinishSubmissionDto,
  ) {
    const assessment = await this.assertAssessmentOpen(
      assessmentId,
      orgId,
      studentId,
    );

    const submission = await this.submissionRepo.findByStudent(
      assessmentId,
      studentId,
    );

    if (!submission) {
      throw new NotFoundException(
        'No active attempt found. Start the assessment first.',
      );
    }

    if (submission.status === 'submitted') {
      throw new ForbiddenException('Assessment already submitted.');
    }

    // Save final answers
    const questions =
      await this.submissionRepo.findQuestionsByAssessment(assessmentId);
    const validIds = new Set(questions.map((q) => q.id));

    for (const answer of dto.answers) {
      if (!validIds.has(answer.questionId)) {
        throw new BadRequestException(
          `Question ${answer.questionId} does not belong to this assessment.`,
        );
      }
    }

    const savedAnswers = await this.submissionRepo.upsertAnswers(
      submission.id,
      orgId,
      dto.answers,
    );

    // ── Auto-grade (skip entirely for manual mode) ───────────────────────────

    const isManual = assessment.grading_mode === 'manual';
    const isHybrid = assessment.grading_mode === 'hybrid';

    let gradedAnswers: Array<{ id: string; isCorrect: boolean }> = [];
    let score: number | null = null;
    let systemSectionScore: number | undefined;
    let essayPending = false;

    if (!isManual) {
      const questionMap = new Map(questions.map((q) => [q.id, q]));

      // For hybrid: only auto-grade system (non-manual) questions
      // For system: auto-grade all non-essay questions
      const autoGradable = savedAnswers.filter((a) => {
        const q = questionMap.get(a.question_id);
        if (!q) return false;
        if (q.type === 'essay' || q.type === 'manual') return false;
        if (q.is_manual) return false;
        return true;
      });

      gradedAnswers = autoGradable.map((a) => {
        const q = questionMap.get(a.question_id)!;
        return {
          id: a.id,
          isCorrect:
            a.answer.trim().toLowerCase() ===
            (q.correct_answer ?? '').trim().toLowerCase(),
        };
      });

      await this.submissionRepo.gradeAnswers(submission.id, gradedAnswers);

      score = gradedAnswers.filter((a) => a.isCorrect).length;
      systemSectionScore = isHybrid ? score : undefined;
      essayPending = savedAnswers.length - gradedAnswers.length > 0;
    }

    // Mark as submitted — also clear reopened_until so extension is consumed
    const updated = await this.submissionRepo.updateStatus(submission.id, {
      status: 'submitted',
      ...(score !== null ? { score } : {}),
      ...(systemSectionScore !== undefined ? { systemSectionScore } : {}),
      submittedAt: new Date(),
    });

    // Clear reopened_until if it was set
    if (submission.reopened_until) {
      await this.submissionRepo
        .clearReopenedUntil(submission.id)
        .catch(() => {});
    }

    // ── Fire-and-forget: auto-mark present ───────────────────────────────────
    if (assessment.class_id) {
      this.attendanceService
        .markPresentFromSubmission({
          orgId,
          classId: assessment.class_id,
          studentId,
          submittedAt: updated.submitted_at ?? new Date(),
        })
        .catch(() => {}); // non-blocking, never throws
    }

    // ── Fire-and-forget: auto-recompute grade ─────────────────────────────────
    if (assessment.class_id && assessment.term_id) {
      this.gradeService
        .recomputeStudentGrade(
          assessment.class_id,
          assessment.term_id,
          studentId,
          orgId,
        )
        .catch((err) =>
          console.error(
            `[Submission] Grade recompute failed for ${studentId}:`,
            err,
          ),
        );
    }

    return {
      submissionId: submission.id,
      score,
      totalGraded: isManual ? 0 : gradedAnswers.length,
      essayPending,
      submittedAt: updated.submitted_at,
    };
  }

  // ── GET ANSWERS (educator view) ───────────────────────────────────────────

  async getAnswers(assessmentId: string, submissionId: string, orgId: string) {
    const submission = await this.submissionRepo.findById(submissionId);

    if (!submission || submission.assessment_id !== assessmentId) {
      throw new NotFoundException('Submission not found.');
    }

    const answers = await this.submissionRepo.findAnswers(submissionId);
    const questions =
      await this.submissionRepo.findQuestionsByAssessment(assessmentId);

    // Merge answers with question text for readability
    const questionMap = new Map(questions.map((q) => [q.id, q]));

    return answers.map((a) => ({
      ...a,
      question: questionMap.get(a.question_id) ?? null,
    }));
  }

  // ── CLOSE EXPIRED DRAFTS ──────────────────────────────────────────────────

  async closeExpiredDrafts(assessmentId: string) {
    return this.submissionRepo.closeExpiredDrafts(assessmentId);
  }
}

import {
  Controller,
  Post,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  ParseFilePipe,
  MaxFileSizeValidator,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { extname, join } from 'path';
import { existsSync, mkdirSync } from 'fs';
import { v4 as uuid } from 'uuid';

import { AuthGuard } from '@/commons/guards/auth.guard';
import { RolesGuard } from '@/commons/guards/role.guard';
import { Roles } from '@/commons/decorators/roles.decorator';
import { CurrentUser } from '@/commons/decorators/current-user.decorator';
import { UploadService } from './upload.service';

// ⚠️ PRODUCTION NOTE: these write to the container's LOCAL filesystem.
// Render (and most managed platforms) use EPHEMERAL storage — any file saved
// here is LOST on every deploy/restart and is not shared across instances.
// For production use object storage (S3/Cloudinary/etc.) or a persistent
// Render Disk mounted at /app/uploads instead of the container filesystem.
const PROFILE_UPLOADS_DIR = join(process.cwd(), 'uploads', 'profiles');
const ORG_LOGO_UPLOADS_DIR = join(process.cwd(), 'uploads', 'organizations');

// Ensure directory exists on module load
if (!existsSync(PROFILE_UPLOADS_DIR)) {
  mkdirSync(PROFILE_UPLOADS_DIR, { recursive: true });
}
if (!existsSync(ORG_LOGO_UPLOADS_DIR)) {
  mkdirSync(ORG_LOGO_UPLOADS_DIR, { recursive: true });
}

const ALLOWED_EXTENSIONS = ['.png', '.jpg', '.jpeg', '.gif', '.webp'];

@Controller('uploads')
@UseGuards(AuthGuard, RolesGuard)
export class UploadController {
  constructor(private readonly uploadService: UploadService) {}

  @Post('profile')
  @Roles('student', 'educator', 'admin')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: (_req, _file, cb) => cb(null, PROFILE_UPLOADS_DIR),
        filename: (_req, file, cb) => {
          const ext = extname(file.originalname).toLowerCase();
          cb(null, `${uuid()}${ext}`);
        },
      }),
      fileFilter: (_req, file, cb) => {
        const ext = extname(file.originalname).toLowerCase();
        if (!ALLOWED_EXTENSIONS.includes(ext)) {
          cb(
            new BadRequestException(
              'Only image files (PNG, JPG, GIF, WEBP) are allowed',
            ),
            false,
          );
          return;
        }
        cb(null, true);
      },
      limits: { fileSize: 2 * 1024 * 1024 },
    }),
  )
  async uploadProfileImage(
    @UploadedFile(
      new ParseFilePipe({
        validators: [new MaxFileSizeValidator({ maxSize: 2 * 1024 * 1024 })],
      }),
    )
    file: Express.Multer.File,
    @CurrentUser('id') accountId: string,
  ) {
    const relativePath = `profiles/${file.filename}`;
    const saved = await this.uploadService.saveProfileImage(
      accountId,
      relativePath,
    );
    return { path: saved };
  }

  @Post('organization-logo')
  @Roles('admin')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: (_req, _file, cb) => cb(null, ORG_LOGO_UPLOADS_DIR),
        filename: (_req, file, cb) => {
          const ext = extname(file.originalname).toLowerCase();
          cb(null, `${uuid()}${ext}`);
        },
      }),
      fileFilter: (_req, file, cb) => {
        const ext = extname(file.originalname).toLowerCase();
        if (!ALLOWED_EXTENSIONS.includes(ext)) {
          cb(
            new BadRequestException(
              'Only image files (PNG, JPG, GIF, WEBP) are allowed',
            ),
            false,
          );
          return;
        }
        cb(null, true);
      },
      limits: { fileSize: 2 * 1024 * 1024 },
    }),
  )
  async uploadOrganizationLogo(
    @UploadedFile(
      new ParseFilePipe({
        validators: [new MaxFileSizeValidator({ maxSize: 2 * 1024 * 1024 })],
      }),
    )
    file: Express.Multer.File,
    @CurrentUser('org_id') orgId: string,
  ) {
    const relativePath = `organizations/${file.filename}`;
    const saved = await this.uploadService.saveOrganizationLogo(
      orgId,
      relativePath,
    );
    return { logoUrl: saved };
  }
}

/**
 * playground-assessment-grading.ts
 *
 * REAL end-to-end playground (no mocks, real Nest module graph, real DB):
 *
 *   1. Seeds a fresh org + school year (SY 2026-2027) with the org-seeder.
 *   2. Configures the academic calendar + semester SETTINGS so the FIRST
 *      SEMESTER ENDED on 2026-08-15 ("now" = 2026-08-16), matching the
 *      "semester settings from the past" requirement.
 *   3. Creates a MAPEH Grade 1 class in that semester, applies the elementary
 *      grading scheme, creates a MANUAL assessment for Term 1, has a student
 *      submit, the educator grades the essay, then grades are computed.
 *
 * Usage (from backend/):
 *   npx ts-node -r tsconfig-paths/register src/seeds/playground-assessment-grading.ts
 *   npx ts-node -r tsconfig-paths/register src/seeds/playground-assessment-grading.ts --keep
 *
 * Default cleans up every row created for the playground org; --keep preserves
 * the data for inspection.
 */

import * as path from 'path';
import { config as loadEnv } from 'dotenv';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { v4 as uuid } from 'uuid';

import { AppModule } from '@/app.module';
import { DatabaseService } from '@/core/database/database.provider';
import { OrgSeederService } from '@/modules/org-seeder/org-seeder.service';
import { SemesterTemplateService } from '@/modules/semester-template/semester-template.service';
import { ClassService } from '@/modules/class/class.service';
import { EnrollmentService } from '@/modules/enrollment/enrollment.service';
import { GradingSchemeService } from '@/modules/grading-scheme/grading-scheme.service';
import { AssessmentEducatorService } from '@/modules/assessment/educator/assessment-educator.service';
import { SubmissionService } from '@/modules/submission/submission.service';
import { GradeEducatorService } from '@/modules/grade/educator/grade-educator.service';
import {
  CreateAssessmentDto,
  GradeEssayDto,
  GradingMode,
} from '@/modules/assessment/dto/assessment.dto';

// ── Config ────────────────────────────────────────────────────────────────────

if (!process.env.DATABASE_URL) {
  loadEnv({ path: path.join(__dirname, '..', '.env') });
  console.log('[playground] DATABASE_URL loaded from backend/.env');
}

const SALT_ROUNDS = 10;
const SEED_PASSWORD = 'seed123';
const KEEP_ORG = process.argv.includes('--keep');

const SY_START = '2026-08-01';
const SY_END = '2027-06-30';
const SY_NAME = 'SY 2026-2027';

// First semester ENDED 2026-08-15 (past); second semester opened 2026-08-16.
const SEM1_TERMS = [
  ['2026-08-01', '2026-08-05'],
  ['2026-08-06', '2026-08-10'],
  ['2026-08-11', '2026-08-15'],
];
const SEM2_TERMS = [
  ['2026-08-16', '2026-12-31'],
  ['2027-01-01', '2027-03-31'],
  ['2027-04-01', '2027-06-30'],
];

const log = (msg: string) => console.log(`[playground] ${msg}`);

async function step(
  label: string,
  fn: () => Promise<unknown> | unknown,
): Promise<void> {
  try {
    await fn();
    log(`PASS ${label}`);
  } catch (err) {
    log(`FAIL ${label} — ${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

function fmt(d: unknown): string {
  if (!d) return '-';
  return new Date(String(d)).toISOString().slice(0, 10);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  let app: INestApplication;
  let db: DatabaseService;

  // `--cleanup <orgId>` only runs cleanup for an existing org (e.g. a leftover
  // from a previously interrupted run) and exits.
  const cleanupArgIdx = process.argv.indexOf('--cleanup');
  const cleanupOrgId =
    cleanupArgIdx >= 0 ? process.argv[cleanupArgIdx + 1] : undefined;

  const orgId = `pg-${uuid()}`;
  const schoolYearId = `pg-sy-${uuid()}`;
  const actorId = `pg-actor-${uuid()}`;
  const short = orgId.slice(3, 9);

  log('--- BOOTING FULL AppModule (real module graph) ---');
  const moduleFixture: TestingModule = await Test.createTestingModule({
    imports: [AppModule],
  }).compile();
  app = moduleFixture.createNestApplication();
  await app.init();

  db = app.get(DatabaseService);

  if (cleanupOrgId) {
    log(`--- CLEANUP-ONLY: deleting all rows for org ${cleanupOrgId} ---`);
    const schoolYears = await db.schoolYear.findMany({
      where: { org_id: cleanupOrgId },
      select: { id: true },
    });
    for (const sy of schoolYears) {
      await cleanup(db, cleanupOrgId, sy.id);
    }
    if (schoolYears.length === 0) {
      await cleanup(db, cleanupOrgId, '');
    }
    await app.close();
    log('Cleanup-only complete.');
    return;
  }

  // moduleFixture.get() resolves ANY provider in the container (exports don't matter).
  const orgSeeder = moduleFixture.get(OrgSeederService);
  const semesterTemplateService = moduleFixture.get(SemesterTemplateService);
  const classService = moduleFixture.get(ClassService);
  const enrollmentService = moduleFixture.get(EnrollmentService);
  const gradingSchemeService = moduleFixture.get(GradingSchemeService);
  const assessmentService = moduleFixture.get(AssessmentEducatorService);
  const submissionService = moduleFixture.get(SubmissionService);
  const gradeEducatorService = moduleFixture.get(GradeEducatorService);

  let educatorId = '';
  let studentId = '';
  let classId = '';
  let termId = '';
  let assessmentId = '';
  let submissionId = '';

  try {
    // ── 1. org + school year fixture ─────────────────────────────────────────
    await step('create org + school year rows', async () => {
      await db.organization.create({
        data: { id: orgId, name: `Playground ${orgId}` },
      });
      await db.schoolYear.create({
        data: {
          id: schoolYearId,
          org_id: orgId,
          name: SY_NAME,
          status: 'active',
          start_date: new Date(`${SY_START}T00:00:00.000Z`),
          end_date: new Date(`${SY_END}T00:00:00.000Z`),
        },
      });
    });

    // ── 2. seed domain data (elementary only) + academic calendar ─────────────
    await step('seedOrg (elementary, first sem ends 2026-08-15)', async () => {
      await orgSeeder.seedOrg({
        orgId,
        schoolYearId,
        actorId,
        programs: ['elementary'],
        seedGradingScales: true,
        seedGradingSchemes: true,
        seedSemesterTemplates: true,
        seedProgramCalendars: true,
        programCalendars: {
          elementary: {
            startDate: SY_START,
            endDate: SY_END,
            notes: 'Playground calendar — 2 semesters, first ends Aug 15',
            breaks: [
              {
                label: 'Semester 1',
                startDate: SY_START,
                endDate: '2026-08-15',
              },
              { label: 'Semester 2', startDate: '2026-08-16', endDate: SY_END },
            ],
          },
        },
      });
    });

    // ── 3. resolve structure ─────────────────────────────────────────────────
    let programId = '';
    let grade1LevelId = '';
    let subjectId = '';
    let schemeTemplateId = '';

    await step(
      'resolve program / level / subject / scheme template',
      async () => {
        const program = await db.program.findFirst({
          where: { org_id: orgId, type: 'elementary' },
        });
        if (!program) throw new Error('elementary program not seeded.');
        programId = program.id;

        const grade1 = await db.level.findFirst({
          where: { org_id: orgId, program_id: programId, name: 'Grade 1' },
        });
        if (!grade1) throw new Error('Grade 1 level not seeded.');
        grade1LevelId = grade1.id;

        const mapeh = await db.subject.findFirst({
          where: {
            org_id: orgId,
            program_id: programId,
            level_id: grade1LevelId,
            name: 'MAPEH',
          },
        });
        if (!mapeh) throw new Error('MAPEH Grade 1 subject not seeded.');
        subjectId = mapeh.id;

        const schemeTpl = await db.gradingSchemeTemplate.findFirst({
          where: { org_id: orgId, program_type: 'elementary' },
        });
        if (!schemeTpl)
          throw new Error('elementary grading scheme template not seeded.');
        schemeTemplateId = schemeTpl.id;
      },
    );

    // ── 4. accounts ──────────────────────────────────────────────────────────
    await step('create educator + student accounts', async () => {
      const hash = await bcrypt.hash(SEED_PASSWORD, SALT_ROUNDS);
      const educator = await db.account.create({
        data: {
          org_id: orgId,
          role: 'educator',
          email: `pg.educator.${short}@test.local`,
          password: hash,
          status: 'active',
        },
      });
      educatorId = educator.id;
      await db.profile.create({
        data: {
          account_id: educator.id,
          full_name: 'Playground Educator',
        },
      });

      const student = await db.account.create({
        data: {
          org_id: orgId,
          role: 'student',
          email: `pg.student.${short}@test.local`,
          password: hash,
          status: 'active',
        },
      });
      studentId = student.id;
      await db.profile.create({
        data: {
          account_id: student.id,
          full_name: 'Playground Student',
        },
      });
      log(
        `educator (${educator.id}) / student (${student.id}) created — password "${SEED_PASSWORD}"`,
      );
    });

    // ── 5. academic placement (studentSchoolYear → program enrollment) ───────
    await step('student academic placement (Grade 1, elementary)', async () => {
      const ssy = await db.studentSchoolYear.create({
        data: {
          org_id: orgId,
          student_id: studentId,
          school_year_id: schoolYearId,
          status: 'active',
        },
      });
      await db.studentProgramEnrollment.create({
        data: {
          org_id: orgId,
          student_school_year_id: ssy.id,
          program_id: programId,
          level_id: grade1LevelId,
          status: 'active',
        },
      });
    });

    // ── 6. semester settings (term dates) — first sem fully in the past ─────
    let sem1Id = '';

    await step('saveTermDates (semester settings from the past)', async () => {
      const assignment = await db.programSemesterAssignment.findUnique({
        where: { program_id: programId },
        include: {
          template: {
            include: {
              semesters: {
                orderBy: { order_index: 'asc' },
                include: { terms: { orderBy: { order_index: 'asc' } } },
              },
            },
          },
        },
      });
      if (!assignment)
        throw new Error('No semester template assigned to elementary program.');

      const termDates: Array<{
        termId: string;
        startDate: string;
        endDate: string;
      }> = [];
      assignment.template.semesters.forEach((sem, si) => {
        const per = si === 0 ? SEM1_TERMS : SEM2_TERMS;
        sem.terms.forEach((t, ti) => {
          termDates.push({
            termId: t.id,
            startDate: per[ti][0],
            endDate: per[ti][1],
          });
        });
      });

      await semesterTemplateService.saveTermDates(orgId, programId, termDates);

      const sem1 = await db.semester.findFirst({
        where: { org_id: orgId, school_year_id: schoolYearId, name: '1st' },
      });
      if (!sem1)
        throw new Error('First semester row was not created by saveTermDates.');
      sem1Id = sem1.id;
      termId = assignment.template.semesters[0].terms[0].id;

      log(
        `term dates set — Semester 1 runs ${fmt(sem1.start_date)} → ${fmt(sem1.end_date)} (ENDED)`,
      );
      log(`class will use template term id ${termId}`);
    });

    // ── 7. class (MAPEH Grade 1, first semester) ─────────────────────────────
    await step(
      'create MAPEH Grade 1 class (semester ended 2026-08-15)',
      async () => {
        const cls = await classService.create(
          orgId,
          {
            subjectId,
            educatorId,
            schoolYearId,
            semesterId: sem1Id,
            capacity: 40,
            schedules: [{ weekday: 1, startTime: '08:00', endTime: '09:00' }],
          },
          actorId,
        );
        if (!cls) throw new Error('Class creation returned null.');
        classId = cls.id;
        log(`class ${classId} created`);
      },
    );

    // ── 8. apply grading scheme to the class ─────────────────────────────────
    await step('apply Elementary Scheme to class', async () => {
      await gradingSchemeService.applyTemplateToClass(orgId, {
        classId,
        templateId: schemeTemplateId,
        name: 'Elementary Scheme (Playground)',
      });
    });

    // ── 9. enroll student (prerequisite gate must pass for MAPEH Gr 1) ───────
    await step('enroll student in the class', async () => {
      await enrollmentService.enroll(
        classId,
        subjectId,
        sem1Id,
        40,
        studentId,
        orgId,
      );
    });

    // ── 10. create MANUAL assessment for Term 1 ──────────────────────────────
    let manualQuestionId = '';
    await step('create manual assessment (Term 1, type activity)', async () => {
      const dto: CreateAssessmentDto = {
        termId,
        type: 'activity',
        title: 'MAPEH Activity 1 — Shapes and Sounds',
        totalItems: 10,
        gradingMode: GradingMode.MANUAL,
        manualMaxScore: 10,
        showBreakdown: true,
        manualInstructions:
          'Perform and describe the activity. Show your work clearly.',
        releaseDate: SY_START, // released Aug 1 (past)
        endDate: '2026-12-31', // still open so the student can submit "now"
      };
      const assessment = await assessmentService.create(
        classId,
        orgId,
        educatorId,
        dto,
      );
      assessmentId = assessment.id;
      const questions = (assessment as any).questions ?? [];
      if (!questions.length)
        throw new Error('No questions created for manual assessment.');
      manualQuestionId = questions[0].id;
      log(`assessment ${assessmentId} created (manual, 1 question)`);
    });

    // ── 11. student submits ──────────────────────────────────────────────────
    await step('student start → save draft → finish', async () => {
      await submissionService.startOrResume(assessmentId, orgId, studentId);
      await submissionService.saveDraft(assessmentId, orgId, studentId, {
        answers: [{ questionId: manualQuestionId, answer: 'My answer draft.' }],
      });
      const finished = await submissionService.finish(
        assessmentId,
        orgId,
        studentId,
        {
          answers: [
            { questionId: manualQuestionId, answer: 'My final answer.' },
          ],
        },
      );
      submissionId = finished.submissionId;
      log(`submitted (${submissionId})`);
    });

    // ── 12. educator grades the essay ────────────────────────────────────────
    await step('educator gradeEssay (8/10)', async () => {
      const dto: GradeEssayDto = { score: 8 };
      await assessmentService.gradeEssay(
        assessmentId,
        submissionId,
        orgId,
        educatorId,
        dto,
      );
    });

    // ── 13. compute grades for Term 1 ────────────────────────────────────────
    const computed = {
      grade: null as { final_score: number; final_grade: string } | null,
    };
    await step('computeGrades(Term 1)', async () => {
      const result = await gradeEducatorService.computeGrades(
        classId,
        termId,
        orgId,
        educatorId,
      );
      log(`computeGrades → ${JSON.stringify(result)}`);
      computed.grade = await db.grade.findFirst({
        where: {
          org_id: orgId,
          student_id: studentId,
          class_id: classId,
          term_id: termId,
        },
        select: { final_score: true, final_grade: true },
      });
    });

    const scheme = await db.gradingScheme.findFirst({
      where: { class_id: classId, org_id: orgId },
      include: { components: true },
    });
    const scale = await db.gradingScaleAssignment.findFirst({
      where: {
        org_id: orgId,
        program_id: programId,
        school_year_id: schoolYearId,
      },
      include: { grading_scale: true },
    });

    log('');
    log('================== PLAYGROUND RESULT ==================');
    log(`org            : ${orgId}`);
    log(`school year    : ${SY_NAME} (${SY_START} → ${SY_END})`);
    log(`semester 1     : 2026-08-01 → 2026-08-15 (ENDED)`);
    log(`assessment     : ${assessmentId} (manual, type=activity)`);
    log(`grading scheme : ${scheme?.name ?? '-'}`);
    log(
      `  components   : ${scheme?.components.map((c) => `${c.name}(${c.type},${c.weight})`).join(', ') ?? '-'}`,
    );
    log(`grading scale  : ${scale?.grading_scale?.name ?? '-'}`);
    log(
      `TERM 1 GRADE   : score=${computed.grade?.final_score ?? '?'}  grade=${computed.grade?.final_grade ?? '?'}`,
    );
    log('======================================================');
    log('Students should be able to see this grade in the app.');
  } finally {
    if (!KEEP_ORG) {
      log(`--- CLEANUP: deleting rows for ${orgId} ---`);
      await cleanup(db, orgId, schoolYearId);
      log('Cleanup complete. (Use --keep to preserve the data.)');
    } else {
      log(
        `--- --keep set: preserved org ${orgId} (school year ${schoolYearId}) ---`,
      );
    }
    await app.close();
  }
}

