    ) {
      return db.enrollmentPeriod.create({
        data: {
          org_id: orgId,
          school_year_id: schoolYearId,
          name: `Period ${lockDateOffsetDays}`,
          token: `e2e6-${uuid().slice(0, 10)}`,
          start_date: new Date(now - 2 * day),
          lock_date: new Date(now + lockDateOffsetDays * day),
          end_date: new Date(now + 10 * day),
          created_by: actorId,
          section_overflow_action: 'expand_capacity',
        },
      });
    }

    async function pendingApplicationFixture(p: {
      orgId: string;
      schoolYearId: string;
      periodId: string;
      programId: string;
      levelId: string;
      email: string;
      name: string;
    }) {
      return db.enrollmentApplication.create({
        data: {
          org_id: p.orgId,
          school_year_id: p.schoolYearId,
          enrollment_period_id: p.periodId,
          application_code: uuid().slice(0, 4).toUpperCase(),
          personal_email: p.email,
          first_name: p.name.split(' ')[0],
          last_name: p.name.split(' ')[1] ?? 'App',
          program_id: p.programId,
          level_id: p.levelId,
          status: 'pending',
        },
      });
    }

    async function existingEnrollment(
      orgId: string,
      schoolYearId: string,
      programId: string,
      levelId: string,
      sectionId: string,
      index: number,
    ) {
      const account = await db.account.create({
        data: {
          org_id: orgId,
          role: 'student',
          email: `fixture-${orgId.slice(0, 6)}-${index}@example.com`,
          password: 'x',
          status: 'active',
        },
      });
      const ssy = await db.studentSchoolYear.create({
        data: {
          org_id: orgId,
          student_id: account.id,
          school_year_id: schoolYearId,
          status: 'active',
        },
      });
      await db.studentProgramEnrollment.create({
        data: {
          org_id: orgId,
          student_school_year_id: ssy.id,
          program_id: programId,
          level_id: levelId,
          section_id: sectionId,
          status: 'active',
        },
      });
      return account.id;
    }

    async function sectionFixture(
      orgId: string,
      schoolYearId: string,
      levelId: string,
      capacity: number,
    ) {
      return db.section.create({
        data: {
          org_id: orgId,
          school_year_id: schoolYearId,
          level_id: levelId,
          name: `Section-${uuid().slice(0, 4)}`,
          capacity,
          order_index: 0,
        },
      });
    }

    async function placeableStudent(
      orgId: string,
      schoolYearId: string,
      tag: string,
    ) {
      const account = await db.account.create({
        data: {
          org_id: orgId,
          role: 'student',
          email: `race-${tag}-${orgId.slice(0, 6)}-${uuid().slice(0, 4)}@example.com`,
          password: 'x',
          status: 'active',
        },
      });
      const ssy = await db.studentSchoolYear.create({
        data: {
          org_id: orgId,
          student_id: account.id,
          school_year_id: schoolYearId,
          status: 'active',
        },
      });
      return { accountId: account.id, ssyId: ssy.id };
    }

    async function activeCountInSection(sectionId: string) {
      return db.studentProgramEnrollment.count({
        where: { section_id: sectionId, status: 'active' },
      });
    }

    beforeAll(async () => {
      const moduleFixture: TestingModule = await Test.createTestingModule({
        imports: [
          CoreModule,
          EnrollmentPortalModule,
          AuthModule,
          AuditLogModule,
          StudentModule,
          StudentEnrollmentModule,
          NotificationModule,
          SchoolYearModule,
        ],
        providers: [
          EnrollmentApprovalService,
          EnrollmentApprovalRepository,
          EnrollmentRegistrarService,
          EnrollmentRegistrarRepository,
        ],
      }).compile();
      app = moduleFixture.createNestApplication();
      await app.init();
      db = app.get(DatabaseService);
      approvalService = app.get(EnrollmentApprovalService);
      autoLock = app.get(EnrollmentAutoLockService);
      registrarRepo = app.get(EnrollmentRegistrarRepository);
      approvalRepo = app.get(EnrollmentApprovalRepository);
      registrarService = app.get(EnrollmentRegistrarService);
    }, 120000);

    it('(a) PROOF: the sweep can lock an application WHILE the approval is inside its window, and the approval write still lands (no write-time pending guard)', async () => {
      return check(
        'item6 (a) approval + sweep both act on the same application',
        async () => {
          const sy = await orgFixture(orgA, 'E2E Item 6a Org');
          const { program, level } = await programLevelFixture(orgA.id, sy.id);
          // lock_date in the PAST so the auto-lock sweep considers this app expired.
          const period = await periodFixture(orgA.id, sy.id, -1);
          const appRow = await pendingApplicationFixture({
            orgId: orgA.id,
            schoolYearId: sy.id,
            periodId: period.id,
            programId: program.id,
            levelId: level.id,
            email: `race-applicant-${orgA.id.slice(0, 6)}@gmail.com`,
            name: 'Race Applicant',
          });

          // Mirrors approve()'s OUTSIDE-transaction pre-check read (service line 39).
          const preCheck = await registrarRepo.findApplicationDetail(
            orgA.id,
            appRow.id,
          );
          log(`(a) pre-check read status: ${preCheck!.status}`);
          expect(preCheck!.status).toBe('pending');

          // Mimic the approval transaction: open a real interactive $transaction, take
          // its read (the pending status), then HOLD while the real sweep commits.
          let markRead!: () => void;
          const readDone = new Promise<void>((r) => (markRead = r));
          let releaseWrite!: () => void;
          const writeGate = new Promise<void>((r) => (releaseWrite = r));

          const approvalWrite = db.$transaction(async (tx) => {
            const inside = await tx.enrollmentApplication.findUnique({
              where: { id: appRow.id },
            });
            markRead();
            await writeGate;
            const res = await approvalRepo.approveInTx(
              tx,
              appRow.id,
              actorId,
              'race-account-id',
            );
            return res.status;
          });

          await readDone; // approval's transaction has its snapshot (pending)

          const sweep = await autoLock.lockExpired(); // real sweep now flips it to locked
          log(`(a) sweep ran (lockedCount=${sweep.lockedCount})`);
          const midState = await db.enrollmentApplication.findUnique({
            where: { id: appRow.id },
            select: { status: true },
          });
          log(`(a) mid-race status after sweep: ${midState?.status}`);
          expect(midState?.status).toBe('locked');

          releaseWrite(); // approval's UNCONDITIONAL update now lands on the locked row
          const writeStatus = await approvalWrite;
          log(`(a) approval transaction wrote status: ${writeStatus}`);

          const finalState = await db.enrollmentApplication.findUnique({
            where: { id: appRow.id },
            select: { status: true, resulting_account_id: true },
          });
          log(
            `(a) final: ${finalState?.status}, resulting_account_id=${finalState?.resulting_account_id}`,
          );

          // The bug: a status guard at write time (e.g. updateMany where status='pending')
          // would have made this write no-op/error. Current code overwrites the lock.
          expect(finalState?.status).toBe('approved');
        },
      );
    }, 120000);

    it('(b) PROOF: two section reads can overlap the same snapshot and BOTH land, oversubscribing past capacity', async () => {
      return check(
        'item6 (b) count-snapshot race oversubscribes the section',
        async () => {
          const sy = await orgFixture(orgB, 'E2E Item 6b Org');
          const { program, level } = await programLevelFixture(orgB.id, sy.id);
          const section = await sectionFixture(orgB.id, sy.id, level.id, 5); // capacity 5
          const period = await periodFixture(orgB.id, sy.id, +1); // lock_date in the FUTURE

          // Section at capacity-1: 4 existing active enrollments.
          for (let i = 0; i < 4; i++) {
            await existingEnrollment(
              orgB.id,
              sy.id,
              program.id,
              level.id,
              section.id,
              i,
            );
          }
          const beforeCount = await activeCountInSection(section.id);
          log(`(b) section before: ${beforeCount}/5`);
          expect(beforeCount).toBe(4);

          // Deterministic interleave: two REAL transactions each read the section
          // count (the exact pattern findEligibleSectionsTx uses) and only AFTER
          // BOTH have read do we let either write. Any write-time guard would have
          // to catch the second write — the current code has none.
          const racerA = await placeableStudent(orgB.id, sy.id, 'racer-a');
          const racerB = await placeableStudent(orgB.id, sy.id, 'racer-b');

          let reads = 0;
          let bothRead!: () => void;
          const bothReadDone = new Promise<void>((r) => (bothRead = r));
          let release!: () => void;
          const writeGate = new Promise<void>((r) => (release = r));

          const racer = (tag: string, accountId: string, ssyId: string) =>
            db.$transaction(async (tx) => {
              log(`(b) txn ${tag} begin`);
              const seen = await tx.studentProgramEnrollment.count({
                where: { section_id: section.id, status: 'active' },
              });
              log(`(b) txn ${tag} read count=${seen}`);
              reads += 1;
              if (reads === 2) bothRead();
              await writeGate;
              await tx.studentProgramEnrollment.create({
                data: {
                  org_id: orgB.id,
                  student_school_year_id: ssyId,
                  program_id: program.id,
                  level_id: level.id,
                  section_id: section.id,
                  status: 'active',
                },
              });
              log(`(b) txn ${tag} wrote`);
              return seen;
            });

          const pA = racer('A', racerA.accountId, racerA.ssyId);
          const pB = racer('B', racerB.accountId, racerB.ssyId);
          await Promise.race([
            bothReadDone,
            new Promise((_res, rej) =>
              setTimeout(
                () => rej(new Error(`read barrier timeout: reads=${reads}`)),
                30000,
              ),
            ),
          ]);
          release(); // both txns continue their unconditional writes simultaneously
          const seenByRacer = await Promise.all([pA, pB]);
          log(
            `(b) both racers read the SAME snapshot count=${seenByRacer[0]}/${seenByRacer[1]}`,
          );
          expect(seenByRacer[0]).toBe(4);
          expect(seenByRacer[1]).toBe(4);

          const afterCount = await activeCountInSection(section.id);
          const sec = await db.section.findUnique({
            where: { id: section.id },
          });
          log(
            `(b) section after overlapping approvals: ${afterCount}/${sec?.capacity}`,
          );

          // Correct behavior: at capacity-1 (4/5) only ONE of the two would be
          // admitted. Both read-and-wrote, so the section is now oversubscribed.
          expect(afterCount).toBeGreaterThan(sec!.capacity);
        },
      );
    }, 120000);

    afterAll(async () => {
      if (!db) return;
      const step = async (label: string, fn: () => Promise<unknown>) => {
        try {
          await fn();
          log(`cleaned ${label}`);
        } catch (err) {
          log(
            `CLEANUP FAIL @ ${label}: ${err instanceof Error ? err.message : err}`,
          );
        }
      };
      for (const org of [orgA, orgB]) {
        await step(`org ${org.id} applications`, () =>
          db.enrollmentApplication.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} program enrollments`, () =>
          db.studentProgramEnrollment.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} school-year enrollments`, () =>
          db.studentSchoolYear.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} accounts`, () =>
          db.account.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} audit logs`, () =>
          db.auditLog.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} periods`, () =>
          db.enrollmentPeriod.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} sections`, () =>
          db.section.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} levels`, () =>
          db.level.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} programs`, () =>
          db.program.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} school years`, () =>
          db.schoolYear.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id}`, () =>
          db.organization.deleteMany({ where: { id: org.id } }),
        );
      }
      await app.close();
    }, 120000);
  },
);

// backend/test/lane1-item7-application-rejection.guards.e2e-spec.ts
//
// Lane 1 item 7 — proof tests against the REAL database.
//
// (a) A rejected application is committed to the data trail (status / reason /
//     reviewer), a corresponding admin audit record exists, and a re-application
//     from the SAME applicant in the SAME school year is rejected — i.e. a
//     rejected application can never be silently re-placed.
// (b) The write-time immutability guard is state-machined, not generic:
//     `updateApplication` blocks ONLY `locked`/`approved`
//     (enrollment-portal.service.ts:236), so a rejected application remains
//     editable but its status stays `rejected`; meanwhile the review path
//     (`requireReviewable`) refuses to approve a rejected application.

import * as path from 'path';
import { config as loadEnv } from 'dotenv';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import { ConflictException } from '@nestjs/common';
import { v4 as uuid } from 'uuid';

import { CoreModule } from '@/core/core.module';
import { EnrollmentPortalModule } from '@/modules/enrollment-portal/enrollment-portal.module';
import { AuthModule } from '@/modules/auth/auth.module';
import { AuditLogModule } from '@/modules/audit-log/audit-log.module';
import { StudentModule } from '@/modules/student/student.module';
import { StudentEnrollmentModule } from '@/modules/student-enrollment/student-enrollment.module';
import { NotificationModule } from '@/modules/notification/notification.module';
import { SchoolYearModule } from '@/modules/school-year/school-year.module';
import { DatabaseService } from '@/core/database/database.provider';
import { EnrollmentPortalService } from '@/modules/enrollment-portal/enrollment-portal.service';
import { EnrollmentRegistrarService } from '@/modules/enrollment-portal/registrar/enrollment-registrar.service';
import type { EnrollmentSessionClaims } from '@/modules/enrollment-portal/entity/enrollment-portal.entity';
import type { UpsertEnrollmentApplicationDto } from '@/modules/enrollment-portal/dto/enrollment-portal.dto';

if (!process.env.DATABASE_URL) {
  loadEnv({ path: path.join(__dirname, '..', '.env') });
}
const runSuite = process.env.DATABASE_URL ? describe : describe.skip;

jest.setTimeout(300000);

function log(msg: string) {
  console.log(`[items7] ${msg}`);
}

async function check(label: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
    log(`PASS ${label}`);
  } catch (err) {
    log(`FAIL ${label} — ${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

runSuite(
  'Lane 1 item 7 — rejection flow, data-trail guard, write-time state machine (real DB)',
  () => {
    let app: INestApplication;
    let db: DatabaseService;
    let portal: EnrollmentPortalService;
    let registrar: EnrollmentRegistrarService;

    const org = {
      id: `e2e7-org-${uuid()}`,
      slug: `e2e7-${uuid().slice(0, 8)}`,
    };
    const actorId = `e2e7-act-${uuid()}`;
    const now = Date.now();
    const day = 24 * 60 * 60 * 1000;

    let sy: { id: string };
    let program: { id: string };
    let level: { id: string };
    let period: { id: string; token: string };

    beforeAll(async () => {
      const moduleFixture: TestingModule = await Test.createTestingModule({
        imports: [
          CoreModule,
          EnrollmentPortalModule,
          AuthModule,
          AuditLogModule,
          StudentModule,
          StudentEnrollmentModule,
          NotificationModule,
          SchoolYearModule,
        ],
      }).compile();
      app = moduleFixture.createNestApplication();
      await app.init();
      db = app.get(DatabaseService);
      portal = app.get(EnrollmentPortalService);
      registrar = app.get(EnrollmentRegistrarService);

      await db.organization.create({
        data: { id: org.id, name: 'E2E Item 7 Org', slug: org.slug },
      });
      sy = await db.schoolYear.create({
        data: {
          org_id: org.id,
          name: `SY ${org.id.slice(0, 6)}`,
          status: 'active',
          start_date: new Date(now - 30 * day),
          end_date: new Date(now + 300 * day),
        },
      });
      program = await db.program.create({
        data: {
          org_id: org.id,
          school_year_id: sy.id,
          name: 'Elementary E2E 7',
          type: 'elementary',
        },
      });
      level = await db.level.create({
        data: {
          org_id: org.id,
          school_year_id: sy.id,
          program_id: program.id,
          name: 'Grade 1',
        },
      });
      period = await db.enrollmentPeriod.create({
        data: {
          org_id: org.id,
          school_year_id: sy.id,
          name: 'E2E Item 7 Period',
          token: `e2e7-${uuid().slice(0, 10)}`,
          start_date: new Date(now - 2 * day),
          lock_date: new Date(now + 5 * day),
          end_date: new Date(now + 5 * day),
          created_by: actorId,
          section_overflow_action: 'no_section',
        },
      });
    }, 120000);

    function sessionFor(email: string): EnrollmentSessionClaims {
      return {
        type: 'enrollment',
        orgId: org.id,
        schoolYearId: sy.id,
        periodId: period.id,
        personalEmail: email,
        applicationId: null,
      };
    }

    function dtoFor(name: string): UpsertEnrollmentApplicationDto {
      return {
        first_name: name.split(' ')[0],
        last_name: name.split(' ')[1] ?? 'Applicant',
        age: 9,
        address: 'Test Address',
        contact_number: '09170000000',
        last_school_graduated: 'Test School',
        program_id: program.id,
        level_id: level.id,
      };
    }

    it('(a) rejected application is committed to the data trail and can never be silently re-placed', async () => {
      return check(
        'item7 (a) rejection data trail + no re-placement',
        async () => {
          const email = `reject-${uuid().slice(0, 8)}@gmail.com`;
          const session = sessionFor(email);

          // Applicant builds a complete application through the portal.
          const created = await portal.createApplication(
            org.slug,
            period.token,
            session,
            dtoFor('Amy Rejected'),
          );
          log(
            `(a) created application ${created.application_code} -> ${created.status}`,
          );
          expect(created.status).toBe('pending');

          // Registrar rejects it with a reason.
          const rejected = await registrar.rejectApplication(
            org.id,
            actorId,
            created.id,
            {
              reason: 'Incomplete documents — missing birth certificate.',
            },
          );
          log(`(a) rejected result status=${rejected.application.status}`);
          expect(rejected.application.status).toBe('rejected');

          // Data trail on the application row itself.
          const row = await db.enrollmentApplication.findUnique({
            where: { id: created.id },
          });
          expect(row?.status).toBe('rejected');
          expect(row?.reviewed_by).toBe(actorId);
          expect(row?.rejection_reason).toBe(
            'Incomplete documents — missing birth certificate.',
          );
          expect(row?.reviewed_at).toBeTruthy();

          // Admin audit record for the rejection.
          const audit = await db.auditLog.findFirst({
            where: {
              org_id: org.id,
              action: 'ENROLLMENT_APPLICATION_REJECT',
              entity_type: 'enrollment_application',
              entity_id: created.id,
            },
          });
          log(`(a) audit: ${audit ? `found id=${audit.id}` : 'MISSING'}`);
          const metadata: any = audit?.metadata ?? null;
          log(`(a) audit metadata: ${JSON.stringify(metadata)}`);
          expect(audit).toBeTruthy();
          expect(metadata?.reason).toBe(
            'Incomplete documents — missing birth certificate.',
          );
          expect(metadata?.personal_email).toBe(email);

          // The SAME applicant tries to re-apply in the same school year.
          await expect(
            portal.createApplication(
              org.slug,
              period.token,
              session,
              dtoFor('Amy Rejected'),
            ),
          ).rejects.toBeInstanceOf(ConflictException);
          log('(a) re-application blocked');
        },
      );
    }, 120000);

    it('(b) the write-time guard is state-based: rejected stays editable, but the review path refuses to approve it', async () => {
      return check('item7 (b) rejected application state machine', async () => {
        const email = `rejected-edit-${uuid().slice(0, 8)}@gmail.com`;
        const session = sessionFor(email);

        const created = await portal.createApplication(
          org.slug,
          period.token,
          session,
          dtoFor('Robert Rejected'),
        );
        await registrar.rejectApplication(org.id, actorId, created.id, {
          reason: 'Duplicate submission.',
        });
        log(`(b) created + rejected (status=rejected)`);

        // updateApplication ONLY blocks locked/approved (service line 236):
        // a rejected application is still editable ...
        const editSession: EnrollmentSessionClaims = {
          ...session,
          applicationId: created.id,
        };
        const updated = await portal.updateApplication(
          org.slug,
          period.token,
          editSession,
          {
            ...dtoFor('Robert Rejected'),
            last_name: 'Rejected-Updated',
          },
        );
        log(`(b) update succeeded, returned last_name=${updated.last_name}`);
        expect(updated.last_name).toBe('Rejected-Updated');

        // ... but the status must NOT be silently flipped back to pending.
        const row = await db.enrollmentApplication.findUnique({
          where: { id: created.id },
        });
        expect(row?.last_name).toBe('Rejected-Updated');
        expect(row?.status).toBe('rejected');
        expect(row?.rejection_reason).toBe('Duplicate submission.');
        log(`(b) status stayed ${row?.status} after edit`);

        // And the REVIEW path refuses to act on a rejected application.
        await expect(
          registrar.approveApplication(org.id, actorId, created.id),
        ).rejects.toBeInstanceOf(ConflictException);
        log('(b) re-approval of rejected application blocked');
      });
    }, 120000);

    afterAll(async () => {
      if (!db) return;
      const step = async (label: string, fn: () => Promise<unknown>) => {
        try {
          await fn();
          log(`cleaned ${label}`);
        } catch (err) {
          log(
            `CLEANUP FAIL @ ${label}: ${err instanceof Error ? err.message : err}`,
          );
        }
      };
      await step('applications', () =>
        db.enrollmentApplication.deleteMany({ where: { org_id: org.id } }),
      );
      await step('student enrollments', () =>
        db.studentProgramEnrollment.deleteMany({ where: { org_id: org.id } }),
      );
      await step('student school-year', () =>
        db.studentSchoolYear.deleteMany({ where: { org_id: org.id } }),
      );
      await step('accounts', () =>
        db.account.deleteMany({ where: { org_id: org.id } }),
      );
      await step('audit logs', () =>
        db.auditLog.deleteMany({ where: { org_id: org.id } }),
      );
      await step('periods', () =>
        db.enrollmentPeriod.deleteMany({ where: { org_id: org.id } }),
      );
      await step('sections', () =>
        db.section.deleteMany({ where: { org_id: org.id } }),
      );
      await step('levels', () =>
        db.level.deleteMany({ where: { org_id: org.id } }),
      );
      await step('programs', () =>
        db.program.deleteMany({ where: { org_id: org.id } }),
      );
      await step('school years', () =>
        db.schoolYear.deleteMany({ where: { org_id: org.id } }),
      );
      await step('organization', () =>
        db.organization.deleteMany({ where: { id: org.id } }),
      );
      await app.close();
    }, 120000);
  },
);

// backend/test/lane1-item8-cross-sy-semester-template.e2e-spec.ts
//
// Lane 1 item 8 — proof tests against the REAL database.
//
// A single semester template assigned to two different programs that live in
// two different SCHOOL YEARS must materialize per-school-year component rows:
//
//  (a) each program's assignment points at the same template, and each
//      assignment carries its OWN term-date mapping (isolated per assignment);
//  (b) the same template term name (e.g. "1st Semester" / "Term 1") yields
//      DISTINCT `Semester`/`Term` rows scoped to each program's school year —
//      the dates of program A's scope do NOT leak into program B's scope, so a
//      cross-school-year "collision" (which an org-wide or template-scoped key
//      would have produced) cannot occur.

import * as path from 'path';
import { config as loadEnv } from 'dotenv';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import { v4 as uuid } from 'uuid';

import { CoreModule } from '@/core/core.module';
import { SemesterTemplateModule } from '@/modules/semester-template/semester-template.module';
import { SemesterTemplateService } from '@/modules/semester-template/semester-template.service';
import { SemesterTemplateRepository } from '@/modules/semester-template/semester-template.repository';
import { DatabaseService } from '@/core/database/database.provider';

if (!process.env.DATABASE_URL) {
  loadEnv({ path: path.join(__dirname, '..', '.env') });
}
const runSuite = process.env.DATABASE_URL ? describe : describe.skip;

jest.setTimeout(300000);

function log(msg: string) {
  console.log(`[items8] ${msg}`);
}

async function check(label: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
    log(`PASS ${label}`);
  } catch (err) {
    log(`FAIL ${label} — ${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

const localDate = (d: Date | null) => (d ? d.toISOString().slice(0, 10) : null);

runSuite(
  'Lane 1 item 8 — cross-school-year semester template (real DB)',
  () => {
    let app: INestApplication;
    let db: DatabaseService;
    let templateService: SemesterTemplateService;
    let templateRepo: SemesterTemplateRepository;

    const org = {
      id: `e2e8-org-${uuid()}`,
      slug: `e2e8-${uuid().slice(0, 8)}`,
    };

    let syA: { id: string };
    let syB: { id: string };
    let programA: { id: string };
    let programB: { id: string };

    beforeAll(async () => {
      const moduleFixture: TestingModule = await Test.createTestingModule({
        imports: [CoreModule, SemesterTemplateModule],
      }).compile();
      app = moduleFixture.createNestApplication();
      await app.init();
      db = app.get(DatabaseService);
      templateService = app.get(SemesterTemplateService);
      templateRepo = app.get(SemesterTemplateRepository);

      await db.organization.create({
        data: { id: org.id, name: 'E2E Item 8 Org', slug: org.slug },
      });

      syA = await db.schoolYear.create({
        data: {
          org_id: org.id,
          name: `SY-A ${org.id.slice(0, 6)}`,
          status: 'active',
          start_date: new Date('2026-06-01'),
          end_date: new Date('2027-03-31'),
        },
      });
      syB = await db.schoolYear.create({
        data: {
          org_id: org.id,
          name: `SY-B ${org.id.slice(0, 6)}`,
          status: 'active',
          start_date: new Date('2026-06-01'),
          end_date: new Date('2027-03-31'),
        },
      });

      programA = await db.program.create({
        data: {
          org_id: org.id,
          school_year_id: syA.id,
          name: 'Program A (SYA)',
          type: 'elementary',
        },
      });
      programB = await db.program.create({
        data: {
          org_id: org.id,
          school_year_id: syB.id,
          name: 'Program B (SYB)',
          type: 'elementary',
        },
      });
    }, 120000);

    it('(a) one template assigned to two programs keeps each assignment’s term dates isolated', async () => {
      return check(
        'item8 (a) assignment + per-assignment term-date isolation',
        async () => {
          const template = await templateService.create(org.id, {
            name: `E2E-${org.id.slice(0, 6)} Template`,
            programType: 'elementary',
            semesters: [
              {
                name: '1st Semester',
                orderIndex: 1,
                terms: [
                  { name: 'Term 1', orderIndex: 1 },
                  { name: 'Term 2', orderIndex: 2 },
                ],
              },
              {
                name: '2nd Semester',
                orderIndex: 2,
                terms: [{ name: 'Term 3', orderIndex: 1 }],
              },
            ],
          });
          const s1 = template.semesters[0];
          const s2 = template.semesters[1];
          const termT1 = s1.terms[0].id;
          const termT2 = s1.terms[1].id;
          const termT3 = s2.terms[0].id;
          log(
            `(a) template ${template.id} semesters=${template.semesters.length}`,
          );

          // Assign the SAME template to programA (SY A) and programB (SY B).
          await templateRepo.assignToProgram({
            orgId: org.id,
            programId: programA.id,
            templateId: template.id,
          });
          await templateRepo.assignToProgram({
            orgId: org.id,
            programId: programB.id,
            templateId: template.id,
          });

          const assA = await templateRepo.findAssignmentByProgram(
            programA.id,
            org.id,
          );
          const assB = await templateRepo.findAssignmentByProgram(
            programB.id,
            org.id,
          );
          expect(assA?.template_id).toBe(template.id);
          expect(assB?.template_id).toBe(template.id);
          expect(assA?.id).not.toBe(assB?.id);

          // Different calendars for the two school years.
          await templateService.saveTermDates(org.id, programA.id, [
            { termId: termT1, startDate: '2026-06-01', endDate: '2026-12-15' },
            { termId: termT2, startDate: '2027-01-04', endDate: '2027-02-10' },
            { termId: termT3, startDate: '2027-02-15', endDate: '2027-03-26' },
          ]);
          await templateService.saveTermDates(org.id, programB.id, [
            { termId: termT1, startDate: '2026-06-10', endDate: '2026-12-20' },
            { termId: termT2, startDate: '2027-01-10', endDate: '2027-02-20' },
            { termId: termT3, startDate: '2027-03-01', endDate: '2027-03-31' },
          ]);

          // Per-assignment term dates must differ (isolation).
          const datesA = await db.programSemesterTermDate.findMany({
            where: { assignment_id: assA!.id },
            orderBy: { start_date: 'asc' },
          });
          const datesB = await db.programSemesterTermDate.findMany({
            where: { assignment_id: assB!.id },
            orderBy: { start_date: 'asc' },
          });
          log(
            `(a) SYA term-date starts: ${datesA.map((d) => localDate(d.start_date)).join(',')} | ` +
              `SYB: ${datesB.map((d) => localDate(d.start_date)).join(',')}`,
          );
          expect(datesA.length).toBe(3);
          expect(datesB.length).toBe(3);
          expect(localDate(datesA[0].start_date)).toBe('2026-06-01');
          expect(localDate(datesB[0].start_date)).toBe('2026-06-10');
          expect(localDate(datesA[0].start_date)).not.toBe(
            localDate(datesB[0].start_date),
          );
        },
      );
    }, 120000);

    it('(b) same-named component rows are scoped per school year — no cross-SY leak', async () => {
      return check(
        'item8 (b) school-year isolation of component rows',
        async () => {
          // Two Semester rows named "1st Semester" must exist — one per school year.
          const firstSemesters = await db.semester.findMany({
            where: { org_id: org.id, name: '1st Semester' },
            orderBy: { school_year_id: 'asc' },
            include: { terms: { orderBy: { order_index: 'asc' as const } } },
          });
          log(
            `(b) "1st Semester" rows: ${firstSemesters.length} -> ` +
              firstSemesters
                .map(
                  (s) =>
                    `${s.school_year_id.slice(0, 6)}=${localDate(s.start_date)}..${localDate(s.end_date)}`,
                )
                .join(' | '),
          );
          expect(firstSemesters.length).toBe(2);

          const semA = firstSemesters.find((s) => s.school_year_id === syA.id);
          const semB = firstSemesters.find((s) => s.school_year_id === syB.id);
          expect(semA).toBeTruthy();
          expect(semB).toBeTruthy();

          // Component dates come from the program’s OWN calendar, not the template’s.
          expect(localDate(semA!.start_date)).toBe('2026-06-01');
          expect(localDate(semA!.end_date)).toBe('2027-02-10');
          expect(localDate(semB!.start_date)).toBe('2026-06-10');
          expect(localDate(semB!.end_date)).toBe('2027-02-20');
          expect(localDate(semA!.start_date)).not.toBe(
            localDate(semB!.start_date),
          );

          // The same term name also resolves to the correct per-SY dates.
          const termA1 = semA!.terms.find((t) => t.name === 'Term 1');
          const termB1 = semB!.terms.find((t) => t.name === 'Term 1');
          expect(termA1).toBeTruthy();
          expect(termB1).toBeTruthy();
          expect(localDate(termA1!.start_date)).toBe('2026-06-01');
          expect(localDate(termB1!.start_date)).toBe('2026-06-10');

          // Full cross-reference sweep: EVERY component row under this org belongs to
          // one of the two school years (no dangling org-wide/unscoped rows).
          // The template defines 2 semesters, so we expect 2 SYs × 2 names = 4 rows,
          // all scoped to either SYA or SYB.
          const allSemesters = await db.semester.findMany({
            where: { org_id: org.id },
            select: { school_year_id: true },
          });
          expect(allSemesters.length).toBe(4);
          for (const s of allSemesters) {
            expect([syA.id, syB.id]).toContain(s.school_year_id);
          }
          log('(b) all component rows correctly scoped to SYA/SYB');
        },
      );
    }, 120000);

    afterAll(async () => {
      if (!db) return;
      const step = async (label: string, fn: () => Promise<unknown>) => {
        try {
          await fn();
          log(`cleaned ${label}`);
        } catch (err) {
          log(
            `CLEANUP FAIL @ ${label}: ${err instanceof Error ? err.message : err}`,
          );
        }
      };
      await step('program term dates', () =>
        db.programSemesterTermDate.deleteMany({ where: { org_id: org.id } }),
      );
      await step('program assignments', () =>
        db.programSemesterAssignment.deleteMany({ where: { org_id: org.id } }),
      );
      await step('terms', () =>
        db.term.deleteMany({ where: { org_id: org.id } }),
      );
      await step('semesters', () =>
        db.semester.deleteMany({ where: { org_id: org.id } }),
      );
      await step('template terms', () =>
        db.semesterTemplateTerm.deleteMany({ where: { org_id: org.id } }),
      );
      await step('template items', () =>
        db.semesterTemplateItem.deleteMany({ where: { org_id: org.id } }),
      );
      await step('templates', () =>
        db.semesterTemplate.deleteMany({ where: { org_id: org.id } }),
      );
      await step('programs', () =>
        db.program.deleteMany({ where: { org_id: org.id } }),
      );
      await step('school years', () =>
        db.schoolYear.deleteMany({ where: { org_id: org.id } }),
      );
      await step('organization', () =>
        db.organization.deleteMany({ where: { id: org.id } }),
      );
      await app.close();
    }, 120000);
  },
);

// backend/test/lane1-item9-enrollment-auto-unenroll.e2e-spec.ts
//
// Lane 1 item 9 — proof tests against the REAL database for "auto unenroll when
// the school year ends":
//  (a) the nightly scheduler task (SchedulerTasks.handleAutoUnenrollOnYearEnd)
//      removes active class enrollments and unenrolls StudentSchoolYear rows for
//      an EXPIRED active school year, then marks the year `ended`;
//  (b) that sweep respects the org's auto_unenroll_on_year_end setting
//      (disabled → enrollments are preserved while the year still ends);
//  (c) the admin SchoolYearService.end() performs the same scrub
//      unconditionally, and its guards reject a pending year (400), an already
//      ended year (409), and a missing year (404).

import * as path from 'path';
import { config as loadEnv } from 'dotenv';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import {
  BadRequestException,
  ConflictException,
  NotFoundException,
} from '@nestjs/common';
import { v4 as uuid } from 'uuid';

import { CoreModule } from '@/core/core.module';
import { SchoolYearModule } from '@/modules/school-year/school-year.module';
import { OrgEnrollmentSettingModule } from '@/modules/org-enrollment-setting/org-enrollment-setting.module';
import { DatabaseService } from '@/core/database/database.provider';
import { SchedulerTasks } from '@/core/scheduler/scheduler.tasks';
import { SchoolYearService } from '@/modules/school-year/school-year.service';
import { OrgEnrollmentSettingService } from '@/modules/org-enrollment-setting/org-enrollment-setting.service';

if (!process.env.DATABASE_URL) {
  loadEnv({ path: path.join(__dirname, '..', '.env') });
}
const runSuite = process.env.DATABASE_URL ? describe : describe.skip;

jest.setTimeout(300000);

function log(msg: string) {
  console.log(`[item9] ${msg}`);
}

async function check(label: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
    log(`PASS ${label}`);
  } catch (err) {
    log(`FAIL ${label} — ${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

runSuite(
  'Lane 1 item 9 — auto-unenroll when the school year ends (real DB)',
  () => {
    let app: INestApplication;
    let db: DatabaseService;
    let scheduler: SchedulerTasks;
    let schoolYearService: SchoolYearService;
    let orgSettingService: OrgEnrollmentSettingService;

    const orgA = {
      id: `e2e9a-org-${uuid()}`,
      slug: `e2e9a-${uuid().slice(0, 8)}`,
    };
    const orgB = {
      id: `e2e9b-org-${uuid()}`,
      slug: `e2e9b-${uuid().slice(0, 8)}`,
    };
    const orgC = {
      id: `e2e9c-org-${uuid()}`,
      slug: `e2e9c-${uuid().slice(0, 8)}`,
    };
    const actorId = `e2e9-act-${uuid()}`;

    const now = Date.now();
    const day = 24 * 60 * 60 * 1000;

    async function orgWithExpiredYear(
      org: { id: string; slug: string },
      name: string,
      status: 'active' | 'pending' | 'ended' = 'active',
    ) {
      await db.organization.create({
        data: { id: org.id, name, slug: org.slug },
      });
      return db.schoolYear.create({
        data: {
          org_id: org.id,
          name: `SY ${org.id.slice(0, 6)}`,
          status,
          start_date: new Date(now - 30 * day),
          end_date: new Date(now - 1 * day),
        },
      });
    }

    // Minimal but complete academic tree: program → level → subject → semester →
    // class (educator + semester are required FKs on Class).
    async function classFixture(orgId: string, syId: string) {
      const program = await db.program.create({
        data: {
          org_id: orgId,
          school_year_id: syId,
          name: 'JHS Item9',
          type: 'jhs',
        },
      });
      const level = await db.level.create({
        data: {
          org_id: orgId,
          school_year_id: syId,
          program_id: program.id,
          name: 'Grade 7',
        },
      });
      const subject = await db.subject.create({
        data: {
          org_id: orgId,
          name: `Subject-${uuid().slice(0, 4)}`,
          subject_type: 'minor',
          program_id: program.id,
          level_id: level.id,
        },
      });
      const semester = await db.semester.create({
        data: {
          org_id: orgId,
          school_year_id: syId,
          name: '1st Semester',
          start_date: new Date(now - 10 * day),
          end_date: new Date(now + 10 * day),
        },
      });
      const educator = await db.account.create({
        data: {
          org_id: orgId,
          role: 'educator',
          email: `edu-${orgId.slice(0, 6)}-${uuid().slice(0, 4)}@example.com`,
          password: 'x',
          status: 'active',
        },
      });
      const cls = await db.class.create({
        data: {
          org_id: orgId,
          subject_id: subject.id,
          educator_id: educator.id,
          school_year_id: syId,
          semester_id: semester.id,
          capacity: 40,
        },
      });
      return { classId: cls.id };
    }

    async function activeClassEnrollment(
      orgId: string,
      syId: string,
      classId: string,
      tag: string,
    ) {
      const student = await db.account.create({
        data: {
          org_id: orgId,
          role: 'student',
          email: `stu-${tag}-${orgId.slice(0, 6)}-${uuid().slice(0, 4)}@example.com`,
          password: 'x',
          status: 'active',
        },
      });
      const ssy = await db.studentSchoolYear.create({
        data: {
          org_id: orgId,
          student_id: student.id,
          school_year_id: syId,
          status: 'active',
        },
      });
      const enrollment = await db.enrollment.create({
        data: {
          org_id: orgId,
          class_id: classId,
          student_id: student.id,
          status: 'active',
        },
      });
      return {
        studentId: student.id,
        ssyId: ssy.id,
        enrollmentId: enrollment.id,
      };
    }

    beforeAll(async () => {
      const moduleFixture: TestingModule = await Test.createTestingModule({
        imports: [CoreModule, SchoolYearModule, OrgEnrollmentSettingModule],
        providers: [
          // The scheduler task only touches `db` + `orgEnrollmentSettingService`
          // on the year-end path, so the remaining deps can stay unneeded.
          {
            provide: SchedulerTasks,
            useFactory: (
              db_: DatabaseService,
              orgSetting: OrgEnrollmentSettingService,
            ) =>
              new SchedulerTasks(
                null as never,
                null as never,
                null as never,
                orgSetting,
                null as never,
                db_,
                null as never,
              ),
            inject: [DatabaseService, OrgEnrollmentSettingService],
          },
        ],
      }).compile();
      app = moduleFixture.createNestApplication();
      await app.init();
      db = app.get(DatabaseService);
      scheduler = app.get(SchedulerTasks);
      schoolYearService = app.get(SchoolYearService);
      orgSettingService = app.get(OrgEnrollmentSettingService);
    }, 120000);

    it('(a) cron unenrolls class enrollments + students for an expired active year', async () => {
      return check(
        'item9 (a) scheduler auto-unenroll on year end',
        async () => {
          const sy = await orgWithExpiredYear(orgA, 'Item9a Org');
          const cls = await classFixture(orgA.id, sy.id);
          const enr = await activeClassEnrollment(
            orgA.id,
            sy.id,
            cls.classId,
            'a',
          );

          await scheduler.handleAutoUnenrollOnYearEnd();

          const yearAfter = await db.schoolYear.findUnique({
            where: { id: sy.id },
          });
          expect(yearAfter?.status).toBe('ended');

          const enrollmentAfter = await db.enrollment.findUnique({
            where: { id: enr.enrollmentId },
          });
          expect(enrollmentAfter?.status).toBe('removed');

          const ssyAfter = await db.studentSchoolYear.findUnique({
            where: { id: enr.ssyId },
          });
          expect(ssyAfter?.status).toBe('unenrolled');
          expect(ssyAfter?.unenrolled_at).not.toBeNull();
        },
      );
    }, 120000);

    it('(b) org setting auto_unenroll_on_year_end=false preserves enrollments (year still ends)', async () => {
      return check(
        'item9 (b) disabled auto-unenroll setting respected',
        async () => {
          const sy = await orgWithExpiredYear(orgB, 'Item9b Org');
          const cls = await classFixture(orgB.id, sy.id);
          const enr = await activeClassEnrollment(
            orgB.id,
            sy.id,
            cls.classId,
            'b',
          );
          await orgSettingService.upsert(orgB.id, {
            auto_unenroll_on_year_end: false,
          });

          await scheduler.handleAutoUnenrollOnYearEnd();

          const yearAfter = await db.schoolYear.findUnique({
            where: { id: sy.id },
          });
          expect(yearAfter?.status).toBe('ended');

          const enrollmentAfter = await db.enrollment.findUnique({
            where: { id: enr.enrollmentId },
          });
          expect(enrollmentAfter?.status).toBe('active');

          const ssyAfter = await db.studentSchoolYear.findUnique({
            where: { id: enr.ssyId },
          });
          expect(ssyAfter?.status).toBe('active');
        },
      );
    }, 120000);

    it('(c) SchoolYearService.end() scrubs enrollments unconditionally and its guards hold', async () => {
      return check('item9 (c) admin end() scrub + guards', async () => {
        const sy = await orgWithExpiredYear(orgC, 'Item9c Org');
        const cls = await classFixture(orgC.id, sy.id);
        const enr = await activeClassEnrollment(
          orgC.id,
          sy.id,
          cls.classId,
          'c',
        );

        await schoolYearService.end(sy.id, orgC.id, actorId);

        const yearAfter = await db.schoolYear.findUnique({
          where: { id: sy.id },
        });
        expect(yearAfter?.status).toBe('ended');
        const enrollmentAfter = await db.enrollment.findUnique({
          where: { id: enr.enrollmentId },
        });
        expect(enrollmentAfter?.status).toBe('removed');
        const ssyAfter = await db.studentSchoolYear.findUnique({
          where: { id: enr.ssyId },
        });
        expect(ssyAfter?.status).toBe('unenrolled');

        // Guards: pending year, already-ended year, missing year.
        const pendingSy = await db.schoolYear.create({
          data: {
            org_id: orgC.id,
            name: 'SY pending',
            status: 'pending',
            start_date: new Date(now - 5 * day),
            end_date: new Date(now + 300 * day),
          },
        });
        await expect(
          schoolYearService.end(pendingSy.id, orgC.id, actorId),
        ).rejects.toBeInstanceOf(BadRequestException);
        await expect(
          schoolYearService.end(sy.id, orgC.id, actorId),
        ).rejects.toBeInstanceOf(ConflictException);
        await expect(
          schoolYearService.end(
            '00000000-0000-4000-8000-000000000000',
            orgC.id,
            actorId,
          ),
        ).rejects.toBeInstanceOf(NotFoundException);
      });
    }, 120000);

    afterAll(async () => {
      if (!db) return;
      const step = async (label: string, fn: () => Promise<unknown>) => {
        try {
          await fn();
          log(`cleaned ${label}`);
        } catch (err) {
          log(
            `CLEANUP FAIL @ ${label}: ${err instanceof Error ? err.message : err}`,
          );
        }
      };
      for (const org of [orgA, orgB, orgC]) {
        await step(`org ${org.id} enrollments`, () =>
          db.enrollment.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} class schedules`, () =>
          db.classSchedule.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} classes`, () =>
          db.class.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} semesters`, () =>
          db.semester.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} subjects`, () =>
          db.subject.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} program enrollments`, () =>
          db.studentProgramEnrollment.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} school-year enrollments`, () =>
          db.studentSchoolYear.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} accounts`, () =>
          db.account.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} audit logs`, () =>
          db.auditLog.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} enrollment settings`, () =>
          db.orgEnrollmentSetting.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} levels`, () =>
          db.level.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} programs`, () =>
          db.program.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id} school years`, () =>
          db.schoolYear.deleteMany({ where: { org_id: org.id } }),
        );
        await step(`org ${org.id}`, () =>
          db.organization.deleteMany({ where: { id: org.id } }),
        );
      }
      await app.close();
    }, 120000);
  },
);

// backend/test/late-enrollment-grading.e2e-spec.ts
//
// Real-database e2e for the late-enrollment grading exclusion rule and the
// Phase 3 override API, modeled on org-seeder.e2e-spec.ts conventions:
// real Prisma client, real services, a unique test org per run, explicit
// cleanup. Ownership rejection (test 6) is verified over real HTTP through
// the real JWT AuthGuard + RolesGuard + service, not a mocked guard.

import * as path from 'path';
import jwt from 'jsonwebtoken';
import request from 'supertest';
import { config as loadEnv } from 'dotenv';
import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { PassportModule } from '@nestjs/passport';
import { v4 as uuid } from 'uuid';

import { DatabaseModule } from '@/core/database/database.module';
import { DatabaseService } from '@/core/database/database.provider';
import { GradeCoreModule } from '@/modules/grade/core/grade-core.module';
import { AuditLogModule } from '@/modules/audit-log/audit-log.module';
import { GradeRepository } from '@/modules/grade/grade.repository';
import { GradeEducatorService } from '@/modules/grade/educator/grade-educator.service';
import { GradeEducatorController } from '@/modules/grade/educator/grade-educator.controller';
import { AuthRepository } from '@/modules/auth/auth.repository';
import { JwtStrategy } from '@/modules/auth/strategies/jwt.strategy';
import jwtConfig from '@/configs/jwt.config';

if (!process.env.DATABASE_URL) {
  loadEnv({ path: path.join(__dirname, '..', '.env') });
}

const hasDbUrl = !!process.env.DATABASE_URL;
const log = (msg: string) => console.log(`[late-enrollment e2e] ${msg}`);

async function check(
  label: string,
  fn: () => void | Promise<unknown>,
): Promise<void> {
  try {
    await fn();
    log(`PASS ${label}`);
  } catch (err) {
    log(`FAIL ${label} — ${err instanceof Error ? err.message : String(err)}`);
    throw err;
  }
}

const DAY = 24 * 60 * 60 * 1000;

jest.setTimeout(120000);

function signToken(secret: string | undefined, sub: string): string {
  if (!secret)
    throw new Error('JWT_SECRET missing from env — cannot sign token.');
  return jwt.sign({ sub }, secret, { expiresIn: '1h' });
}

describe('[late-enrollment] grading exclusion — real DB end to end', () => {
  let available = false;

  let moduleRef: TestingModule;
  let app: INestApplication;
  let db: DatabaseService;
  let svc: GradeEducatorService;

  let orgId = '';
  let ownerId = '';
  let intruderId = '';
  let studentId = '';
  let classMixId = '';
  let classAllPreId = '';
  let termId = '';
  let b1Id = '';
  let p1Id = '';
  const tenantCleanups: Array<(d: DatabaseService) => Promise<unknown>> = [];
  let ownerToken = '';
  let intruderToken = '';

  beforeAll(async () => {
    if (!hasDbUrl) {
      log('SKIPPED — DATABASE_URL not set; e2e needs a real DB.');
      return;
    }
    available = true;

    moduleRef = await Test.createTestingModule({
      imports: [
        ConfigModule.forRoot({ isGlobal: true, load: [jwtConfig] }),
        PassportModule.register({ defaultStrategy: 'jwt' }),
        DatabaseModule,
        GradeCoreModule,
        AuditLogModule,
      ],
      controllers: [GradeEducatorController],
      providers: [
        GradeRepository,
        GradeEducatorService,
        AuthRepository,
        JwtStrategy,
      ],
    }).compile();

    app = moduleRef.createNestApplication();
    await app.init();

    db = moduleRef.get(DatabaseService);
    svc = moduleRef.get(GradeEducatorService);

    const now = new Date();
    const preEnroll = new Date(now.getTime() - 10 * DAY);
    const postEnrollA = new Date(now.getTime() + 5 * DAY);
    const postEnrollB = new Date(now.getTime() + 6 * DAY);

    const org = await db.organization.create({
      data: { name: `late-enr-${uuid().slice(0, 8)}` },
    });
    orgId = org.id;
    tenantCleanups.push((d) =>
      d.organization.delete({ where: { id: org.id } }),
    );

    const schoolYear = await db.schoolYear.create({
      data: {
        org_id: org.id,
        name: `SY-${uuid().slice(0, 8)}`,
        start_date: new Date(now.getFullYear(), 0, 1),
        end_date: new Date(now.getFullYear() + 1, 0, 1),
        status: 'active',
      },
    });
    tenantCleanups.push((d) =>
      d.schoolYear.delete({ where: { id: schoolYear.id } }),
    );

    const program = await db.program.create({
      data: {
        org_id: org.id,
        school_year_id: schoolYear.id,
        name: 'P1',
        type: 'college',
      },
    });
    tenantCleanups.push((d) => d.program.delete({ where: { id: program.id } }));

    const gradingScale = await db.gradingScale.create({
      data: {
        org_id: org.id,
        name: 'E2E Scale',
        program_type: 'college',
        ranges: [
          {
            minPercent: 0,
            maxPercent: 74,
            gradeValue: 'F',
            remark: 'Failed',
            isPassing: false,
          },
          {
            minPercent: 75,
            maxPercent: 100,
            gradeValue: 'P',
            remark: 'Passed',
            isPassing: true,
          },
        ],
      },
    });
    tenantCleanups.push((d) =>
      d.gradingScale.delete({ where: { id: gradingScale.id } }),
    );

    await db.gradingScaleAssignment.create({
      data: {
        org_id: org.id,
        grading_scale_id: gradingScale.id,
        program_id: program.id,
        school_year_id: schoolYear.id,
      },
    });
    tenantCleanups.push((d) =>
      d.gradingScaleAssignment.deleteMany({ where: { org_id: org.id } }),
    );

    const mkAccount = async (role: string) => {
      const a = await db.account.create({
        data: {
          org_id: org.id,
          role: role as any,
          email: `${uuid().slice(0, 12)}@late.test`,
          password: 'x',
          status: 'active',
        },
      });
      tenantCleanups.push((d) => d.account.delete({ where: { id: a.id } }));
      return a.id;
    };
    ownerId = await mkAccount('educator');
    intruderId = await mkAccount('educator');
    studentId = await mkAccount('student');

    const semester = await db.semester.create({
      data: {
        org_id: org.id,
        school_year_id: schoolYear.id,
        name: 'Sem 1',
        start_date: new Date(now.getFullYear(), 0, 1),
        end_date: new Date(now.getFullYear() + 1, 0, 1),
      },
    });
    tenantCleanups.push((d) =>
      d.semester.delete({ where: { id: semester.id } }),
    );

    const term = await db.term.create({
      data: {
        org_id: org.id,
        semester_id: semester.id,
        name: 'Term 1',
        order_index: 1,
        start_date: new Date(now.getFullYear(), 0, 1),
        end_date: new Date(now.getFullYear() + 1, 0, 1),
      },
    });
    termId = term.id;
    tenantCleanups.push((d) => d.term.delete({ where: { id: term.id } }));

    const subject = await db.subject.create({
      data: { org_id: org.id, name: 'E2E Subj', program_id: program.id },
    });
    tenantCleanups.push((d) => d.subject.delete({ where: { id: subject.id } }));

    const mkClass = async (label: string) => {
      const cls = await db.class.create({
        data: {
          org_id: org.id,
          subject_id: subject.id,
          educator_id: ownerId,
          school_year_id: schoolYear.id,
          semester_id: semester.id,
          capacity: 40,
        },
      });
      tenantCleanups.push((d) => d.class.delete({ where: { id: cls.id } }));
      return cls.id;
    };
    classMixId = await mkClass('mix');
    classAllPreId = await mkClass('all-pre');

    // Mixed class enrollment (enrolled now; pre-released assessments are excluded).
    await db.enrollment.create({
      data: {
        org_id: org.id,
        class_id: classMixId,
        student_id: studentId,
        status: 'active',
      },
    });
    // All-pre class enrollment.
    await db.enrollment.create({
      data: {
        org_id: org.id,
        class_id: classAllPreId,
        student_id: studentId,
        status: 'active',
      },
    });
    tenantCleanups.push((d) =>
      d.enrollment.deleteMany({ where: { org_id: org.id } }),
    );

    const scheme = await db.gradingScheme.create({
      data: {
        org_id: org.id,
        class_id: classMixId,
        name: 'E2E Scheme',
        is_default: true,
      },
    });
    tenantCleanups.push((d) =>
      d.gradingScheme.delete({ where: { id: scheme.id } }),
    );
    const comps = [
      { name: 'Written Tasks', type: 'written', weight: 60 },
      { name: 'Performance Task', type: 'performance', weight: 40 },
    ];
    for (const c of comps) {
      const cc = await db.gradingSchemeComponent.create({
        data: { org_id: org.id, grading_scheme_id: scheme.id, ...c },
      });
      tenantCleanups.push((d) =>
        d.gradingSchemeComponent.delete({ where: { id: cc.id } }),
      );
    }

    const mkAssessment = async (
      classId: string,
      type: string,
      title: string,
      release: Date,
      totalItems = 50,
    ) => {
      const a = await db.assessment.create({
        data: {
          org_id: org.id,
          class_id: classId,
          term_id: term.id,
          type,
          title,
          total_items: totalItems,
          release_date: release,
          end_date: new Date(now.getTime() + 30 * DAY),
          is_published: true,
        },
      });
      tenantCleanups.push((d) => d.assessment.delete({ where: { id: a.id } }));
      return a.id;
    };

    // Mixed class: B1 pre-enrollment (excluded), B2/B3 post-enrollment (included),
    // P1 performance pre-enrollment (excluded) → performance category must drop out.
    const b2Id = await mkAssessment(classMixId, 'written', 'B2', postEnrollA);
    const b3Id = await mkAssessment(classMixId, 'written', 'B3', postEnrollB);
    b1Id = await mkAssessment(classMixId, 'written', 'B1', preEnroll);
    p1Id = await mkAssessment(classMixId, 'performance', 'P1', preEnroll);
    // All-pre class: both released before enrollment.
    const aPre1 = await mkAssessment(classAllPreId, 'written', 'A1', preEnroll);
    const aPre2 = await mkAssessment(classAllPreId, 'written', 'A2', preEnroll);

    const mkSubmission = async (assessmentId: string, score: number) => {
      const s = await db.submission.create({
        data: {
          org_id: org.id,
          assessment_id: assessmentId,
          student_id: studentId,
          status: 'submitted',
          score,
          manual_score: null,
          submitted_at: now,
        },
      });
      tenantCleanups.push((d) => d.submission.delete({ where: { id: s.id } }));
      return s.id;
    };

    let subB1Id: string;
    let subP1Id: string;
    await mkSubmission(b2Id, 35); // 70%
    await mkSubmission(b3Id, 45); // 90%
    subB1Id = await mkSubmission(b1Id, 20); // 40% — excluded by default in mixed
    subP1Id = await mkSubmission(p1Id, 45); // 90% — excluded
    await mkSubmission(aPre1, 40); // 80%
    await mkSubmission(aPre2, 40); // 80%

    tenantCleanups.push((d) =>
      d.grade.deleteMany({ where: { org_id: org.id } }),
    );
    tenantCleanups.push((d) =>
      d.assessmentGradingOverride.deleteMany({ where: { org_id: org.id } }),
    );
    tenantCleanups.push((d) =>
      d.auditLog.deleteMany({ where: { org_id: org.id } }),
    );

    ownerToken = signToken(process.env.JWT_SECRET, ownerId);
    intruderToken = signToken(process.env.JWT_SECRET, intruderId);

    // Keep references for later mutation in scenario 5.
    (globalThis as any).__subB1Id = subB1Id;
    (globalThis as any).__subP1Id = subP1Id;
  });

  afterAll(async () => {
    if (!available) return;
    for (const cleanup of tenantCleanups.reverse()) {
      try {
        await cleanup(db);
      } catch {
        /* best-effort */
      }
    }
    await app.close();
    await moduleRef.close();
  });

  const breakdownByCategory = async (classId: string) => {
    const termGrades = await svc.getGradesByTerm(
      classId,
      termId,
      orgId,
      ownerId,
    );
    const student = termGrades.students.find(
      (s: any) => s.studentId === studentId,
    );
    if (!student) throw new Error('student row missing from term grades');
    return {
      written: student.categoryBreakdown.find((c: any) => c.type === 'written'),
      performance: student.categoryBreakdown.find(
        (c: any) => c.type === 'performance',
      ),
    };
  };

  const computeAndFetchGrade = async (classId: string) => {
    await svc.computeGrades(classId, termId, orgId, ownerId);
    return db.grade.findFirst({
      where: {
        org_id: orgId,
        student_id: studentId,
        class_id: classId,
        term_id: termId,
      },
    });
  };

  it('(2) mixed: only post-enrollment assessments are averaged; full drop renormalizes', async () => {
    if (!available) return;
    const bd = await breakdownByCategory(classMixId);
    await check('scenario 2 — written rawAverage = (70+90)/2 = 80', () => {
      expect(bd.written!.rawAverage).toBe(80);
      expect(bd.performance!.isAllExempted).toBe(true);
      expect(bd.performance!.rawAverage).toBeNull();
    });

    await check(
      'scenario 2 — final grade = 80 (performance category dropped, not zero-penalized)',
      async () => {
        const grade = await computeAndFetchGrade(classMixId);
        expect(grade?.final_score).toBe(80);
      },
    );

    await check(
      'scenario 2 — excluded cells carry reason default_excluded',
      async () => {
        const termGrades = await svc.getGradesByTerm(
          classMixId,
          termId,
          orgId,
          ownerId,
        );
        const student = termGrades.students.find(
          (s: any) => s.studentId === studentId,
        );
        const b1 = student!.assessmentScores.find(
          (s: any) => s.assessmentId === b1Id,
        );
        expect(b1.included).toBe(false);
        expect(b1.inclusionReason).toBe('default_excluded');
      },
    );
  });

  it('(6) HTTP: override POST works for the owner; non-owner is rejected over real HTTP', async () => {
    if (!available) return;
    const http = request(app.getHttpServer());

    await check(
      'HTTP — unauthenticated status call rejects with 401',
      async () => {
        await http
          .get(
            `/classes/${classMixId}/grades/students/${studentId}/assessments/status`,
          )
          .expect(401);
      },
    );

    await check('HTTP — non-owner GET status rejects with 403', async () => {
      await http
        .get(
          `/classes/${classMixId}/grades/students/${studentId}/assessments/status`,
        )
        .set('Authorization', `Bearer ${intruderToken}`)
        .expect(403);
    });

    await check('HTTP — non-owner POST override rejects with 403', async () => {
      await http
        .post(
          `/classes/${classMixId}/grades/students/${studentId}/assessments/${b1Id}/override`,
        )
        .set('Authorization', `Bearer ${intruderToken}`)
        .send({ overrideStatus: 'MISSING' })
        .expect(403);
    });

    await check(
      'HTTP — owner POST override succeeds and is audited',
      async () => {
        await http
          .post(
            `/classes/${classMixId}/grades/students/${studentId}/assessments/${b1Id}/override`,
          )
          .set('Authorization', `Bearer ${ownerToken}`)
          .send({ overrideStatus: 'MISSING' })
          .expect(201);

        const audit = await db.auditLog.count({
          where: { org_id: orgId, action: 'assessment_status_override' },
        });
        expect(audit).toBe(1);

        const res = await http
          .get(
            `/classes/${classMixId}/grades/students/${studentId}/assessments/status`,
          )
          .set('Authorization', `Bearer ${ownerToken}`)
          .expect(200);
        const statusList = Array.isArray(res.body) ? res.body : res.body?.data;
        const b1 = statusList.find((r: any) => r.assessmentId === b1Id);
        expect(b1.overrideStatus).toBe('MISSING');
        expect(b1.countsTowardGrade).toBe(true);
      },
    );

    await check(
      'HTTP — owner DELETE override reverts and removes the row',
      async () => {
        await http
          .delete(
            `/classes/${classMixId}/grades/students/${studentId}/assessments/${b1Id}/override`,
          )
          .set('Authorization', `Bearer ${ownerToken}`)
          .expect(200);

        const rows = await db.assessmentGradingOverride.count({
          where: { assessment_id: b1Id, student_id: studentId },
        });
        expect(rows).toBe(0);
      },
    );

    await check(
      'HTTP — non-owner DELETE override rejects with 403',
      async () => {
        await http
          .delete(
            `/classes/${classMixId}/grades/students/${studentId}/assessments/${b1Id}/override`,
          )
          .set('Authorization', `Bearer ${intruderToken}`)
          .expect(403);
      },
    );
  });

  it('(3) override include: all three assessments average and grade changes exactly', async () => {
    if (!available) return;
    await check(
      'scenario 3 — write include override for the pre-enrollment B1',
      async () => {
        await svc.setAssessmentStatusOverride(
          classMixId,
          b1Id,
          studentId,
          orgId,
          ownerId,
          {
            overrideStatus: 'MISSING',
          } as any,
        );
      },
    );

    await check(
      'scenario 3 — written rawAverage = (40+70+90)/3 = 66.67',
      async () => {
        const bd = await breakdownByCategory(classMixId);
        expect(bd.written!.rawAverage).toBe(66.67);
      },
    );

    await check(
      'scenario 3 — final grade = 66.67 (all three counted)',
      async () => {
        const grade = await computeAndFetchGrade(classMixId);
        expect(grade?.final_score).toBe(66.67);
      },
    );
  });

  it('(4) override then delete: grade reverts exactly to the default-exclusion result', async () => {
    if (!available) return;
    await check(
      'scenario 4 — delete the override via the service (Phase 3 endpoint path)',
      async () => {
        const res = await svc.deleteAssessmentStatusOverride(
          classMixId,
          b1Id,
          studentId,
          orgId,
          ownerId,
        );
        expect(res.deleted).toBe(1);
      },
    );

    await check('scenario 4 — final grade reverts to exactly 80', async () => {
      const grade = await computeAndFetchGrade(classMixId);
      expect(grade?.final_score).toBe(80);
    });
  });

  it('(5) exempted submission stays exempt even when override would include the assessment', async () => {
    if (!available) return;
    await check('scenario 5 — mark B1 submission exempted', async () => {
      await db.submission.update({
        where: { id: (globalThis as any).__subB1Id },
        data: { is_exempted: true },
      });
    });

    await check(
      'scenario 5 — default exclusion still yields 80 (exemption is independent)',
      async () => {
        const grade = await computeAndFetchGrade(classMixId);
        expect(grade?.final_score).toBe(80);
      },
    );

    await check(
      'scenario 5 — forced include does NOT resurrect an exempted submission',
      async () => {
        await svc.setAssessmentStatusOverride(
          classMixId,
          b1Id,
          studentId,
          orgId,
          ownerId,
          {
            overrideStatus: 'MISSING',
          } as any,
        );
        const grade = await computeAndFetchGrade(classMixId);
        expect(grade?.final_score).toBe(80);
        // Clean up override so later assertions and cleanup stay deterministic.
        await svc.deleteAssessmentStatusOverride(
          classMixId,
          b1Id,
          studentId,
          orgId,
          ownerId,
        );
      },
    );
  });

  it('(1) all-pre-enrollment component reports no eligible assessments, not a 0%', async () => {
    if (!available) return;
    await check(
      'scenario 1 — categoryBreakdown is all-exempted, not 0',
      async () => {
        const termGrades = await svc.getGradesByTerm(
          classAllPreId,
          termId,
          orgId,
          ownerId,
        );
        const student = termGrades.students.find(
          (s: any) => s.studentId === studentId,
        );
        const written = student!.categoryBreakdown.find(
          (c: any) => c.type === 'written',
        );
        expect(written!.rawAverage).toBeNull();
        expect(written!.isAllExempted).toBe(true);
      },
    );

    await check(
      'scenario 1 — final score is 0 with no active categories (non-div-by-zero)',
      async () => {
        const grade = await computeAndFetchGrade(classAllPreId);
        expect(grade?.final_score).toBe(0);
      },
    );
  });
});

// backend/test/org-seeder.e2e-spec.ts
//
// REAL end-to-end test for the OrgSeeder flow. No mocks, no stubs, no fake
